[' Here's a C function that meets the requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int is_integer(const char *str) {
    if (*str == '\0') return 0;

    int valid = isdigit(*str);
    while (*++str) valid &= isdigit(*str);
    return valid;
}

size_t read_ints(int **arr, size_t *len) {
    char str[1024];
    size_t count = 0;

    while (1) {
        printf("Enter an integer or 'q' to quit: ");
        if (!fgets(str, sizeof(str), stdin) || feof(stdin)) break;

        str[strlen(str) - 1] = '\0'; // Remove newline character

        if (strcmp(str, "q") == 0) return count;
        if (!is_integer(str)) {
            printf("Invalid input! Please enter an integer or 'q' to quit.\n");
            continue;
        }

        int *new_arr = realloc(*arr, sizeof(int) * (count + 1));
        if (!new_arr) {
            fprintf(stderr, "Out of memory! Terminating...\n");
            return count;
        }
        *arr = new_arr;
        (*arr)[count] = atoi(str);
        ++count;
    }

    // Free the last position in case the user entered fewer than 10,000 integers.
    free((*arr) + count);
    *len = count;
    return count;
}

int max_in_array(const int *arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; ++i)
        max = (max > arr[i]) ? max : arr[i];
    return max;
}

void find_largest(void) {
    int *nums = NULL;
    size_t len = 0, count;

    while ((count = read_ints(&nums, &len)) > 0 && len < 10000) {}

    if (len == 0) {
        printf("No integers entered!\n");
        return;
    }

    int max = max_in_array(nums, len);
    printf("The largest integer is: %d\n", max);
    free(nums);
}
```

This code defines three functions:
- `is_integer()` checks if a given string represents an integer.
- `read_ints()` reads integers from the standard input and dynamically allocates memory for them, handling errors such as out of memory or invalid input. It also keeps track of the number of elements read.
- `max_in_array()` calculates the maximum value in an array of integers.

The main function, `find_largest()`, demonstrates how to use these functions to find and print the largest integer entered by the user. It continues reading input until 10,000 integers have been entered or the user decides to quit.']

