```c
#include "log_api.h"
#include <string.h>
#include <stdarg.h>

static GThreadPool *thread_pool;
static sem_t global_write_semaphore;

static inline void init_sem(sem_t *sem, unsigned int value) {
    sem_init(sem, 0, value);
}

void log_api_init(struct logging_context **ctx, const char *config_filename) {
    // Initialize thread pool and global write semaphore
    thread_pool = g_thread_pool_new(log_api_log_func, NULL, FALSE, 0);
    init_sem(&global_write_semaphore, MAX_NUM_THREADS);

    // Load configuration from file and set up logging context
}

void log_api_fini(struct logging_context *ctx) {
    g_thread_pool_unref(thread_pool);
    if (ctx->curl_handle) curl_easy_cleanup(ctx->curl_handle);
    fclose(ctx->logfile);
}

void log_api_set_min_level(struct logging_context *ctx, log_level_t level) {
    ctx->config.min_log_level = level;
}

void log_api_log(struct logging_context *ctx, log_level_t level, const char *format, ...) {
    if (level < ctx->config.min_log_level) return;

    // Wait for write semaphore before writing to avoid contention
    sem_wait(&global_write_semaphore);

    // Write log message to local file and remote logging service (if configured)
}

static void* log_api_log_func(GThreadPool *pool, gpointer data) {
    // Process pending logs here
    return NULL;
}
