import csv
import sys
from typing import Tuple, Dict, Iterable
import warnings
import errno
import gzip

class StreamingCSVProcessor:
    def __init__(self, input_file, interface):
        self.input_file = input_file
        self.interface = interface
        self.row_count = 0
        self.missing_value_count = 0
        self.error_count = 0
        self.warning_count = 0
        self.processed_rows = []

    def process(self):
        try:
            with self._open_input() as f:
                reader = csv.reader(f, delimiter=',')
                for row in self._iterable_rows(reader):
                    if self.stopped():
                        break
                    try:
                        transformed_row = self.preprocess(row)
                        self.postprocess(transformed_row)
                        self.interface.send(transformed_row)
                        self.row_count += 1
                    except Exception as e:
                        self.error_count += 1
                        warnings.warn(f"Error processing row {self.row_count}: {str(e)}", stacklevel=2)
                    finally:
                        self._handle_missing_values(row)

            self.summary()
        except KeyboardInterrupt:
            print("Interrupted, saving state...")
            self.save_state()
            sys.exit(0)

    def _open_input(self):
        if self.input_file.endswith('.gz'):
            return gzip.open(self.input_file, 'rt')
        else:
            return open(self.input_file, 'rt')

    def _iterable_rows(self, reader):
        for row in reader:
            yield row

    def preprocess(self, row: Iterable[str]) -> Iterable[str]:
        # Implement your preprocessing logic here
        pass

    def postprocess(self, row: Iterable[str]) -> None:
        # Implement your postprocessing logic here
        pass

    def stopped(self) -> bool:
        return False  # Implement a mechanism to check if the processing should be interrupted.

    def save_state(self):
        with open('state.pickle', 'wb') as f:
            import pickle
            pickle.dump((self.row_count, self.missing_value_count, self.error_count, self.warning_count, self.processed_rows), f)

    def load_state(self):
        if not self._file_exists('state.pickle'):
            return
        with open('state.pickle', 'rb') as f:
            state = pickle.load(f)
            (self.row_count, self.missing_value_count, self.error_count, self.warning_count, self.processed_rows) = state

    def _file_exists(self, filename):
        try:
            open(filename, 'rb')
            return True
        except OSError as exception:
            if exception.errno != errno.ENOENT:
                raise
            return False

    def summary(self):
        print(f"Processed {self.row_count} rows")
        print(f"Missing values count: {self.missing_value_count}")
        print(f"Error count: {self.error_count}")
        print(f"Warning count: {self.warning_count}")
