#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/rc4.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    const EVP_CIPHER *cipher;
    int mode; // ECB, CBC, or CFB
} encryption_stage;

encryption_stage* create_encryption_stage(const EVP_CIPHER *cipher, int mode) {
    encryption_stage *new_stage = (encryption_stage *) malloc(sizeof(encryption_stage));
    new_stage->cipher = cipher;
    new_stage->mode = mode;
    return new_stage;
}

void destroy_encryption_stage(encryption_stage *stage) {
    free(stage);
}

const EVP_CIPHER* build_pipeline(encryption_stage **stages, int stage_count) {
    int i;
    const EVP_CIPHER *final_cipher = NULL;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    for (i = 0; i < stage_count; ++i) {
        // Handle edge cases: ensure stages are not NULL and stages with the same cipher have different modes.
        if (!stages[i] || final_cipher && stages[i]->cipher == final_cipher) {
            fprintf(stderr, "Invalid configuration.\n");
            return NULL;
        }

        // Initialize the current cipher context with the given stage settings.
        EVP_CIPHER_CTX_init(ctx);
        EVP_CIPHER_CTX_set_cipher(ctx, stages[i]->cipher);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_ encryption_MODE_EAX, 0, NULL); // Set default to EAX mode.
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_ encryption_MODE_OFB, stages[i]->mode, NULL); // Override with the specified mode.

        // Add the current cipher context to the final pipeline.
        if (!final_cipher) {
            final_cipher = ctx->cipher;
        } else {
            EVP_CIPHER *new_cipher = EVP_CIPHER_dup(ctx->cipher);
            final_cipher = EVP_EncryptUpdateInit(final_cipher, NULL, NULL, new_cipher);
        }
    }

    // Return the final configured cipher.
    return final_cipher;
}

int main() {
    // Example usage: Create a pipeline with AES-CBC, DES-ECB, and null encryption stages.
    encryption_stage *aes_cbc = create_encryption_stage(EVP_aes_128_cbc(), EVP_CIPHER_MODE_CBC);
    encryption_stage *des_ecb = create_encryption_stage(EVP_des_ecb(), EVP_CIPHER_MODE_ECB);
    encryption_stage *null = create_encryption_stage(NULL, 0); // Null encryption stage.

    const EVP_CIPHER *pipeline = build_pipeline(&aes_cbc, 3);

    // Clean up memory and return the final cipher for further usage.
    destroy_encryption_stage(aes_cbc);
    destroy_encryption_stage(des_ecb);
    destroy_encryption_stage(null);

    return 0;
}
```']

