import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.ConcurrentHashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantLock;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class PokemonRepository {
    private final Map<String, JsonObject> cache = new ConcurrentHashMap<>();
    private static final Gson gson = new Gson();
    private static final ReentrantLock lock = new ReentrantLock();
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/%s/";

    public JsonObject getPokemon(String pokemon) {
        String normalizedPokemon = normalizeType(pokemon);
        if (normalizedPokemon == null) {
            throw new IllegalArgumentException("Invalid Pokémon type: " + pokemon);
        }

        lock.lock();
        try {
            JsonObject cachedData = cache.get(normalizedPokemon);
            if (cachedData != null) {
                return cachedData;
            }

            URL url = new URL(String.format(API_URL, normalizedPokemon));
            BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream(), StandardCharsets.UTF_8));
            String response = reader.lines().collect(Collectors.joining("\n"));
            JsonObject pokeData = gson.fromJson(response, JsonObject.class);

            if (pokeData != null && pokeData.get("id") != null) {
                cache.put(normalizedPokemon, pokeData);
                return pokeData;
            }
        } finally {
            lock.unlock();
        }

        throw new RuntimeException("Failed to fetch Pokémon data for: " + normalizedPokemon);
    }

    private String normalizeType(String pokemon) {
        // Implement case-insensitive and abbreviation handling for the given Pokémon type.
    }
}
