typedef struct BlockCipher {
    const char* name;
    void* (*init)(int keySize, int blockSize);
    int keySize;
    int blockSize;
} BlockCipher;

struct Algorithm {
    const char* libName;
    std::vector<HashFunction> hashFunctions;
    std::vector<BlockCipher> blockCiphers;
};

std::unordered_map<std::string, Algorithm> supportedLibraries;
pthread_mutex_t mutex;

void* loadLibrary(const char* libName) {
    void* handle = dlopen(libName, RTLD_LAZY);
    if (!handle) {
        perror("dlopen");
        return nullptr;
    }
    return handle;
}

Algorithm getSupportedAlgorithms() {
    Algorithm algorithms;

    // Initialize supported libraries and their corresponding algorithms
    // ...

    // Load each library and retrieve hash functions and block ciphers
    pthread_mutex_lock(&mutex);
    for (const auto& lib : supportedLibraries) {
        void* handle = loadLibrary(lib.first.c_str());
        if (!handle) continue;

        // Load and verify the availability of each algorithm
        // ...

        algorithms.hashFunctions.insert(algorithm.hashFunctions.end(), lib.second.hashFunctions.begin(), lib.second.hashFunctions.end());
        algorithms.blockCiphers.insert(algorithms.blockCiphers.end(), lib.second.blockCiphers.begin(), lib.second.blockCiphers.end());
    }
    pthread_mutex_unlock(&mutex);

    return algorithms;
}

void freeAlgorithm(Algorithm* alg) {
    for (auto& func : alg->hashFunctions)
        if (func.init) free(func.init);
    for (auto& cipher : alg->blockCiphers)
        if (cipher.init) free(cipher.init);
}

void* getAlgorithmList() {
    Algorithm algorithms = getSupportedAlgorithms();
    void** results = malloc(algorithms.hashFunctions.size() + algorithms.blockCiphers.size());
    int index = 0;

    for (const auto& func : algorithms.hashFunctions) {
        results[index++] = &func;
    }

    for (const auto& cipher : algorithms.blockCiphers) {
        results[index++] = &cipher;
    }

    return results;
}
