        fprintf(stderr, "Usage: %s <config_file> <operation>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config* config = mmap(NULL, sizeof(Config), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    load_config(argv[1], &config);
    config->resource_sem = sem_init( Semaphore_NAME, 1, config->operation_mode == 0 ? 1 : config->performance_threshold / MAX_THREADS + 1);
    int operation = atoi(argv[2]);

    pthread_t* threads = malloc(MAX_THREADS * sizeof(pthread_t));
    for (int i = 0; i < MAX_THREADS; ++i) {
        Config thread_config = *config;
        thread_config.resource_sem = config->resource_sem;
        pthread_create(&threads[i], NULL, perform_operation, &thread_config);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(config->resource_sem);
    munmap(config, sizeof(Config));

    return EXIT_SUCCESS;
}
