#[derive(Serialize, Deserialize, Debug)]
struct Config {
    system_calls: Vec<SystemCall>,
    dependencies: Vec<Dependency>,
    external_sources: ExternalSources,
}

#[derive(Serialize, Deserialize, Debug)]
struct SystemCall {
    name: String,
    arguments: Vec<Argument>,
}

#[derive(Serialize, Deserialize, Debug)]
struct Dependency {
    path: String,
    optional: bool,
}

#[derive(Serialize, Deserialize, Debug)]
struct ExternalSources {
    api_url: String,
    db_connection_string: Option<String>,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
enum Argument {
    Value(String),
    Dependency(DependencyRef),
}

struct DependencyRef(Arc<Dependency>);

impl Config {
    async fn load_from_path(&self, temp_file: &mut NamedTempFile) -> Result<(), ConfigError> {
        let mut content = vec![];
        fs::read_to_end(Path::new(temp_file.path()), &mut content)?;
        let config_json: Value = serde_json::from_slice(&content)?;
        let config: Self = serde_json::from_value(config_json)?;
        self.validate(&config)?;
        Ok(())
    }

    fn validate(&self, config: &Config) -> Result<(), ConfigError> {
        if config.external_sources.db_connection_string.is_some() && config.system_calls.is_empty() {
            return Err(ConfigError::EmptySystemCallsWithDBConnection);
        }

        let mut system_call_count = 0;
        for call in &config.system_calls {
            system_call_count += call.arguments.len();
        }

        let arguments_total = config
            .system_calls
            .iter()
            .flat_map(|call| &call.arguments)
            .filter(|arg| matches!(arg, Argument::Dependency(_)))
            .count();

        if system_call_count != arguments_total {
            return Err(ConfigError::MismatchedSystemCallArguments);
        }

        let mut dependency_set: HashSet<String> = HashSet::new();
        for dep in &config.dependencies {
            if dependency_set.contains(&dep.path) {
                return Err(ConfigError::DuplicateDependency(dep.path));
            }
            dependency_set.insert(dep.path.clone());
        }

        if config.external_sources.api_url.is_empty() && !config.dependencies.is_empty() {
            return Err(ConfigError::MissingAPIURLWithDependencies);
        }

        let max_size = 1024 * 1024; // 1MB limit
        if config.to_string().len() > max_size {
            return Err(ConfigError::ConfigurationFileTooLarge);
        }

        Ok(())
    }
}

