#include <algorithm>
#include <iterator>
#include <set>
#include <vector>

void insertAfterAndClean(std::vector<std::string>& vec, const std::string& target, const std::string& insert, const std::string& dupToRemove) {
    if (target.empty()) return;

    std::set<std::string> unique_vec;
    for (const auto& str : vec) {
        if (str == dupToRemove) continue;
        unique_vec.insert(str);
    }

    vec.assign(unique_vec.begin(), unique_vec.end());
    auto it = std::find(vec.begin(), vec.end(), target);

    if (it != vec.end()) {
        auto afterIt = it;
        ++afterIt;
        vec.insert(afterIt, insert);
    } else {
        vec.push_back(insert);
    }
}
