using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;

public class QueryExecutor
{
    private readonly IMemoryCache _cache;
    private readonly string _connectionString;
    private readonly int _pageSize;

    public QueryExecutor(IMemoryCache cache, IConfiguration configuration, int pageSize = 50)
    {
        _cache = cache;
        _connectionString = configuration.GetConnectionString("DefaultConnection");
        _pageSize = pageSize;
    }

    public async Task<IDataReader> ExecuteQueryAsync(string schemaName, string queryTemplate, IDictionary<string, object> parameters)
    {
        var cacheKey = $"{schemaName}:{queryTemplate}";
        var cachedResult = _cache.Get(cacheKey);

        if (cachedResult != null)
        {
            return await Task.FromResult((IDataReader)cachedResult);
        }

        using (var connection = new System.Data.SqlClient.SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            var builder = new SqlCommandBuilder(new SqlCommand(queryTemplate, connection));
            var command = builder.GetInsertCommand() as SqlCommand;
            command.CommandType = CommandType.Text;

            foreach (var parameter in parameters)
            {
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
            }

            var nonClusteredIndexes = GetNonClusteredIndexColumns(command);

            // Apply sorting and filtering here based on queryTemplate and parameters
            // Implement pagination using OFFSET and LIMIT or TOP and SKIP depending on the database system
            command.Parameters["@Skip"] = (parameters["PageIndex"] ?? 0) * _pageSize;
            command.Parameters["@Take"] = _pageSize;

            var dataReader = await command.ExecuteReaderAsync();

            // Cache the result for future queries with the same schema, queryTemplate and parameters
            _cache.Set(cacheKey, dataReader);

            return dataReader;
        }
    }

    private IEnumerable<string> GetNonClusteredIndexColumns(SqlCommand command)
    {
        var indexColumns = new List<string>();

        foreach (var index in command.GetIndicesOfSpecifiedOrdinal(0)) // 0 represents the first column
        {
            var indexDef = command.SchemaInformation.TableSchema + "." + command.SchemaInformation.IndexName;
            indexColumns.AddRange(command.GetIndexColumnNames(index).Select(cn => cn.ColumnName));
        }

        return indexColumns;
    }
}
