using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Threading;
using System.Text;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace MyApplication
{
    public class ConfigLoader
    {
        private readonly IConfiguration _config;
        private readonly ILogger<ConfigLoader> _logger;

        public ConfigLoader(IConfiguration config, ILogger<ConfigLoader> logger)
        {
            _config = config;
            _logger = logger;
        }

        public void Initialize()
        {
            if (_config.GetValue<string>("XML_CONFIG_DIR") == null)
                SetEnvVariable();

            ValidateEnvironmentVariable();
        }

        private string GetExpectedElementValue(string elementName)
        {
            var configPath = _config["XML_CONFIG_DIR"];
            var xmlDoc = new XmlDocument();
            xmlDoc.Load(Path.Combine(configPath, "configuration.xml"));

            var elements = xmlDoc.DocumentElement.SelectNodes("/" + elementName);

            if (elements == null || elements.Count > 1)
                throw new Exception($"More than one '{elementName}' element found.");

            return elements[0].InnerText;
        }

        private void SetEnvVariable()
        {
            var expectedValue = GetExpectedElementValue("expectedDirectory");
            _logger.LogInformation($"Setting environment variable XML_CONFIG_DIR to {expectedValue}.");

            var currentDir = Directory.GetCurrentDirectory();
            var envVarDir = Path.Combine(currentDir, expectedValue);

            if (!Directory.Exists(envVarDir))
                Directory.CreateDirectory(envVarDir);

            Environment.SetEnvironmentVariable("XML_CONFIG_DIR", envVarDir);
        }

        private void ValidateEnvironmentVariable()
        {
            var currentDir = Directory.GetCurrentDirectory();
            var configPath = _config["XML_CONFIG_DIR"];

            if (currentDir != configPath)
                throw new Exception("Invalid XML_CONFIG_DIR environment variable.");
        }
    }
}
```
