import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.concurrent.*;
import javax.imageio.ImageIO;

public class FileLoader {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static ConcurrentHashMap<String, BufferedImage> themeBitmaps = new ConcurrentHashMap<>();
    private static AtomicBoolean defaultThemeDirInitialized = new AtomicBoolean(false);
    private static String defaultThemeDirectory;

    public static MoSTState loadStateWithTheme(String fileName) {
        File file = new File(getOrInitDefaultThemeDirectory(), fileName);

        if (!file.exists()) return null;

        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(new FileInputStream(file));
            Object object = ois.readObject();
            if (object instanceof MoSTState) {
                BufferedImage themeBitmap = themeBitmaps.getOrDefault(fileName, loadOrRecycleThemeBitmap(fileName));
                return new LoadedState(object, themeBitmap);
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            if (ois != null) try { ois.close(); } catch (IOException e) {}
        }

        return null;
    }

    private static String getOrInitDefaultThemeDirectory() {
        if (!defaultThemeDirInitialized.get()) {
            defaultThemeDirectory = Paths.get("").toAbsolutePath().toString() + File.separator + "defaultTheme";
            try {
                Files.createDirectories(Paths.get(defaultThemeDirectory));
                defaultThemeDirInitialized.set(true);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return defaultThemeDirectory;
    }

    private static BufferedImage loadOrRecycleThemeBitmap(String fileName) {
        BufferedImage bitmap = themeBitmaps.get(fileName);
        if (bitmap != null && !bitmap.isDisposed()) return bitmap;

        bitmap = ImageIO.read(FileLoader.class.getClassLoader().getResourceAsStream("default/" + fileName));
        themeBitmaps.putIfAbsent(fileName, bitmap);
        return bitmap;
    }
}

public class LoadedState {
    private final MoSTState stateObject;
    private final BufferedImage themeBitmap;

    public LoadedState(MoSTState stateObject, BufferedImage themeBitmap) {
        this.stateObject = stateObject;
        this.themeBitmap = themeBitmap;
    }

    // Getters for stateObject and themeBitmap
}
```

This code creates a FileLoader class that loads the state object from a file, optimizes resource usage by utilizing a caching mechanism for the theme bitmap, initializes a default theme directory if it's not already configured, and integrates with an external theme service for dynamic updates. All operations are wrapped in try-finally blocks to safely close resources and handle potential I/O errors. The loaded state object along with the updated theme bitmap and default theme directory status is returned as LoadedState instance.']

