const fs = require('fs-extra');
const path = require('path');
const util = require('util');
const { promisify } = require('util');
const logger = /* your logging system instance */; // Logging system implementation not provided, replace with the appropriate object or function.

const readFileWithExtensions = async (directory, extensions, dataSource) => {
  const lstat = promisify(fs.lstat);
  const readdir = promisify(fs.readdir);
  let fileCount = 0;
  let successfulReads = 0;
  let totalSize = 0;

  try {
    const files = await readdir(directory);

    for (const file of files) {
      filePath = path.join(directory, file);
      if (!dataSource.isValidFile(file)) continue;

      const stats = await lstat(filePath);
      totalSize += stats.size;
      fileCount++;

      try {
        const content = await fs.readFile(filePath, 'utf8');

        if (extensions.some(ext => file.endsWith(`.${ext}`))) {
          successfulReads++;
          const metadata = dataSource.getMetadata(filePath); // Assuming a method `getMetadata` is available on your data source object
          logger.info(`Successfully read file: ${file} - Size: ${stats.size}, Last Modified: ${metadata.lastModified}`);
        }
      } catch (error) {
        logger.error(`Failed to read file: ${file}: ${error.message}`);
      }
    }
  } catch (error) {
    logger.error(`Error reading directory: ${directory}: ${error.message}`);
  }

  logger.info(`Total files: ${fileCount}, Successful reads: ${successfulReads}, Total size: ${totalSize}`);
};
```

