const events = require('events');
const logService = require('log-service'); // External logging service wrapper
const Promise = require('bluebird');
const _ = require('lodash');
const blueslip = require('blueslip');

class TestRunner extends events.EventEmitter {
  constructor(options) {
    super();
    this.moduleName = options.moduleName;
    this.testSuite = options.testSuite;
    this.maxConcurrent = options.maxConcurrent || 1;
    this.resetFrequency = options.resetFrequency || 5; // Number of tests to run between resets
    this.resourceMonitor = options.resourceMonitor;
  }

  async start() {
    try {
      const module = require(this.moduleName);
      this.emit('log', `Starting test suite for ${this.moduleName}`);

      let concurrentTests = _.take(this.testSuite, this.maxConcurrent);
      while (concurrentTests.length) {
        const test = concurrentTests.shift();
        const resetBeforeTest = test.resetBeforeEach || false;

        if (resetBeforeTest && blueslip.isResetNeeded()) {
          await blueslip.reset();
        }

        this.emit('log', `Running test ${test.name}`);
        const startTime = Date.now();
        const testPromise = Promise.coroutine(function*() {
          try {
            yield test.fn(); // Test function with potentially asynchronous operations
          } catch (err) {
            this.emit('log', `Test ${test.name} failed: ${err.message}`);
            const report = generateReport(err);
            logService.sendReport(report);
          }
        }).call({});

        testPromise.then(() => {
          this.emit('log', `Test ${test.name} completed in ${Date.now() - startTime}ms`);
          if (resetBeforeTest) blueslip.reset(); // Reset after the test completes if required
          concurrentTests = _.union(concurrentTests, _.difference(this.testSuite, _.compact(concurrentTests)));
        }).catch((err) => {
          this.emit('log', `Encountered an error during test execution: ${err.message}`);
          logService.sendReport({error: err});
        });
      }

      if (this.resourceMonitor) {
        await this.resourceMonitor.checkResourceContention(); // Check for resource contention before running more tests
        if (!this.resourceMonitor.canRunTests()) {
          this.emit('log', 'Resource contention detected, switching to sequential test execution');
          this.maxConcurrent = 1;
        }
      }
    } catch (err) {
      this.emit('log', `Error while loading module: ${err.message}`);
      logService.sendReport({error: err});
    }
  }
}

function generateReport(err) {
  // Generate detailed error report with stack trace and other relevant information
}
