["```javascript
import axios from 'axios';

class DialogFieldUpdater {
  constructor(dialog, fieldNames) {
    this.dialog = dialog;
    this.fieldNames = new Map(fieldNames.map((name) => [name, new Set()]));
  }

  async updateFields(resourceId) {
    try {
      const response = await axios.get(`/api/data/${resourceId}`);
      if (response.status === 200) {
        response.data.forEach((item) => {
          this.fieldNames.forEach((fields, fieldName) => {
            fields.has(item.name) && fields.add(item);
          });
        });
        this.dialog.scope().apply();
      }
    } catch (error) {
      // Provide clear and informative feedback to the user in case of errors or failures
      console.error(`Error fetching data: ${error.message}`);
    }
  }

  async refreshField(fieldName, callback) {
    try {
      const response = await axios.get(`/api/data/${this.dialog.scope().$parent.$ctrl.resourceId}/${fieldName}`);
      if (response.status === 200 && this.fieldNames.has(fieldName)) {
        const fieldSet = this.fieldNames.get(fieldName);
        fieldSet.clear();
        fieldSet.add(response.data);
        callback(response.data);
        this.dialog.scope().apply();
      }
    } catch (error) {
      console.error(`Error fetching data for ${fieldName}: ${error.message}`);
    }
  }
}
```
