```kotlin
private fun parseThemeFiles(context: Context, directory: File): List<ThemeBitmap> {
    return directory.walk()
        .filter { it.isFile && it.extension == "png" }
        .map { Path(it) }
        .parallelStream()
        .map { path ->
            val options = BitmapFactory.Options().apply { inPreferredConfig = Bitmap.Config.ARGB_8888 }
            BitmapFactory.decodeFile(path.toString(), options)
            val metadata = ImageDecoder.createSource(context, FileInputStream(path)).metadata
            ThemeBitmap(options.outBitmap).also { bitmap ->
                bitmap.resolution = options.outWidth.toLong() * options.outHeight.toLong()
                bitmap.orientation = metadata.rotationDegrees
            }
        }
        .toList()
}
