    unsafe { setrlimit(RLIMIT_RSS, &rlim64::from_parts(0, RLIMIT_RSS::RLIM64_INFINITY)) };

    let project_path = env::args().nth(1).unwrap();
    let object_file = format!("{project_path}.out");
    let output_file = format!("{project_path}.log");

    let mut config = Configuration::new();
    config.set_driver_name("custom_rustc");
    config.set_object_file(Some(&object_file));
    config.output_kind = OutputKind::Binary;

    let session = Session::new(config);
    let driver = DriverBuilder::new()
        .execution_mode(ExecutionMode::default())
        .session(session)
        .build();

    let start_time = Instant::now();
    let rss_before = getrusage().rss;

    if let Ok(mut cmd) = driver.driver(&[project_path], &[], &mut stdout_hook, None) {
        cmd.stderr(stdout_hook);
        cmd.env_clear();
        cmd.spawn().unwrap();
    } else {
        log("Compilation error:", Error::description());
        return;
    }

    wait_for_completion(&cmd, LOG_THRESHOLD);

    let rss_after = getrusage().rss;
    let elapsed = start_time.elapsed();
    log(format!("Elapsed time: {}s", elapsed.as_secs()), "");
    log(format!("Resident set size before compilation: {}", rss_before), "");
    log(format!("Resident set size after compilation: {}", rss_after), "");
}

fn stdout_hook<W: Write>(data: &[u8], _kind: OutputKind) -> Result<(), Error> {
    let mut writer = BufWriter::new(FromRawFd::from(1));
    writer.write_all(data)?;
    Ok(())
}

fn getrusage() -> libc::rusage {
    let mut rusage = libc::rusage { ..Default::default() };
    unsafe { getrusage(RLIMIT_RSS, &mut rusage) };
    rusage
}

fn wait_for_completion(cmd: &Command, log_threshold: usize) {
    let mut elapsed = Instant::now();
    loop {
        if cmd.try_wait().is_ok() {
            return;
        }

        std::thread::sleep(std::time::Duration::from_secs(1));
        if elapsed.elapsed().as_secs() > 60 * log_threshold {
            log("Compilation stuck, force killing...", "");
            cmd.kill().unwrap();
        }
        elapsed = Instant::now();
    }
}

fn log(message: String, additional: String) {
    let file = OpenOptions::new()
        .write(true)
        .create_always(true)
        .open(&output_file)
        .unwrap();
    writeln!(file, "{} - {}", message, additional).unwrap();
}
