    public function __construct($config) {
        $this->limit = intval($config['attempts']);
        $this->interval = intval($config['interval']);
    }

    public function allow() {
        if ($this->failedAttempts < $this->limit) {
            $this->reset();
            return true;
        }

        sleep($this->interval);
        return false;
    }

    public function incrementFailedAttempt() {
        ++$this->failedAttempts;
    }

    public function reset() {
        $this->failedAttempts = 0;
    }
}

