class CustomLogEntry:
    def __init__(self, timestamp: str, sequence_number: int, log_entry: str):
        self.timestamp = timestamp
        self.sequence_number = sequence_number
        self.log_entry = log_entry

    def __lt__(self, other: 'CustomLogEntry'):
        return self.timestamp < other.timestamp

class LogProcessor:
    def __init__(self, log_queue: queue.Queue, external_service):
        self.log_queue = log_queue
        self.external_service = external_service
        self.timestamp_pattern = re.compile(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}.\d{3}')

    def parse_log(self, log_entry: str) -> Union[CustomLogEntry, None]:
        match = self.timestamp_pattern.match(log_entry)
        if not match:
            return None
        timestamp = match.group()
        try:
            sequence_number = int(re.search(r'\d+', log_entry).group())
        except AttributeError:
            return None
        return CustomLogEntry(timestamp, sequence_number, log_entry)

    def process_log_entries(self):
        sorted_logs = []
        while True:
            log_entry = self.log_queue.get()
            if log_entry is None or not isinstance(log_entry, CustomLogEntry):
                continue
            sorted_logs.append(log_entry)
            sorted_logs.sort()
            for entry in sorted_logs:
                self.external_service.send_log(entry)

class ExternalLogService:
    def send_log(self, log: CustomLogEntry):
        # Implement your external service here
        print(f"Sent log: {log.timestamp}, {log.sequence_number}, {log.log_entry}")

def main():
    executor = ThreadPoolExecutor()
    log_queue = queue.Queue()
    external_service = ExternalLogService()
    log_processor = LogProcessor(log_queue, external_service)

    def receive_logs(channel):
        for log in channel:
            if isinstance(log, CustomLogEntry):
                log_queue.put(log)
            elif log is None:
                continue
            else:
                logging.error("Received invalid log entry", extra={"invalid_entry": log})

    executor.submit(receive_logs, stream_channel) # Replace 'stream_channel' with your actual log stream
    log_processor.process_log_entries()

if __name__ == "__main__":
    main()
