    }
    boost::property_tree::read_xml(configFile, m_settings);
}

ConfigManager::~ConfigManager() {}

template<typename T>
T ConfigManager::getSetting(const std::string& key, bool throwOnMissing) {
    std::lock_guard<std::mutex> lock(m_mutex);
    auto it = m_settings.get<T>(key, T{});
    if (it == T{}) {
        if (throwOnMissing) {
            throw std::runtime_error("Setting '" + key + "' not found.");
        } else {
            return T{};
        }
    }
    return it;
}

