use std::env;
use std::fs::File;
use std::io::{BufWriter, Write};
use std::sync::Arc;
use std::time::Instant;

use log::*;
use reqwest::Client;
use serde_json::Value;
use tokio::task::spawn;
use tokio::runtime::{self, RuntimeExecutor};

type Fn = Box<dyn FnOnce() + Send + Sync>;

struct Worker {
    func: Arc<Fn>,
}

impl Worker {
    async fn run(&self) {
        (self.func)();
    }
}

fn register_function(name: &str, func: Fn) {
    let arc_func = Arc::new(func);
    WORKERS.lock().unwrap().insert(name.to_string(), Arc::downgrade(&arc_func));
}

const MAX_LOGGING_INTERVAL: u64 = 1000; // in milliseconds
const LOG_FILE: &str = "operation_logs.txt";
static mut LOGGER: Option<BufWriter<File>> = None;
static mut LAST_LOG_TIME: Option<Instant> = None;
static WORKERS: std::sync::Mutex<std::collections::HashMap<String, Arc<Fn>>> = std::sync::Mutex::new(std::collections::HashMap::new());

fn log(format: &str, args: &[&'static str], level: &'static str) {
    if let Some(ref mut logger) = unsafe { &mut *LOGGER } {
        if let Some(last_log_time) = unsafe { &*LAST_LOG_TIME } {
            let elapsed = Instant::now().duration_since(*last_log_time);
            if elapsed.as_millis() > MAX_LOGGING_INTERVAL {
                *LAST_LOG_TIME = Some(Instant::now());
                write_to_log(logger, format, args).unwrap();
            }
        } else {
            unsafe { *LAST_LOG_TIME = Some(Instant::now()) };
            write_to_log(logger, format, args).unwrap();
        }
    }
    if let Ok(level_from_str) = level.parse::<LevelFilter>() {
        match level_from_str {
            LevelFilter::Trace => trace!(target: "app", **args),
            LevelFilter::Debug => debug!(target: "app", **args),
            LevelFilter::Info => info!(target: "app", **args),
            LevelFilter::Warn => warn!(target: "app", **args),
            LevelFilter::Error => error!(target: "app", **args),
        }
    }
}

fn write_to_log(logger: &mut BufWriter<File>, format: &str, args: &[&'static str]) -> std::io::Result<()> {
    let mut out = logger.buf();
    snprintf!(&mut out, format, args)
}

async fn fetch_data(url: &str) -> Result<Value, reqwest::Error> {
    let client = Client::new();
    let response = client.get(url).send().await?;
    response.json::<Value>().await
}

fn main() {
    env_logger::init();
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <function_name>", args[0]);
        return;
    }

    let function_name = &args[1];
    if !WORKERS.lock().unwrap().contains_key(function_name) {
        eprintln!("No registered function named '{}'", function_name);
        return;
    }

    let worker = Worker { func: Arc::downgrade(*WORKERS.lock().unwrap().get(function_name).unwrap()) };
    spawn(async move {
        let mut runtime = runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("Failed to build the runtime.");
        runtime.block_on(worker.run());
    });
}
```

