void generate_unique_values(Record *records, size_t N, int minValue, int maxValue) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    RAND_seed((unsigned long)time(NULL));
    for (size_t i = 0; i < N; ++i) {
        int value;
        do {
            value = RAND_int(minValue, maxValue + 1);
        } while (findInArray(records, value));
        pthread_mutex_lock(&mutex);
        records[i].value = value;
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);
}

int findInArray(Record *array, int value) {
    for (size_t i = 0; i < array_len(array); ++i) {
        if (array[i].value == value) return 1;
    }
    return 0;
}

size_t array_len(void* array) {
    size_t len = 0;
    char *arr = (char*)array;
    while (*arr++) len++;
    return len / sizeof(Record);
}

void free_all(int *offsets, int *keys, Record *records) {
    free(offsets); offsets = NULL;
    free(keys); keys = NULL;
    free(records); records = NULL;
}

