#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <stdatomic.h>
#include <hash_map.h> // A thread-safe hash map implementation (e.g., Boost.Unordered)

typedef struct {
    float value;
    time_t timestamp;
    bool error;
} element;

struct cache {
    atomic_uint max_entries;
    void* doubles; // double precision floating-point numbers
    void* ids; // unique identifiers (unsigned long)
    void* elements; // struct element pointers
    hash_map_t* map; // thread-safe hash map for cache lookup
    pthread_mutex_t mutex;
};

cache* create_cache(size_t max_entries) {
    cache *c = malloc(sizeof(cache));
    c->max_entries = max_entries;
    c->doubles = mmap(NULL, max_entries * sizeof(double), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    c->ids = mmap(NULL, max_entries * sizeof(unsigned long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    c->elements = mmap(NULL, max_entries * sizeof(element*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    c->map = hash_map_create();
    pthread_mutex_init(&c->mutex, NULL);
    return c;
}

void* get_or_create(cache *c, unsigned long id) {
    element *e;
    if (hash_map_get(c->map, &id, (void**)&e))
        return e;

    pthread_mutex_lock(&c->mutex);
    size_t index = hash_map_size(c->map) % c->max_entries;
    if (!hash_map_contains_key(c->map, &index)) {
        element *elem = (element*)((char*)c->elements + index * sizeof(element*));
        elem->value = rand() / RAND_MAX * 100.0;
        elem->timestamp = time(NULL);
        elem->error = false;
        hash_map_put(c->map, &index, elem);
    }
    e = (element*)((char*)c->elements + index * sizeof(element*));
    pthread_mutex_unlock(&c->mutex);

    return e;
}

void update_element(cache *c, unsigned long id, float value) {
    element *e = get_or_create(c, id);
    e->value = value;
}

void destroy_cache(cache *c) {
    munmap((char*)c->doubles, c->max_entries * sizeof(double));
    munmap((char*)c->ids, c->max_entries * sizeof(unsigned long));
    munmap((char*)c->elements, c->max_entries * sizeof(element*));
    hash_map_destroy(c->map);
    pthread_mutex_destroy(&c->mutex);
    free(c);
}
```

