// Memory allocation function for records
Record* allocate_record() {
    if (record_capacity <= record_index) {
        void *new_pool = realloc(record_pool, record_capacity + BLOCK_SIZE);
        if (!new_pool) return NULL;
        record_pool = new_pool;
    }
    Record* rec = (Record*)((char*)record_pool + record_index * sizeof(Record));
    record_index++;
    return rec;
}

// Custom logging function with configurable level and output format
void custom_log(int level, const char* fmt, ...) {
    // Handle logging based on the level and output format settings
}

// Function to manage memory allocation and initialization for an array of records
Record* init_records(size_t size) {
    if (!record_pool) record_pool = malloc(BLOCK_SIZE);
    record_capacity = BLOCK_SIZE;
    record_index = 0;

    Record* records = calloc(size, sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < size; i++) {
        records[i] = *allocate_record();
        records[i].value = get_random_unique_value();
    }
    return records;
}

// Get a unique random integer value within a specified range
int get_random_unique_value() {
    static int last_value = INT_MIN;
    int value = rand() % MAX_VALUE;

    while (last_value == value) value = rand() % MAX_VALUE;
    last_value = value;
    return value;
}
