main.c:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "dns_resolver.h"
#include "union_find.h"
#include "log.h"

struct hostname {
    char *hostname;
    double ip[2]; // last two numerical fields
};

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    UF_t *uf = uf_init(); // Initialize Union-Find data structure

    struct hostname *hostnames = NULL;
    size_t capacity = 0, count = 0;

    clock_t start_dns, end_dns, start_file, end_file;

    double total_ip[2] = {0.0, 0.0};

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        if (!capacity || count == capacity) {
            capacity *= 2;
            hostnames = realloc(hostnames, capacity * sizeof(struct hostname));
        }

        struct hostname *current = &hostnames[count];
        current->hostname = strdup(line);

        start_dns = clock();
        char ip_str[INET6_ADDRSTRLEN] = {0};
        int err = dns_resolve(current->hostname, ip_str);
        end_dns = clock();

        if (err) {
            fprintf(stderr, "Error resolving DNS for %s: %s\n", current->hostname, strerror(err));
            continue;
        }

        sscanf(ip_str, "%lf.%lf", &(current->ip[0]), &(current->ip[1]));

        uf_union(uf, count); // Add hostname to the connected component

        total_ip[0] += current->ip[0];
        total_ip[1] += current->ip[1];
        count++;
    }

    start_file = clock();
    fclose(file);

    if (count > 0) {
        double avg = (total_ip[0] / count + total_ip[1] / count) / 2.0;
        printf("Average of the last two numerical fields: %.6f\n", avg);
    } else {
        fprintf(stderr, "No valid data found in the file\n");
    }

    end_file = clock();

    log_time("DNS resolution", start_dns, end_dns);
    log_time("File processing", start_file, end_file);

    for (size_t i = 0; i < count; i++) {
        free(hostnames[i].hostname);
    }
    free(hostnames);

    uf_destroy(uf);

    return 0;
}
```

In this code, the main function reads a filename from the command line and opens the file. It then initializes the Union-Find data structure and dynamically allocates memory for hostnames. The function processes each line in the file by resolving its DNS, calculating the average of the last two numerical fields, and updating the connected component in the Union-Find data structure. Finally, it logs the time taken for DNS resolution and file processing and frees allocated resources before exiting.']

