#include <chrono>

namespace asio = boost::asio;

class InterfaceTable {
public:
    virtual BoostOptional<std::string> FindVmUuidFromMetadataIp(const std::string& ip) const {
        // Mock implementation for testing purposes
        static std::map<std::string, std::string> mock_data = {{"192.168.1.1", "uuid-0001"}, {"192.168.1.2", "uuid-0002"}};
        auto it = mock_data.find(ip);
        return it != mock_data.end() ? it->second : BoostOptional<std::string>();
    }
};

class SandeshClient {
private:
    asio::io_service io_service;
    asio::ip::tcp::socket socket;
    InterfaceTable interfaceTable;
    std::vector<int> numbers;
    int numRequests = 0, activeSessions = 0;
    std::mutex mtx;

    void SendRequest(const std::string& url) {
        try {
            asio::ip::tcp::resolver resolver(io_service);
            auto endpoint = *resolver.resolve({"api.example.com", 80});
            socket.async_connect(endpoint, [this, url](boost::system::error_code ec) {
                if (!ec) {
                    ++activeSessions;
                    std::string request = "GET /path?numbers=" + std::accumulate(
                        numbers.begin(), numbers.end(), std::string{}, [](const auto& a, const auto& b) { return a + "," + std::to_string(b); }) + "\n";
                    boost::system::error_code ec;
                    socket.write_some(asio::buffer(request), ec);
                    if (!ec) {
                        ++numRequests;
                        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate network latency
                        socket.close(ec);
                    }
                } else {
                    LogError("Failed to connect: " + ec.message());
                }
                --activeSessions;
            });
        } catch (const std::exception& e) {
            LogError("Exception while sending request: " + e.what());
        }
    }

public:
    void Run(InterfaceTable& interfaceTable, int port) {
        for (;;) {
            int num;
            if (!std::cin >> num) {
                LogError("Invalid input");
                exit(1);
            }

            numbers.push_back(num);
            if (numbers.size() >= 10000) {
                auto largest = *std::max_element(numbers.begin(), numbers.end());
                LogInfo("Largest number: " + std::to_string(largest));

                for (auto& n : numbers) {
                    SendRequest(interfaceTable.FindVmUuidFromMetadataIp(std::to_string(n)).value_or(""));
                }

                numbers.clear();
            }
        }
    }

    void LogInfo(const std::string& msg) {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << "[INFO] " << msg << '\n';
    }

    void LogError(const std::string& msg) {
        std::lock_guard<std::mutex> lock(mtx);
        std::cerr << "[ERROR] " << msg << '\n';
    }
};

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: SandeshClient <InterfaceTable implementation>\n";
        return 1;
    }

    InterfaceTable interfaceTable;
    SandeshClient client(interfaceTable);

    try {
        client.Run(reinterpret_cast<void*>(const_cast<char*>(argv[1])), 8080);
    } catch (const std::exception& e) {
        client.LogError("Exception: " + e.what());
    }

    return 0;
}
```']

[' Here is a basic implementation of a thread-safe MD5 hash utility class in Java using `java.security.MessageDigest` for hashing and `ConcurrentHashMap` for caching. The cache uses `SoftReference` to automatically clear expired entries when memory becomes low. Additionally, I've added a mechanism to reset the cache when needed.

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentModificationException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.weakref.SoftReference;

public final class MD5Util {
    private static final int CACHE_EXPIRY_SECS = 60; // Cache expires after 1 minute
    private static final ConcurrentHashMap<String, SoftReference<byte[]>> cache = new ConcurrentHashMap<>();
    private static MessageDigest md;

    static {
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static byte[] hash(String input) {
        String key = input + System.nanoTime(); // Ensure cache keys are unique per execution
        SoftReference<byte[]> cacheEntry = cache.get(key);
        if (cacheEntry != null && !cacheEntry.getSoftValue().equals(null)) {
            return cacheEntry.get(); // Return cached hash
        }

        byte[] bytes = md.digest(input.getBytes(StandardCharsets.UTF_8));
        SoftReference<byte[]> newCacheEntry = new SoftReference<>(bytes);
        cache.putIfAbsent(key, newCacheEntry); // Put new entry if it doesn't exist yet

        return bytes;
    }

    public static void reset() {
        try {
            cache.clear();
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Periodically clear expired cache entries
     */
    private static final Thread cleanerThread = new Thread(() -> {
        while (true) {
            try {
                TimeUnit.SECONDS.sleep(CACHE_EXPIRY_SECS);
                cache.values().removeIf(entry -> entry.get() == null); // Remove expired entries
            } catch (InterruptedException e) {
                // Ignore and continue looping
            }
        }
    });

    static {
        cleanerThread.setDaemon(true);
        cleanerThread.start();
    }
}
```

This utility class ensures efficient resource utilization by reusing the same instance of `MessageDigest` and caching computed hashes. Concurrent requests are handled using a thread-safe cache, and memory usage is managed with weak references. The cleaner thread periodically removes expired entries from the cache to maintain optimal memory usage.

To integrate this class into an existing application architecture, developers can simply import it in the required modules and use its `hash()` method for computing MD5 hashes of input strings.']

