#define MAX_RTNIS 10000 // Configurable threshold for unique RNTIs

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    Node *head, *tail;
    sem_t lock;
    size_t size;
};

void log_warning(const char* msg) {
    // Implement your logging function here.
}

sem_t mutex;

void init_mutex() {
    sem_init(&mutex, 0, 1);
}

void destroy_mutex() {
    sem_destroy(&mutex);
}

struct list* create_list() {
    struct list *list = (struct list *)malloc(sizeof(struct list));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    sem_init(&(list->lock), 0, 1);
    init_mutex();
    return list;
}

void destroy_list(struct list* list) {
    Node *curr = list->head;
    while (curr != NULL) {
        Node *temp = curr;
        curr = curr->next;
        free(temp);
    }
    free(list);
    destroy_mutex();
}

void enqueue(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&(list->lock));

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        sem_post(&(list->lock));
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    // Check for duplicate RNTIs and ensure thread safety.
    pthread_mutex_lock(&mutex);
    Node *curr = list->head;
    while (curr != NULL) {
        if (curr->data.rnti == new_node->data.rnti) {
            free(new_node);
            sem_post(&(list->lock));
            pthread_mutex_unlock(&mutex);
            log_warning("Duplicate RNTI detected.");
            return;
        }
        curr = curr->next;
    }
    pthread_mutex_unlock(&mutex);

    // Add the new node to the list.
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++(list->size);

    sem_post(&(list->lock));
}

NFAPI_CRC_INDICATION_PDU_T dequeue(struct list* list) {
    if (sem_trywait(&(list->lock)) != 0) {
        return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return an empty structure on lock failure.
    }

    Node *temp = list->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    list->head = temp->next;
    free(temp);
    --(list->size);
    sem_post(&(list->lock));

    return data;
}
