// Custom memory pool using an STL unordered_map to store allocated blocks.
class MemoryPool {
private:
    std::mutex mtx;
    std::unordered_map<void*, bool> pool;
public:
    void* allocate(size_t size) {
        void* memory = std::malloc(size);
        if (memory == nullptr) {
            throw std::bad_alloc();
        }
        pool[memory] = true;
        return memory;
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mtx);
        if (pool.find(ptr) != pool.end()) {
            pool[ptr] = false;
        } else {
            std::cerr << "Trying to deallocate invalid memory block" << std::endl;
        }
        std::free(ptr);
    }
};

// Custom data_point structure
struct DataPoint {
    double value;
    char key;
    DataPoint() {}
    DataPoint(double v, char k) : value(v), key(k) {}
};

// Function to initialize the dataset
void initDataset(size_t N, double minValue, double maxValue, MemoryPool& memPool, std::logger& logger) {
    // Ensure minValue < maxValue
    if (minValue >= maxValue) {
        throw std::invalid_argument("Min value must be strictly less than Max value.");
    }

    // Generate unique characters and store them in a vector
    std::vector<char> keys;
    for (size_t i = 'a'; i <= 'z' && i + N <= 'z'; ++i) {
        keys.push_back(static_cast<char>(i));
    }

    // Ensure the number of generated characters is equal to N
    if (keys.size() != N) {
        throw std::runtime_error("Not enough unique characters were generated.");
    }

    // Allocate memory for data_points using custom MemoryPool and store them in a vector
    auto dpVec = std::vector<DataPoint, allocator<DataPoint>>((N), memPool.allocate(sizeof(DataPoint)));
    std::vector<DataPoint*> dataPoints(dpVec.data(), dpVec.data() + N);

    // Randomly fill the double values for each DataPoint and store them in the vector
    std::default_random_engine generator;
    std::uniform_real_distribution<> distribution(minValue, maxValue);

    logger << "Generating random values within [" << minValue << ", " << maxValue << "]" << std::endl;
    for (DataPoint* dp : dataPoints) {
        double value = distribution(generator);
        // Ensure the generated value is unique across the dataset
        bool unique = true;
        for (auto other : dataPoints) {
            if (other != dp && fabs(value - other->value) < 1e-9) {
                unique = false;
                break;
            }
        }
        if (!unique) {
            // If a unique value can't be found, retry with another value
            while (!unique) {
                value = distribution(generator);
                unique = true;
                for (auto other : dataPoints) {
                    if (other != dp && fabs(value - other->value) < 1e-9) {
                        unique = false;
                        break;
                    }
                }
            }
        }
        dp->value = value;
        dp->key = keys[dp - dataPoints.data()];
    }

    // Log the resulting dataset
    logger << "Generated dataset with N=" << N << ", MinValue=" << minValue << ", MaxValue=" << maxValue << std::endl;
}
