#include <hash_map.h>  // Custom hash table implementation for unique value tracking

// Slab allocator structure definition
typedef struct slab {
    void *slab_start;
    size_t slab_size;
    size_t index;
} slab_t;

// Function to find the next power of 2 greater than n
uint32_t next_power_of_two(uint32_t n) {
    uint32_t pow = 1;
    while (pow < n) pow <<= 1;
    return pow;
}

// Slab allocator functions
slab_t *create_slab(size_t size, size_t num_slabs);
void *slab_alloc(slab_t *slab);
void slab_free(slab_t *slab, void *ptr);

// Custom memory pool
typedef struct mem_pool {
    slab_t *slabs;
    size_t num_slabs;
} mem_pool_t;

mem_pool_t *create_memory_pool(size_t size) {
    uint32_t num_slabs = next_power_of_two((size + sizeof(slab_t)) / sizeof(void*));
    slab_t *slabs = malloc(num_slabs * sizeof(slab_t));
    if (!slabs) return NULL;

    for (size_t i = 0; i < num_slabs; ++i) {
        slabs[i].slab_start = malloc((next_power_of_two(size)) * sizeof(void*));
        if (!slabs[i].slab_start) break;
        slabs[i].slab_size = next_power_of_two(size);
        slabs[i].index = 0;
    }

    mem_pool_t *pool = malloc(sizeof(mem_pool_t));
    if (!pool) {
        free_memory_pool(slabs, num_slabs);
        return NULL;
    }

    pool->slabs = slabs;
    pool->num_slabs = num_slabs;
    return pool;
}

void *allocate_from_memory_pool(mem_pool_t *pool, size_t size) {
    for (size_t i = 0; i < pool->num_slabs; ++i) {
        if (pool->slabs[i].index + size <= pool->slabs[i].slab_size) {
            void *ptr = pool->slabs[i].slab_start + pool->slabs[i].index;
            pool->slabs[i].index += size;
            return ptr;
        }
    }
    return NULL;
}

void free_memory_pool(slab_t *slabs, size_t num_slabs) {
