// Custom hash table implementation for unique value tracking
typedef struct hash_map {
    int num_buckets;
    uint32_t *keys;
    void **values;
    pthread_mutex_t lock;
} hash_map_t;

hash_map_t *create_hash_map(size_t num_buckets) {
    hash_map_t *table = malloc(sizeof(hash_map_t));
    if (!table) return NULL;

    table->num_buckets = next_power_of_two(num_buckets);
    table->keys = calloc(table->num_buckets, sizeof(uint32_t));
    table->values = calloc(table->num_buckets, sizeof(void*));
    table->lock = PTHREAD_MUTEX_INITIALIZER;

    return table;
}

bool insert_hash_map(hash_map_t *table, uint32_t key, void *value) {
    if (key < 0 || key >= table->num_buckets) return false;

    pthread_mutex_lock(&table->lock);
    for (uint32_t i = table->keys[key] % table->num_buckets; ; ++i) {
        if (!table->keys[i]) {
            table->keys[i] = key;
            table->values[i] = value;
            pthread_mutex_unlock(&table->lock);
            return true;
        }
        if (table->keys[i] == key) {
            pthread_mutex_unlock(&table->lock);
            return false;
        }
    }
}

void *get_hash_map(hash_map_t *table, uint32_t key) {
    if (key < 0 || key >= table->num_buckets) return NULL;

    pthread_mutex_lock(&table->lock);
    for (uint32_t i = table->keys[key] % table->num_buckets; ; ++i) {
        if (!table->keys[i]) continue;
        if (table->keys[i] == key) {
            void *value = table->values[i];
            pthread_mutex_unlock(&table->lock);
            return value;
        }
    }
}

// Example usage:
mem_pool_t *memory_pool = create_memory_pool(sizeof(int));
hash_map_t *unique_values = create_hash_map(1024);

