        // Check for uniqueness and store in the hash map
        int value = *(int*)ptr;
        void *existing = get_hash_map(unique_values, value);
        if (!existing) {
            insert_hash_map(unique_values, value, ptr);
        } else {
            free(ptr);
        }
    }
}

