            if (!idPtr) throw std::runtime_error("Failed to allocate memory for all record IDs.");
            futures[i] = std::async(std::launch::async, &generateID, 16);
            records[i].userID.reset(idPtr);
        }

        for (auto &future : futures) {
            auto id = future.get();
            for (size_t i = 0; i < records.size(); ++i) {
                if (!std::strcmp(id, records[i].userID.get())) {
                    records[i].value = 0.0;
                    break;
                }
            }
        }
    }

    ~Allocator() {
        for (auto &record : records) {
            delete[] record.userID.release();
        }
        pthread_mutex_destroy(&mutex);
