#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Custom memory pool
typedef struct MemBlock {
    void *data;
    size_t size;
    struct MemBlock *next;
} MemBlock;

MemBlock *memPool = NULL;

void initMemoryPool(size_t blockSize) {
    MemBlock *current, *newBlock;
    newBlock = (MemBlock*) malloc(sizeof(MemBlock));
    if (!newBlock) return;

    newBlock->size = blockSize;
    newBlock->next = NULL;
    memPool = newBlock;

    current = memPool;
    while ((current->next = (MemBlock*) malloc(sizeof(MemBlock))) != NULL) {
        current = current->next;
        current->size = blockSize;
        current->next = NULL;
    }
}

void* allocate(size_t size) {
    MemBlock *current = memPool;
    while (current != NULL) {
        if (current->size >= size) {
            void *data = (char*)current + (current->size - size);
            current->size -= size;
            return data;
        }
        current = current->next;
    }

    // Allocation failed, fall back to malloc
    return malloc(size);
}

void deallocate(void *ptr) {
    MemBlock *current = memPool;
    while (current != NULL) {
        if ((char*)current + current->size == ptr) {
            free(current->next);
            current->next = NULL;
            return;
        }
        current = current->next;
    }

    // Not in the memory pool, fall back to free
    free(ptr);
}

