struct Node {
    double value;
    std::string str;
    int index;

    Node(double v, const char* s, int i) : value(v), str(s), index(i) {}
};

typedef boost::intrusive_ptr<Node> NodePtr;

class DataStructures {
public:
    // Static member for serialization/deserialization
    static std::vector<char> serialize() { /* Implement serialization */ }

    static void deserialize(const std::vector<char>& data) { /* Implement deserialization */ }

private:
    DataStructures() {} // Prevent instantiation
    friend class Singleton;

    boost::unordered_map<std::string, NodePtr> _doubles;
    boost::unordered_map<std::string, std::vector<NodePtr>> _strings;
    boost::mutex _mutex;

    void insert(const char* key, const char* value, int index) {
        boost::unique_lock<boost::mutex> lock(_mutex);

        double val = atof(value);

        if (_doubles.find(key) == _doubles.end()) { // If not found in doubles map
            NodePtr newNode = std::make_shared<Node>(val, key, index);
            _doubles[key] = newNode;
        }

        if (_strings.find(key) == _strings.end()) { // If not found in strings map
            _strings[key] = {};
        }

        _strings[key].push_back(_doubles[key]); // Insert into the correct vector in the strings map
    }

    NodePtr find(const char* key) const {
        auto it = _doubles.find(key);
        return it != _doubles.end() ? it->second : nullptr;
    }
};

class Singleton {
public:
    static DataStructures& instance() {
        static DataStructures dataStructures;
        return dataStructures;
    }
};
