#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int value;
} Record;

struct shared_data {
    Record *records;
    size_t offsets_size;
    size_t keys_size;
    size_t limit;
    size_t *offsets;
    int *keys;
};

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Record* init_records(struct shared_data *data, size_t offsets_size, size_t keys_size, size_t limit) {
    if (offsets_size >= RSIZEMAX || keys_size >= INT_MAX || limit <= 0)
        return NULL;

    data->limit = limit;
    data->offsets_size = offsets_size;
    data->keys_size = keys_size;

    size_t record_size = sizeof(Record) + sizeof(void *) * 2; // account for offset and key pointers

    data->records = mmap(NULL, (record_size * limit), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data->records == MAP_FAILED) {
        free(data->offsets);
        free(data->keys);
        return NULL;
    }

    data->offsets = (size_t*)((char *)data->records + record_size * limit);
    data->keys = (int*)((char *)data->offsets + offsets_size * limit);

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < offsets_size; ++i) {
        if (data->offsets[i] >= limit || data->keys[i] >= INT_MAX) {
            munmap((char *)data->records, record_size * limit);
            free(data->offsets);
            free(data->keys);
            return NULL;
        }
    }
    pthread_mutex_unlock(&mutex);

    size_t records_allocated = offsets_size;
    while (records_allocated < offsets_size) {
        void *prev_records = data->records;
        size_t new_records_size = records_allocated * record_size + record_size;
        data->records = mmap(NULL, new_records_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (data->records != MAP_FAILED) {
            memmove((char *)data->records + record_size * records_allocated, prev_records, (prev_records - data->records) * record_size);
            records_allocated *= 2;
        } else {
            munmap((char *)prev_records, new_records_size);
            free(data->offsets + offsets_size);
            free(data->keys + keys_size);
            return NULL;
        }
    }

    for (size_t i = 0; i < offsets_size; ++i) {
        data->records[i].value = *(int *)(&data->offsets[i]);
        data->offsets[i] = (size_t)((char *)data->records + record_size * i);
        data->keys[i] = *(int *)&data->offsets[i];
    }

    return data->records;
