hashmap* init_hashmap() {
    hashmap *hash = (hashmap*)malloc(sizeof(hashmap));
    hash->size = 1 + (MAX_ENTRIES / 10); // Round up to next prime number for optimal load distribution.
    hash->table = (hashentry**)calloc(hash->size, sizeof(hashentry*));
    hash->locks = (pthread_mutex_t*)calloc(hash->size, sizeof(pthread_mutex_t));

    // Initialize each bucket as empty.
    for (unsigned int i = 0; i < hash->size; ++i) {
        hash->table[i] = NULL;
        pthread_mutex_init(&hash->locks[i], NULL);
    }

    return hash;
}

void new_time(entry *entry) {
    #ifdef _WIN32
        time_t now;
        struct tm *local_time = localtime_s(&now, NULL);
        entry->timestamp = mktime(local_time);
    #else
        time_t now;
        struct tm *local_time;

        if (!(now = time(NULL))) {
            perror("time");
            exit(EXIT_FAILURE);
        }
        local_time = localtime(&now);
        entry->timestamp = mktime(local_time);
    #endif
}

unsigned long hashfunc(const char *key, unsigned int table_size) {
    unsigned long hv = 0;
    for (int i = 0; i < strlen(key); ++i) {
        hv = (hv << 5) + hv + key[i];
        hv &= hv; // Force lower 32 bits.
        hv %= table_size;
    }
    return hv;
}

void insert(hashmap *hash, entry* data, unsigned int index) {
    pthread_mutex_lock(&hash->locks[index]);
    hashentry current = hash->table[index];

    while (current != NULL) {
        if (strcmp(data->key, current->data.key) == 0) {
            // Key already exists, handle duplicates as needed.
            current->data.id = data->id;
            current->data.timestamp = data->timestamp;
            pthread_mutex_unlock(&hash->locks[index]);
            return;
        }
        current = current->next;
    }

    // No duplicate found, insert new entry.
    hashentry newnode = (hashentry)malloc(sizeof(struct hashnode));
    newnode->data = *data;
    newnode->next = hash->table[index];
    hash->table[index] = newnode;
    pthread_mutex_unlock(&hash->locks[index]);
}

void* add_entry(void *arg) {
    entry *new_entry = create_entry((const char*)arg, (unsigned long)(pthread_self()));
    validate_id(new_entry->id, "http://example.com/validate"); // Validate the id if required.
    unsigned int index = hashfunc(new_entry->key, hashmap->size);
    insert(hashmap, new_entry, index);
}
```

