}

void initialize_arrays(long** offsets, int* keys, double** timestamps, record** records, size_t num_records, DAO* dao) {
    *offsets = malloc(num_records * sizeof(long));
    *keys = calloc(num_records, sizeof(int));
    *timestamps = malloc(num_records * sizeof(double));
    *records = malloc(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        // Ensure uniqueness of keys and timestamps within the range
        bool unique_key = true;
        double valid_timestamp = true;
        while (!unique_key || !valid_timestamp) {
            records[i].key = rand_range(0, INT_MAX);
            unique_key = true;
            for (size_t j = 0; j < i; ++j) {
                if (records[i].key == records[j].key) {
