            current_time.tm_mday += (records[i].timestamp - seconds) / (60 * 60 * 24);
            valid_timestamp = mktime(&current_time) >= 0 && mktime(&current_time) <= TIME_MAX;
        }

        records[i].offset = rand_range(0, LONG_MAX);
        (*keys)[i] = records[i].key;
        (*timestamps)[i] = records[i].timestamp;
    }

    // Update the database with the records, ensuring data integrity and handling error conditions
