        auto it = m_map.find(str);
        if (it != m_map.end())
            return nullptr;

        NodeUPtr newNode(new Node{value, &str, index});
        m_map.insert(std::make_pair(std::hash<std::string>()(str), std::move(newNode)));
        balanceLoad();
        return newNode;
    }

    const NodeUPtr get(const std::string& str) {
        auto it = m_map.find(str);
        if (it == m_map.end())
            return nullptr;
        return it->second;
