[' Here's a C++ code implementation for the given tasks, utilizing the `std::atomic`, `std::vector` and `new/delete` for dynamic memory management. This code does not include the pre-existing logging framework integration; you should replace the `LOG_INFO` macro with your own logging function.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <atomic>
#include <thread>
#include <chrono>

// Record structure
struct Record {
    double value;
    std::string userID;
};

// Global counters to track memory usage
std::atomic<int> offsetsCount{0}, keysCount{0}, valuesCount{0}, recordsCount{0};
std::mutex g_mutex;

// Custom memory pool for efficient allocation/deallocation
class MemoryPool {
public:
    MemoryPool() : freeList(nullptr), numFreeBlocks(0) {}

    void* allocate(size_t size) {
        if (numFreeBlocks > 0) {
            void* block = freeList;
            freeList = static_cast<void*>(freeList->freeNext);
            --numFreeBlocks;
            return block;
        } else {
            return ::operator new(size);
        }
    }

    void deallocate(void* ptr, size_t size) {
        if (static_cast<std::uintptr_t>(ptr) % alignof(std::max_align_t)) {
            throw std::runtime_error("Memory block not correctly aligned.");
        }

        auto block = static_cast<char*>(ptr);
        block->freeNext = freeList;
        freeList = block;
        ++numFreeBlocks;
    }

private:
    char* freeList;
    int numFreeBlocks;
};

// Function to perform the tasks
void allocateDataStructures(int N, MemoryPool& pool) {
    auto offsets = static_cast<long*>(pool.allocate(N * sizeof(long)));
    auto keys = static_cast<int*>(pool.allocate(N * sizeof(int)));
    auto values = static_cast<double*>(pool.allocate(N * sizeof(double)));
    auto records = static_cast<Record*>(pool.allocate(N * sizeof(Record)));

    for (size_t i = 0; i < N; ++i) {
        offsets[i] = -1;
        keys[i] = i;
        values[i] = 0;
        records[i].value = 0;

        // Generate unique user ID for each record
        std::string userId = "user_" + std::to_string(keys[i]);
        size_t idLength = userId.size();
        char* userIDMemory = static_cast<char*>(pool.allocate(idLength + 1));
        std::memcpy(userIDMemory, userId.c_str(), idLength + 1);
        records[i].userID = userIdMemory;
    }
}

// Atomic operation to increment the global counter
void incrementCounter(std::atomic<int>& counter) {
    while (true) {
        int current = counter.load();
        if (counter.compare_exchange_strong(current, current + 1)) {
            break;
        }
    }
}

// Function to log the operation
void LOG_INFO(const char* msg) {
