#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Custom logging function
void log_msg(const char *filename, const char *format, ...) {
    FILE *logfile = fopen(filename, "a");
    if (logfile == NULL) return;

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    va_list args;
    va_start(args, format);
    vfprintf(logfile, format, args);
    va_end(args);
    fputs("\n", logfile);
    fclose(logfile);
}

// Semaphore structure definition
typedef struct semaphore {
    const char *name;
    sem_t sem;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int ref_count;
    FILE *logfile;
} Semaphore;

// Helper function to initialize semaphore structure
Semaphore* create_semaphore(const char *name, int value) {
    Semaphore *sem = malloc(sizeof(Semaphore));
    if (!sem) return NULL;

    sem->name = name;
    sem->ref_count = 1;
    sem->mutex = PTHREAD_MUTEX_INITIALIZER;
    sem->cond = PTHREAD_COND_INITIALIZER;

    // Initialize semaphore with the specified value and name
    if (sem_init(&sem->sem, 0, value) != 0) {
        log_msg("semaphore.log", "Failed to create semaphore: %s\n", strerror(errno));
        free(sem);
        return NULL;
    }

    // Initialize custom logging mechanism with the specified filename
    char logfilename[256];
    snprintf(logfilename, sizeof(logfilename), "./semaphore.log");
    sem->logfile = fopen(logfilename, "a");
    if (!sem->logfile) {
        log_msg("semaphore.log", "Failed to open log file: %s\n", strerror(errno));
        sem_destroy(&sem->sem);
        free(sem);
        return NULL;
    }

    return sem;
}

// Helper function to delete semaphore, ensuring all references are freed before deletion
void destroy_semaphore(Semaphore **sem) {
    if (!*sem || (*sem)->ref_count > 1) return;

    pthread_mutex_lock(&(*sem)->mutex);

    // Write error message if semaphore is being deleted while still in use
    if ((*sem)->ref_count > 1) {
        log_msg((*sem)->logfile, "Attempt to delete semaphore %s while in use.\n", (*sem)->name);
    }

    // Decrement reference count and perform cleanup only if it's the last reference
    (*sem)->ref_count--;

    pthread_mutex_unlock(&(*sem)->mutex);

    // Perform actual cleanup when ref_count reaches zero
    if ((*sem)->ref_count == 0) {
        fclose((*sem)->logfile);
        sem_destroy(&(*sem)->sem);
        free(*sem);
        *sem = NULL;
    }
}

// Implementation of a function that waits on the semaphore, with configurable timeout
int wait_semaphore(Semaphore *sem, int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;

    pthread_mutex_lock(&sem->mutex);
    int ret = sem_wait_timeout(&sem->sem, &ts);
    pthread_mutex_unlock(&sem->mutex);

    return ret;
}

// Register cleanup handlers for atexit
void atexit_cleanup(Semaphore **semaphores, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (semaphores[i]) destroy_semaphore(&semaphores[i]);
    }
}
```

