    public class QueryBuilder
    {
        private readonly ILogger<QueryBuilder> _logger;
        private readonly IDistributedCache _cache;
        private readonly IConfiguration _configuration;
        private readonly DbConnection _connection;

        public QueryBuilder(ILogger<QueryBuilder> logger, IDistributedCache cache, IConfiguration configuration, DbConnection connection)
        {
            _logger = logger;
            _cache = cache;
            _configuration = configuration;
            _connection = connection;
        }

        public async Task<IDataReader> BuildQueryAsync(Dictionary<string, object> parameters, string queryConfigPath)
        {
            var queryConfig = LoadQueryConfig(queryConfigPath);

            var builder = new SqlServer.SqlCommandBuilder(_connection)
                .Select(BuildFieldList(queryConfig))
                .From(BuildTableAlias(queryConfig))
                .Where(BuildFilter(parameters, queryConfig))
                .OrderBy(BuildSort(queryConfig))
                .Paging(BuildPagination(parameters))
                .Join(BuildJoins(queryConfig))
                .NestedQuery(BuildNestedQueries(queryConfig))
                .DynamicFieldSelection()
                .Cache(_cache, BuildCacheKey(), _configuration.GetValue<TimeSpan>("Caching:Expiration"))
                .Async();

            try
            {
                var command = builder.BuildCommand();
                await ExecuteQuery(command, parameters);

                return await command.ExecuteReaderAsync();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing query: {Sql}", command.CommandText);
                throw;
            }
        }

        private XElement LoadQueryConfig(string path) => XElement.Load(File.OpenRead(path));

        // Implementation details for methods like BuildFieldList, BuildTableAlias, BuildFilter, BuildSort, BuildPagination, BuildJoins, BuildNestedQueries etc., depending on the specific requirements of the schema and configuration file.

        private string BuildCacheKey() => $"{nameof(QueryBuilder)}:{_connection.ConnectionString}:{HashCode(_configuration.Root)}";

        private async Task ExecuteQuery(DbCommand command, Dictionary<string, object> parameters)
        {
            if (parameters != null && parameters.Any())
                await _connection.OpenAsync();

            foreach (var parameter in parameters)
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);

            try
            {
                await command.ExecuteNonQueryAsync();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing query: {Sql}", command.CommandText);
                throw;
            }

            if (parameters != null && parameters.Any())
                await _connection.CloseAsync();
        }
    }
}
