struct record { int value; };

class MemoryManager {
private:
    std::atomic<size_t> offsetIndex{0};
    std::atomic<size_t> keyIndex{0};
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<record> records;
    sem_t semaphore;
    mutex mtx;

public:
    MemoryManager(size_t N, int minValue, int maxValue) {
        if (sem_init(&semaphore, 0, static_cast<unsigned>(1)) != 0) {
            throw std::runtime_error("Failed to initialize semaphore.");
        }

        offsets.resize(N);
        keys.reserve(N);
        records.resize(N);

