                this->offsetIndex++;
                lock.unlock();
            });
        }

        for (auto& t : producers) {
            t.join();
        }
    }

    ~MemoryManager() {
        // Cleanup resources when the MemoryManager object goes out of scope
        delete[] offsets.data();
        sem_destroy(&semaphore);
    }
