typedef struct MemoryManager {
    long *offsets;
    int *keys;
    Record **records;
    size_t offsetSize, keyCount, recordCapacity, maxRecords;
    pthread_mutex_t mutex;
} MemoryManager;

MemoryManager *create_memory_manager(size_t max_size) {
    if (max_size > (1ull << 20)) // 1 MB limit
        max_size = (1ull << 20);

    MemoryManager *mm = malloc(sizeof(MemoryManager));
    mm->offsetSize = sizeof(long) * max_size;
    mm->maxRecords = (max_size * 1000) / sizeof(Record); // estimate based on size of Record structure
    mm->recordCapacity = mm->maxRecords / 2; // initial capacity for records

    mm->offsets = calloc(max_size, sizeof(long));
    if (!mm->offsets) {
        free(mm);
        return NULL;
    }

    mm->keys = malloc(sizeof(int) * mm->recordCapacity);
    if (!mm->keys) {
        free(mm->offsets);
        free(mm);
        return NULL;
    }

    mm->records = calloc(mm->recordCapacity, sizeof(Record*));
    if (!mm->records) {
        free(mm->offsets);
        free(mm->keys);
        free(mm);
        return NULL;
    }

    pthread_mutex_init(&mm->mutex, NULL);
    return mm;
}

void destroy_memory_manager(MemoryManager *mm) {
    for (size_t i = 0; i < mm->recordCapacity; ++i)
        free(mm->records[i]);
    free(mm->records);

    free(mm->keys);
    free(mm->offsets);
    pthread_mutex_destroy(&mm->mutex);
    free(mm);
}

void *random_int(void *param) {
