    for (size_t i = 0; i < mm->recordCapacity; ++i) {
        if (!mm->records[i]) {
            mm->records[i] = malloc(sizeof(Record));
            if (!mm->records[i]) {
                pthread_mutex_unlock(&mm->mutex);
                return data;
            }
            break;
        }
    }

    for (size_t i = 0, j = 0; i < keyCount && j < mm->recordCapacity; ++i, ++j) {
        if (!mm->records[j]) continue;

        mm->keys[i] = random_int(&(mm->maxRecords));
        while (has_key(mm, mm->keys[i])) {
            mm->keys[i] = random_int(&(mm->maxRecords));
        }

        mm->records[j]->key = mm->keys[i];
        mm->records[j]->value = random_int(&((1ull << 30) - 1)); // a 32-bit integer range
        data.usedKeys[mm->keys[i]]++;
        data.keysUsed++;
    }

    pthread_mutex_unlock(&mm->mutex);

    return data;
}

bool has_key(MemoryManager *mm, int key) {
    for (size_t i = 0; i < mm->recordCapacity; ++i) {
        if (mm->records[i] && mm->records[i]->key == key)
            return true;
    }
    return false;
}

