    pthread_mutex_init(&lock, NULL);
}

void cleanup() {
    free(records);
    free(keys);
    free(offsets);
    pthread_mutex_destroy(&lock);
}

record_t* create_record() {
    record_t *newRecord = (record_t*) malloc(sizeof(record_t));
    if (!newRecord) {
        fprintf(stderr, "Failed to allocate memory for a new record.\n");
        return NULL;
    }
    newRecord->value = minValue + rand() % ((maxValue - minValue) + 1);
    return newRecord;
}

void create_arrays(unsigned long N) {
    keys = (int*) malloc((N+1)*sizeof(int));
    offsets = (long*) malloc((N+1)*sizeof(long));

    for (unsigned long i = 0; i < N; ++i) {
        keys[i] = i;
        offsets[i] = i;
    }
}

void* thread_func() {
    record_t *record;
    while (1) {
        pthread_mutex_lock(&lock);

        if (!records || records + N < &records[N]) {
            create_arrays(N);
            records = (record_t*) realloc(records, sizeof(record_t) * N);
            if (!records) {
                pthread_mutex_unlock(&lock);
                continue;
            }

            for (unsigned long i = 0; i < N; ++i) {
                record = create_record();
                records[offsets[i]] = *record;
                offsets[keys[i]] = offsets[i] + 1;
            }
        }

        pthread_mutex_unlock(&lock);
        break;
    }

    return NULL;
}
