#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Custom memory pool allocator
typedef struct MemBlock {
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* memPool = NULL;

void* customAlloc(size_t size) {
    if (memPool == NULL) {
        memPool = malloc(sizeof(MemBlock));
        memPool->size = 0;
        memPool->next = NULL;
    }

    MemBlock* current = memPool;
    MemBlock* newBlock;

    while (current != NULL && current->size + size > current->size) {
        current = current->next;
    }

    if (current == NULL) {
        newBlock = malloc(sizeof(MemBlock));
        newBlock->size = size;
        newBlock->next = memPool;
        memPool = newBlock;
    } else {
        void* allocatedMemory = ((char*) current + current->size);
        current->size += size;
        return allocatedMemory;
    }

    return NULL; // Return null if no memory was allocated
}

// Record structure
typedef struct Record {
    int value;
} Record;

// Helper function to find the maximum value in an array
int findMax(Record* arr, size_t n) {
    int max = arr[0];

    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

// Function to dynamically allocate and initialize arrays
void initArrays(size_t N, int minValue, int maxValue, void(*logFunction)(char*,...)) {
    long* offsets = (long*) customAlloc(N * sizeof(long));
    int* keys = (int*) customAlloc(N * sizeof(int));

    if (!offsets || !keys) {
        logFunction("Memory allocation failed");
        return;
    }

