struct Record {
    int value;
};

class DatasetManager {
public:
    explicit DatasetManager(size_t N, int minValue, int maxValue) : _N(N), _minValue(minValue), _maxValue(maxValue) {}

    // Allocate memory for and initialize the arrays.
    void Initialize() {
        _offsets.resize(_N);
        std::iota(_offsets.begin(), _offsets.end(), 0);

        _keys.resize(_N);
        std::fill_n(_keys.begin(), _N, -1); // Mark all keys as unassigned

        _records.resize(_N);

        GenerateUniqueValues();
    }

    // Generate the record values with unique random integers within [minValue, maxValue].
    void GenerateUniqueValues() {
        std::mt19937 rng(std::random_device{}());
        std::uniform_int_distribution<> dist(_minValue, _maxValue);

        std::unique_ptr<Record[], std::default_delete<Record[]>> recordArray(_records.data(), default_delete<Record[]>());

        for (size_t i = 0; i < _N; ++i) {
            int value = dist(rng);
            Record* currentRecord = &recordArray[_offsets[i]];

            while (_keys[currentRecord->value] != -1 || currentRecord->value == value) {
                value = dist(rng);
                currentRecord = &recordArray[dist(rng) % _N]; // Rotate to another position in the array if the value is already assigned
            }

            currentRecord->value = value;
            _keys[value] = static_cast<int>(i);
        }
    }

private:
    size_t _N;
    int _minValue, _maxValue;
    std::vector<long> _offsets; // Offset array for the keys
    std::vector<int> _keys; // Key array
    std::unique_ptr<Record[]> _records; // Value array
};

void FindLargest(const DatasetManager& manager) {
    const auto& records = manager._records.data();
    int largestValue = *std::max_element(records, records + manager._N);
    std::cout << "Largest value: " << largestValue << std::endl;
}

