    std::cin >> N >> minValue >> maxValue;

    try {
        DatasetManager manager(N, minValue, maxValue);
        manager.Initialize();

        Logger::Log("Initialized dataset with " + std::to_string(N) + " records.");

        FindLargest(manager);
    } catch (const std::exception& e) {
        Logger::Log("Error initializing dataset: " + std::string(e.what()));
    }

    return 0;
}
