```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int *keys, *offsets, *used;
static record *records;
static size_t N, minValue, maxValue, maxIterations;

void log(const char *msg) {
    double elapsed = (double)(clock() - start) / CLOCKS_PER_SEC;
    printf("%s [%f s]\n", msg, elapsed);
}

void init() {
    keys = malloc(N * sizeof(int));
    offsets = calloc(N, sizeof(long));
    records = calloc(N, sizeof(record));
    used = calloc(maxValue - minValue + 1, sizeof(int));
    start = clock();
    log("Memory allocation and initialization");
}

void fillRecords() {
    for (size_t i = 0; i < N; ++i) {
        int value = minValue + rand() % (maxValue - minValue + 1);
        while (used[value]) {
            if (++i >= N || maxIterations <= 0) {
                log("Failed to allocate unique value within allowed iterations");
                exit(EXIT_FAILURE);
            }
            value = minValue + rand() % (maxValue - minValue + 1);
        }
        records[i].value = value;
        used[value] = 1;
    }
}

void cleanup() {
    free(keys);
    free(offsets);
    free(records);
    free(used);
}

void* createDataset(void *arg) {
    init();
    fillRecords();
    return NULL;
}

int main() {
    srand(time(NULL));
    N = 100000;
    minValue = 0;
    maxValue = 99999;
    maxIterations = 1000;

    pthread_t thread;
    if (pthread_create(&thread, NULL, createDataset, NULL)) {
        log("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    cleanup();
    return 0;
}
```

