#include <iostream>
#include <vector>
#include <random>
#include <cstdlib>
#include <json/json.h>
#include <fstream>
#include <system_error>

struct Record { int value; };

void generate_records(std::vector<Record>& records, size_t N, int minValue, int maxValue) {
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> distrib(minValue, maxValue);

    std::set<int> used;
    for (size_t i = 0; i < N; ++i) {
        int value;
        do {
            value = distrib(gen);
        } while (used.count(value));
        records[i] = Record{value};
        used.insert(value);
    }
}

std::vector<Record> create_dataset(size_t N, int minValue, int maxValue) {
    std::vector<long> offsets(N);
    std::vector<int> keys(N);
    std::iota(keys.begin(), keys.end(), 0);

    std::vector<Record> records(N);
    try {
        generate_records(records, N, minValue, maxValue);
        std::cout << "Memory allocation and initialization successful.\n";
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        throw;
    }

    return records;
}

void save_dataset(const std::vector<Record>& records, const std::string& filename, const Json::Serializer& serializer) {
    Json::Value root;
    Json::Array array;

    for (const auto& record : records) {
        Json::Value obj;
        obj["value"] = static_cast<int>(record.value);
        array.append(obj);
    }

    root["records"] = array;
    serializer.Save(root, filename);
}

Json::Value load_dataset(const std::string& filename, const Json::Deserializer& deserializer) {
    Json::Value root;
    try {
        deserializer.LoadFile(filename, root);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        throw;
    }

    const Json::Value& records = root["records"];
    if (!records.isArray()) {
        throw std::runtime_error("Invalid dataset format");
    }

    Json::Value result;
    result["records"] = records;
    return result;
}

int main(int argc, char* argv[]) {
    size_t N = 10000;
    int minValue = -1000, maxValue = 1000;

    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " [N] [minValue] [maxValue]\n";
        return 1;
    }

    N = std::stoul(argv[1]);
    minValue = std::stoi(argv[2]);
    maxValue = std::stoi(argv[3]);

    auto dataset = create_dataset(N, minValue, maxValue);

    // Save the dataset to disk in JSON format
    const std::string json_filename = "dataset.json";
    save_dataset(dataset, json_filename, Json::Serializer{});

    // Load the dataset from disk and print its content
    auto loaded_dataset = load_dataset(json_filename, Json::Deserializer{});
    const Json::Value& records = loaded_dataset["records"];

    for (const auto& record : records) {
        std::cout << "(" << record[0].u.numberValue << ", " << record[1].u.numberValue << ") ";
    }
    std::cout << "\n";
}
```

