    json_t *item;
    json_t *status;
    json_t *msg;
    json_string_t *s;
    json_error_t error;

    root = json_object();
    item = json_array();
    status = json_integer(success);
    msg = json_string(message);
    s = json_string(json_dumps(msg, 0));

    json_array_append_new(item, status);
    json_array_append_new(item, msg);
    json_object_set(root, "response", item);

    char *output = json_dumps(root, 0, 4, JSON_ERROR_STRING(&error));
    free(s.string);
    json_decref(msg);
    json_decref(status);
    json_decref(item);
    json_decref(root);

    if (output == NULL) {
        fprintf(stderr, "Failed to generate JSON response: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    return output;
}

