        getline(&request_str, &user.password, stdin);
        request = json_loads(request_str, 0, &error);
        if (!request) {
            fprintf(stderr, "Failed to parse JSON request: %s\n", error.text);
            continue;
        }

        json_object_foreach(request, key, value) {
            if (strcmp(key->string, "id") == 0) {
                user.id = json_integer_value(value);
            } else if (strcmp(key->string, "name") == 0) {
                strcpy(user.name, json_string_value(value));
            } else if (strcmp(key->string, "email") == 0) {
                strcpy(user.email, json_string_value(value));
            } else if (strcmp(key->string, "password") == 0) {
                strcpy(user.password, json_string_value(value));
            } else if (strcmp(key->string, "sub_action") == 0) {
                user.sub_action = json_integer_value(value);
            }
        }

        // Validate and process the request
        if (!user.id && !user.name || !user.email || !user.password) {
            curl = NULL;
            strcpy(request_str, generate_response(0, "Missing required fields."));
        } else {
            // Perform email validation and manage user account based on 'sub_action'
            if (user.id && user.email[0] != '\0') {
                curl = email_validation_request(user.email);
