                    char response[256];
                    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
                    if (res != CURLE_OK) {
                        fprintf(stderr, "Failed to get response code: %s\n", curl_easy_strerror(res));
                        curl_easy_cleanup(curl);
                        strcpy(request_str, generate_response(0, "Failed to validate email."));
                    } else if (res == 200) {
                        curl_easy_getinfo(curl, CURLINFO_REMOTE_CONTENT_LENGTH_NOTIFIER, NULL);
                        curl_easy_read(curl, response, sizeof(response), NULL);
                        curl_easy_cleanup(curl);

                        if (strchr(response, 'F') != NULL) {
                            strcpy(request_str, generate_response(0, "Email already exists."));
                        } else {
                            manage_user_account(&user);
