#include <vector>
#include <string>
#include <unordered_set> // For fast duplicate removal and lookup
#include <mutex> // For thread-safety when modifying the vector

std::vector<std::string> enhancedInsertAndClean(std::vector<std::string>& vec, const std::string& target, const std::string& insert, const std::string& removeDuplicate) {
    // Create an unordered set to store unique strings for faster lookup and removal of duplicates.
    std::unordered_set<std::string> uniqueSet(vec.begin(), vec.end());

    // Use a mutex to ensure thread-safety when modifying the vector concurrently.
    std::mutex mtx;

    // Find the first occurrence of the target string in the vector, or append the insertion string if not found.
    auto it = std::find(vec.begin(), vec.end(), target);
    if (it == vec.end()) {
        std::lock_guard<std::mutex> lock(mtx); // Acquire a lock before modifying the vector to ensure thread-safety.
        vec.push_back(insert);
    } else {
        // Remove any duplicates of the target string from the vector and update the uniqueSet accordingly.
        uniqueSet.erase(it);
        auto itDuplicate = std::find(it + 1, vec.end(), target);
        while (itDuplicate != vec.end()) {
            if (uniqueSet.count(*itDuplicate) > 0) {
                std::lock_guard<std::mutex> lock(mtx); // Acquire a lock before modifying the vector to ensure thread-safety.
                vec.erase(itDuplicate);
            }
            itDuplicate = std::find(it + 1, vec.end(), target);
        }
    }

    // Erase any occurrences of strings that should be removed from the vector and update the uniqueSet accordingly.
    for (auto it = vec.begin(); it != vec.end();) {
        if (it->compare(removeDuplicate) == 0 && uniqueSet.count(*it) > 1) {
            std::lock_guard<std::mutex> lock(mtx); // Acquire a lock before modifying the vector to ensure thread-safety.
            it = vec.erase(it);
        } else {
            ++it;
        }
    }

    return vec;
}
