void allocateResources(size_t N, size_t minValue, size_t maxValue, std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>* records) {
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<> distr(minValue, maxValue);

    std::set<int> uniqueValues;

    offsets.resize(N);
    keys.resize(N);

    for (size_t i = 0; i < N; ++i) {
        keys[i] = static_cast<int>(i);
        int value;
        do {
            value = distr(rng);
        } while (uniqueValues.count(value) > 0);
        uniqueValues.insert(value);
        records->at(i).value = value;
    }

    // Integrate with logging framework here
}

void saveToFile(const std::string& filename, const rapidjson::Document& doc) {
    std::ofstream file(filename);
    if (file.is_open()) {
        rapidjson::Writer<rapidjson::StringBuffer> writer;
        doc.Accept(writer);
        file << writer.GetString();
    } else {
        std::cerr << "Error opening file for writing: " << filename << std::endl;
    }
}

void loadFromFile(const std::string& filename, rapidjson::Document& doc) {
    // Implement loading from file here
}

rapidjson::Document serializeToJson(const std::vector<Record>& records) {
    rapidjson::Document doc;
    doc.SetObject();

    rapidjson::Value array(rapidjson::kArrayType);
    for (const auto& record : records) {
        rapidjson::Value item(rapidjson::kObjectType);
        item.AddMember("value", record.value, doc.GetAllocator());
        array.PushBack(item, doc.GetAllocator());
    }
    doc.AddMember("records", array, doc.GetAllocator());

    return doc;
}

std::vector<Record> deserializeFromJson(const rapidjson::Document& doc) {
    const rapidjson::Value& records = doc["records"];
    std::vector<Record> result;
    result.reserve(records.Size());

    for (size_t i = 0; i < records.Size(); ++i) {
        const rapidjson::Value& item = records[i];
        Record record;
        record.value = item["value"].GetInt();
        result.push_back(record);
    }

    return result;
}
