// Callback function prototype
typedef void (*callback_func)(Record*);

void create_data_set(size_t limit_kb, size_t max_keys, size_t min_val, size_t max_val, size_t* offsets, int* keys, Record** records, callback_func cb) {
    size_t total_memory = 0; // Keep track of current memory usage in bytes
    size_t key_sum = 0; // Sum of all keys

    offsets = (long*) calloc(max_keys + 1, sizeof(long));
    if (!offsets) {
        perror("Error: Failed to allocate memory for offsets");
        return;
    }

    keys = (int*) realloc((void*)offsets, ((total_memory += (max_keys + 1)) * sizeof(long)) + max_keys * sizeof(int));
    if (!keys) {
        perror("Error: Failed to reallocate memory for offsets and keys");
        free(offsets);
        return;
    }

    total_memory += max_keys * sizeof(int);

    records = (Record**) malloc((total_keys = max_keys) * sizeof(Record*));
    if (!records) {
        perror("Error: Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random seed and generator
    srand((unsigned int)time(NULL));

    // Allocate additional memory for the first record, as offset calculation starts from 1
    long* temporary_offsets = (long*) calloc(total_keys + 1, sizeof(long));
    if (!temporary_offsets) {
        perror("Error: Failed to allocate memory for temporary_offsets");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Fill the temporary offsets array, considering the potential edge cases
    for (size_t i = 1; i <= total_keys; ++i) {
        temporary_offsets[i] = i;
    }

    size_t current_key_index = 0;
    while (current_key_index < max_keys) {
        // Select a random index from the remaining keys and update its corresponding offset value
        size_t rand_index = temporary_offsets[rand() % (total_keys - current_key_index)];

        keys[current_key_index] = rand() % (max_val - min_val + 1) + min_val;
        key_sum += keys[current_key_index];

        // Update offsets for the remaining keys
        if (keys[current_key_index] < max_keys - current_key_index) {
            for (size_t j = rand_index + 1; j <= total_keys && j <= keys[current_key_index]; ++j) {
                temporary_offsets[j] = temporary_offsets[j + 1];
            }
            temporary_offsets[rand_index] = current_key_index + 1;
        }

        // Increment current key index and allocate memory for the corresponding record
        records[current_key_index] = (Record*) malloc(sizeof(Record));
        if (!records[current_key_index]) {
            perror("Error: Failed to allocate memory for a record");
            free(offsets);
            free(keys);
            free(temporary_offsets);
            free(records);
            return;
        }

        // Call the provided callback function, if any
        if (cb) {
            cb(records[current_key_index]);
        }

        ++current_key_index;
    }

    // Handle memory deallocation in a separate function, ensuring thread safety
    void free_resources() {
        for (size_t i = 0; i < total_keys; ++i) {
            if (records[i]) free(records[i]);
        }
        free(records);
        free(keys);
        free(offsets);
        free(temporary_offsets);
    }
}
