typedef struct {
    int key;
    double value;
} data_item;

void init_random_data(data_item** items, size_t* sizes, size_t total_items, size_t double_size, size_t long_size, size_t struct_size) {
    *items = malloc(total_items * struct_size);
    if (!*items) {
        fprintf(stderr, "Memory allocation for data failed.\n");
        exit(1);
    }

    srand(time(NULL));
    size_t chunk_size = total_items / 4; // Adjust this value to balance memory fragmentation and concurrency
    pthread_t threads[4];

    for (size_t i = 0; i < 4; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == 3) ? total_items : (start + chunk_size);

        args_t args = { .items = *items, .sizes = sizes, .start = start, .end = end };
        if (pthread_create(&threads[i], NULL, worker, &args)) {
            fprintf(stderr, "Failed to create thread.\n");
            exit(1);
        }
    }

    for (size_t i = 0; i < 4; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Failed to join thread.\n");
            exit(1);
        }
    }
}

void* worker(void* arg) {
    args_t* args = static_cast<args_t*>(arg);
