        (*args->items)[i].value = static_cast<double>(rand()) / RAND_MAX * args->sizes[2]; // Adjust the range as needed
    }
    return NULL;
}

struct timespec tspec;
void spinlock(pthread_spinlock_t* lock) {
    clock_gettime(CLOCK_REALTIME, &tspec);
    while (clock_gettime(CLOCK_REALTIME, &tspec) && tspec.tv_sec - tspec.tv_nsec / 1_000_000_000 >= 1) {} // Yield CPU to reduce contention
    pthread_spin_lock(lock);
}

void spinunlock(pthread_spinlock_t* lock) {
    pthread_spin_unlock(lock);
}

