void testAndInitializeRecords(const char* label, TestFunc test) {
    // Allocate memory for offsets and keys arrays
    offsets = calloc(3, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets array.\n");
        return;
    }

    keys = calloc(3, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys array.\n");
        free(offsets);
        return;
    }

    // Allocate and map record array with PROT_READ | PROT_WRITE | PROT_EXEC permissions
    size_t records_size = sizeof(Record) * 1024; // Adjust as needed for scalability
    if (records_memory_allocated + records_size > MAX_KB) {
        fprintf(stderr, "Error: Allocated memory exceeds the specified limit.\n");
        free(offsets);
        free(keys);
        return;
    }

    if ((records_memory_map = mmap(NULL, records_size, PROT_READ | PROT_WRITE | PROT_EXEC, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate and map memory for record array.\n");
        free(offsets);
        free(keys);
        return;
    }

    records_memory_allocated += records_size;

    // Initialize records with random values within a specified range
    for (int i = 0; i < 1024; ++i) {
        Record* record_ptr = (Record*)(records_memory_map + i * sizeof(Record));
        record_ptr->value = rand() % 100;

        // Update offsets, keys, and sum of keys
        offsets[2] += sizeof(Record);
        keys[(int)((i + 1) / 3)]++;
    }

    // Call the test function if it is provided and all conditions are met
    if (test && keys[2] <= THRESHOLD) {
        test(label, "test_record_initialization");
    }
}

void deallocateResources() {
    if (records_memory_map != MAP_FAILED) {
        munmap(records_memory_map, records_memory_allocated);
    }

    free(offsets);
    free(keys);

    records_memory_map = MAP_FAILED;
    records_memory_allocated = 0;
}
