Record* create_records(size_t count) {
    size_t i;
    Record *records = malloc(count * sizeof(Record));

    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Seed random number generator with current time, for reproducible results
