typedef struct {
    int value;
    char* identifier;
} record;

struct hash_table {
    long* offsets;
    int* keys;
    record** records;
    size_t size;
    size_t capacity;
};

// Hash function for generating unique identifiers
unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % capacity;
}

struct hash_table* create_hash_table(size_t initial_capacity, size_t max_kb) {
    struct hash_table* table = malloc(sizeof(*table));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->offsets = calloc(initial_capacity, sizeof(long));
    if (!table->offsets) {
        free(table);
        return NULL;
    }
    table->keys = calloc(initial_capacity, sizeof(int));
    if (!table->keys) {
        free(table->offsets);
        free(table);
        return NULL;
    }

    table->records = malloc(initial_capacity * sizeof(*(table->records)));
    if (!table->records) {
        free(table->offsets);
        free(table->keys);
        free(table);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        table->records[i] = malloc(sizeof(*(table->records[i])) * 2);
        if (!table->records[i]) {
            free(table->offsets);
            free(table->keys);
            free(table->records);
            free(table);
            return NULL;
        }
    }

    table->size = 0;
    table->max_kb = max_kb;
    return table;
}

int add_record(struct hash_table* table, int key, long offset) {
    if (table->size + sizeof(*(table->records[table->size])) > table->capacity - table->size) {
        size_t new_capacity = table->capacity * 2;
        void** temp_records = realloc(table->records, new_capacity * sizeof(*(table->records)));

        if (!temp_records) return 1; // Failed to allocate memory

        table->records = temp_records;
        table->capacity *= 2;
    }

    record* current = &(table->records[table->size]);

    current->value = rand() % THRESHOLD;
    current->identifier = malloc(32); // Adjust this value to control the uniqueness of identifiers
    snprintf(current->identifier, 32, "%lu-%lu-%06ld", (unsigned long)time(NULL), hash(current->identifier), (long)rand());

    table->offsets[table->size] = offset;
    table->keys[table->size] = key;
    ++table->size;
    return 0; // Successfully added the record
}

void destroy_hash_table(struct hash_table* table) {
    for (size_t i = 0; i < table->size; ++i) {
        free(table->records[i]->identifier);
    }
    free(table->records);
    free(table->offsets);
    free(table->keys);
    free(table);
}
