pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static Record* record_cache[1024];

Record* get_cached_record() {
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < sizeof(record_cache) / sizeof(Record*); ++i) {
        if (!record_cache[i]) {
            record_cache[i] = create_record();
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return record_cache[i];
}

void manage_records(size_t num_records, size_t record_size) {
    Record* records = malloc(num_records * record_size);
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = get_cached_record();
        initialize_record(&records[i]);
    }

    // Process the records here and release memory when done

    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < num_records; ++i) {
        free_record(records + i);
    }
    pthread_mutex_unlock(&cache_lock);

    free(records);
}
