async function runTests(label, f, timeout, verbose = false) {
  let startTime = Date.now();
  const testUtil = require('testUtil').reset(); // Resetting the mocking library to its initial state

  function retry(fn, maxRetries = 3, backoff = 2) {
    return async function() {
      let attempts = 0;
      while (attempts < maxRetries) {
        try {
          return await fn();
        } catch (e) {
          if (attempts === maxRetries - 1) {
            throw e;
          }
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, backoff++) * 100)); // Exponential backoff
        }
      }
    };
  }

  const test = retry(() =>
    new Promise((resolve, reject) => {
      const id = setInterval(() => {
        if (Date.now() - startTime > timeout) {
          clearInterval(id);
          reject(new Error(`Test "${label}" timed out after ${timeout}ms`));
        } else if (!verbose) {
          console.log(`\n\tExecuting test "${label}"...`);
        }
        f();
        testUtil.reset(); // Resetting the mocking library after each test
        clearInterval(id);
        resolve();
      }, 100);
    })
  );

  try {
    await test;
    console.log(`\tTest "${label}" passed`);
  } catch (error) {
    console.error(`\tTest "${label}" failed:\n\t${error.message}`);
  }

  // Automatic test coverage reports based on the test results
  // ... Implement this feature as per your specific testing and reporting tools requirements.
}
