#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    char *identifier;
    int value;
} Record;

struct ComplexData {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t size;
    unsigned long threshold;
};

void cleanup(struct ComplexData *data) {
    if (data->offsets) free(data->offsets);
    if (data->keys) free(data->keys);
    for (size_t i = 0; i < data->size; ++i) {
        if (data->records[i].identifier) free(data->records[i].identifier);
    }
    if (data->records) free(data->records);
}

struct ComplexData *create_complex_data(size_t capacity, unsigned long threshold, size_t limit_in_kb) {
    struct ComplexData *data = malloc(sizeof(*data));
    data->capacity = capacity;
    data->threshold = threshold;

    if (limit_in_kb > 0 && sizeof(long) + sizeof(int) + sizeof(Record) * capacity + sizeof(*data) > limit_in_kb * 1024) {
        fprintf(stderr, "Insufficient memory\n");
        free(data);
        return NULL;
    }

    data->offsets = calloc(capacity, sizeof(long));
    data->keys = malloc(capacity * sizeof(int));
    data->records = calloc(capacity, sizeof(Record));

    for (size_t i = 0; i < capacity; ++i) {
        data->records[i].identifier = malloc(32);
        sprintf(data->records[i].identifier, "ID%lu", i);
        data->records[i].value = 0;
    }

    return data;
}

void serialize(struct ComplexData *data, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    fwrite(data->offsets, sizeof(long), data->size, file);
    fwrite(data->keys, sizeof(int), data->size, file);
    for (size_t i = 0; i < data->size; ++i) {
        size_t len = strlen(data->records[i].identifier);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(data->records[i].identifier, len, 1, file);
        fwrite(&data->records[i].value, sizeof(int), 1, file);
    }
    fclose(file);
}

struct ComplexData *deserialize(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return NULL;
    }

    struct ComplexData *data = calloc(1, sizeof(*data));
    size_t capacity = 0;
    long offset;
    int key;

    while (fread(&offset, sizeof(long), 1, file) > 0) {
        if (capacity == data->capacity) {
            data->capacity *= 2;
            data->offsets = realloc(data->offsets, data->capacity * sizeof(long));
            data->keys = realloc(data->keys, data->capacity * sizeof(int));
            data->records = realloc(data->records, data->capacity * sizeof(Record));
        }

        fread(&key, sizeof(int), 1, file);
        data->keys[capacity] = key;
        data->records[capacity].value = 0;

        size_t identifier_len;
        if (fread(&identifier_len, sizeof(size_t), 1, file) <= 0) break;
        data->records[capacity].identifier = malloc(identifier_len);
        if (fread(data->records[capacity].identifier, identifier_len, 1, file) <= 0) break;

        capacity++;
    }

    rewind(file);

    for (size_t i = 0; i < capacity; ++i) {
        if (fread(&data->records[i].value, sizeof(int), 1, file) <= 0) break;
        data->records[i].identifier[identifier_len] = '\0';
    }

    fclose(file);

    // Integrity check: ensure the sum of all integer values does not exceed the threshold
    int sum = 0;
    for (size_t i = 0; i < capacity; ++i) {
        sum += data->records[i].value;
        if (sum > data->threshold) {
            fprintf(stderr, "Integrity violation: sum exceeds threshold\n");
            cleanup(data);
            return NULL;
        }
    }

    return data;
}
```

