```javascript
function traverseDom(rootElement, selector, metadataCallback, batchSize = 10) {
  const collectedElements = [];

  function traverse(node) {
    if (node.matches && node.matches(selector)) {
      if (metadataCallback) {
        metadataCallback(node).then((data) => {
          collectedElements.push({ el: node, data });
        }).catch((error) => console.error(`Error fetching metadata for ${node}:`, error));
      } else {
        collectedElements.push({ el: node });
      }
    }

    if (!node.hasAttribute('data-batch-processed')) {
      let processedNodes = 0;

      for (let i = 0; i < batchSize && node.children.length > processedNodes; i++) {
        const child = node.children[processedNodes++];
        traverse(child);
      }

      node.setAttribute('data-batch-processed', 'true');
    }
  }

  traverse(rootElement);
  return Promise.resolve(collectedElements);
}
```"]

