typedef struct MemoryPool {
    void** buffer;
    size_t capacity;
    size_t count;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialSize) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->buffer = malloc(initialSize * sizeof(void*));
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    pool->capacity = initialSize;
    pool->count = 0;

    return pool;
}

void* memoryPoolAlloc(MemoryPool* pool) {
    if (pool->count >= pool->capacity) {
        void** tempBuffer = realloc(pool->buffer, (pool->capacity * 2) * sizeof(void*));
        if (!tempBuffer) return NULL;
        pool->buffer = tempBuffer;
        pool->capacity *= 2;
    }

    return pool->buffer[pool->count++];
}

void memoryPoolFree(MemoryPool* pool, void* ptr) {
    if (ptr) pool->count--;
}

