[' Here's a simplified C++ example using `nlohmann::json` library for parsing JSON, `std::unordered_map` as a custom hash table, and `boost::log` for logging. The code does not include all the error handling and optimization requirements but provides a good starting point.

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <boost/log/trivial.hpp>
#include <nlohmann/json.hpp>

namespace bl = boost::log;
using json = nlohmann::json;

struct Node {
    size_t id;
    bool visited = false;
    int distanceFromSource = INT32_MAX;
    std::vector<Node*> adjacencies;
};

struct Edge {
    Node* node1;
    Node* node2;
    int weight;
};

class Graph {
public:
    Graph(const json& config) : nodes_(nullptr), edges_(nullptr), maxNodes_(config["max_nodes"].get<size_t>()), maxEdges_(config["max_edges"].get<size_t>()) {
        loadConfig(config);
    }

    ~Graph() {
        clear();
    }

    void addEdge(Node* node1, Node* node2, int weight) {
        auto edgeKey = std::make_pair(std::hash<size_t>()(node1->id), std::hash<size_t>()(node2->id));
        if (edgeTable_.count(edgeKey)) return; // duplicate edge

        edges_.push_back({node1, node2, weight});
        edgeTable_[edgeKey] = &edges_.back();
    }

private:
    void loadConfig(const json& config) {
        std::ifstream ifs(config["file"].get<std::string>());
        json j;
        ifs >> j;

        if (j.find("nodes") == j.end() || j["nodes"].size() < 1) {
            BL_ERROR << "Invalid number of nodes in configuration";
            return;
        }

        nodeThreshold_ = j["nodes"].size();

        auto pNode = std::make_shared<Node>();
        pNode->id = 0;
        nodes_.push_back(pNode.get());

        for (const auto& nodeData : j["nodes"]) {
            auto newNode = std::make_shared<Node>(*nodes_[0]); // copy metadata from the first node
            newNode->id = nodeData["id"].get<size_t>();
            nodes_.push_back(newNode.get());
        }

        if (j.find("probability") == j.end() || j["probability"].get<double>() < 0 || j["probability"].get<double>() > 1) {
            BL_ERROR << "Invalid probability of edge creation";
            return;
        }

        if (j.find("weight_range") == j.end() || j["weight_range"].size() != 2 || j["weight_range"][0] > j["weight_range"][1]) {
            BL_ERROR << "Invalid edge weight range";
            return;
        }

        edgeThreshold_ = nodes_.size();
    }

    void clear() {
        for (auto node : nodes_) delete node;
        for (auto edge : edges_) delete[] edge;
        nodes_.clear();
        edges_.clear();
        edgeTable_.clear();
    }

private:
    std::vector<Node*> nodes_;
    std::vector<Edge> edges_;
    std::unordered_map<std::pair<size_t, size_t>, Edge*> edgeTable_;
    size_t nodeThreshold_;
    size_t edgeThreshold_;
    size_t maxNodes_;
    size_t maxEdges_;
};
```

In this example, I have created a `Graph` class that dynamically allocates memory for the graph data structure. The constructor takes in a JSON configuration object and initializes the graph based on the provided settings. The `addEdge` function is used to add an edge between two nodes with a specific weight. An unordered map (edgeTable) is used as a custom hash table to validate edges, preventing duplicate edges from being created.

Error handling is not exhaustive in this example but provides some descriptive error messages when needed. The `clear` function deallocates all allocated resources upon exit, avoiding memory leaks.']

