// Helper function to generate a unique random number within [minValue, maxValue]
int generate_unique(Record* records, size_t N, int minValue, int maxValue) {
    int value;
    do {
        value = rand() % (maxValue - minValue + 1) + minValue;
    } while (valueInArray(value, records, N));
    return value;
}

// Helper function to check if a number is in the array
int valueInArray(int value, Record* records, size_t N) {
    for (size_t i = 0; i < N; ++i)
        if (records[i].value == value)
            return 1;
    return 0;
}

// Helper function to log an event with a specified level of detail
