// Function for initializing the arrays and records
void init(size_t N, int minValue, int maxValue, Record** records, long* offsets, int* keys) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety

    *records = malloc(N * sizeof(Record));
    if (!*records) {
        log_event("Error allocating memory for records.", 1);
        return;
    }

    *offsets = calloc(N, sizeof(long));
    if (!*offsets) {
