        free(*records);
        return;
    }

    *keys = malloc(N * sizeof(int));
    if (!*keys) {
        log_event("Error allocating memory for keys.", 1);
        free(*offsets);
        free(*records);
        return;
    }

    pthread_mutex_lock(&lock); // Lock for concurrent operations
    init_records(*records, N);
    for (size_t i = 0; i < N; ++i)
        (*keys)[i] = i;
    pthread_mutex_unlock(&lock);

    init_records(records, N); // Generate unique random values for each record
    for (size_t i = 0; i < N; ++i) {
        int value = generate_unique(records, N, minValue, maxValue);
        (*records)[(*keys)[i]].value = value;
        (*offsets)[i] = value;
    }
}

// Cleanup function to free allocated resources
void cleanup(Record* records, long* offsets, int* keys) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
