size_t users_capacity = 0;
size_t users_used = 0;

struct timespec backoff;
int rate_limit = 100; // requests per second
int current_requests = 0;
time_t reset_timestamp = 0;

static inline void sleep_until(struct timespec *ts) {
    struct timespec now, remaining;
    clock_gettime(CLOCK_REALTIME, &now);
    if (now.tv_sec >= ts->tv_sec && now.tv_nsec >= ts->tv_nsec) return;
    remaining.tv_sec = ts->tv_sec - now.tv_sec;
    remaining.tv_nsec = ts->tv_nsec - now.tv_nsec;
    while (remaining.tv_sec >= 0 && remaining.tv_nsec >= 0) {
        nanosleep(&remaining, &now);
        clock_gettime(CLOCK_REALTIME, &now);
        remaining.tv_sec = ts->tv_sec - now.tv_sec;
        remaining.tv_nsec = ts->tv_nsec - now.tv_nsec;
    }
}

void rate_limit_check() {
    struct timespec cur_time;
    clock_gettime(CLOCK_REALTIME, &cur_time);

    if (cur_time.tv_sec >= reset_timestamp) {
        current_requests = 0;
        reset_timestamp += rate_limit * 1000; // convert to microseconds before multiplication
    }

    sleep_until(&(struct timespec){
        .tv_sec = cur_time.tv_sec,
        .tv_nsec = (cur_time.tv_nsec + rate_limit * 1000 - current_requests) % 1e9
    });

    ++current_requests;
}

