        if (max_user->id < users[i].id) max_user = &users[i];
    }
    return max_user;
}

int create_or_update_user(UserData* user) {
    rate_limit_check();
    pthread_mutex_lock(&users_mutex);

    UserData* user_data = malloc(sizeof(UserData));
    memcpy(user_data, user, sizeof(UserData));

    if (validate_user(user_data) == 0) {
