            user_count++;
        }
        if (!user->password) user_data->password = generate_secure_password();

        if (strlen(user_data->email) > users_capacity - users_used) {
            size_t new_capacity = users_capacity * 2;
            while (new_capacity < users_count + users_used) new_capacity *= 2;
            UserData* new_users = realloc(users, sizeof(UserData) * new_capacity);
            if (!new_users) {
                free(user_data);
