    if (!doubles) {
        fprintf(stderr, "Error: Failed to allocate memory for doubles.\n");
        goto error;
    }

    strings = malloc(num_strings * sizeof(char*));
    if (!strings) {
        fprintf(stderr, "Error: Failed to allocate memory for strings.\n");
        free(doubles);
        goto error;
    }

    points = malloc(num_points * sizeof(Point));
    if (!points) {
        fprintf(stderr, "Error: Failed to allocate memory for points.\n");
        free(doubles);
        free(strings);
        goto error;
    }

    // Initialize the data structures.
    for (size_t i = 0; i < num_doubles; ++i) {
        doubles[i] = rand() * (max_double - min_double) / RAND_MAX + min_double;
    }

    for (size_t i = 0; i < num_strings; ++i) {
        size_t color_index = rand() % color_count;
        strings[i] = strdup(colors[color_index]);
        if (!strings[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for string #%zu.\n", i);
            goto error;
        }
    }

    for (size_t i = 0; i < num_points; ++i) {
        Point* current_point = &points[i];
        current_point->x = rand() * (max_double - min_double) / RAND_MAX + min_double;
        current_point->y = rand() * (max_double - min_double) / RAND_MAX + min_double;
        current_point->color = strings[rand() % num_strings];
        current_point->timestamp = time(NULL);
        current_point->status = false;
    }

    return points;

error:
    if (points) free(points);
    if (doubles) free(doubles);
    if (strings) {
        for (size_t i = 0; i < num_strings; ++i) free(strings[i]);
        free(strings);
    }
    return NULL;
}
