typedef struct {
    int value;
    char *buffer;
} record;

int allocate_and_initialize(size_t offset_count, size_t key_count, size_t buffer_size, int min_value, int max_value, log_func_t log) {
    long *offsets = malloc(offset_count * sizeof(long));
    if (!offsets) {
        log("Error: Failed to allocate memory for offsets.");
        return 1;
    }

    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        log("Error: Failed to allocate memory for keys.");
        free(offsets);
        return 1;
    }

    record *records = malloc(key_count * sizeof(record));
    if (!records) {
        log("Error: Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        return 1;
    }

    srand(time(NULL)); // Initialize random number generator

    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        size_t unique_chars = (keys[i] >= buffer_size ? buffer_size : keys[i]);
        records[i].buffer = malloc(unique_chars);
        if (!records[i].buffer) {
            log("Error: Failed to allocate memory for record buffer.");
            for (; i > 0; --i) free(records[i - 1].buffer); // Free previously allocated buffers up to the faulty one
            free(offsets);
            free(keys);
            free(records);
            return 1;
        }

        memset(records[i].buffer, 'a' + i, unique_chars); // Fill buffer with unique ASCII characters based on key value
    }

    for (size_t i = 0; i < offset_count - 1; ++i) {
        offsets[i] = i; // Initialize offset array with sequential values up to the second last index
    }
    // Calculate and assign remaining offset values based on the positions of the records in the keys array
    for (size_t i = offset_count - 1; i > 0; --i) {
        size_t j = rand() % i; // Randomly select an index to swap with
        size_t temp = offsets[j];
        offsets[j] = offsets[i];
        offsets[i] = temp;
    }

    for (size_t i = 0; i < key_count; ++i) {
        records[offsets[i]].value = keys[i];
    }

    return 0; // Return success status
}

void deallocate(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < keys[key_count - 1]; ++i) { // Iterate up to the last key index
        free(records[i].buffer);
    }
    free(records);
}
