#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    int value;
    void *key;
} record;

typedef struct cache_s {
    size_t capacity;
    size_t count;
    sem_t lock;
    pthread_mutex_t data_lock;
    record *data;
    record *cache;
    size_t cache_size;
    void *keys;
} cache;

cache* create_cache(void *keys, size_t capacity) {
    cache *c = malloc(sizeof(cache));
    if (!c) return NULL;
    c->capacity = capacity;
    c->count = 0;
    sem_init(&c->lock, 0, 1);
    pthread_mutex_init(&c->data_lock, NULL);
    c->keys = keys;
    c->cache = NULL;
    c->cache_size = 0;
    return c;
}

record* find_in_cache(cache *c, void *key) {
    for (size_t i = 0; i < c->cache_size; ++i) {
        if (c->cache[i].key == key) return &c->cache[i];
    }
    return NULL;
}

record* find_in_data(cache *c, void *key) {
    pthread_mutex_lock(&c->data_lock);
    for (size_t i = 0; i < c->count; ++i) {
        if (c->data[i].key == key) {
            record *res = &c->data[i];
            pthread_mutex_unlock(&c->data_lock);
            return res;
        }
    }
    pthread_mutex_unlock(&c->data_lock);
    return NULL;
}

void insert(cache *c, void *key, int value) {
    sem_wait(&c->lock);
    record *r = find_in_cache(c, key);
    if (r) {
        r->value = value;
        sem_post(&c->lock);
        return;
    }
    record *new_record = malloc(sizeof(record));
    if (!new_record) goto error_handling;
    new_record->key = key;
    new_record->value = value;

    if (c->count == c->capacity) {
        // Eviction strategy based on LRU, Least Recently Used or other strategies.
        record *oldest = c->data[0];
        for (size_t i = 1; i < c->count; ++i) {
            if (c->data[i].key > oldest->key) oldest = &c->data[i];
        }
        free(oldest);
    }
    pthread_mutex_lock(&c->data_lock);
    c->data[c->count] = *new_record;
    ++c->count;
    sem_post(&c->lock);

    if (!c->cache || c->cache_size == 0) {
        c->cache = malloc(sizeof(record));
        if (!c->cache) goto error_handling;
        c->cache_size = 1;
        c->cache[0] = *new_record;
    } else {
        for (size_t i = c->cache_size - 1; i > 0; --i) {
            c->cache[i] = c->cache[i-1];
        }
        c->cache[0] = *new_record;
    }
    return;
error_handling:
    fprintf(stderr, "Error allocating memory\n");
    free(c);
}

void update(cache *c, void *key, int value) {
    record *r = find_in_data(c, key);
    if (!r) return; // Key not found in the data structure
    r->value = value;
}

// Similar batch delete implementation

// Implement persistence layer integration and logging functions
```

