        free(record->user_id);
    }
    free(record);
}

int cumulative_sum(const Record* records, size_t count, int* total) {
    for (size_t i = 0; i < count; ++i) {
        *total += records[i].key;
    }
    return *total;
}

void manage_collection(int min, int max, int limit, size_t memory_threshold) {
    Record* collection = NULL;
    size_t count = 0;
    int total = 0;

    while (1) {
        int current_sum = cumulative_sum(collection, count, &total);
        if (current_sum > limit) {
            log("Warning: The cumulative sum of the current collection exceeds the specified limit.");
            break;
        }

        if (memory_usage() > memory_threshold && count > 0) {
            free_record(collection[rand() % count]);
            --count;
        }

        Record* new_record = create_record(min, max);
        collection = realloc(collection, sizeof(Record) * (count + 1));
        if (!collection) {
            log("Error: Failed to reallocate memory for the collection.");
            exit(EXIT_FAILURE);
        }
        collection[count] = *new_record;
        ++count;
    }

    // Log memory usage statistics here.
}
