#include <atomic>
#include <chrono>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <unordered_map>
#include <vector>

// Define the Task structure
struct Task {
    std::string name;
    double priority;
    struct timestamp {
        std::chrono::system_clock::time_point lastUpdate;
        // Add more timestamp fields as needed
    } lastUpdateTime;
};

// Thread-safe singly linked list node for Task
struct TaskNode {
    std::unique_ptr<Task> task;
    std::unique_ptr<TaskNode> next;
    std::atomic<bool> isDeleted = false;

    TaskNode(std::unique_ptr<Task> t, std::unique_ptr<TaskNode> n)
        : task(std::move(t)), next(std::move(n)) {}
};

class TaskCollection {
public:
    // Initialize the TaskCollection with given parameters (e.g., storage path, log file)
    void init(const std::string& storagePath, const std::string& logFile);

    // Add a new task to the collection, returning the added task if successful or null if failed
    Task* addTask(const std::string& name, double priority);

    // Update the last update time of an existing task by its name, returning true if found and updated or false otherwise
    bool updateTask(const std::string& name);

    // Remove a task from the collection by its name, returning true if found and removed or false otherwise
    bool removeTask(const std::string& name);

private:
    // Thread-safe linked list operations
    void insertNodeSafe(TaskNode* newNode);
    TaskNode* findTaskNode(const std::string& name);
    void eraseNodeSafe(TaskNode* nodeToDelete);

    // Hash table for efficient lookups and dynamic allocation
    std::unordered_map<std::string, std::unique_ptr<TaskNode>> tasks;
    std::mutex tasksMutex;

    // Persistent storage system
    using Storage = std::unique_ptr<StorageSystem>;
    Storage storage;

    // Logging mechanism
    boost::log::trivial::logger logger;
};
