  2. Java Function (disjoint pairs using Union-Find):

```java
import java.util.*;

public class PairFinder {
    private int[] parent;
    private int[] rank;

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path Compression
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;

        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
            rank[rootY] += rank[rootX];
        } else {
            parent[rootY] = rootX;
            rank[rootX] += rank[rootY];
        }
    }

    public int countPairs(int[] arr) {
        int n = arr.length;
        this.parent = new int[n];
        this.rank = new int[n];

        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            rank[i] = 1;
        }

        long startTime = System.currentTimeMillis();
        int pairs = 0;
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (find(arr[i]) != find(arr[j])) {
                    union(arr[i], arr[j]);
                    pairs++;
                }
            }
        }
        long elapsedTime = System.currentTimeMillis() - startTime;

        System.out.printf("Number of disjoint pairs: %d\n", pairs);
        System.out.printf("Elapsed time (ms): %d\n", elapsedTime);
        return pairs;
    }
}
