// Namespace for memory allocation
void* namespace_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        // Attempt to allocate in different block of memory
        ptr = malloc(size);
        if (!ptr) {
            abort();
        }
    }
    return ptr;
}

void log_memory_operation(const char* operation, void* ptr, size_t size) {
    // Implement logging system here that supports high-throughput environments without introducing bottlenecks
}

// Thread-safe random number generator using pthread mutex
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;
void thread_rand(int* seed) {
    if (seed == NULL) {
        // Seed with current time to have unique values each time the function is called
        time_t now = time(NULL);
        *seed = (int)now;
    }
    pthread_mutex_lock(&rand_mutex);
    int random = *seed % RAND_MAX;
    *seed = (*seed + 1) % RAND_MAX;
    pthread_mutex_unlock(&rand_mutex);
    return random;
}

void init_data(size_t N, size_t* offsets, int* keys, record** records, int minValue, int maxValue) {
    // Initialize arrays with given parameters
    offsets = (size_t*)namespace_alloc(N * sizeof(size_t));
    keys = (int*)namespace_alloc(N * sizeof(int));
    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
    }
    *records = (record*)namespace_alloc(N * sizeof(record));

    // Set values to random unique integers within the specified range, using pthread for thread-safe random number generation
    record* records_ptr = *records;
    int current_value, used_values[MAXINT]; // Adjust MAXINT as needed for your integer limit
    memset(used_values, -1, sizeof(used_values));

    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i) {
        int idx = i; // To make the closure work correctly with pthreads
        pthread_create(&threads[i], NULL, (void*(*)(void*))[](void* arg) {
            for (size_t j = 0; j < N; ++j) {
                while (1) {
                    current_value = thread_rand(&idx);
                    if (used_values[current_value] == -1) {
                        used_values[current_value] = idx; // Mark the value as used in this thread
                        records_ptr[j].value = current_value;
                        break;
                    }
                }
            }, &idx);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Log successful memory allocation and initialization operation
    log_memory_operation("Allocation", offsets, sizeof(size_t) * N);
    log_memory_operation("Allocation", keys, sizeof(int) * N);
    log_memory_operation("Allocation", records, sizeof(record) * N);
}

// Context manager pattern for automatic memory deallocation on function exit
void init_data_context(size_t N, size_t* offsets, int* keys, record** records, int minValue, int maxValue) {
    init_data(N, offsets, keys, records, minValue, maxValue);

    free(offsets);
    free(keys);
    free(*records);
}
```

