typedef struct {
    int id;
    char *setting;
    struct device_config *next;
} device_config;

typedef struct {
    device_config *head;
    device_config *tail;
    // Other necessary device structure members
} network_device;

device_config* filter_and_update(int *settings, int num_settings, network_device *dev, int start_id, int end_id) {
    if (start_id > end_id || start_id < 0 || end_id < 0) {
        perror("Invalid range");
        return NULL;
    }

    device_config *new_head = NULL, *new_tail = NULL, *current = dev->head;
    for (int i = 0; i < num_settings; ++i) {
        while (current && current->id < start_id)
            current = current->next;

        if (!current || current->id > end_id)
            continue; // Setting not within the specified range, skip to next setting

        device_config *new_setting = malloc(sizeof(device_config));
        if (!new_setting) {
            perror("Memory allocation failure");
            return NULL;
        }

        new_setting->id = current->id;
        new_setting->setting = strdup(current->setting); // Handle potential string duplication issues
        if (!new_setting->setting) {
            free(new_setting);
            perror("Memory allocation failure");
            return NULL;
        }

        if (!new_head) {
            new_head = new_tail = new_setting;
        } else {
            new_tail->next = new_setting;
            new_tail = new_setting;
        }
    }

    if (new_head) { // If a new configuration list was created, update the device's configuration and return it
        new_tail->next = dev->tail ? dev->tail->next : NULL;
        dev->tail = new_tail;
    }

    return new_head;
}
