import asyncio
from base64 import encode, decode, urlsafe_encode, urlsafe_decode
import gzip
import zlib
import hashlib

class DataProcessor:
    def __init__(self):
        self.pipeline = Pipeline()

    async def process(self, stream, chunk_size=8192):
        for chunk in iter(lambda: stream.read(chunk_size), b""):
            for transform in self.pipeline.stages:
                if transform["type"] == "hash":
                    digest = hashlib.new(transform["algorithm"], chunk).digest()
                    await asyncio.sleep(0)  # Yield control to other tasks/streams
                    stream.write(digest)
                elif transform["type"] == "compression":
                    if transform["algorithm"] == "gzip":
                        compressed = gzip.compress(chunk)
                    elif transform["algorithm"] == "zstd":
                        compressed = zlib.compress(chunk, zlib.MAX_WBITS + 15)
                    await asyncio.sleep(0)  # Yield control to other tasks/streams
                    stream.write(compressed)
                elif transform["type"] == "encoding":
                    if transform["algorithm"] == "Base64":
                        encoded = encode(chunk).decode("utf-8")
                    elif transform["algorithm"] == "URLSafeBase64":
                        encoded = urlsafe_encode(chunk).decode("utf-8")
                    await asyncio.sleep(0)  # Yield control to other tasks/streams
                    stream.write(encoded.encode())
                else:  # Null stage for testing purposes
                    pass
            await asyncio.sleep(0)  # Yield control to other tasks/streams

class Pipeline:
    def __init__(self):
        self.stages = []

    async def add_stage(self, transform_dict):
        stage = {k: v for k, v in transform_dict.items() if k != "type"}
        self.stages.append({"type": "null", **stage})  # Default to null stage
        self.stages.append({"type": transform_dict["type"], **transform_dict})
