["```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    int value;
    long offset;
} Record;

struct System {
    size_t capacity;
    size_t count;
    long *offsets;
    int *keys;
    Record *records;
    sem_t mutex; // Thread synchronization
    sem_t mem_full; // Memory full condition variable
    sem_t mem_empty; // Memory empty condition variable
};

void init_system(struct System **system, size_t capacity) {
    *system = malloc(sizeof(struct System));
    (*system)->capacity = capacity;
    (*system)->count = 0;
    (*system)->offsets = calloc(capacity + 1, sizeof(long));
    (*system)->keys = malloc((capacity + 1) * sizeof(int));
    (*system)->records = malloc((capacity + 1) * sizeof(Record));
    sem_init(&(*system)->mutex, 0, 1);
    sem_init(&(*system)->mem_full, 0, 0);
    sem_init(&(*system)->mem_empty, 0, capacity);
}

void destroy_system(struct System *system) {
    free(system->offsets);
    free(system->keys);
    free(system->records);
    sem_destroy(&system->mutex);
    sem_destroy(&system->mem_full);
    sem_destroy(&system->mem_empty);
    free(system);
}

int insert_record(struct System *system, int key, int value) {
    if (system->count == system->capacity) {
        sem_wait(&system->mem_full);
        if (system->count == system->capacity) { // Memory full condition persists even after waiting
            return -1;
        }
    }

    bool duplicate = false;
    for (size_t i = 0; i < system->count; ++i) {
        if (system->keys[i] == key) {
            duplicate = true;
            break;
        }
    }

    if (duplicate) return -1; // Duplicate key found

    system->offsets[system->count + 1] = system->count > 0 ? system->offsets[system->count] : 0;
    system->keys[system->count] = key;
    system->records[system->count].value = value;
    system->records[system->count].offset = system->offsets[system->count + 1];
    ++(system->count);

    sem_post(&system->mem_empty); // Notify that one slot is available
    return 0;
}

// Function for handling concurrent access and managing memory usage.
```

