#define MAX_RECORDS 65536
#define RANDOM_MAX 1000000

int dns_lookup(const char *hostname, char **ip) {
    struct hostent *he;
    if ((he = gethostbyname(hostname)) == NULL) {
        herrno_t err = h_errno;
        if (err != 0) {
            fprintf(stderr, "gethostbyname: %s\n", hstrerror(err));
            return -1;
        }
        return -2;
    }
    *ip = strdup(he->h_addr_list[0]->s_addr);
    return 0;
}

int dns_cache(char **cache, int *count, char *hostname, char *ip) {
    int i;
    for (i = 0; i < *count; ++i) {
        if (!strcmp(cache[i], hostname)) {
            return -3; // Host already in cache
        }
    }

    if (*count >= MAX_HOSTNAMES) {
        return -4; // Cache is full
    }

    *cache[*count] = strdup(hostname);
    ++(*count);

    return 0;
}

int initialize(Record **records, int *num_records, long *offsets, int *keys, char ***hostnames, int *num_hostnames) {
    *records = malloc(MAX_RECORDS * sizeof(Record));
    if (!*records) {
        perror("malloc: records");
        return -1;
    }

    *offsets = malloc(MAX_HOSTNAMES * sizeof(long));
    if (!*offsets) {
        perror("malloc: offsets");
        free(*records);
        return -1;
    }

    *keys = malloc(MAX_HOSTNAMES * sizeof(int));
    if (!*keys) {
        perror("malloc: keys");
        free(*offsets);
        free(*records);
        return -1;
    }

    *hostnames = malloc(MAX_HOSTNAMES * sizeof(char*));
    if (!*hostnames) {
        perror("malloc: hostnames");
        free(*keys);
        free(*offsets);
        free(*records);
        return -1;
    }

    memset(*offsets, 0, MAX_HOSTNAMES * sizeof(long));
    memset(*keys, 0, MAX_HOSTNAMES * sizeof(int));
    *num_records = *num_hostnames = 0;

    return 0;
}

int populate(Record **records, int num_records, long *offsets, int *keys, char ***hostnames, int num_hostnames) {
    int i, j;
    for (i = 0; i < num_hostnames; ++i) {
        if (dns_lookup((*hostnames)[i], &(*offsets)[i]) != 0) {
            perror("dns_lookup");
            return -1;
        }
        if (dns_cache(*hostnames, &num_hostnames, (*hostnames)[i], inet_ntoa(((struct in6_addr *)((*offsets)[i]))))) {
            perror("dns_cache");
            return -1;
        }
    }

    for (i = 0; i < num_hostnames; ++i) {
        srandom(*offsets[i]);
        (*records)[j++].key = (*keys)[i] = keys[i]++;
        (*records)[j++].offset = offsets[i];
    }

    return 0;
}

int main() {
    Record *records;
    long *offsets;
    int *keys, num_records, num_hostnames;
    char **hostnames;

    if (initialize(&records, &num_records, &offsets, &keys, &hostnames, &num_hostnames)) {
        perror("initialize");
        return -1;
    }

    // Fill 'hostnames' array with hostnames to resolve
    // ...

    if (populate(&records, num_records, offsets, keys, &hostnames, num_hostnames)) {
        perror("populate");
        return -1;
    }

    // Use the records, offsets and keys arrays for further processing...

    free(offsets);
    free(keys);
    free(hostnames);
    free(records);

    return 0;
}
