#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h> // For posix_memalign

typedef struct {
    int value;
    size_t offset;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static long *offsets = NULL;
static int *keys = NULL;
static record *records = NULL;
static size_t capacity = 0;
static size_t offset_cap = 0;
static size_t key_cap = 0;
static size_t record_cap = 0;

void init_pipeline(size_t initial_capacity) {
    if (initial_capacity == 0) {
        initial_capacity = 16;
    }

    capacity = initial_capacity;
    offsets = malloc(sizeof(long) * capacity);
    posix_memalign((void **)&keys, 64, sizeof(int) * capacity);
    posix_memalign((void **)&records, 64, sizeof(record) * capacity);

    // Initialize to avoid null pointer access in the following steps.
    offsets[0] = -1;
}

void free_pipeline() {
    free(offsets);
    free(keys);
    free(records);
    capacity = 0;
}

bool add_record(int key, int value) {
    if (pthread_mutex_lock(&mutex) != 0) {
        return false;
    }

    size_t i;
    for (i = 0; i < capacity; ++i) {
        if (keys[i] == key && records[i].value == value) {
            pthread_mutex_unlock(&mutex);
            return false;
        }
        if (keys[i] == 0) {
            keys[i] = key;
            records[i].value = value;
            records[i].offset = offsets[i];
            offsets[i] = i + 1;
            pthread_mutex_unlock(&mutex);
            return true;
        }
    }

    if (capacity == record_cap) {
        expand();
    }

    size_t last = capacity - 1;
    keys[last] = key;
    records[last].value = value;
    records[last].offset = offsets[last];
    offsets[last] = offsets[i];
    offsets[i] = last + 1;

    pthread_mutex_unlock(&mutex);
    return true;
}

void expand() {
    size_t new_capacity = capacity * 2;
    long *new_offsets = malloc(sizeof(long) * new_capacity);
    int *new_keys = realloc(keys, sizeof(int) * new_capacity);
    record *new_records = realloc(records, sizeof(record) * new_capacity);

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        // Handle memory allocation failure.
        return;
    }

    posix_memalign((void **)&new_records, 64, sizeof(record) * new_capacity);

    if (offsets != NULL) {
        memcpy(new_offsets, offsets, sizeof(long) * capacity);
    }
    if (keys != NULL) {
        memcpy(new_keys, keys, sizeof(int) * capacity);
    }

    free(offsets);
    free(keys);
    free(records);

    offsets = new_offsets;
    keys = new_keys;
    records = new_records;
    record_cap *= 2;
}
