#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>

typedef struct {
    int value;
    size_t offset;
    char *metadata;
} Record;

struct System {
    size_t offsets_capacity, offsets_size;
    long *offsets;

    size_t keys_capacity, keys_size;
    int *keys;

    size_t records_capacity, records_size;
    Record *records;

    size_t metadata_capacity, metadata_size;
    char **metadata;

    size_t map_capacity, map_size;
    int *map_keys;
    char **map_values;

    pthread_mutex_t lock;
    sem_t sem_mem_usage;
};

void init_system(struct System *system, size_t offsets_capacity, size_t keys_capacity, size_t records_capacity) {
    system->offsets = mmap(NULL, sizeof(long) * offsets_capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (system->offsets == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    system->keys = malloc(sizeof(int) * keys_capacity);
    if (!system->keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    system->records = malloc(sizeof(Record) * records_capacity);
    if (!system->records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    system->metadata = malloc(sizeof(char*) * records_capacity);
    if (!system->metadata) {
        fprintf(stderr, "Failed to allocate memory for metadata.\n");
        exit(EXIT_FAILURE);
    }

    system->map_keys = malloc(sizeof(int) * keys_capacity);
    if (!system->map_keys) {
        fprintf(stderr, "Failed to allocate memory for map_keys.\n");
        exit(EXIT_FAILURE);
    }

    system->map_values = malloc(sizeof(char*) * keys_capacity);
    if (!system->map_values) {
        fprintf(stderr, "Failed to allocate memory for map_values.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&system->lock, NULL);
    sem_init(&system->sem_mem_usage, 0, 1);
}

void free_system(struct System *system) {
    munmap(system->offsets, sizeof(long) * system->offsets_capacity);
    free(system->keys);
    free(system->records);
    free(system->metadata);
    free(system->map_keys);
    free(system->map_values);
    pthread_mutex_destroy(&system->lock);
    sem_destroy(&system->sem_mem_usage);
}

// ... (Add functions for adding records, validating keys, monitoring memory usage, and handling concurrent access)
