```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long value;
    int key;
} record;

struct data_manager {
    long *offsets;
    int *keys;
    record *records;
    size_t offset_capacity, offset_size;
    size_t key_capacity, key_size;
    size_t record_capacity, record_size;
    pthread_mutex_t lock;
};

struct data_manager* create_data_manager(size_t initial_capacity);
void destroy_data_manager(struct data_manager *manager);
void resize_offsets(struct data_manager *manager);
void resize_keys(struct data_manager *manager);
record* create_record();
void insert_record(struct data_manager *manager, int key, long value);
long get_next_offset(struct data_manager *manager);
int find_key(struct data_manager *manager, int key);

// Implement the functions as follows:

struct data_manager* create_data_manager(size_t initial_capacity) {
    struct data_manager *manager = malloc(sizeof(struct data_manager));
    if (!manager) return NULL;

    manager->offsets = calloc(initial_capacity, sizeof(long));
    if (!manager->offsets) goto error;
    manager->keys = calloc(initial_capacity, sizeof(int));
    if (!manager->keys) goto error;
