#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define LOG_FILE "database.log"
#define MEMORY_THRESHOLD 90

typedef struct {
    int key;
    long offset;
    pthread_mutex_t mutex;
} Record;

struct Database {
    Record* records;
    size_t current_size;
    size_t max_size;
    FILE* log_file;
};

void log(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        log("Out of memory: Failed to allocate Record");
        return NULL;
    }
    pthread_mutex_init(&record->mutex, NULL);
    return record;
}

void destroy_record(Record* record) {
    pthread_mutex_destroy(&record->mutex);
    free(record);
}

struct Database* create_database() {
    struct Database* db = malloc(sizeof(Database));
    if (!db) {
        log("Out of memory: Failed to allocate Database");
        return NULL;
    }
    db->records = calloc(MAX_RECORDS, sizeof(Record));
    if (!db->records) {
        log("Out of memory: Failed to allocate Records array");
        free(db);
        return NULL;
    }
    db->current_size = 0;
    db->max_size = MAX_RECORDS;
    db->log_file = fopen(LOG_FILE, "w");
    if (!db->log_file) {
        log("Failed to open log file");
    }
    return db;
}

void destroy_database(struct Database* db) {
    for (size_t i = 0; i < db->current_size; ++i) {
        destroy_record(db->records[i]);
    }
    free(db->records);
    fclose(db->log_file);
    free(db);
}

int get_random_key(struct Database* db) {
    time_t now = time(NULL);
    int seed = (int)(now * now + now + 1);
    srand(seed);
    int key;
    do {
        key = rand() % (db->max_size / 2);
    } while (key < db->current_size && db->records[key].key == key);
    return key;
}

void* insert_record(void* arg) {
    struct Database* db = arg;
    int key = get_random_key(db);
    Record* record = create_record();
    if (!record) return NULL;
    record->key = key;
    record->offset = (long) rand() * RAND_MAX;
    pthread_mutex_lock(&record->mutex);
    for (size_t i = 0; i < db->current_size; ++i) {
        if (db->records[i].key == key) {
            pthread_mutex_unlock(&record->mutex);
            destroy_record(record);
            return NULL;
        }
    }
    for (size_t i = 0; i < db->current_size; ++i) {
        if (db->records[i].key > key) {
            memmove(&(db->records[i + 1]), &(db->records[i]), (db->current_size - i) * sizeof(Record));
            break;
        }
    }
    db->records[key] = *record;
    ++(db->current_size);
    pthread_mutex_unlock(&record->mutex);
    return record;
}

long* find_offset(struct Database* db, int key) {
    for (size_t i = 0; i < db->current_size; ++i) {
        if (db->records[i].key == key) {
            return &(db->records[i].offset);
        }
    }
    return NULL;
}

void print_memory_usage(struct Database* db) {
    double memory_percentage = ((double)(db->current_size * sizeof(Record)) / (double)getpagesize()) * 100.0;
    if (memory_percentage >= MEMORY_THRESHOLD) {
        log("Memory usage warning: Reached %f%% of memory limit", memory_percentage);
    } else if (memory_percentage > 80) {
        log("Memory usage alert: Approaching %f%% of memory limit", memory_percentage);
    }
}
```

