// Maximum number of concurrent threads allowed
#define MAX_THREADS 16

// Record structure definition
typedef struct {
    int value;
} record;

// Global memory pool for efficient resource allocation (optional, can be replaced with local pool)
record* global_memory_pool = NULL;
size_t global_memory_pool_capacity = 0;
size_t global_memory_pool_count = 0;

pthread_mutex_t global_memory_pool_lock;

// Function to load resource bundle, validate structure, and return number of items.
size_t load_resource_bundle(const char* file_path, const char* bundle_identifier, int minValue, int maxValue, bool threadSafe) {
    FILE* fp = fopen(file_path, "r");
    if (!fp) {
        return 0;
    }

    // Metadata and resource buffer storage.
    size_t metadata_size, item_count, offsets_capacity, keys_capacity, records_capacity;
    fread(&metadata_size, sizeof(size_t), 1, fp);
    record* records = NULL;
    int* keys = NULL;
    long* offsets = malloc(metadata_size * sizeof(long));

    if (threadSafe) {
        pthread_mutex_init(&global_memory_pool_lock, NULL);
    }

    // Read metadata and resources from file.
    fseek(fp, 0, SEEK_SET);
    fread(&item_count, sizeof(size_t), 1, fp);
    fread(&offsets_capacity, sizeof(size_t), 1, fp);
    fread(&keys_capacity, sizeof(size_t), 1, fp);
    fread(&records_capacity, sizeof(size_t), 1, fp);

    if (metadata_size != (offsets_capacity + 1) || item_count > metadata_size || offsets_capacity < 2 || keys_capacity < item_count || records_capacity < item_count) {
        fclose(fp);
        free(offsets);
        return 0;
    }

    // Initialize key array with sequential integers.
    keys = calloc(keys_capacity, sizeof(int));
    for (size_t i = 0; i < item_count; ++i) {
        keys[i] = i;
    }

    // Allocate and initialize record array with unique random values.
    records = malloc(records_capacity * sizeof(record));
    for (size_t i = 0; i < item_count; ++i) {
        records[i].value = minValue + rand() % (maxValue - minValue + 1);
    }

    // Read offsets from file and ensure they are sorted.
    fseek(fp, sizeof(metadata_size) + sizeof(item_count) + sizeof(offsets_capacity) + sizeof(keys_capacity) + sizeof(records_capacity), SEEK_SET);
    for (size_t i = 0; i < offsets_capacity; ++i) {
        fread(&offsets[i], sizeof(long), 1, fp);
    }

    qsort(offsets, offsets_capacity, sizeof(long), (int (*)(const void*, const void*)) compareLongs);

    // Validate that offsets are non-decreasing and within range.
    for (size_t i = 1; i < offsets_capacity; ++i) {
        if (offsets[i - 1] > offsets[i]) {
            fclose(fp);
            free(offsets);
            free(keys);
            free(records);
            return 0;
        }
    }

    // Set up memory management strategy for concurrent access.
    if (threadSafe) {
        pthread_t* threads = malloc(MAX_THREADS * sizeof(pthread_t));
        thread_local record** local_memory_pools = calloc(MAX_THREADS, sizeof(record*));
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            pthread_create(&threads[i], NULL, manage_resource_pool, (void*)local_memory_pools + i);
        }
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
        free(threads);
    }

    // Return number of items in the resource bundle.
    return item_count;
}

// Function to manage a local memory pool for each thread.
void* manage_resource_pool(void* arg) {
    record** local_memory_pool = (record**)arg;
    size_t capacity = global_memory_pool_capacity;
    if (local_memory_pool) {
        capacity = *((size_t*)local_memory_pool);
    }
    size_t count = 0;

    // Allocate and initialize local memory pool.
    record* local_memory_pool_buffer = malloc(capacity * sizeof(record));
    if (global_memory_pool) {
        memcpy(local_memory_pool_buffer, global_memory_pool, capacity * sizeof(record));
    }

    while (1) {
        pthread_mutex_lock(&global_memory_pool_lock);
        record* record_to_allocate = NULL;
        if (count < capacity && global_memory_pool_count > 0) {
            record_to_allocate = &global_memory_pool[global_memory_pool_count - 1];
            global_memory_pool_count--;
        }
        pthread_mutex_unlock(&global_memory_pool_lock);

        if (record_to_allocate) {
            local_memory_pool_buffer[count] = *record_to_allocate;
            count++;
        } else {
            // Use global memory pool when local memory is exhausted.
            if (global_memory_pool && global_memory_pool_capacity > count) {
                pthread_mutex_lock(&global_memory_pool_lock);
                record* record_to_allocate = &global_memory_pool[count];
                record_to_allocate->value = rand() % (maxValue - minValue + 1) + minValue;
                count++;
                pthread_mutex_unlock(&global_memory_pool_lock);
            } else {
                break;
            }
        }
    }

    *((size_t*)local_memory_pool) = count;
    return NULL;
}

// Function to free all allocated memory.
void cleanup() {
    if (global_memory_pool) {
        free(global_memory_pool);
    }
    if (records) {
        free(records);
    }
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }
}

// Function to compare two long integers for qsort.
int compareLongs(const void* a, const void* b) {
    return (*(long*)a - *(long*)b);
}

// Entry point function.
int main() {
    srand((unsigned int)time(NULL));
    int item_count = load_resource_bundle("data/mydata.bin", &records, &keys, &offsets);
    for (int i = 0; i < item_count; ++i) {
        printf("%d ", records[i].value);
    }
    cleanup();
    return 0;
}

