        free(arr_dbl);
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    item **arr_item = (item**)calloc(num_items, sizeof(item*));
    if (!arr_item) {
        perror("Error allocating memory for items");
        free(arr_dbl);
        free(arr_char);
        return NULL;
    }

    item init_item = {"", 0};
    pthread_mutex_t *item_locks = (pthread_mutex_t*)calloc(num_items, sizeof(pthread_mutex_t));
    if (!item_locks) {
        perror("Error allocating item locks");
        free(arr_dbl);
        free(arr_char);
        free(arr_item);
        return NULL;
    }

    srand(seed);
    for (size_t i = 0; i < num_items; ++i) {
        char str[256];
        snprintf(str, sizeof(str), "%.*s%d", rand() % 127 + 32, "", rand() % 10000); // Generate a random ASCII string of up to 255 characters

        pthread_mutex_init(&item_locks[i], NULL);
        arr_item[i] = (item*)calloc(1, sizeof(item));
        if (!arr_item[i]) {
            perror("Error allocating memory for item");
            free(str);
            pthread_mutex_destroy(&lock);
            pthread_mutex_destroy(&item_locks[i]);
            free(arr_dbl);
            free(arr_char);
            free(arr_item);
            free(item_locks);
            return NULL;
        }
        memcpy(arr_item[i], &init_item, sizeof(item)); // Initialize each item with a default empty string and 0 identifier

        pthread_mutex_lock(&item_locks[i]);
        strcpy(arr_item[i]->str, str);
        arr_item[i]->id = rand() % 10000; // Set the item's identifier to a random number within the given range
        pthread_mutex_unlock(&item_locks[i]);
    }

    return arr_item;
}

void deallocate(item** arr, size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
        if (arr[i]) {
            pthread_mutex_destroy(&arr[i]->lock);
            free(arr[i]);
        }
    }
    free(arr);
}
