#include <pthread.h>

typedef struct data_item {
    char str[32];
    int id;
    double value;
} data_item;

// Thread-safe memory allocation function using pthread_mutex_t for synchronization
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        pthread_mutex_lock(&g_mutex);
        ptr = malloc(size);
        if (!ptr) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&g_mutex);
            exit(EXIT_FAILURE);
        }
        pthread_mutex_unlock(&g_mutex);
    }
    return ptr;
}

// Initialize and populate arrays with data
void init_arrays(size_t* dArr, char** cArr, unsigned long* tArr, data_item** diArr, size_t num_items) {
    *dArr = safe_malloc(num_items * sizeof(double));
    *cArr = safe_malloc(num_items * sizeof(char));
    *tArr = safe_malloc(num_items * sizeof(unsigned long));
    *diArr = safe_malloc(num_items * sizeof(data_item));

    // Initialize double array with random numbers
    for (size_t i = 0; i < num_items; ++i) {
        (*dArr)[i] = (double)(rand() % MAX_RANDOM_DOUBLE);
    }

    // Initialize char array with unique character sequences
    for (size_t i = 0; i < num_items; ++i) {
        sprintf((*cArr + i), "%c%lu", 'a' + (i % 26), i);
    }

    // Initialize timestamp array with current time in microseconds
    for (size_t i = 0; i < num_items; ++i) {
        (*tArr)[i] = (unsigned long)(get_microseconds());
    }

    // Initialize struct array with unique strings, random ids and values
    for (size_t i = 0; i < num_items; ++i) {
        sprintf((*diArr + i)->str, "%c%lu", 'A' + (i % 26), i);
        (*diArr + i)->id = rand() % MAX_RANDOM_INT;
        (*diArr + i)->value = (double)(rand() % MAX_RANDOM_DOUBLE);
    }
}

// Helper function to calculate microseconds since the Unix Epoch
unsigned long get_microseconds(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (unsigned long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
}

// Global mutex to protect safe_malloc from concurrent access
pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
