const stream = require('stream');
const { promisify } = require('util');
const https = require('https');
const fs = require('fs');
const readline = require('readline');

class OAuthRequestParser extends stream.Readable {
  constructor(request) {
    super();
    this._request = request;
    this._key = '';
    this._cert = '';
    this._pause = false;
  }

  _read() {
    if (this._pause) return;

    const chunkSize = 1024; // Adjust according to your requirements
    const data = this._request.slice(this._offset, this._offset + chunkSize);

    if (!data || !data.length) {
      this.push(null);
      return;
    }

    this._offset += data.length;

    if (data[0] === 42) { // PEM header detection
      const boundaryIndex = data.indexOf('\n--');
      const line = data.slice(0, boundaryIndex);

      if (line.startsWith('PRIVATE KEY')) this._key += line;
      else if (line.startsWith('CERTIFICATE')) this._cert += line;

      this.push(data.slice(boundaryIndex));
    } else {
      this._key += data;
      this._cert += data;
      this.push(data);
    }
  }

  pause() {
    this._pause = true;
  }

  resume() {
    this._pause = false;
  }

  async generatePEMCertificateFromOAuthRequest(timeout) {
    const timeoutId = setTimeout(() => this.emit('error', new Error('Timeout reached')), timeout);

    try {
      this.resume();
      await new Promise((resolve) => this.on('end', resolve));

      if (this._key && this._cert) {
        const pem = `${this._key}\n${this._cert}`;
        this.emit('data', pem);
      } else {
        this.emit('error', new Error('Could not generate PEM certificate.'));
      }
    } catch (err) {
      clearTimeout(timeoutId);
      this.emit('error', err);
    }
  }
}

// Usage example:
const request = https.request(/* your OAuth request here */);
const parser = new OAuthRequestParser(request);
parser.generatePEMCertificateFromOAuthRequest(3000);
