using namespace boost::beast;
using namespace curl;

struct ServerInfo {
    string url;
    size_t response_time = 0;
    int load = 0;
};

class LoadBalancer {
public:
    void addServer(const ServerInfo& server) { servers_.insert(server); }

    ServerInfo getNextServer() {
        auto it = servers_.begin();
        if (it == servers_.end()) throw runtime_error("No servers available");
        auto best_server = *it;
        size_t min_load = best_server.load;

        for (auto server = ++it; server != servers_.end(); ++it) {
            if (server->load < min_load) {
                best_server = *server;
                min_load = server->load;
            }
        }

        best_server.response_time += chrono::duration_cast<chrono::milliseconds>(
                                       steady_clock::now() - best_server.last_request_time)
                                           .count();
        best_server.load++;
        best_server.last_request_time = steady_clock::now();

        return best_server;
    }

private:
    set<ServerInfo> servers_;
};

struct RequestData {
    int id;
    curl_easy_handle* easy;
};

class HttpClient {
public:
    void start(const ServerInfo& server, size_t request_id) {
        RequestData data{request_id, curl_easy_init()};
        if (!data.easy) throw runtime_error("Failed to initialize cURL");

        auto strand = io_context_.get_strand();
        auto callback = [this, &data](curl_transfer_info transferInfo) {
            constexpr int MAX_RETRIES = 3;
            if (transferInfo.data != data.easy) return false;
            if (transferInfo.result != CURLE_OK && ++data.id < MAX_RETRIES) return true;

            curl_easy_cleanup(data.easy);
            data.easy = nullptr;

            // Handle error here, notify administrator if necessary
            cout << "Error: Request " << data.id << " failed" << endl;

            return false;
        };

        curl_easy_setopt(data.easy, CURLOPT_URL, server.url.c_str());
        curl_easy_setopt(data.easy, CURLOPT_WRITEFUNCTION, [](void* buffer, size_t size, size_t nmemb, void* stream) {
            auto input = static_cast<char*>(buffer);
            for (size_t i = 0; i < size * nmemb; ++i) {
                int number = static_cast<int>(input[i]);
                // Process the integer here, update the dynamically allocated array and call the helper function
            }
            return size * nmemb;
        });
        curl_easy_setopt(data.easy, CURLOPT_ERRORBUFFER, "");
        curl_easy_setopt(data.easy, CURLOPT_FAILONERROR, true);
        curl_easy_setopt(data.easy, CURLOPT_NOSIGNAL, 1L); // Prevent cURL from terminating the application on errors
        curl_easy_setopt(data.easy, CURLOPT_TIMEOUT, 5.0); // Set timeout to 5 seconds
        curl_easy_setopt(data.easy, CURLOPT_VERBOSE, 0L); // Disable verbose output for cleaner logging
        curl_easy_setopt(data.easy, CURLOPT_USERAGENT, "MyDynamicHTTPClient/1.0");

        strand.wrap([this, data](io_service& io) {
            try {
                curl_easy_perform(data.easy);
                io.post(strand); // Call post() to continue processing other tasks in the strand
            } catch (const exception& e) {
                cout << "Error: Request " << data.id << ": " << e.what() << endl;
            }
        }, io_context_);

        request_data_.insert(data);
    }

    void stop() {
        for (auto& req : request_data_) {
            curl_easy_cleanup(req.second.easy);
        }
        request_data_.clear();
    }

private:
    io_context io_context_;
    multiset<RequestData> request_data_;
};

