#include <curl/curl.h>

struct FSA {
    std::map<int, std::vector<std::pair<int, double>>> transitions;
};

class StateListManager {
private:
    int numStates;
    boost::ptr_vector<FSA*> stateTable;
    std::string apiKey;
    FSA* currentState;

    static thread_local curl_global_t *curlGlobal;
    static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
    }

public:
    StateListManager(int* states, int numStates, FSA* lastState, const std::string& apiKey) : numStates(numStates), stateTable(numStates + 1, nullptr) {
        for (int i = 0; i < numStates; ++i) {
            if (!stateTable[i]) {
                stateTable[i] = new FSA();
            }
            stateTable[i]->transitions = std::map<int, std::vector<std::pair<int, double>>>();
        }
        if (!stateTable[numStates]) {
            stateTable[numStates] = lastState;
        }
        this->apiKey = apiKey;
    }

    ~StateListManager() {
        for (FSA* state : stateTable) {
            delete state;
        }
    }

    FSA* getCurrentState() const {
        return currentState;
    }

    void setCurrentState(int newState) {
        if (newState < 0 || newState >= numStates) {
            throw std::invalid_argument("Invalid state");
        }
        if (currentState != stateTable[newState]) {
            currentState = stateTable[newState];
            // Fetch transition probabilities from API
            curl_easy_setopt(curlGlobal->handle, CURLOPT_URL, ("http://api.example.com/transition-probs?state=" + std::to_string(newState)).c_str());
            curl_easy_setopt(curlGlobal->handle, CURLOPT_WRITEFUNCTION, WriteCallback);
            curl_easy_setopt(curlGlobal->handle, CURLOPT_WRITEDATA, &currentState->transitions);
            curl_easy_perform(curlGlobal->handle);
        }
    }

    static void init() {
        // Initialize environment variables, load autoloader, and configure application from YAML file
    }

    static FSA* createStateList(int* states, int numStates, FSA* lastState, const std::string& apiKey) {
        if (stateTable.capacity() < numStates + 1) {
            stateTable.reserve(stateTable.capacity() * 2);
        }
        return new StateListManager(states, numStates, lastState, apiKey).stateTable[numStates];
    }
};

thread_local curl_global_t* StateListManager::curlGlobal = curl_global_init(CURL_GLOBAL_ALL);
