    memset(new_shapes + *size, 0, sizeof(shape));
    free(mem_pool->data);
    mem_pool->data = new_shapes;
    mem_pool->capacity *= growth_factor;
    mem_pool->used += (*size + 1) - *size;
    *shapes = mem_pool->data;
    *size *= growth_factor;
    pthread_mutex_unlock(&mem_lock);
