    std::unique_ptr<Record> acquire() {
        boost::mutex::scoped_lock lock(mu_);
        auto iter = cb_.in().push_back(data_.get());
        data_[*iter] = { 0 }; // Reset the value for reuse
        return std::move(data_[*iter]);
    }

    void release(std::unique_ptr<Record> rec) {
        boost::mutex::scoped_lock lock(mu_);
        data_[cb_.out().pop_front()] = *rec;
    }

private:
    std::unique_ptr<Record[]> data_;
    boost::circular_buffer<std::size_t> cb_; // Circular buffer to keep track of free records
    mutable boost::mutex mu_;              // Mutex for thread safety
    boost::mt19937 randGen_;                // Mersenne Twister pseudo-random number generator
};

void init(size_t N, size_t minValue, size_t maxValue) {
    auto offsets = std::make_unique<long[]>(N);
    std::iota(offsets.get(), offsets.get() + N, 0);

    auto keys = offsets.get();
    auto recordsPool = MemoryPool{N};
    auto records = recordsPool.acquire(); // Acquire a record from the pool

    boost::mutex::scoped_lock lock(mu_);
    boost::random_device rd;
    boost::uniform_int_distribution<> distrib(minValue, maxValue);

    for (size_t i = 0; i < N; ++i) {
        while (!distrib(rd) || std::find(records.begin(), records.end(), i) != records.end()) {} // Adjust the range and avoid collisions
        records[i] = distrib(rd);                   // Set the value of each record's int field to a random value
        keys[records[i]] = i;                      // Map each unique index to its corresponding random value
    }

    // Logging implementation goes here...
}
```

