[' Here's a high-level design for your request in C++, using Boost libraries and the Cryptopp library for MD5 hashing:

```cpp
#include <boost/thread.hpp>
#include <boost/filesystem.hpp>
#include <boost/random/mersenne_twister.hpp>
#include <boost/algorithm/string/join.hpp>
#include <cryptopp/filters.h>
#include <cryptopp/md5.h>
#include <vector>
#include <unordered_map>
#include <iostream>
#include <fstream>

namespace HashProcessing {
    class Node {
        public:
            Node() : rng(), thread(std::bind(&Node::process, this)) {}
            ~Node() {}

            void init(unsigned int seed) {
                boost::random::seed_seq seq{static_cast<unsigned long>(seed), static_cast<unsigned int>(seed * 2), static_cast<unsigned long>(seed * 3), static_cast<unsigned int>(seed * 4)};
                rng.seed(seq);
            }

            std::vector<std::string> process(const std::vector<std::string>& inputs, unsigned int numThreads) {
                results.clear();
                processedInputs.clear();

                for (auto& input : inputs) {
                    if (!input.empty()) {
                        processedInputs.insert(input);
                    }
                }

                thread.detach();

                while (processedInputs.size() > 0 && results.size() < inputs.size()) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }

                return results;
            }

        private:
            void process() {
                boost::filesystem::path cachePath("./cache");
                boost::filesystem::create_directories(cachePath);

                CryptoPP::MD5 hashFunction;
                std::stringstream ss;

                for (auto it = processedInputs.begin(); it != processedInputs.end(); ) {
                    auto const input = *it++;

                    if (cachedResults.find(input) != cachedResults.end()) {
                        results.insert(results.end(), cachedResults[input]);
                        continue;
                    }

                    CryptoPP::StringSource ss(input, true, new CryptoPP::ArraySink<byte>(buffer));
                    hashFunction.CalculateDigest(ss);

                    for (auto& byte : buffer) {
                        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<unsigned int>(byte);
                    }

                    auto hexHash = ss.str();
                    cachedResults[input] = hexHash;
                    boost::filesystem::ofstream file((cachePath / input + ".hex").string(), std::ios::binary);
                    file << hexHash;
                    file.close();

                    results.insert(results.end(), hexHash);
                }
            }

            boost::random::mt19937 rng;
            std::unordered_set<std::string> processedInputs, results;
            std::unordered_map<std::string, std::vector<std::string>> cachedResults;
            std::vector<byte> buffer;
            boost::thread thread;
    };
}
```

This code defines a `HashProcessing::Node` class that processes batches of strings by generating their MD5 hashes and caching frequently accessed results in disk-based cache for efficient memory usage. The class has an integrated Mersenne Twister random number generator as a member variable and can handle multi-threading using Boost libraries.

Integration into your existing system would require adding instances of this node, managing their lifecycles, and orchestrating the data flow between them to process up to 1 million strings per second without significant latency. You may also need to implement fault tolerance mechanisms to handle partial failures gracefully and ensure seamless integration with other components in your system architecture.']

