void* memory_pool_alloc(struct memory_pool* pool, size_t type) {
    switch (type) {
        case LONG:
            if (pool->array_long == NULL || pool->capacity <= 0) return NULL;
            break;
        case INT:
            if (pool->array_int == NULL || pool->capacity <= 0) return NULL;
            break;
        case RECORD:
            if (pool->array_record == NULL || pool->capacity <= 0) return NULL;
            break;
        default:
