[' C (ANSI C):

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} Record;

size_t array_size(size_t max) {
    size_t size = 1;
    while (size < max) size *= 2;
    return size;
}

long* allocate_offsets(size_t size) {
    long *offsets = (long*) malloc(sizeof(long) * size);
    if (!offsets) return NULL;
    for (int i = 0; i < size - 1; ++i) offsets[i] = i + 1;
    return offsets;
}

int* allocate_keys(size_t size) {
    int *keys = (int*) malloc(sizeof(int) * size);
    if (!keys) return NULL;
    for (int i = 0; i < size; ++i) keys[i] = rand() % 100;
    return keys;
}

Record* allocate_records(size_t size) {
    Record *records = (Record*) malloc(sizeof(Record) * size);
    if (!records) return NULL;
    for (int i = 0; i < size; ++i) records[i].key = rand() % 100;
    return records;
}

void populate_array(long *offsets, int *keys, Record **records, size_t max, size_t *size) {
    *size = array_size(max);
    long *new_offsets = allocate_offsets(*size);
    if (!new_offsets) return;
    int *new_keys = allocate_keys(*size);
    if (!new_keys) goto cleanup;
    Record *new_records = allocate_records(*size);
    if (!new_records) goto cleanup;

    for (int i = 0; i < *size - 1; ++i) {
        new_offsets[i] = offsets[i];
        new_keys[i] = keys[i];
        new_records[i].key = records[new_offsets[i] - 1]->key;
    }

    free(offsets);
    free(keys);
    *size -= 1;
    offsets = new_offsets;
    keys = new_keys;
    records = new_records;

cleanup:
    if (new_offsets) free(new_offsets);
    if (new_keys) free(new_keys);
    if (new_records) free(new_records);
}

void my_malloc_or_die(void *ptr, const char *msg) {
    if (!ptr) {
        fprintf(stderr, "%s\n", msg);
        exit(EXIT_FAILURE);
    }
}

void create_record_arrays(size_t max, long **offsets, int **keys, Record **records, size_t *records_size) {
    *offsets = allocate_offsets(1);
    my_malloc_or_die(*offsets, "Failed to allocate offset array");
    *keys = allocate_keys(1);
    my_malloc_or_die(*keys, "Failed to allocate key array");
    *records = allocate_records(1);
    my_malloc_or_die(*records, "Failed to allocate record array");

    populate_array(*offsets, *keys, *records, max, records_size);
}

