import os
import subprocess
import shlex

def replace_placeholders(config_file, replacements):
    command = ['sed', '-i', '{} {}'.format(*replacements)]
    process = subprocess.Popen(command, stdin=subprocess.PIPE, universal_newlines=True)
    try:
        for replacement in replacements:
            process.stdin.write('s/{}/{}/\n'.format(*replacement))
        process.stdin.close()
        process.wait(timeout=10)
    except subprocess.CalledProcessError as e:
        print("Sed command failed with error:", e)
    else:
        if not process.returncode == 0:
            raise ValueError("Sed command execution returned non-zero status.")

