import re

def validate_input(config_file, replacements):
    if not os.path.isfile(config_file):
        raise FileNotFoundError("Configuration file does not exist.")
    for replacement in replacements:
        if not all([isinstance(val, str) for val in replacement[1:]]):
            raise ValueError("Invalid input parameters.")
        pattern = re.compile(replacement[0])
        if not bool(pattern.match(config_file)):
            raise ValueError("Placeholder not found in configuration file.")
