    if (!record) {
        perror("Out of memory");
        exit(EXIT_FAILURE);
    }

    record->string = malloc((string_length + 1) * sizeof(char));
    if (!record->string) {
        free(record);
        perror("Out of memory");
        exit(EXIT_FAILURE);
    }

    memcpy(record->string, input_buffer, string_length * sizeof(char));
    record->string[string_length] = '\0';
    return record;
}

Record** create_collection(size_t size) {
    Record** collection = malloc(sizeof(Record*) * size);
    if (!collection) {
        perror("Out of memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        collection[i] = NULL;
    }

    return collection;
}

void populate_collection(Record** collection, size_t size) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < size; ++i) {
        char input_buffer[1024];
        printf("Enter the string for record %zu: ", i);
        scanf("%s", input_buffer);

        size_t string_length = safe_strlen(input_buffer);
        if (string_length > 1023) {
            fprintf(stderr, "String exceeded maximum length\n");
            continue;
        }

        Record* record = create_record(input_buffer, string_length);
        if (!record) {
            perror("Out of memory");
            exit(EXIT_FAILURE);
        }

        init_random(&record->integer, 100, 200);
        collection[i] = record;
    }
}

void cleanup(Record** collection, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (collection[i]) {
            free(collection[i]->string);
            free(collection[i]);
        }
    }

    free(collection);
}
