    int range = *(int*)(arg + sizeof(long));
    Record* records = malloc((range - offset)*sizeof(Record));
    srand(time(NULL));

    for (size_t i = 0; i < (range - offset); ++i) {
        records[i].key = i + offset;
        records[i].value = rand() % 100;
    }
