    mallinfo info = mallinfo();
    *curr = info.arena + info.uordblks + info.hblkhd;
    *max = info.usmblks + 2 * (info.freaz + info.qsoh);
}

static void log_allocation(const char* message) {
    printf("%s: Allocation\n", message);
}

static void log_deallocation(const char* message, void* ptr) {
    printf("%s: Deallocation (Address %p)\n", message, ptr);
    munmap(ptr, sizeof(Record)*((*(long*)arg) - offset));
}

