using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class RecordManager {
    private readonly Dictionary<int, int> _records = new Dictionary<int, int>();
    private readonly List<KeyValuePair<string, object>> _parameters;
    private readonly string _connectionString;
    private readonly string _sqlCommand;
    private readonly TimeSpan _timeout;

    public RecordManager(List<KeyValuePair<int, int>> records, string connectionString, string sqlCommand, TimeSpan timeout) {
        _records = records.ToDictionary(x => x.Key, x => x.Value);
        _connectionString = connectionString;
        _sqlCommand = sqlCommand;
        _timeout = timeout;
        _parameters = new List<KeyValuePair<string, object>>();
    }

    public async Task ExecuteAsync() {
        using (var connection = new SqlConnection(_connectionString)) {
            await connection.OpenAsync();

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            Parallel.ForEach(_records, options, (keyValuePair) => {
                var key = keyValuePair.Key;
                var value = keyValuePair.Value;

                _parameters.Clear();
                _parameters.Add(new KeyValuePair<string, object>("@id", key));
                _parameters.Add(new KeyValuePair<string, object>("@value", value));

                using (var command = new SqlCommand(_sqlCommand, connection)) {
                    command.Parameters.AddRange(_parameters.ToArray());
                    try {
                        await command.ExecuteNonQueryAsync();
                    } catch (Exception ex) {
                        Console.WriteLine(ex);
                    }
                }
            });
        }
    }
}
