    char* dirPath = (char*)args[0];
    char** filenames = (char**)args[1];
    int N = *(int*)args[2];
    Record* records = *(Record**)args[3];

    for (int i = 0; i < NUM_THREADS * BATCH_SIZE; ++i) {
        char fileName[1024];
        strcpy(fileName, dirPath);
        strcat(fileName, "/");
        if (i >= N) {
            i -= N;
            sprintf(fileName + strlen(fileName), "%s%ld", filenames[i % N], time(NULL));
        } else {
            uuid_t id;
            char idStr[37];
            uuid_generate(id);
            snprintf(idStr, sizeof(idStr), "%08x-%04x-%04x-%02x%02x-%02x%02x%02x",
                    id[1], id[2], id[3],
                    id[4], id[5], id[6], id[7]);
            snprintf(fileName + strlen(fileName), sizeof(fileName) - strlen(fileName), "%s%ld_%s%lu_%s",
                    idStr, filenames[i / N]->size(), sha256sum(filenames[i / N]), filenames[i / N]->st_mtime());
        }
        if (fileName[strlen(fileName) + 256 - 1] != '\0') {
            // Ensure the total length does not exceed 256 characters
            fprintf(stderr, "File name exceeded maximum length: %s\n", fileName);
            continue;
        }

        int key = hashFunction(fileName);
        if (key >= N || records[key].key == key) {
            // Collision handling
            for (int j = 1; j < N; ++j) {
                key = (key + j) % N;
                if (records[key].key != key) {
                    break;
                }
            }
        }

        strcpy(records[key].record, fileName);
    }

    return NULL;
}
```

