#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

typedef struct record {
    int key;
    long value;
} Record;

struct mem_pool {
    void *data;
    size_t size;
    struct mem_pool *next;
};

void init_mem_pool(size_t size, struct mem_pool **head) {
    if (!*head) {
        *head = malloc(sizeof(struct mem_pool));
        (*head)->size = size;
        (*head)->next = NULL;
    } else {
        struct mem_pool *current = *head;
        while (current->next)
            current = current->next;
        current->next = malloc(sizeof(struct mem_pool));
        current = current->next;
        current->size = size;
        current->next = NULL;
    }
}

void *get_mem_block(struct mem_pool **head, size_t size) {
    struct mem_pool *current = *head;
    if (!current || current->size < size) {
        init_mem_pool(size, head);
        current = *head;
    }

    void *block = mmap((void *)current + current->size, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (MAP_FAILED == block) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    current->size -= size;
    return block;
}

void put_mem_block(struct mem_pool **head, void *ptr, size_t size) {
    struct mem_pool *current = *head;
    if (current->size + size > current->size) {
        current->size += size;
        munmap((void *)current->data + current->size, size);
    } else {
        void *block = current->data + current->size;
        mprotect(block, size, PROT_READ | PROT_WRITE);
        current->size += size;
    }
}

pthread_mutex_t lock;
Record records[N];
long offsets[N];
int keys[N];

void init_data_structure(size_t N, int minValue, int maxValue) {
    pthread_mutex_init(&lock, NULL);

    void *mem = get_mem_block(&mem_pool, sizeof(Record) * N + sizeof(long) * 2 * N);
    records = mem;
    offsets = (long *)((char *)mem + sizeof(Record) * N);
    keys = (int *)((char *)offsets + sizeof(long) * N);

    for (size_t i = 0; i < N; ++i) {
        records[i].key = -1;
        keys[i] = i;
    }

    srand(time(NULL));
    int unique_count = 0;

    while (unique_count < N) {
        int value = rand() % ((maxValue - minValue + 1) + unique_count);
        value += minValue;

        int index = -1;
        pthread_mutex_lock(&lock);
        for (size_t i = 0; i < N; ++i) {
            if (records[i].key == -1 && keys[i] == unique_count) {
                index = i;
                break;
            }
        }
        pthread_mutex_unlock(&lock);

        if (index != -1) {
            records[index].value = value;
            records[index].key = unique_count;
            offsets[unique_count] = (long)&records[index];
            keys[index] = -1;
            ++unique_count;
        }
    }
}

