measurement_buffer* init_measurement_buffer(size_t initial_capacity) {
    measurement_buffer* buffer = malloc(sizeof(measurement_buffer));
    if (!buffer) return NULL;

    buffer->data = calloc(initial_capacity, sizeof(measurement));
    if (!buffer->data) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = initial_capacity;
    buffer->size = 0;
    return buffer;
}

void resize_measurement_buffer(measurement_buffer* buffer, size_t new_capacity) {
    if (new_capacity <= buffer->size) return; // No need to resize if new capacity is smaller than current size

    measurement* temp = realloc(buffer->data, new_capacity * sizeof(measurement));
    if (!temp) {
        fprintf(stderr, "Failed to resize measurement buffer\n");
        exit(1);
    }

    buffer->data = temp;
    buffer->capacity = new_capacity;
}

void append_measurement(measurement_buffer* buffer, const time_t timestamp, const float temperature, const char* sensor_id) {
    if (buffer->size == buffer->capacity) resize_measurement_buffer(buffer, 2 * buffer->capacity); // Double the capacity when full

    strncpy(buffer->data[buffer->size].sensor_id, sensor_id, sizeof(buffer->data[buffer->size].sensor_id));
    buffer->data[buffer->size].timestamp = timestamp;
    buffer->data[buffer->size].temperature = temperature;
    buffer->size++;
}

