#include <stdbool.h>

typedef struct {
    int value;
    size_t ref_count;
} record;

typedef struct modular_library {
    long offsets[]; // User-provided default values
    int* keys;
    record* records;
    size_t total_records;
    size_t key_capacity;
    pthread_mutex_t mutex;
    void* (*allocator)(size_t); // Custom allocator function pointer
} ModularLibrary;

ModularLibrary* modular_library_init(void* (*allocator)(size_t)) {
    ModularLibrary* library = malloc(sizeof(ModularLibrary));
    if (!library) return NULL;

    library->keys = NULL;
    library->records = NULL;
    library->total_records = 0;
    library->key_capacity = 1024;
    library->allocator = allocator;

    pthread_mutex_init(&library->mutex, NULL);
    return library;
}

void modular_library_resize_keys(ModularLibrary* library) {
    int* new_keys = (int*)library->allocator(library->key_capacity * 2);
    if (!new_keys) return;

    size_t i;
    for (i = 0; i < library->key_capacity; ++i) {
        if (library->keys[i])
            new_keys[i] = library->keys[i];
    }
    free(library->keys);

    library->keys = new_keys;
    library->key_capacity *= 2;
}

record* modular_library_get_record(ModularLibrary* library, int key) {
    pthread_mutex_lock(&library->mutex);
    record* record = NULL;
    size_t i;
    for (i = 0; i < library->key_capacity; ++i) {
        if (!library->records[i].ref_count && library->keys[i] == key) {
            library->records[i].ref_count = 1;
            record = &library->records[i];
            break;
        }
    }

    if (record) ++library->total_records;

    pthread_mutex_unlock(&library->mutex);
    return record;
}

void modular_library_release_record(ModularLibrary* library, record* record) {
    pthread_mutex_lock(&library->mutex);
    if (--record->ref_count == 0) {
        --library->total_records;
        record->ref_count = 1; // Allow reuse after cleanup
    }
    pthread_mutex_unlock(&library->mutex);
}
