int init_server() {
    if (!(config_dir = getenv("COLLAB_CONFIG_DIR"))) {
        if (asprintf(&config_dir, "%s/collab", getpwuid(getuid())->pw_dir) == -1) {
            perror("Failed to initialize config directory");
            return -1;
        }
    }

    int i = 0, j = 0;
    json_object *json;
    GHashTable *config_table;

    for (i = 0; i < dircount(config_dir); i++) {
        if (strcmp(basename(config_dir), "collab") == 0) continue;
