        if ((json = json_tokenizer_file(filename)) == NULL) {
            perror("Failed to parse configuration file");
            continue;
        }
        config_table = json_object_get_gconst_object(json, "settings");
        g_hash_table_foreach(config_table, (GHFunc)parse_setting, NULL);
    }

    int server_fd, client_fd[FD_SETSIZE];
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    fd_set readfds, master_fds;
    memset(client_fd, -1, sizeof client_fd);
    master_fds = (fd_set){ .fd_count = 1 };
    master_fds.fd[0] = server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (master_fds.fd[0] == -1) {
        perror("Failed to create server socket");
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_ANY);
    address.sin_port = htons(CONFIG_PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Failed to bind server socket");
        return -1;
    }

    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Failed to listen on server socket");
        return -1;
    }

    message messages[MAX_MESSAGES];
    for (i = 0; i < MAX_MESSAGES; ++i) {
        messages[i].timestamp = time(NULL);
        asprintf(&messages[i].id, "msg_%d", i + 1);
        messages[i].content = strdup("default_message");
    }

    while (1) {
        readfds = master_fds;
        if (select(FD_SETSIZE, &readfds, NULL, NULL, NULL) < 0) {
            perror("Failed to select on server socket");
            return -1;
        }

        for (i = 0; i < FD_SETSIZE; ++i) {
            if (FD_ISSET(i, &readfds)) {
                if (i == server_fd && accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen) > 0) {
                    client_fd[j++] = new_client(address, addrlen);
                    FD_SET(client_fd[j - 1], &master_fds);
                } else { // handle client connection
                    process_client(i, config);
                }
            }
        }
    }
}
