```javascript
const path = require('path');
const fs = require('fs');

module.exports = (compiler, options) => {
  compiler.hooks.compilation.tap('ModifyFilenamePlugin', compilation => {
    const lastWordLength = compilation.options.context.split('/').pop().split('.').length - 1;
    compilation.options.outputFileTools.publicPath = `/${lastWordLength}/`;

    compilation.hooks.assetEmitted.tap('ModifyFilenamePlugin', (asset, source) => {
      if (!asset.name.endsWith('.js')) return;

      const extList = ['js', 'min.js', 'map'];
      const extIndex = Math.floor(Math.random() * extList.length);
      const newName = asset.name.replace(/\.[^.]+$/, `.${extList[extIndex]}`);

      if (fs.existsSync(path.join(compilation.outputPath, newName))) {
        let count = 2;
        let newFileName = newName;
        while (fs.existsSync(path.join(compilation.outputPath, newFileName))) {
          newFileName = `${newName}-${count++}`;
        }
      }

      compilation.updateAsset(asset, source, newFileName);
    });
  });
};
