typedef struct CacheLine {
    Record data[64];
    size_t used;
} CacheLine;

struct MemPool {
    CacheLine *cache;
    size_t cacheSize, capacity, allocated;
    pthread_mutex_t mutex;
};

MemPool memPoolInit(size_t capacity) {
    MemPool pool = {.capacity = capacity, .allocated = 0, .cacheSize = 64 * sizeof(Record), .cache = malloc(sizeof(CacheLine))};
    pool.cache[0].used = capacity;
    return pool;
}

Record* memPoolAlloc(MemPool *pool) {
    if (pool->allocated + sizeof(Record) > pool->capacity) resizeMemPool(pool);

    pthread_mutex_lock(&pool->mutex);
    Record *record = &pool->cache[--pool->cache[0].used];
    int index = record->value;
    record->value = arc4random() % (pool->capacity - 1) + 1; // initialize with a unique random value
