    int *keys = calloc(N, sizeof(int));

    for (size_t i = 0; i < N; ++i) keys[i] = i;

    // Implement concurrent operations here
    pthread_t threads[N];

    for (size_t i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, [=](void *arg) {
            Record *offset = memPoolAlloc(&pool);
            int key = keys[pthread_self() % N];
            offset->value = key;
            keys[key] = pthread_self(); // Associate key with thread ID for debugging purposes
            logEvent(fmt::format("Thread {} allocated memory at offset {}, key: {}", pthread_self(), offset->value, key));
        }, NULL);
    }

    for (size_t i = 0; i < N; ++i) pthread_join(threads[i], NULL);

    free(keys);
    cleanup(&pool);
}
