["```javascript
const fs = require('fs');
const metadataService = require('./metadata-service'); // Assuming you have a separate metadata-service module
let totalFilesProcessed = 0; // Shared memory store for tracking total files processed

const MAX_FILE_SIZE = 1e6; // Set your desired maximum file size limit (in bytes)

function processFile(filePath) {
  return new Promise((resolve, reject) => {
    const chunkSize = 1024; // Performance optimization for large files
    let fileContent = '';
    let currentChunkIndex = 0;

    const fileStream = fs.createReadStream(filePath, { highWaterMark: chunkSize });

    fileStream.on('error', (err) => {
      reject(err);
    });

    fileStream.on('data', (chunk) => {
      if (fileContent.length + chunk.length > MAX_FILE_SIZE) {
        console.warn(`Warning: File size exceeded (${filePath} is ${fileContent.length + chunk.length} bytes, max is ${MAX_FILE_SIZE} bytes).`);
      } else {
        fileContent += chunk;
      }
      currentChunkIndex++;
    });

    fileStream.on('end', () => {
      if (fileContent.length <= MAX_FILE_SIZE) {
        totalFilesProcessed++; // Atomically increment the counter for thread safety

        metadataService.getMetadata(filePath)
          .then((metadata) => {
            resolve({ content: fileContent, metadata });
          })
          .catch((err) => {
            console.error(`Error fetching metadata for ${filePath}:`, err);
            resolve({ content: fileContent }); // Return file content without metadata if service is unavailable
          });
      } else {
        reject(new Error('File size exceeded the limit.'));
      }
    });
  });
}

module.exports = processFile;
```
