}

void* allocate_and_initialize(memory_manager_t* manager) {
    data_t* data = &manager->data[manager->length];
    init_data_with_random_chars(data, 10, 50);
    manager->keys[manager->length] = rand() % manager->capacity;
    manager->offsets[manager->length++] = manager->length - 1;
    return data;
}

void deallocate(memory_manager_t* manager, void* data) {
    free(((data_t*)data)->buffer);
}

void* select_and_initialize_compression(const char* workload_characteristics, memory_manager_t* manager) {
    compressor_context_t context = select_compression(workload_characteristics);
    void* compressed_data = malloc(context.compress(context.handle, ((data_t*)data)->buffer, data->length, &data->length));
    data->buffer = compressed_data;
    manager->context = context;

    return data;
}

void* decompress(memory_manager_t* manager, void* data) {
    ((data_t*)data)->length = manager->context.decompress(manager->context.handle, ((data_t*)data)->buffer, ((data_t*)data)->length, &data->length);
    return data;
}
