    if (this.isRunning) return;
    this.isRunning = true;

    const recursiveReadDirectory = (directory) =>
      new Promise((resolve, reject) => {
        fs.readdir(directory, (err, files) => {
          if (err) return reject(err);

          _.each(files, (file) => {
            const filePath = path.join(directory, file);
