[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>
#include <stdbool.h>
#include <unistd.h>
#include <assert.h>

typedef struct {
    double value;
    unsigned long timestamp;
    char *path;
} metadata;

// Function to generate unique timestamps within the provided range
unsigned long generate_unique_timestamp(unsigned long start, unsigned long step) {
    static unsigned long used[RLIM64_MAX / step] = {0};
    for (;;) {
        unsigned long timestamp = start + (rand() % (step));
        if (!used[timestamp - start]) {
            used[timestamp - start] = 1;
            return timestamp;
        }
    }
}

// Custom deleter function to free resources deterministically
void custom_deleter(void *ptr) {
    free(ptr);
}

// Function for allocating unique file paths and returning a copy
char* get_unique_filepath(const char *dir, size_t M) {
    static pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;
    static size_t used[RLIM64_MAX] = {0};
    static char paths[RLIM64_MAX][256];

    for (size_t i = 0; i < M; ++i) {
        pthread_rwlock_wrlock(&lock);
        int j;
        for (j = 0; j < i && used[j] != 0; ++j) {}
        if (j == i) { // all used, find unused
            for (; j < M; ++j) {
                if (!used[j]) {
                    break;
                }
            }
        }
        assert(j < M);
        snprintf(paths[i], sizeof(paths[i]), "%s/%d", dir, j);
        used[i] = 1;
        pthread_rwlock_wunlock(&lock);
    }

    char *results = malloc(M * sizeof(char*));
    for (size_t i = 0; i < M; ++i) {
        results[i] = strdup(paths[i]);
    }
    return results;
}

void* allocate_metadata(size_t M, double minValue, double maxValue) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    metadata *metadatas = malloc(M * sizeof(metadata));
    for (size_t i = 0; i < M; ++i) {
        pthread_mutex_lock(&mutex);
        while (true) {
            double value = minValue + rand() / (RAND_MAX / (maxValue - minValue + 1.0));
            bool unique = true;
            for (size_t j = 0; j < i; ++j) {
                if (metadatas[j].value == value) {
                    unique = false;
                    break;
                }
            }
            if (unique) {
                metadatas[i].value = value;
                metadatas[i].timestamp = generate_unique_timestamp(0, M);
                char *path = get_unique_filepath("/path/to/directory", M);
                metadatas[i].path = path;
                pthread_mutex_unlock(&mutex);
                break;
            }
            pthread_mutex_unlock(&mutex);
            usleep(1 + rand() % (1 << 20)); // Exponential backoff
        }
    }
    return metadatas;
}

void log_allocation(const char *msg, void *ptr, size_t size) {
    // Implement logging with adjustable levels and batching
}

void clean_up(metadata *metadatas, size_t M) {
    for (size_t i = 0; i < M; ++i) {
        free(metadatas[i].path);
    }
    free(metadatas);
}

void example_function(size_t M, double minValue, double maxValue) {
    metadata *metadatas = allocate_metadata(M, minValue, maxValue);
    log_allocation("Allocated metadatas", metadatas, sizeof(metadata) * M);
    // Use the allocated resources here...
    clean_up(metadatas, M);
}
```

