    size_t offset_capacity;
    size_t key_capacity;
    size_t record_capacity;
    pthread_mutex_t mutex;
};

void* manageDataStructures(size_t offset_count, size_t key_count, size_t record_count, int min_value, int max_value, size_t max_memory) {
    struct control_block *cb;
    size_t alignment = getpagesize();

    // Calculate required sizes and ensure they do not exceed max_memory.
    size_t offset_size = offset_count * sizeof(long);
    size_t key_size = key_count * sizeof(int);
    size_t record_size = record_count * sizeof(record);
    if (offset_size + key_size + record_size > max_memory) {
        return NULL;
    }

    // Allocate memory for control block and initialize mutex.
    cb = mmap(NULL, sizeof(*cb), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (cb == MAP_FAILED) {
        return NULL;
    }
    pthread_mutex_init(&cb->mutex, NULL);

    // Allocate and initialize offsets array.
    cb->offsets = malloc(offset_count * sizeof(long));
    if (cb->offsets == NULL) {
        free(cb);
        return NULL;
    }

    // Allocate and initialize keys array.
    cb->keys = malloc(key_count * sizeof(int));
    if (cb->keys == NULL) {
        free(cb->offsets);
        free(cb);
        return NULL;
    }

    // Allocate and initialize records array with random values.
    cb->records = malloc(record_count * sizeof(record));
    if (cb->records == NULL) {
        free(cb->keys);
        free(cb->offsets);
        free(cb);
        return NULL;
    }

    // Seed random number generator and fill records array with unique random values.
    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        while (1) {
            cb->records[i].value = rand() % (max_value - min_value + 1) + min_value;
            int is_unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (cb->records[j].value == cb->records[i].value) {
                    is_unique = 0;
                    break;
                }
            }
            if (is_unique) {
                break;
            }
        }
    }

    // Set capacity and pointers in control block.
    cb->offset_capacity = offset_count;
    cb->key_capacity = key_count;
    cb->record_capacity = record_count;

    return cb;
}
