std::mutex mtx;
std::atomic<size_t> nextKey(0);

// Memory Pool for long and int types
struct MemPool {
    std::vector<long> longMem;
    std::vector<int> intMem;
    size_t capacity = 0;

    void init(size_t size) {
        if (capacity > 0) return; // Prevent reinitialization
        longMem.reserve(size);
        intMem.reserve(size);
        capacity = size;
    }

    long* allocLong() {
        if (longMem.empty()) {
            longMem.resize(capacity, 0);
        }
        auto it = std::next(longMem.begin(), nextKey);
        ++nextKey;
        return it;
    }

    int* allocInt() {
        if (intMem.empty()) {
            intMem.resize(capacity, 0);
        }
        auto it = std::next(intMem.begin(), nextKey);
        ++nextKey;
        return it;
    }
};

struct MemPoolManager {
    static MemPool pool;

    MemPool& getPool() {
        if (!pool.capacity) pool.init(1024); // Initialize the memory pool with default capacity of 1024
        return pool;
    }
};

