typedef struct record {
    int key;
    long offset;
} Record;

struct collection {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void initialize(struct collection*, size_t, size_t);
Record* create_record(int key, long offset);
void destroy(struct collection*);
void serialize(const struct collection*, FILE*);
void deserialize(struct collection*, FILE*);

// Thread-safe function to initialize the collection with random values within a specified range.
void initialize(struct collection *collection, size_t capacity, size_t max_size) {
    if (capacity * sizeof(Record) > max_size) {
        fprintf(stderr, "Error: Maximum memory size exceeded.\n");
        return;
    }

    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(capacity * sizeof(Record));
    if (!collection->records) {
        perror("Error allocating memory");
        return;
    }

    collection->capacity = capacity;
    collection->size = 0;

    srand(time(NULL));

    for (size_t i = 0; i < capacity && collection->size < max_size / sizeof(Record); ++i) {
        Record record = create_record(rand() % 100, rand());
        pthread_mutex_lock(&collection->lock);
        collection->records[collection->size++] = record;
        pthread_mutex_unlock(&collection->lock);
    }
}

// Helper function to create a new 'record' structure with the given key and offset values.
Record* create_record(int key, long offset) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Error allocating memory");
        return NULL;
    }

    record->key = key;
    record->offset = offset;

    return record;
}

// Function to destroy the collection and free associated resources.
void destroy(struct collection *collection) {
    if (collection->records) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        collection->capacity = 0;
        collection->size = 0;
        collection->records = NULL;
    }
}

