void init_arrays(size_t *keys_len, size_t *offsets_len, size_t *records_num, Record ***records, int *seed) {
    if (*keys_len == 0 || *offsets_len == 0 || *records_num == 0) {
        fprintf(stderr, "Invalid input sizes.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int *keys = malloc(*keys_len * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    long *offsets = malloc(*offsets_len * sizeof(long));
    if (!offsets) {
        free(keys);
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    Record **records_ptr = malloc(*records_num * sizeof(Record*));
    if (!records_ptr) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *records_num; ++i) {
        if (!(records_ptr[i] = malloc(sizeof(Record)))) {
            for (size_t j = 0; j < i; ++j) free(records_ptr[j]);
            free(offsets);
            free(keys);
            free(records_ptr);
            fprintf(stderr, "Failed to allocate memory for a single record.\n");
            exit(EXIT_FAILURE);
        }
    }

    time_t now = time(NULL);
    unsigned long seed_now = (unsigned long)now * (*seed);

    for (size_t i = 0; i < *records_num; ++i) {
        pthread_mutex_lock(&mutex);
        records_ptr[i]->value = random_within_range(1, INT_MAX, seed_now);
        records_ptr[i]->identifier = 'A' + (i % 26);
        pthread_mutex_unlock(&mutex);
    }

    *records = records_ptr;
}

void log_if_needed(int level, const char *message) {
    if (level <= MAX_LOGGING) {
        printf("%s\n", message);
    }
}

void verify_memory(size_t keys_len, size_t offsets_len, size_t records_num) {
    if ((keys_len + offsets_len + records_num * sizeof(Record)) < THRESHOLD) return;

    log_if_needed(1, "Memory usage exceeds threshold. Cleanup may be required.");
}
```

