char* decrypt_message(const char* base64_encoded, const EVP_CIPHER_CTX* ctx) {
    int len = BIO_sk_num(base64_encoded);
    BIO *bmem = NULL, *bbio;
    char *buf, *ret;

    bbio = BIO_new_mem_buf(base64_encoded, len);
    bmem = BIO_new(BIO_s_mem());
    (void)BIO_push(bmem, bbio);

    while ((len = DECRYPT(ctx, BIO_read(bbio, buf, 1))) > 0) {
        BIO_write(bmem, buf, len);
    }

    ret = BIO_get_mem_ptr(bmem);

    BIO_free_all(bbio);
    BIO_free(bmem);
    return ret;
}

