            std::vector<std::string> chunkedStrings;
            for (auto i = 0u; i < strings.size(); i += chunkSize) {
                if (i + chunkSize > strings.size()) break;
                chunkedStrings.push_back(strings.substr(i, chunkSize));
            }

            // Process each chunk concurrently using multi-threading...
        }

        std::vector<std::string> getMD5(const std::vector<std::string>& strings) {
            std::vector<std::string> hashes;
            for (auto& str : strings) {
                auto cacheKey = md5Cache.get().find(str);
                if (cacheKey != md5Cache.get().end()) {
                    hashes.push_back(cacheKey->second);
                } else {
                    unsigned char digest[MD_DIGEST_LENGTH];
                    SHA1_CTX ctx;
                    SHA1_Init(&ctx);
                    SHA1_Update(&ctx, str.c_str(), str.length());
                    SHA1_Final(digest, &ctx);

                    std::stringstream ss;
                    for (auto i = 0; i < MD_DIGEST_LENGTH; ++i) {
                        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(digest[i]);
                    }
                    auto hash = ss.str();

                    md5Cache.get().emplace(std::move(str), std::move(hash));
                    hashes.push_back(std::move(hash));
                }
            }
            return hashes;
        }
    };
}
