2. Hash-based Unique Record Allocation:

```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class ConcurrentRecordPool {
    private final int minValue, maxValue;
    private final ConcurrentHashMap<Long, Integer> records = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();

    public ConcurrentRecordPool(int minValue, int maxValue) {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public Record getRecord() {
        long key = generateUniqueKey();
        return new Record(key, 0);
    }

    private long generateUniqueKey() {
        lock.lock();
        try {
            long key;
            do {
                key = System.currentTimeMillis() | (ThreadLocalRandom.current().nextLong() << 32);
            } while (records.putIfAbsent(key, 1) != null);
            return key;
        } finally {
            lock.unlock();
        }
    }
}
```

