import java.util.*;
import java.util.concurrent.ConcurrentLinkedQueue;

public class MemoryPool {
    private final ConcurrentLinkedQueue<Record> freeRecords = new ConcurrentLinkedQueue<>();
    private final ConcurrentRecordPool recordPool;

    public MemoryPool(ConcurrentRecordPool recordPool) {
        this.recordPool = recordPool;
    }

    public Record acquire() {
        Record record;
        if (!freeRecords.isEmpty()) {
            record = freeRecords.poll();
        } else {
            record = recordPool.getRecord();
        }
        return record;
    }

    public void release(Record record) {
        record.setValue(-1); // Mark as free
        freeRecords.add(record);
    }
}
```

