public class Trie {
    private final Map<Character, Trie> children = new HashMap<>();
    private final int value;

    public void put(String key) {
        // Implement recursive method to insert the given key into the trie structure
    }

    public int get(String key) {
        return find(key, 0);
    }

    private int find(String key, int index) {
        if (index == key.length()) {
            return value;
        }
        Trie child = children.getOrDefault(key.charAt(index), null);
        return child != null ? child.find(key, index + 1) : -1;
    }
}
