typedef struct {
    int value;
} Record;

void allocateDataStructures(int N, int minValue, int maxValue) {
    // Allocate and initialize arrays for offsets and keys
    long* offsets = malloc(N * sizeof(long));
    if (!offsets) {
        LOG(0, "Failed to allocate memory for offsets\n");
        return;
    }

    int* keys = malloc(N * sizeof(int));
    if (!keys) {
        LOG(0, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize keys with sequential integers
    for (int i = 0; i < N; ++i) {
        keys[i] = i;
    }

    // Allocate memory for record structures and populate them with random values
    Record* records = malloc(N * sizeof(Record));
    if (!records) {
        LOG(0, "Failed to allocate memory for records\n");
        free(keys);
        free(offsets);
        return;
    }

    // Use a set data structure to ensure unique random numbers are generated
    bool values[maxValue - minValue + 1] = { false };
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        int value = minValue + rand() % (maxValue - minValue + 1);
        while (values[value - minValue]) {
            value = minValue + rand() % (maxValue - minValue + 1);
        }
        values[value - minValue] = true;
        records[i].value = value;
    }

    // Perform integrity checks and edge case handling
    if (N <= 0) {
        LOG(0, "Invalid dataset size: N should be greater than zero\n");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    // ... Add more integrity checks and edge case handling as needed

    // Integrate with pre-existing logging framework to record memory allocations and initializations
    LOG(logLevel, "Allocation successful: offsets, keys, records\n");

    // Optimize for memory efficiency and performance by using batch processing or memory-mapped files (optional)

    // Cleanup procedure on function exit
    free(records);
    free(keys);
    free(offsets);
}
