// Custom memory tracking structure
typedef struct _MemBlock {
    void *ptr;
    size_t size;
    char name[64];
} MemBlock;

#define LOG(fmt, args...) fprintf(stderr, "[MEMORY] " fmt "\n", ##args)

void *safe_malloc(size_t size, const char *name) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Out of memory");
        exit(1);
    }
    MemBlock *mb = (MemBlock *)calloc(1, sizeof(MemBlock));
    strncpy(mb->name, name, sizeof(mb->name));
    mb->size = size;
    mb->ptr = ptr;
    LOG("Allocated %zu bytes for %s", size, mb->name);
    return ptr;
}

void safe_free(void *ptr, const char *name) {
    MemBlock *mb = (MemBlock *)calloc(1, sizeof(MemBlock));
    strncpy(mb->name, name, sizeof(mb->name));
    mb->ptr = ptr;
    LOG("Freed %zu bytes for %s", mb->size, mb->name);
    free(mb->ptr);
}

// Function implementation
