#include <errno.h>
#include <netdevice.h> // Pre-existing logging framework header

typedef struct {
    int value;
    long offset;
    char *identifier;
} record;

struct config_data {
    size_t cap, len;
    record *config;
    long offsets[1];
    int keys[1];
    char identifiers[1][256];
    pthread_mutex_t mutex;
};

void config_init(struct config_data **cd, size_t mem_pool) {
    struct config_data *config = mmap(NULL, mem_pool, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (config == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    config->cap = mem_pool;
    config->len = 0;
    config->config = (record*)((uintptr_t)(config + 1));
    for (size_t i = 0; i < sizeof(config->offsets) / sizeof(long); ++i) {
        config->offsets[i] = 0;
    }
    for (size_t i = 0; i < sizeof(config->keys) / sizeof(int); ++i) {
        config->keys[i] = -1;
    }
    for (size_t i = 0; i < sizeof(config->identifiers) / sizeof(char*); ++i) {
        config->identifiers[i][0] = '\0';
    }
    pthread_mutex_init(&config->mutex, NULL);
}

void config_destroy(struct config_data *cd) {
    munmap((void*)((uintptr_t)(cd + 1)), cd->cap);
    pthread_mutex_destroy(&cd->mutex);
}

record* config_add(struct config_data *cd, int value, long offset, const char *identifier) {
    if (cd->len == cd->cap) {
        size_t new_cap = cd->cap * 2;
        record *new_config = realloc(cd->config, sizeof(record) * new_cap);
        if (!new_config) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        memmove(new_config + cd->cap, cd->config, cd->len * sizeof(record));
        cd->config = new_config;
        cd->cap = new_cap;
    }

    record *new_rec = &cd->config[cd->len++];
    new_rec->value = value;
    new_rec->offset = offset;
    size_t id_idx = 0;
    for (size_t i = 0; i < cd->len; ++i) {
        if (!cd->keys[i]) {
            cd->keys[i] = id_idx++;
            strcpy(cd->identifiers[id_idx], identifier);
            break;
        }
    }
    return new_rec;
}

int config_load(struct config_data *cd, int *settings, size_t num_settings, int start, int end, FILE *fd) {
    pthread_mutex_lock(&cd->mutex);

    for (size_t i = 0; i < num_settings; ++i) {
        if (i >= start && i <= end) {
            const int value = rand() % 100 + 50; // Replace with your custom logic to generate values within the specified range.
            long offset = cd->offsets[i];
            char identifier[256] = ""; // Replace with your custom logic to generate unique identifiers for each configuration record.
            config_add(cd, value, offset, identifier);
        }
    }

    pthread_mutex_unlock(&cd->mutex);

    char line[4096];
    size_t num_read = 0;
    while ((num_read = getline(&line, sizeof(line), fd)) != -1) {
        if (line[0] == '#') continue; // Skip comments

        record *new_rec;
        char *token = strtok(line, ",");
        int value = atoi(token);
        long offset = 0;
        token = strtok(NULL, "\n");
        if (token) {
            offset = atol(token);
        }
        token = strtok(NULL, "\n");
        char *identifier;
        if (token) {
            identifier = malloc(strlen(token) + 1);
            strcpy(identifier, token);
        } else {
            continue; // Skip malformed lines
        }

        new_rec = config_add(cd, value, offset, identifier);
    }

    return num_read; // Return the number of lines processed.
}

