```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h> // For memory pool integration

typedef struct {
    int key;
    long offset;
    char *user_id;
} record;

typedef struct point {
    int x, y;
} point;

typedef struct mem_block {
    void *data;
    size_t size;
    struct mem_block *next;
} mem_block;

struct global_mem_manager {
    mem_block *head;
};

static struct global_mem_manager gmm; // Global memory manager instance
pthread_mutex_t gmm_lock = PTHREAD_MUTEX_INITIALIZER; // Lock for global memory manager

// Factory functions for record structures and arrays
record *create_record(int key, long offset);
void delete_record(record **rec);
double *allocate_array_double(size_t size);
char *allocate_array_char(size_t size);
point **allocate_array_point(size_t size);

// Function to manage the dynamic collection of records
void manage_collection(size_t N, int range_min, int range_max, int limit, void (*log_func)(const char *msg)) {
    record *records = allocate_array_record(N);
    double *doubles = allocate_array_double(N);
    char *chars = allocate_array_char(N);
    point **points = allocate_array_point(N);
    int sum = 0;

    // Initialize key array and other structures
    for (size_t i = 0; i < N; ++i) {
        chars[i] = 'a' + i;
        points[i]->x = i * 10;
        points[i]->y = i * 20;
        records[i].key = (rand() % (range_max - range_min + 1)) + range_min;
    }

    // Main loop for managing the collection
    size_t processed = 0;
    while (processed < N) {
        sum += records[processed].key;
        if (sum > limit) {
            log_func(("Reached memory limit: Processed records:", processed));
            break;
        }

        // Implement your periodic memory usage check strategy here

        // Perform operations on the collection...

        ++processed;
    }

    // Free resources and handle errors gracefully
    for (size_t i = 0; i < processed; ++i) {
        free(records[i].user_id);
    }
    free(chars);
    free(points);
    free(doubles);
    free(records);
}

// Factory functions implementation
record *create_record(int key, long offset) {
    record *rec = malloc(sizeof(record));
    if (!rec) {
        // Custom error handling for allocation failures
        fprintf(stderr, "Error: Failed to allocate memory for record\n");
        return NULL;
    }

    rec->key = key;
    rec->offset = offset;
    rec->user_id = malloc(10); // Assuming a maximum user ID length of 10 characters
    if (!rec->user_id) {
        free(rec);
        return NULL;
    }
    memset(rec->user_id, 0, 10);

    return rec;
}

void delete_record(record **rec) {
    if (*rec) {
        free((*rec)->user_id);
        free(*rec);
        *rec = NULL;
    }
}

// Global memory manager implementation (for the factory pattern)
void register_memory_block(mem_block *mb) {
    pthread_mutex_lock(&gmm_lock);
    mem_block *current = &gmm.head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = mb;
    pthread_mutex_unlock(&gmm_lock);
}

void* allocate(size_t size) {
    pthread_mutex_lock(&gmm_lock);
    mem_block *current = gmm.head;
    while (current != NULL && current->size <= size) {
        current = current->next;
    }

    if (current == NULL || (current != NULL && current->size >= size)) {
        void *data = malloc(size);
        if (!data) {
            pthread_mutex_unlock(&gmm_lock);
            return NULL;
        }
        mem_block *new_mb = malloc(sizeof(mem_block));
        if (!new_mb) {
            free(data);
            pthread_mutex_unlock(&gmm_lock);
            return NULL;
        }
        new_mb->data = data;
        new_mb->size = size;
        new_mb->next = current;
        register_memory_block(new_mb);
    } else {
        void *data = current->data;
        mem_block *temp = current;
        current = current->next;
        temp->next = NULL; // Detach the block from the memory chain
        current->size -= size;
    }

    pthread_mutex_unlock(&gmm_lock);
    return data;
}
```

