import re

class FileProcessor:
    def __init__(self, filename):
        self.filename = filename
        self.sequence_number = None

    def read_file(self):
        try:
            with open(self.filename) as f:
                lines = [line.strip() for line in f]
                self.sequence_number = re.search(r'\d+', lines[-1]).group(0) if lines else None
                lines = sorted(lines, key=lambda x: (x.isdigit() and int(x) or float(x)))
            return lines
        except Exception as e:
            print("Error reading file:", e)
            self.sequence_number = None
            return []

    def process(self):
        lines = self.read_file()
        if self.sequence_number is not None:
            print("\nLast line sequence number:", self.sequence_number)
        for line in lines:
            print(line)
