namespace DynamicRangeGenerator
{
    public class DynamicRangeGenerator
    {
        private float _minValue;
        private float _maxValue;
        private bool _externalDependency;

        public DynamicRangeGenerator(float minValue, float maxValue)
        {
            if (minValue > maxValue)
                throw new ArgumentException("Initial range values must be in a valid order.");

            SetRange(minValue, maxValue);
        }

        public void SetRange(float newMinValue, float newMaxValue)
        {
            if (_externalDependency)
            {
                Console.WriteLine("Attempting to change range while external dependencies are active. Please wait or abort the ongoing processes.");
                return;
            }

            if (newMinValue > newMaxValue)
                throw new ArgumentException("New range values must be in a valid order.");

            _minValue = newMinValue;
            _maxValue = newMaxValue;
        }

        private float GetRandomFloat(float minValue, float maxValue, bool useExclusiveMax)
        {
            Random random = new Random();
            if (useExclusiveMax && maxValue <= minValue + 0.001f)
                return minValue;

            double range = maxValue - minValue;
            double rndNum = (double)(random.NextDouble() * Math.Abs(range));
            if (useExclusiveMax)
                rndNum += minValue;

            return (float)(rndNum / range + minValue);
        }

        private int GetRandomInt(int minValue, int maxValue, bool useExclusiveMax)
        {
            Random random = new Random();
            if (useExclusiveMax && maxValue <= minValue + 1)
                return minValue;

            int rangeSize = maxValue - minValue;
            int rndNum = random.Next(rangeSize);
            if (useExclusiveMax)
                return rndNum + minValue;
            else
                return rndNum + minValue - (rangeSize - 1);
        }

        public override string ToString()
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine($"Dynamic Range Generator ({_minValue} - {_maxValue})");
            if (_externalDependency)
                sb.AppendLine("External dependencies active.");

            return sb.ToString();
        }
    }
}
