        {
            if (validateRange && newMinValue > newMaxValue)
                throw new ArgumentException("Invalid range parameters. newMinValue must be less than or equal to newMaxValue.");

            if ((_minValue < newMinValue && _maxValue <= newMinValue) || (_minValue > newMaxValue && _maxValue > newMaxValue))
                throw new Exception("Proposed range overlaps with the existing range. Range change is not allowed.");

