void init_logging(const char *filename) {
    log_file = filename;
    pthread_mutex_init(&log_mutex, NULL);
}

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Write the formatted message to the log file while acquiring the mutex.
    pthread_mutex_lock(&log_mutex);
        vfprintf(stderr, format, args);
        fprintf(stderr, "\n");
    pthread_mutex_unlock(&log_mutex);
}

void* allocate_and_initialize_data(void *arg) {
    const size_t *params = arg;
    int64_t *ints = mmap(NULL, params[0] * sizeof(int64_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (ints == MAP_FAILED) {
        log_message("Failed to allocate memory for int array.\n");
        return NULL;
    }

    uint64_t *keys = mmap(NULL, params[0] * sizeof(uint64_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (keys == MAP_FAILED) {
        log_message("Failed to allocate memory for key array.\n");
        munmap(ints, params[0] * sizeof(int64_t));
        return NULL;
    }

    float *floats = mmap(NULL, params[0] * sizeof(float), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (floats == MAP_FAILED) {
        log_message("Failed to allocate memory for float array.\n");
        munmap(keys, params[0] * sizeof(uint64_t));
        munmap(ints, params[0] * sizeof(int64_t));
        return NULL;
    }

    Record *records = calloc(params[0], sizeof(Record));
    if (records == NULL) {
        log_message("Failed to allocate memory for record array.\n");
        munmap(floats, params[0] * sizeof(float));
        munmap(keys, params[0] * sizeof(uint64_t));
        munmap(ints, params[0] * sizeof(int64_t));
        return NULL;
    }

    // Populate the arrays with random values and keys.
    for (size_t i = 0; i < params[0]; ++i) {
        int64_t j, k;
        float value;

        // Avoid collisions within each field but not necessarily across fields.
        do {
            j = rand() % params[0];
            k = keys[j];
        } while (k != i);
        keys[i] = i;

        int64_t integer = rand() * (1 + params[3] - params[2]) / RAND_MAX + params[2];
        float floating = (rand() * (1 + params[5] - params[4]) / RAND_MAX + params[4]);

        ints[i] = integer;
        floats[i] = floating;
        records[i].integer = integer;
        records[i].floating = floating;
        records[i].key = i;
    }

    // Log the information and free memory.
    log_message("Successfully allocated and initialized data for N=%zu, int range [%lf, %lf], float range [%lf, %lf]\n", params[0], params[2], params[3], params[4], params[5]);

    munmap(floats, params[0] * sizeof(float));
    munmap(keys, params[0] * sizeof(uint64_t));
    free(records);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 7) {
        log_message("Usage: %s N minIntValue maxIntValue minFloatValue maxFloatValue seed\n", argv[0]);
        return -1;
    }

    const size_t N = atoi(argv[1]);
    const double minIntValue = atof(argv[2]), maxIntValue = atof(argv[3]);
    const double minFloatValue = atof(argv[4]), maxFloatValue = atof(argv[5]);
    unsigned int seed = atoi(argv[6]);

    srand(seed);

    init_logging("log.txt");

    pthread_t threads[1];
    void *result;
    const size_t params[] = {N, minIntValue, maxIntValue, minFloatValue, maxFloatValue, seed};
    if (pthread_create(threads, NULL, &allocate_and_initialize_data, params) != 0) {
        log_message("Failed to create thread.\n");
        return -1;
    }

    if (pthread_join(threads[0], &result)) {
        log_message("Failed to join thread.\n");
        return -1;
    }

    return 0;
}

