#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct data_point {
    double value;
    struct data_point *next;
} data_point;

int check_uint64_t_overflow(uint64_t N) {
    if (N > UINT64_MAX - (uint64_t)sizeof(data_point)*N) {
        fprintf(stderr, "Error: Input size %lu exceeds available uint64_t memory.\n", N);
        return 1;
    }
    return 0;
}

void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

void free_custom(void *ptr) {
    free(ptr);
}

int init(uint64_t N, double minValue, double maxValue, data_point*** array, uint64_t** keys) {
    if (check_uint64_t_overflow(N)) return 1;

    *array = (data_point*)custom_malloc(sizeof(data_point)*N);
    if (!*array) return 1;

    (*array)[0].next = *array + 1;
    for (uint64_t i = 1; i < N - 1; ++i) {
        (*array)[i].next = (*array + i + 1);
    }
    (*array)[N - 1].next = NULL;

    *keys = (uint64_t*)custom_malloc(sizeof(uint64_t)*N);
    if (!*keys) return 1;

    for (uint64_t i = 0; i < N; ++i) {
        (*keys)[i] = i;
    }

    data_point *current = *array;
    srand(time(NULL));
    for (uint64_t i = 0; i < N; ++i) {
        double value;
        do {
            value = (double)(rand() % ((int)((maxValue - minValue + 1) * DBL_MAX)) + minValue);
        } while (alreadyExists(current, value));
        current->value = value;
        current = current->next;
    }

    return 0;
}

int alreadyExists(data_point* head, double val) {
    data_point *current = head;
    while (current != NULL) {
        if (fabs((current->value) - val) < DBL_EPSILON) return 1;
        current = current->next;
    }
    return 0;
}

void log_init(uint64_t N, double minValue, double maxValue) {
    // Implement your logging framework here.
}

int main() {
    uint64_t N = 10000;
    double minValue = -1.0;
    double maxValue = 1.0;
    data_point* array;
    uint64_t* keys;
    if (init(N, minValue, maxValue, &array, &keys)) return 1;
    log_init(N, minValue, maxValue);
    free_custom(array);
    free_custom(keys);
    return 0;
}
