    int i, j = 0;
    for (i = start; i < end; ++i) {
        if (settings[i] != -1) {
            ConfigRecord *record = obtain_memory();
            record->value = settings[i];
            record->offset = offset_array[j];
            snprintf(record->identifier, 256, "%d", j);
            ++j;
        }
