    close(fd);

    // Utilize a buffering mechanism for efficient batch processing
    char buffer[1024 * 1024];
    read_from_file_into_buffer("config.txt", buffer, sizeof(buffer));
    process_config_lines(buffer, device);

    // Performance monitoring and notifications
    monitor_memory_usage();
    monitor_latency();
}

// Function to obtain memory from the pool
ConfigRecord *obtain_memory() {
    pthread_mutex_lock(&memory_pool_mutex);
    if (num_allocated < max_allocated) {
        ConfigRecord *record = memory_pool[num_allocated++];
        memset(record, 0, sizeof(*record));
        pthread_mutex_unlock(&memory_pool_mutex);
        return record;
    } else {
        size_t new_size = max_allocated * 2;
        void **new_memory_pool = reallocarray(memory_pool, new_size, sizeof(*memory_pool[0]));
        if (new_memory_pool != NULL) {
            max_allocated = new_size;
            pthread_mutex_unlock(&memory_pool_mutex);
            return obtain_memory();
        } else {
            // Handle memory allocation failure gracefully
            log_error("Memory allocation failed. Reducing memory usage and continuing...");
            max_allocated /= 2;
            num_allocated -= (max_allocated / 2);
            pthread_mutex_unlock(&memory_pool_mutex);
        }
    }
}

// Function to deallocate all resources
void free_resources() {
    // Deallocate dynamically allocated memory here
}
