```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sqlite3.h>

typedef struct {
    long offset;
    int key;
    int value[2];
} Record;

void init_array(int max, void** arr) {
    *arr = calloc(max + 1, sizeof(**arr));
    if (!*arr) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    memset(record, 0, sizeof(Record));
    return record;
}

int read_line(FILE* file, char** line) {
    int size = 0;
    char c;

    while ((c = fgetc(file)) != EOF && size < 1024) {
        if (isspace(c)) continue;
        size++;
    }

    if (size > 0) {
        *line = realloc(*line, size + 1);
        (*line)[size] = '\0';
        fseek(file, -1, SEEK_CUR);
    }

    return size;
}

int process_record(char* line, Record* record) {
    char* token = strtok(line, ",");

    int i = 0;
    while (token != NULL && i < sizeof(record->value) / sizeof(record->value[0])) {
        record->value[i++] = atoi(token);
        token = strtok(NULL, ",");
    }

    if (i == 0 || i > sizeof(record->value) / sizeof(record->value[0]) - 1) return -1;

    record->value[i] = (record->value[i-1] + record->value[i-2]) / 2;
    return 0;
}

void free_record(Record* record) {
    free(record);
}

int main() {
    FILE* file = fopen("dataset.txt", "r");
    if (!file) {
        perror("File open error");
        return EXIT_FAILURE;
    }

    int max_records = 10000;
    Record* records = create_record();

    int max_offsets = 10000;
    long* offsets = NULL;
    init_array(max_offsets, (void**)&offsets);

    int max_keys = 10000;
    int* keys = NULL;
    init_array(max_keys, (void**)&keys);

    char line[1024] = {0};

    while (read_line(file, line) > 0 && fgetc(file) != EOF) {
        int index = offsets[*offsets];

        if (index < max_records) {
            strcpy(records[index].value[sizeof(records[index].value)/sizeof(records[index].value[0]) - 1], line);
            records[index]->key = keys[*keys];
            records[index]->offset = *offsets;
        } else {
            Record* new_record = create_record();
            memcpy(new_record, records[index-1], sizeof(*records));
            strcpy(new_record->value[sizeof(new_record->value)/sizeof(new_record->value[0]) - 1], line);
            new_record->key = keys[*keys];
            new_record->offset = *offsets;

            free_record(records[index-1]);

            offsets[*keys] = *offsets;
            keys++;
            offsets++;

            memcpy(records, &new_record, sizeof(*records));
        }

        int result = process_record(line, records[*offsets]);
        if (result < 0) {
            printf("Invalid record: %s\n", line);
        } else {
            printf("%ld,%d,%d,%d\n", records[*offsets]->offset, records[*offsets]->key, records[*offsets]->value[0], records[*offsets]->value[1]);
        }
    }

    free(records);
    free(offsets);
    free(keys);

    fclose(file);
    return EXIT_SUCCESS;
}
```

