    void encrypt(const uint8_t* input, size_t length, uint8_t* output);
    void decrypt(const uint8_t* input, size_t length, uint8_t* output);
};

Encryptor::Encryptor(EncryptionMode mode) :
        mode_(mode), encryptor_handle_(nullptr), lock_(SEM_INITIALIZE(&lock_, 1)) {}

Encryptor::~Encryptor() {
    if (encryptor_handle_) {
        close_external_library(encryptor_handle_); // Close the library handle before deallocation
        free(encryptor_handle_);
    }
}

void Encryptor::configure(const char* parameters) {
    // Configure the selected encryption mode based on the provided parameters
    if (mode_ == DES_ECB) {
        encryptor_handle_ = init_ecb_library(parameters);
    } else if (mode_ == DES_EDE) {
        encryptor_handle_ = init_ede_library(parameters);
    } // ... and so on for other cipher modes
}

