    pthread_mutex_lock(&lock_);
    if (encryptor_handle_) {
        encrypt_external_library(encryptor_handle_, input, length, output);
    } else {
        // Handle the case where there is no selected encryption mode (e.g., NULL_ENCRYPTION)
    }
    pthread_mutex_unlock(&lock_);
}

void Encryptor::decrypt(const uint8_t* input, size_t length, uint8_t* output) {
    // Implement decryption similar to the encrypt method
}
