['```rust
use rand::{thread_rng, Rng};
use reqwest::Client;

const RECORD_COUNT: usize = 1000;
const KEY_RANGE: std::ops::RangeInclusive<i32> = -100..100;
const OFFSET_SIZE: usize = 8;
const KEY_SIZE: usize = 4;
const RECORD_SIZE: usize = std::mem::size_of::<i32>();

fn initialize_records_and_http_client() -> (Box<[i32]>, Vec<Record>, Client) {
    let mut rng = thread_rng();
    let records = vec![Record::default(); RECORD_COUNT];

    for i in 0..RECORD_COUNT {
        records[i].key = i as i32;
        records[i].value = rng.gen::<u64>() as i32 % KEY_RANGE.len() + *KEY_RANGE.start();
    }

    let offsets = Box::new(vec![0; OFFSET_SIZE * RECORD_COUNT]);
    let mut offset_iter = offsets.as_mut_slice().chunks_exact(OFFSET_SIZE);
    for (index, record) in records.iter().enumerate() {
        offset_iter.next().unwrap().copy_from_slice(&[record.key as u64]);
    }

    let http_client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(30))
        .max_redirects(0)
        .build().expect("Failed to initialize HTTP client");

    (offsets, records, http_client)
}

#[derive(Default)]
struct Record {
    key: i32,
    value: i32,
}
```

This code defines a function `initialize_records_and_http_client` that initializes two components (offsets and records) and an HTTP client under strict performance and reliability constraints. The chosen third-party crate for handling HTTP requests is reqwest.

* The `offsets` vector is initialized with a fixed size based on the number of records and the size of each offset value. Memory is allocated in chunks to optimize memory usage and initialization speed.
* The `records` vector contains a default-initialized struct that represents the record, which includes a key and value field. The key field is set sequentially (0 to RECORD_COUNT - 1) to ensure idempotency. The value field is randomly generated within the given range using the rand crate's thread_rng().
* The HTTP client is initialized with reasonable timeout settings, max redirects of 0, and built using reqwest's Client::builder(). This configuration ensures graceful handling of network failures or timeouts while maintaining idempotency.

To improve performance, the code uses chunking when filling the offsets vector to minimize the number of memory copies. Additionally, by seeding the random number generator with the system's current thread (thread_rng()), we avoid predictable sequences and potential side effects.

The function returns a tuple containing the initialized offsets, records, and HTTP client, ensuring that the components can be easily used within the application. The lack of comments or explanations adheres to the requirement for minimal documentation but may impact code readability and maintainability in larger projects.']

["```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    struct Node *prev;
    struct Node *next;
} Node;

Node* create_node(int key) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = key;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void init_list(Node** head, Node** tail) {
    *head = create_node(rand() % 100);
    *tail = *head;
}

Node* get_new_node(int key) {
    Node* new_node = create_node(key);
    if (!new_node) return NULL;
    new_node->next = *head;
    if (*head) (*head)->prev = new_node;
    else *tail = new_node;
    *head = new_node;
    return new_node;
}

void update_keys(Node* node, int min, int max) {
    while (node != NULL) {
        node->key = rand() % (max - min + 1) + min;
        node = node->next;
    }
}

Node* find_prev_node(Node* current) {
    Node* temp = current->prev;
    while (temp && temp != current)
        temp = temp->prev;
    return temp;
}

void delete_node(Node** node_ptr) {
    Node* to_delete = *node_ptr;
    if (!to_delete || !to_delete->prev || !to_delete->next) return;
    to_delete->prev->next = to_delete->next;
    to_delete->next->prev = to_delete->prev;
    free(to_delete);
    *node_ptr = NULL;
}
```

In this code, the `Node` structure represents each node in the doubly linked list. The `create_node()` function initializes a new node with a given key and sets both pointers to null.

