using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography.SHA256;
using System.Globalization;
using Microsoft.Extensions.Logging;
using MemoryCache = System.Runtime.Caching.MemoryCache;

public class StringProcessor
{
    private readonly ILogger<StringProcessor> _logger;
    private readonly MemoryCache _cache;
    private readonly int _maxCacheSize;
    private readonly TimeSpan _timeLimitForProcessing;

    public StringProcessor(ILogger<StringProcessor> logger, MemoryCache cache, int maxCacheSize = 1000, TimeSpan timeLimitForProcessing = TimeSpan.FromMilliseconds(10))
    {
        _logger = logger;
        _cache = cache;
        _maxCacheSize = maxCacheSize;
        _timeLimitForProcessing = timeLimitForProcessing;
    }

    public async Task<Dictionary<string, byte[]>> ProcessStringsAsync(IEnumerable<string> inputStrings)
    {
        var normalizedStrings = inputStrings.Select(NormalizeString).ToList();
        var hashes = new Dictionary<string, byte[]>();

        var cachedHashes = _cache.GetAll().OfType<DataItem>().Where(item => item.Key is string key && normalizedStrings.Contains(key)).Select(item => (string)item.Key).ToHashSet();

        var tasks = new List<Task>();

        foreach (var normalizedString in normalizedStrings)
        {
            if (cachedHashes.Contains(normalizedString))
            {
                hashes[normalizedString] = _cache[(string)normalizedString].Value as byte[];
                continue;
            }

            tasks.Add(Task.Run(() =>
            {
                var hash = ComputeHash(normalizedString);
                Interlocked.Increment(ref _cache.AddOrUpdate(normalizedString, hash, (key, value) => new DataItem(key, value), TimeSpan.FromMinutes(5))) ;
                hashes[normalizedString] = hash;
            }));
        }

        await Task.WhenAll(tasks);

        return hashes;
    }

    private string NormalizeString(string input) => input == null ? string.Empty : input.Trim().ToLowerInvariant().Where(c => char.IsLetterOrDigit(c) || c == '.' || c == ',' || c == '?').Aggregate((a, c) => a + c);

    private byte[] ComputeHash(string data)
    {
        using (var hasher = SHA256.Create())
        {
            var dataBytes = Encoding.UTF8.GetBytes(data);
            return hasher.ComputeHash(dataBytes);
        }
    }
}

public class DataItem : CacheItem
{
    public DataItem(object key, object value) : base(key, value, _maxCacheSize) { }

    protected override void OnExpire() => _logger.LogWarning("Cache item expired: {Key}", Key);
}
```
