void hash(int key, int* table_size, long* table) {
    long h1 = key % *table_size;
    long h2 = (key * A + B) % C;
    long index = (h1 + h2) % *table_size;

    // Linear probing with increment of 1
    while (table[index] != -1 && index != h1)
        index = (index + 1) % *table_size;

    return index;
}

void init_hash_table(int size, int* table, long* offsets) {
    for (int i = 0; i < size; ++i) {
        table[i] = -1;
        offsets[i] = 0;
    }
}

void add_nic_config(int key, NID_config nic_config) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int table_size = sizeof(record) * 2; // Initial size of the hash table
    int* table = malloc(table_size * sizeof(int));
    long* offsets = malloc(table_size * sizeof(long));
    init_hash_table(table_size, table, offsets);

    int index = hash(key, &table_size, offsets);
    pthread_mutex_lock(&lock);
    record rec = { key, offsets[index], nic_config };
    offsets[index] += sizeof(record);
    table[index] = (int)&rec;
    pthread_mutex_unlock(&lock);
}

