void* memPool;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

Record* initRecords(size_t offsetSize, size_t keySize, size_t recordSize, size_t numRecords, double minVal, double maxVal) {
    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0 || numRecords <= 0 || minVal > maxVal) {
        fprintf(stderr, "Invalid input parameters.\n");
        exit(1);
    }

    long* offsets = malloc((numRecords + 64) * sizeof(long)); // Align for cache performance
    int* keys = malloc((numRecords + 64) * sizeof(int)); // Align for cache performance
    Record* records = (Record*)memPool;
    memPool += (recordSize + 64); // Advance the pool

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    pthread_mutex_lock(&log_mutex);
    struct MemLog* log = (struct MemLog*)calloc(1, sizeof(struct MemLog));
    if (!log) {
        fprintf(stderr, "Memory allocation for log failed.\n");
        exit(1);
    }
    pthread_mutex_unlock(&log_mutex);

    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = minVal + rand()/(RAND_MAX/ (maxVal - minVal));
    }

    return records;
}

void* memPoolInit(size_t initialSize) {
    if (!initialSize) {
        fprintf(stderr, "Initial memory pool size cannot be zero.\n");
        exit(1);
    }

    void* start = malloc(initialSize + 64); // Align for cache performance
    if (!start) {
        fprintf(stderr, "Memory allocation for initial memory pool failed.\n");
        exit(1);
    }

    memPool = start;
    return start + 64; // Skip alignment padding
}
