#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct entry {
    long *value;
    int key;
} Entry;

struct dynamic_list {
    size_t size;
    size_t capacity;
    Entry **entries;
    pthread_mutex_t mutex;
};

void init_dynamic_list(struct dynamic_list *list) {
    list->size = 0;
    list->capacity = 4;
    list->entries = malloc(sizeof(Entry*) * list->capacity);
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
}

bool is_empty(const struct dynamic_list *list) {
    return list->size == 0;
}

void grow_dynamic_list(struct dynamic_list *list) {
    size_t new_capacity = list->capacity * 2;
    Entry **new_entries = realloc(list->entries, sizeof(Entry*) * new_capacity);
    if (new_entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for dynamic list\n");
        exit(1);
    }
    list->entries = new_entries;
    list->capacity = new_capacity;
}

void insert_entry(struct dynamic_list *list, long value, int key) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) grow_dynamic_list(list);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->key > key) {
            memmove(&list->entries[i+1], &list->entries[i], sizeof(Entry*) * (list->size - i));
            list->entries[i] = malloc(sizeof(Entry));
            list->entries[i]->value = value;
            list->entries[i]->key = key;
            ++list->size;
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }
    list->entries[list->size] = malloc(sizeof(Entry));
    list->entries[list->size]->value = value;
    list->entries[list->size]->key = key;
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

int binary_search(const struct dynamic_list *list, int key) {
    pthread_mutex_lock(&list->mutex);
    size_t left = 0;
    size_t right = list->size - 1;
    while (left <= right) {
        size_t mid = (left + right) / 2;
        if (list->entries[mid]->key == key) {
            pthread_mutex_unlock(&list->mutex);
            return mid;
        } else if (list->entries[mid]->key < key) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

Entry* get_entry(struct dynamic_list *list, int index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    Entry* entry = list->entries[index];
    pthread_mutex_unlock(&list->mutex);
    return entry;
}

void remove_entry(struct dynamic_list *list, int key) {
    size_t index = binary_search(list, key);
    if (index != -1) {
        pthread_mutex_lock(&list->mutex);
        memmove(list->entries + index, list->entries + index + 1, sizeof(Entry*) * (list->size - index - 1));
        free(list->entries[index]);
        --list->size;
        pthread_mutex_unlock(&list->mutex);
    }
}

void remove_entry_by_index(struct dynamic_list *list, size_t index) {
    if (index >= list->size || index < 0) return;
    pthread_mutex_lock(&list->mutex);
    memmove(list->entries + index, list->entries + index + 1, sizeof(Entry*) * (list->size - index - 1));
    free(list->entries[index]);
    --list->size;
    pthread_mutex_unlock(&list->mutex);
}
```

