typedef struct {
    char *name;
    int quantity;
    char *description;
} Item;

struct ItemManager {
    size_t capacity;
    size_t count;
    Item **items;
    pthread_mutex_t mutex;
};

void init_item(Item *item, const char *name, int quantity) {
    item->name = strdup(name);
    item->quantity = quantity;
    item->description = NULL;
}

void read_file(struct ItemManager *manager, FILE *fp) {
    size_t capacity = 16;
    size_t count = 0;

    Item **items = malloc(capacity * sizeof(*items));
    for (Item *item = items; count < capacity; ++item)
        item->description = NULL;

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        Item *item = items + count++;
        if (count >= capacity) {
            capacity *= 2;
            Item **tmp_items = realloc(items, capacity * sizeof(*items));
            if (!tmp_items) {
                // Handle memory allocation failure gracefully
                free_item_manager(manager);
                return;
            }
            items = tmp_items;
        }

        char *token = strtok(line, " ");
        init_item(item, token, 1);

        // Allocate and read item description
        token = strtok(NULL, "\n");
        if (token) {
            item->description = strdup(token);
        }
    }

    manager->capacity = capacity;
    manager->count = count;
    manager->items = items;
}

void apply_discount(Item *item, float discount) {
    item->quantity = (int)(item->quantity * (1 - discount));
}

void free_item(Item *item) {
    if (item->description) {
        free(item->description);
    }
    free(item->name);
    memset(item, 0, sizeof(*item));
}

void free_item_manager(struct ItemManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free_item(manager->items[i]);
    }
    free(manager->items);
    pthread_mutex_destroy(&manager->mutex);
}

struct ItemManager* create_item_manager(const char *filename, float discount) {
    struct ItemManager *manager = malloc(sizeof(*manager));
    manager->capacity = 0;
    manager->count = 0;
    manager->items = NULL;
    pthread_mutex_init(&manager->mutex, NULL);

    FILE *fp = fopen(filename, "r");
    if (!fp) {
        // Handle file opening failure gracefully
        free_item_manager(manager);
        return NULL;
    }

    read_file(manager, fp);
    apply_discount_all(manager, discount);
    fclose(fp);

    return manager;
}

void apply_discount_all(struct ItemManager *manager, float discount) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        apply_discount(manager->items[i], discount);
    }
    pthread_mutex_unlock(&manager->mutex);
}
