typedef union ConfigParam {
    char str[64];
    int num;
} ConfigParam;

typedef struct ConfigEntry {
    ConfigParam param;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConfigEntry;

struct Config {
    ConfigEntry *entries;
    size_t num_entries;
    size_t max_concurrent;
    int range_start, range_end;
    pthread_mutex_t log_mutex;
    FILE *log_file;
};

Config *init_config(size_t num_entries, size_t max_concurrent, int range_start, int range_end) {
    if (num_entries == 0 || max_concurrent == 0 || range_start > range_end) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Config *config = malloc(sizeof(Config));
    if (!config) {
        perror("Memory allocation failed");
        return NULL;
    }

    config->num_entries = num_entries;
    config->max_concurrent = max_concurrent;
    config->range_start = range_start;
    config->range_end = range_end;

    config->entries = malloc(num_entries * sizeof(ConfigEntry));
    if (!config->entries) {
        perror("Memory allocation failed");
        free(config);
        return NULL;
    }

    pthread_mutex_init(&config->log_mutex, NULL);

    for (size_t i = 0; i < num_entries; ++i) {
        ConfigEntry *entry = &config->entries[i];
        pthread_mutex_init(&entry->mutex, NULL);
        pthread_cond_init(&entry->cond, NULL);
    }

    config->log_file = fopen("config.log", "w");
    if (!config->log_file) {
        perror("Could not open log file for writing");
        free(config->entries);
        free(config);
        return NULL;
    }

    return config;
}

void deinit_config(Config *config) {
    if (config->log_file) fclose(config->log_file);
    free(config->entries);
    free(config);
}

void log_config(const char *message, Config *config) {
    pthread_mutex_lock(&config->log_mutex);

    time_t current = time(NULL);
    struct tm *timeinfo = localtime(&current);
    fprintf(config->log_file, "%s %d-%02d-%02d %02d:%02d:%02d: [%s] %s\n",
            asctime(timeinfo), timeinfo->tm_year + 1900, timeinfo->tm_mon + 1,
            timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            pthread_self(), message);
    pthread_mutex_unlock(&config->log_mutex);
}

void *configure(void *arg) {
    ConfigEntry *entry = arg;
    entry->param.num = rand() % (config->range_end - config->range_start + 1) + config->range_start;

    pthread_mutex_lock(&entry->mutex);
    entry->param.str[sizeof(entry->param.str) - 1] = '\0'; // Ensure null termination
    snprintf(entry->param.str, sizeof(entry->param.str), "Entry %ld configured", pthread_self());
    log_config(entry->param.str, config);
    pthread_mutex_unlock(&entry->mutex);

    pthread_cond_broadcast(&entry->cond);
    return NULL;
}

void manage_configuration(Config *config) {
    pthread_t threads[config->num_entries];
    size_t active_threads = 0;

    for (size_t i = 0; i < config->num_entries; ++i) {
        int rc = pthread_create(&threads[active_threads], NULL, configure, &config->entries[i]);
        if (rc) {
            perror("Could not create thread");
            break;
        }
        active_threads++;
        if (active_threads >= config->max_concurrent) {
            for (size_t j = 0; j < active_threads; ++j)
                pthread_join(threads[j], NULL);
            active_threads = 0;
        }
    }

    if (active_threads > 0)
        for (size_t j = 0; j < active_threads; ++j)
            pthread_join(threads[j], NULL);
}
