#include <iostream>
#include <unordered_map>
#include <vector>
#include <random>
#include <thread>

class GarbageCollector {
public:
    void collect() {}  // Place your garbage collection logic here
};

struct Record {
    int value;
};

std::unordered_map<int, Record> records;

void initializeArrays(int N, int minValue, int maxValue) {
    if (N <= 0 || static_cast<unsigned>(N) > std::numeric_limits<std::size_t>::max()) {
        std::cerr << "Invalid N value" << std::endl;
        return;
    }

    std::vector<long> offsets(N);
    std::vector<int> keys(N);

    std::mt19937 gen(std::random_device{}()); // thread-safe random number generator
    std::uniform_int_distribution<> distrib(minValue, maxValue);

    for (auto& key : keys) {
        if (records.count(key)) {
            while (true) {
                key = distrib(gen);
                if (!records.count(key)) break;
            }
        }
        records[key] = Record{0};
    }

    for (auto& offset : offsets) {
        if (records.empty()) break;
        int key;
        do {
            key = keys[gen() % N];
        } while (records[key].value != 0);
        offset = key;
        records[key].value++; // mark record as used
    }
}

