struct line {
    char *data;
    size_t length;
};

void destroy_line(struct line *line) {
    if (line && line->data) free(line->data);
}

struct line read_line(FILE *file) {
    struct line line = {0};
    char c;
    size_t capacity = 1, pos = 0;

    while ((c = fgetc(file)) != EOF) {
        if (pos >= capacity) {
            capacity *= 2;
            line.data = realloc(line.data, capacity);
        }
        line.data[pos++] = c;
    }

    line.length = pos;
    line.data[pos] = '\0';
    return line;
}

double calculate_weighted_average(const double *values, size_t count, double weight_factor) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += values[i] * pow(weight_factor, count - i - 1);
    }
    return sum;
}

void process_file(const char *path, FILE *file, double weight_factor) {
    struct line line;
    size_t total_lines = 0;

    while ((line = read_line(file)) .length > 0) {
        ++total_lines;
        char **fields = calloc(4, sizeof(char *));
        char *token = strtok((char *) line.data, " ");
        size_t field_count = 0;
        while (token) {
            fields[field_count++] = token;
            token = strtok(NULL, " ");
        }
        if (field_count < 3) continue; // Ignore invalid lines

        double weights[] = {1.0 / 3.0, 1.0 / 6.0, 1.0 / 6.0};
        double sum = 0.0;
        for (size_t i = field_count - 3; i < field_count; ++i) {
            sum += atof(fields[i]);
            weights[i - field_count + 3] *= weight_factor;
        }
        fields[field_count - 1] = malloc((int) (strlen(fields[field_count - 1]) + 20) * sizeof(char));
        snprintf(fields[field_count - 1], strlen(fields[field_count - 1]) + 20, "%f", calculate_weighted_average(sum, weights, weight_factor));

        for (size_t i = 0; i < field_count; ++i) {
            printf("%s%c", fields[i], i < field_count - 1 ? ',' : '\n');
            free(fields[i]);
        }
        free(fields);
    }

    destroy_line(&line);
}

int main(int argc, char **argv) {
    const char *input_dir = ".";
    double weight_factor = 1.0;
    int verbose = 0;
    const char *log_file = "error.log";
    const char *output_dir = "processed/";

    static struct option long_options[] = {
        {"help", no_argument, NULL, 'h'},
        {"verbose", no_argument, NULL, 'v'},
        {"weight-factor", required_argument, NULL, 'w'},
        {"output_directory", required_argument, NULL, 'o'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "hvw:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h': printf("Usage: %s [options]\n", argv[0]); return EXIT_SUCCESS;
            case 'v': verbose = 1; break;
            case 'w': weight_factor = atof(optarg); break;
            case 'o': output_dir = optarg; break;
            default: printf("Invalid option\n"); return EXIT_FAILURE;
        }
    }

    if (weight_factor <= 0.0) {
        fprintf(stderr, "Weight factor must be greater than 0.0\n");
        return EXIT_FAILURE;
    }

    DIR *dir = opendir(input_dir);
    if (!dir) {
        perror("opendir");
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", input_dir, entry->d_name);
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        int fd = open(file_path, O_RDONLY);
        if (fd < 0) {
            perror("open");
            continue;
        }

        struct stat st;
        fstat(fd, &st);
        close(fd);

        if (!S_ISREG(st.st_mode)) continue; // Skip non-regular files

        FILE *file = fopen(file_path, "r");
        if (!file) {
            perror("fopen");
            continue;
        }

        process_file(file_path, file, weight_factor);
        fclose(file);
    }
    closedir(dir);

    mkdir(output_dir, S_IRWXU | S_IRGRP | S_IROTH);

    printf("Total lines processed: %lu\n", total_lines);
    return EXIT_SUCCESS;
}
