namespace mem_manager {

constexpr size_t max_memory = 100000000; // Maximum memory usage limit (bytes)
std::mutex mtx;
boost::thread_specific_ptr<void*> heap_ptr;

class Record {
public:
    int value;

    Record() : value(0) {}
};

class Array {
public:
    long offset;
    std::vector<int> keys;
    std::vector<Record> records;

    Array(long offset, size_t capacity)
        : offset(offset), keys(capacity), records(capacity) {}
};

class ConcurrentMemoryManager {
private:
    void* heap;
    size_t total_used = 0;

public:
    std::unique_ptr<Array> create_array(long offset, size_t capacity);
    Record& get_record(Array& array, int key);

    ConcurrentMemoryManager() {
        heap = mmap(nullptr, max_memory, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (heap == MAP_FAILED) {
            throw std::runtime_error("Memory allocation failed");
        }
        heap_ptr.reset(heap);
    }

    ~ConcurrentMemoryManager() {
        munmap((char*)heap_ptr.get(), max_memory);
    }
};

std::unique_ptr<Array> ConcurrentMemoryManager::create_array(long offset, size_t capacity) {
    Array* arr = static_cast<Array*>(((char*)heap_ptr.get() + total_used));
    total_used += sizeof(Array) + sizeof(int) * (capacity + 1) + sizeof(Record) * (capacity + 1);
    if (total_used > max_memory) {
        throw std::runtime_error("Memory limit exceeded");
    }
    new (arr) Array(offset, capacity);
    for (size_t i = 0; i < capacity + 1; ++i) {
        arr->keys[i] = -1;
        new (&arr->records[i]) Record();
    }
    return std::unique_ptr<Array>(arr);
}

Record& ConcurrentMemoryManager::get_record(Array& array, int key) {
    mtx.lock();
    if (array.keys[key] == -1) {
        for (size_t i = 0; i < array.records.size(); ++i) {
            if (array.keys[i] == -1) {
                array.keys[i] = key;
                break;
            }
        }
    }
    Record* rec = &array.records[array.keys[key]];
    mtx.unlock();
    return *rec;
}

