typedef struct {
    int value;
} record;

void log_success(const char* message) {
    // Integrate with an existing logging framework here
    printf("%s\n", message);
}

void* create_record_array(int N, int minValue, int maxValue, void** records, pthread_mutex_t* mutex) {
    *records = malloc(N * sizeof(record));
    if (*records == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    log_success("Record array created");

    for (int i = 0; i < N; ++i) {
        int value;
        do {
            value = rand() % (maxValue - minValue + 1) + minValue;
        } while (i < N && values_exist(*records, value));

        pthread_mutex_lock(mutex);
        (*records)[i].value = value;
        pthread_mutex_unlock(mutex);
    }

    return *records;
}

int values_exist(record* records, int value) {
    for (int i = 0; i < N; ++i) {
        if (records[i].value == value) {
            return 1;
        }
    }
    return 0;
}

void cleanup_record_array(void* records) {
    free(records);
    log_success("Record array cleaned up");
}

int main() {
    // Initialize a mutex for concurrent access
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int N = 1024;
    int minValue = -100, maxValue = 100;
    record* records;

    create_record_array(N, minValue, maxValue, &records, &mutex);

    // Use the created dataset here...

    cleanup_record_array(records);

    pthread_mutex_destroy(&mutex);
    return 0;
}
