import java.util.*;
import java.util.concurrent.*;
import java.net.*;
import com.google.common.base.*;
import com.google.common.collect.*;
import org.slf4j.*;
import javax.annotation.*;

public class UserActionProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(UserActionProcessor.class);
    private final Map<String, Action> actionRegistry;
    private ExecutorService executor;

    public UserActionProcessor() {
        actionRegistry = new ConcurrentHashMap<>();
        executor = Executors.newFixedThreadPool(200);
    }

    public void registerAction(@NotNull String actionId, @NotNull Action action) {
        actionRegistry.putIfAbsent(actionId, action);
    }

    public Future<?> processUserRequest(@NotNull String userId, @NotNull URL url, @NotNull List<String> actionNames) {
        UserRequestData userRequest = new UserRequestData(userId, url, actionNames);
        return executor.submit(() -> processUserRequestInternal(userRequest));
    }

    private void processUserRequestInternal(@NotNull UserRequestData userRequest) {
        try {
            List<Action> matchedActions = Lists.newArrayList();

            for (Map.Entry<String, Action> entry : actionRegistry.entrySet()) {
                String actionId = entry.getKey();
                if (userRequest.actionNames.contains(actionId)) {
                    matchedActions.add(entry.getValue());
                }
            }

            for (Action action : matchedActions) {
                try {
                    action.execute(userRequest);
                } catch (Exception e) {
                    LOGGER.error("Error executing action '{}' for user '{}': {}", action.getId(), userRequest.userId, e.getMessage());
                }
            }
        } finally {
            // Log request processing details and resource usage metrics here
        }
    }

    public void shutdown() {
        if (executor != null) {
            executor.shutdownNow();
        }
    }
}
```

