static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static char *log_buffer = NULL;
static size_t log_capacity = 0, log_size = 0;

void init_logs(size_t capacity) {
    if (log_buffer) free(log_buffer);
    log_buffer = malloc(capacity);
    log_capacity = capacity;
    log_size = 0;
}

void log(const char *format, ...) {
    va_list args;
    char buffer[4096];

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    pthread_mutex_lock(&log_mutex);
    if (log_size + strlen(buffer) >= log_capacity) {
        log_capacity *= 2;
        log_buffer = realloc(log_buffer, log_capacity);
    }
    strcpy(log_buffer + log_size, buffer);
    log_size += strlen(buffer);
    pthread_mutex_unlock(&log_mutex);
}

void *log_async(void *arg) {
    while (1) {
        sleep(1);
        pthread_mutex_lock(&log_mutex);
        if (log_size > 0) {
            fputs(log_buffer, stderr);
            log_size = 0;
        }
        pthread_mutex_unlock(&log_mutex);
    }
}

void start_log_thread() {
    pthread_t thread;
    pthread_create(&thread, NULL, log_async, NULL);
}

int aligned_alloc(size_t alignment, size_t size) {
    size_t allocated = ((((size_t)1 + size + alignment - 1)) / alignment) * alignment;
    void *ptr = malloc(allocated);
    if (!ptr) return 0;
    memset((char *) ptr + size, 0, aligned - size);
    return (char *) ptr;
}

