} Record;

int allocate_memory(size_t N, int minValue, int maxValue, int* keys, long* offsets, Record** records) {
    if (maxValue - minValue + 1 < N) {
        printf("Warning: Specified range is insufficient for given N. Adjusting N or using a default value scheme.\n");
        N = N / 10; // Example adjustment strategy
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t chunkSize = (N + (sizeof(Record) * N) - 1) / sizeof(Record);
    size_t numChunks = (N + chunkSize - 1) / chunkSize;
    Record** chunks = malloc(numChunks * sizeof(Record*));

    for (size_t i = 0; i < numChunks; ++i) {
        chunks[i] = malloc(chunkSize * sizeof(Record));
    }

    size_t chunkIndex = 0;
    size_t currentKey = 0;
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
