            ++chunkIndex %= numChunks;
        } else {
            pthread_mutex_unlock(&lock);
            --i; // Backtrack and retry with a new key
        }
    }

    pthread_mutex_destroy(&lock);
    free(chunks);

    return 0;
}

void cleanup(Record* records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        free(records + i);
