AES256GCMContext aes256gcm_init(const uint8_t* password, size_t passwordLen, const uint8_t* aad, size_t aadLen) {
    if (passwordLen > KEY_SIZE || aadLen > MAX_INPUT_LEN) {
        std::cerr << "Error: Input size exceeds the limit." << std::endl;
        throw std::runtime_error("Input size too large.");
    }

    auto passwd = readInput(password);
    if (!passwd) {
        // Handle errors from reading password gracefully.
        throw std::runtime_error("Error reading password.");
    }

    auto aadData = readInput(aad);
    if (!aadData) {
