    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key, static_cast<unsigned char*>(aadData.get()), IV_LENGTH) != 1) {
        throw std::runtime_error("Error initializing cipher.");
    }

    AES256GCMContext context;
    context.ctx = ctx;
    return context;
}

void aes256gcm_cleanup(AES256GCMContext* ctx) {
    EVP_CIPHER_CTX_free((*ctx).ctx);
}
