static const int minValue = -100;
static const int maxValue = 100;
static size_t recordsCapacity = 0;

void initialize(int n) {
    if (n <= 0) return;

    pthread_mutex_lock(&init_lock);
    if (N > 0) {
        N = n;
    }
    pthread_mutex_unlock(&init_lock);

    keys = malloc(N * sizeof(int));
    offsets = calloc(N, sizeof(long));
    records = realloc(NULL, recordsCapacity + N * sizeof(Record));
    recordsCapacity += N;
}

Record* populate(void) {
    Record *records_ptr = records;

    for (size_t i = 0; i < recordsCapacity; ++i) {
        int j;
        do {
            j = (rand() % (recordsCapacity - i)) + i;
        } while (records_ptr[j].value != 0 && j < recordsCapacity);

        if (j >= recordsCapacity) continue; // handle edge case: resizing needed

