    double d;
    char c;
    int index;
};

void init_memory(double* d, char* c, struct item** s, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        d[i] = (double)(rand() % 201 - 100);
        c[i] = 'a' + (i % 26);
        s[i] = malloc(sizeof(*s));
        *s[i] = (struct item){.d = d[i], .c = c[i], .index = i};
    }
}

void init_transaction_array(transaction* t, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        t[i].item_ptr = &s[i];
    }
}

void cumulative_sum(transaction *t, double *cum_sum) {
    cum_sum[0] = t[0].value;
    for (size_t i = 1; i < M; ++i) {
        cum_sum[i] = cum_sum[i - 1] + t[i].value;
    }
}

void* handle_memory(void *arg) {
    transaction* t = (transaction*) arg;
    t->item_ptr->d = (*t->item_ptr->index % 201) * 0.5 - 100;
    return NULL;
}

int main() {
