int init_node_array(size_t num_nodes, Node*** nodes, size_t* error_code) {
    if (num_nodes == 0 || !nodes) {
        *error_code = 1; // Invalid input parameters
        return -1;
    }

    *nodes = malloc(num_nodes * sizeof(Node*));
    if (!*nodes) {
        *error_code = 2; // Memory allocation failure
        return -1;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        (*nodes)[i] = malloc(sizeof(Node));
        if (!(*nodes)[i]) {
            *error_code = 3; // Memory allocation failure
            free(*nodes);
            return -1;
        }

        // Initialize double value with a random number within given range
        (*((*nodes)[i]))->value = (double)rand() / RAND_MAX * 100.0;

        // Allocate unique name and set char* pointer
        size_t j;
        for (j = 0; j < i; ++j) {
            if ((*((*nodes)[i])->name == (*((*nodes)[j])->name)) {
                free((*((*nodes)[i])->name);
                free(*nodes);
                *error_code = 4; // Name collisions
                return -1;
            }
        }

        (*((*nodes)[i])->name = strdup(names[rand() % MAX_NAMES]);
        if (!(*((*nodes)[i])->name) {
            free(*nodes);
            for (size_t k = 0; k < i; ++k) {
                free((*nodes)[k]->name);
            }
            *error_code = 5; // Memory allocation failure
