// Memory pool for long offsets
static pthread_mutex_t offsetPoolMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t offsetPoolSize = 0;
static long *offsetPool = NULL;

void logOperation(const char* operation) {
    // Implement logging framework integration here
}

int allocateMemory(size_t n, size_t *longArray, int *keyArray, Record **recordArray) {
    if (n > RAND_MAX - MIN_VALUE + 1) {
        return -1; // Insufficient range
    }

    // Allocate and initialize long array using memory pooling
    if (!offsetPool || offsetPoolSize <= n) {
        pthread_mutex_lock(&offsetPoolMutex);
        if (!offsetPool || offsetPoolSize <= n) {
            size_t newPoolSize = n + offsetPoolSize;
            if (newPoolSize > offsetPoolSize) {
                long *temp = realloc(offsetPool, newPoolSize * sizeof(long));
                if (!temp) {
                    pthread_mutex_unlock(&offsetPoolMutex);
                    return -1; // Memory allocation failure
                }
                offsetPool = temp;
            }
            offsetPoolSize = newPoolSize;
        }
        longArray = offsetPool;
    }

    for (size_t i = 0; i < n; ++i) {
        longArray[i] = i;
    }

    // Allocate and initialize int key array
    intArray = malloc(n * sizeof(int));
    if (!intArray) {
        logOperation("Memory allocation failure");
        return -1; // Memory allocation failure
    }
    for (size_t i = 0; i < n; ++i) {
        keyArray[i] = i;
    }

    // Allocate and initialize record array with random values
    Record *temp = calloc(n, sizeof(Record));
    if (!temp) {
        logOperation("Memory allocation failure");
        free(intArray);
        return -1; // Memory allocation failure
    }
    *recordArray = temp;

    for (size_t i = 0; i < n; ++i) {
        int value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        while (findDuplicate(temp, value)) {
            value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        }
        temp[i].value = value;
    }

    logOperation("Memory allocation successful");
    return 0;
}

int findDuplicate(Record *array, int value) {
    for (size_t i = 0; i < array_size; ++i) {
        if (array[i].value == value) {
            return 1;
        }
    }
    return 0;
}

