```cpp
#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <random>
#include <pthread.h>
#include <boost/property_tree/ptree.hpp>
#include <boost/pool/object_pool.hpp>
#include <boost/pool/simple_pool.hpp>
#include <boost/unordered_map.hpp>

struct Node {
    double value;
    std::string* name;
};

using NodePool = boost::object_pool<Node>;
using NameMap = boost::unordered_map<std::string, size_t>;
using StatTracker = boost::property_tree::ptree;

StatTracker stats;

void addName(const std::string& name) {
    if (name_map.find(name) == name_map.end()) {
        name_map[name] = 1;
    } else {
        ++name_map[name];
    }
}

NodePool* getPool(size_t size, StatTracker& stats) {
    static std::vector<std::string> predefinedNames = {"Alice", "Bob", "Charlie", "David"};
    static NameMap name_map;
    static pthread_mutex_t names_mutex = PTHREAD_MUTEX_INITIALIZER;

    NodePool* pool = new NodePool(sizeof(Node));

    std::mt19937 gen(std::random_device{}());
    std::uniform_real_distribution<> distr(0.0, 100.0);

    pthread_mutex_lock(&names_mutex);

    for (size_t i = 0; i < size; ++i) {
        Node* node = pool->construct();
        node->value = distr(gen);
        std::string& name = *(node->name = new std::string());

        for (const auto& predefinedName : predefinedNames) {
            if (!addName(name)) {
                name = predefinedName;
                break;
            }
        }
    }

    pthread_mutex_unlock(&names_mutex);

    stats.put("nodes", size);
    stats.put("unique_names", name_map.size());

    return pool;
}

void destroyNode(Node* node) {
    delete node->name;
    node->name = nullptr;
    nodePool.destroy(node);
}

int main() {
    // Replace this with the code to initialize and run multiple threads using the NodePool function.
}
