record* initialize_data_structures(int n_offsets, int n_keys, int min_value, int max_value) {
    if (n_offsets > n_keys) {
        n_offsets = n_keys;
    }

    long *offsets = mmap(NULL, sizeof(long) * n_offsets, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    int *keys = malloc(sizeof(int) * n_keys);
    record *records = mmap(NULL, sizeof(record) * n_offsets, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    total_allocated += (sizeof(long) * n_offsets + sizeof(int) * n_keys + sizeof(record) * n_offsets);

    srand(time(NULL));

