        offsets[i] = i;
        records[i].key = keys[i] = i;
        sprintf(records[i].value, "%d", rand() % (max_value - min_value + 1) + min_value);
    }

    return records;
}

void free_data_structures(record *records) {
    munmap((void *)records, sizeof(record) * total_allocated);
    free(records);
    total_allocated = 0;
}
