function traverseDom(node, selectorPattern) {
    const matches = [];
    function traverse(node, pattern, acc) {
        if (node === null) return;

        if (pattern.test(node)) {
            acc.push(node);
        }

        for (let i = 0; i < node.childNodes.length; ++i) {
            traverse(node.childNodes[i], pattern, acc);
        }
    }

    traverse(node, new RegExp(`^${selectorPattern}$`), matches);
    return matches;
}
