struct string_pool {
    size_t capacity;
    size_t count;
    char **strings;
    pthread_mutex_t lock;
};

data_item* create_data_array(size_t *size) {
    *size = 0;
    data_item *array = malloc(*size * sizeof(data_item));
    if (!array) return NULL;

    for (size_t i = 0; i < *size; ++i) {
        array[i].id = i;
        // Call function to load random string from dynamic source
        strcpy(array[i].name, load_random_string());
        array[i].value = rand() % 100 + 50; // Generate random float value within range [50, 150)
    }

    return array;
}

void resize_data_array(data_item **array, size_t *size, size_t new_capacity) {
    if (new_capacity <= *size) return;

    data_item *temp = realloc(*array, new_capacity * sizeof(data_item));
    if (!temp) return;

    *array = temp;

    for (size_t i = *size; i < new_capacity; ++i) {
        (*array)[i].id = i;
        // Call function to load random string from dynamic source
        strcpy((*array)[i].name, load_random_string());
        (*array)[i].value = rand() % 100 + 50;
    }

    *size = new_capacity;
}

struct string_pool *create_string_pool(size_t capacity) {
    struct string_pool *pool = malloc(sizeof(struct string_pool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->count = 0;
    pool->strings = calloc(capacity, sizeof(char*));
    if (!pool->strings) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void add_string_to_pool(struct string_pool *pool, const char *str) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count < pool->capacity) {
        pool->strings[pool->count++] = strdup(str);
        pthread_mutex_unlock(&pool->pool->lock);
        return;
    }

    free(pool->strings[0]); // Free least recently used string if necessary
    memmove(pool->strings, pool->strings + 1, (pool->capacity - 1) * sizeof(char*));
    pool->strings[pool->capacity - 1] = strdup(str);
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
}

const char* load_random_string() {
    // Code to load a random string from dynamic source goes here.
    // If the source is unavailable, call add_string_to_pool with a fallback string.
    struct string_pool *pool = get_string_pool();
    if (pool) add_string_to_pool(pool, "fallback_string");

    if (!pool || pool->count == 0) {
        // Use default list of strings as a fallback
        static const char *default_strings[] = {"default_string1", "default_string2", "default_string3"};
        return default_strings[rand() % sizeof(default_strings)/sizeof(default_strings[0])];
    }

    pthread_mutex_lock(&pool->lock);
    char *str = pool->strings[rand() % pool->count];
    pthread_mutex_unlock(&pool->lock);
    return str;
}
