#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

#define ALIGNMENT 16
#define KEY_COUNT_INIT 4
#define VALUE_MAX 256

typedef long offset_t;
typedef struct {
    int value;
    offset_t key_offset;
} record_t;

struct cache_t {
    record_t* records;
    offset_t* keys;
    size_t count;
    size_t capacity;
};

void* aligned_malloc(size_t size) {
    void* ptr = malloc(size + ALIGNMENT);
    if (ptr == NULL) return NULL;
    long aligned_ptr = ((long)ptr + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
    memmove(aligned_ptr, ptr, size);
    return aligned_ptr;
}

void aligned_free(void* ptr) {
    if (ptr != NULL) free(((char*)ptr) - ALIGNMENT);
}

struct cache_t* create_cache() {
    struct cache_t* cache = malloc(sizeof(struct cache_t));
    if (!cache) return NULL;
    cache->records = aligned_malloc(KEY_COUNT_INIT * sizeof(record_t));
    if (!cache->records) goto err;
    cache->keys = aligned_malloc(KEY_COUNT_INIT * sizeof(offset_t));
    if (!cache->keys) goto err;
    cache->count = 0;
    cache->capacity = KEY_COUNT_INIT;
    return cache;

err:
    destroy_cache(cache);
    return NULL;
}

void destroy_cache(struct cache_t* cache) {
    if (!cache) return;
    for (size_t i = 0; i < cache->count; ++i) {
        aligned_free((char*)cache->records + i * sizeof(record_t));
    }
    aligned_free((char*)cache->records);
    aligned_free((char*)cache->keys);
    free(cache);
}

int find_empty_slot(struct cache_t* cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        if (!cache->keys[i]) return (int)i;
    }
    return -1;
}

void insert(struct cache_t* cache, offset_t key, int value) {
    int index = find_empty_slot(cache);
    if (index == -1 && cache->count == cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        record_t* temp_records = aligned_malloc((new_capacity + 1) * sizeof(record_t));
        offset_t* temp_keys = aligned_malloc((new_capacity + 1) * sizeof(offset_t));
        if (!temp_records || !temp_keys) goto err;

        for (size_t i = 0; i < cache->count; ++i) {
            memcpy(&temp_records[i], &cache->records[i], sizeof(record_t));
            temp_keys[i] = cache->keys[i];
        }

        free(cache->records);
        free(cache->keys);
        cache->capacity = new_capacity;
        cache->records = temp_records;
        cache->keys = temp_keys;
    }

    if (index == -1) index = cache->count++;

    record_t* record = &cache->records[index];
    offset_t key_offset = align(key, ALIGNMENT);
    offset_t diff = key_offset - cache->keys[index];
    if (diff > 0) {
        memmove((char*)record + sizeof(record_t), (char*)record, sizeof(record_t));
        record->key_offset += diff;
    }

    record->value = value;
    cache->keys[index] = key_offset;
}

int retrieve(struct cache_t* cache, offset_t key) {
    offset_t key_offset = cache->keys[find_slot(cache, key)];
    if (key_offset == 0) return -1;

    record_t* record = &cache->records[find_slot(cache, key)];
    offset_t diff = key_offset - ((char*)record - (char*)cache->keys);
    memmove((char*)record, (char*)record + sizeof(record_t), sizeof(record_t));
    return record->value;
}

int find_slot(struct cache_t* cache, offset_t key) {
    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->keys[i] == key) return i;
    }
    return -1;
}

void destroy_and_report_stats(struct cache_t* cache) {
    printf("Total allocated bytes: %lu\n", ((char*)cache->records + cache->capacity * sizeof(record_t)) - (char*)cache->keys);
    printf("Current free bytes: %lu\n", (char*)cache->keys + cache->capacity * sizeof(offset_t) - (char*)cache->records);
}

long align(long value, long alignment) {
    return (value + alignment - 1) & ~(alignment - 1);
}
