pthread_mutex_t data_lock, log_lock;
int num_processes = 0;
struct logfile logs[MAX_LOGS];
struct errlogfile errlogs[2]; // Error logs for successful and unsuccessful command executions

// Function prototypes
void rotate_log(struct logfile *log);
void handle_signal(int signum);
void execute_command(char *cmd, char **args);
int find_free_key();
long total_allocated = 0;

void* create_value(void) {
    void *ptr = mmap(NULL, VALUE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    long value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    sprintf((char*) ptr, "%ld", value);
    return ptr;
}

int main(int argc, char **argv) {
    // Initialize semaphore and mutexes
    sem_init(&sem, 0, MAX_PROCESSES);
    pthread_mutex_init(&data_lock, NULL);
    pthread_mutex_init(&log_lock, NULL);

    // Set up log files
    int i;
    for (i = 0; i < MAX_LOGS; ++i) {
        sprintf(logs[i].path, "log%d.txt", i);
        logs[i].fd = open(logs[i].path, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    }

    // Signal handling
    signal(SIGCHLD, handle_signal);

    while (1) {
        char cmd[256];
        scanf("%s", cmd);
        if (!strcmp(cmd, "exit")) break;

        execute_command(cmd, argv + 1);
    }

    // Clean up and exit
    sem_destroy(&sem);
    pthread_mutex_destroy(&data_lock);
    pthread_mutex_destroy(&log_lock);

    return 0;
}

void rotate_log(struct logfile *log) {
    if (log->fd > LOG_ROTATE_SIZE) {
        char new_path[256];
        sprintf(new_path, "log%d.txt", (log - logs + 1) % MAX_LOGS);
        int new_fd = open(new_path, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        dup2(new_fd, log->fd);
        close(new_fd);
    }
}

void handle_signal(int signum) {
    if (signum == SIGCHLD) {
        int status;
        waitpid(-1, &status, WNOHANG);
    }
}

void execute_command(char *cmd, char **args) {
    pthread_mutex_lock(&data_lock);
    if (num_processes < MAX_PROCESSES && sem_trywait(&sem)) {
        ++num_processes;
        pid_t pid = fork();

        if (!pid) {
            close(logs[log_index]->fd); // Close log file in child process
            execute_and_log_command(cmd, args);
            exit(0);
        } else if (pid > 0) {
            struct timespec timeout = { CHILD_TIMEOUT, 0 };
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            const struct timespec timeout_abstime = { (long long int)timeout.tv_sec + now.tv_nsec / timeout.tv_nsec * timeout.tv_sec, now.tv_nsec % timeout.tv_nsec };
            if (timerfd_create(CLOCK_REALTIME, TFD_NONBLOCK | TFD_CLOEXEC) == -1 || timerfd_settime(timerfd_create(CLOCK_REALTIME, TFD_NONBLOCK | TFD_CLOEXEC), 0, &timeout_abstime, NULL) == -1) {
                perror("timerfd");
            } else {
                if (read(timerfd_create(CLOCK_REALTIME, TFD_NONBLOCK | TFD_CLOEXEC), &now, sizeof(struct timespec)) <= 0 || now.tv_sec >= timeout.tv_sec + now.tv_nsec / timeout.tv_nsec) {
                    kill(pid, SIGTERM);
                } else {
                    waitpid(pid, NULL, 0);
                }
            }
        }
        pthread_mutex_unlock(&data_lock);
    }
}
