    upld_filename = tmpnam((char *)std::malloc(sizeof(char) * _NSGETC));
    if (upld_filename == nullptr || (file = fopen(upld_filename, "wb")) == nullptr) {
        std::cerr << "Error creating temporary file for uploading" << std::endl;
        return "";
    }

    curl = curl_easy_init();
    if (!curl) {
        std::cerr << "Error initializing curl handle" << std::endl;
        fclose(file);
        remove(upld_filename);
        return "";
    }

    // Configure curl options here based on the given parameters and threading requirements

    // Perform the upload in a loop with retries and timeouts
    for (int i = 0; i < retryAttempts; ++i) {
        CURLcode res;

        // Reset file pointer and read from temporary file in chunks
        fseek(file, 0, SEEK_SET);
        while ((readBytes = fread(buffer.get(), 1, chunkSize, file)) > 0) {
            totalBytes += readBytes;
            res = curl_easy_write(curl, buffer.get(), readBytes, totalBytes);
            if (res != CURLE_OK) break;
        }

        // Perform the rest of the upload and close the file
        if (res == CURLE_OK || res == CURLE_WRITE_ERROR) {
            res = curl_easy_perform(curl);
            fclose(file);
            remove(upld_filename);
            if (res == CURLE_OK) return url;
        }
    }

    // Cleanup the resources here and handle errors

    return "";
}
