// Asynchronous Reduction Function (Note: C doesn't have native async/await support. Here's a pseudo-code using coroutines and libunwind)
#include <coroutine>
#include <libunwind>

typedef struct Reducer {
    long initial_value;
    void (*callback)(long acc, const long* val, void* user_data);
    void* user_data;
} Reducer;

void async_reduce(Reducer reducer, size_t array_size, const long* input_array) {
    // Coroutine implementation is out of scope for this example. For demonstration purposes, we'll use a simple recursive reduction function instead.
    reduce(reducer, input_array, 0);
}

void reduce(Reducer reducer, const long* array, size_t index) {
    if (index == array_size) {
        // Base case: we've processed the entire array, invoke callback with final result.
        reducer.callback(reducer.initial_value, NULL, reducer.user_data);
        return;
    }

    long partial_result = reducer.initial_value + array[index];

    // Recursive call to process next element in the array.
    reduce({ .initial_value = partial_result }, array, index + 1);
}
