#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Custom allocator with retries
void* custom_malloc(size_t size, size_t num_retries) {
    void *ptr = malloc(size);

    if (!ptr && num_retries > 0) {
        return custom_malloc(size, --num_retries);
    }

    return ptr;
}

// Probabilistic hash-based resolution strategy for unique values
uint32_t probabilistic_hash(int value) {
    uint64_t hash = 5381;
    int c;

    while (value != 0) {
        c = (value & 0x7FFF);
        value >>= 15;
        hash = ((hash << 5) + hash) + c;
        hash &= ((uint64_t)1 << 64) - 1;
    }

    return (uint32_t)(hash & 0x7FFFFFFF);
}

// Multi-threaded function to set record values
void thread_func(int id, int N, int minValue, int maxValue, int *keys, long *offsets, record **records) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = keys[id]; i < N && i < MAX_N; i++) {
        int hash = probabilistic_hash(records[i]->value);
        int j = id + hash % num_threads;

        pthread_mutex_lock(&lock);
        while (records[j]->value != 0) {
            j = (j + 1) % num_threads;
        }
        pthread_mutex_unlock(&lock);

        records[j]->value = rand() % (maxValue - minValue + 1) + minValue;
        keys[id] = i + 1;
    }
}

// Function to initialize arrays and records
void init(int N, int num_threads, int minValue, int maxValue, record ***records, long **offsets, int **keys) {
    const int MAX_N = 1000000; // Threshold for dynamic resizing

    *keys = (int*)calloc(N, sizeof(int));
    if (!*keys) {
        fprintf(stderr, "Failed to allocate keys array\n");
        exit(EXIT_FAILURE);
