typedef struct {
    int id;
    char attributes[MAX_LENGTH];
} object;

static object* objects = NULL;
static size_t num_objects = 0;
static size_t max_length = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int timeout_ms = 1000; // Default timeout in milliseconds

void initialize(size_t N, size_t maxLength) {
    if (N <= 0) {
        fprintf(stderr, "Error: Invalid or zero number of objects.\n");
        return;
    }

    this_thread = pthread_self();
    mlockall(MCL_CURRENT | MCL_FUTURE); // Lock memory for this thread and its children

    if (objects) {
        free(objects);
    }

    objects = calloc(N, sizeof(object));

    if (!objects) {
        fprintf(stderr, "Error: Failed to allocate memory for objects.\n");
        pthread_exit(this_thread); // Exit the current thread gracefully
    }

    num_objects = N;
    max_length = maxLength;
    srand(time(NULL));

    initializeAttributes();
}

void initializeAttributes() {
    for (size_t i = 0; i < num_objects; ++i) {
        objects[i].id = i + 1;
        snprintf(objects[i].attributes, max_length, "%.*s", max_length, generateRandomString());

        // Ensure attribute strings are unique within the array
        while (hasDuplicateAttribute()) {
            objects[i].id = rand() % num_objects + 1;
            snprintf(objects[i].attributes, max_length, "%.*s", max_length, generateRandomString());
        }
    }
}

void appendObject() {
    if (num_objects == 0) {
        fprintf(stderr, "Error: Cannot add an object to an empty collection.\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    size_t new_size = num_objects + 1;

    if (new_size > num_objects) {
        object* tmp = realloc(objects, new_size * sizeof(object));

        if (!tmp) {
            pthread_mutex_unlock(&mutex);
