using Newtonsoft.Json;

namespace MessageDecryptionService
{
    public class DecryptionConfig
    {
        public string Algorithm { get; set; }
        public byte[] Key { get; set; }
        public byte[] InitializationVector { get; set; }
    }

    public class MessageMetadata
    {
        public string Algorithm { get; set; }
        public string HmacHash { get; set; }
    }

    public class DecryptionService
    {
        private Dictionary<string, Func<byte[], byte[]>> _decryptors = new Dictionary<string, Func<byte[], byte[]>>();
        private HMACSHA256 _hmac;

        public DecryptionService(Dictionary<string, DecryptionConfig> decryptionConfigs)
        {
            foreach (var config in decryptionConfigs)
            {
                var algorithmName = config.Key;
                _decryptors[algorithmName] = CreateDecryptor(config.Value);
                RegisterHmacFunction(algorithmName, config.Value.Algorithm);
            }
        }

        private void RegisterHmacFunction(string algorithmName, string hmacAlgorithm)
        {
            _hmac = new HMACSHA256(Encoding.UTF8.GetBytes(algorithmName));
        }

        private Func<byte[], byte[]> CreateDecryptor(DecryptionConfig config)
        {
            return (encryptedData) =>
            {
                using (var decryptor = GetDecryptor(config.Algorithm))
                {
                    var decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
                    return decryptedData;
                }
            };
        }

        private AesManaged GetDecryptor(string algorithm) => Aes.Create(_decryptors[algorithm]);

        public async Task<string> DecryptMessageAsync(Stream messageStream, Dictionary<string, DecryptionConfig> decryptionConfigs)
        {
            using (var reader = new StreamReader(messageStream))
            {
                var metadataJson = await reader.ReadToEndAsync();
                var metadata = JsonConvert.DeserializeObject<MessageMetadata>(metadataJson);
                var encryptedData = await ReadAllBytesAsync(messageStream);

                if (!VerifyHmacHash(metadata, encryptedData))
                {
                    LogError("Invalid HMAC hash");
                    return null;
                }

                var decryptor = _decryptors[metadata.Algorithm];
                var decryptedData = await Task.Run(() => decryptor(encryptedData));

                return Encoding.UTF8.GetString(decryptedData);
            }
        }

        private bool VerifyHmacHash(MessageMetadata metadata, byte[] encryptedData)
        {
            var hmac = _hmac.ComputeHash(Encoding.UTF8.GetBytes(metadata.Algorithm + encryptedData));
            return hmac.SequenceEqual(Convert.FromBase64String(metadata.HmacHash));
        }

        private async Task<byte[]> ReadAllBytesAsync(Stream stream)
        {
            var buffer = new byte[16 * 1024];
            using (var ms = new MemoryStream() )
            {
                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    ms.Write(buffer, 0, bytesRead);
                }
                return ms.ToArray();
            }
        }

        private void LogError(string message)
        {
            // Implement logging functionality here
        }
    }
}
