typedef struct {
    int value;
} record_t;

record_t** initialize_record_system(long* offsets, int* keys, size_t max_size, size_t min_value, size_t max_value) {
    if (!offsets || !keys || max_size <= 0 || min_value > max_value)
        return NULL;

    qsort(offsets, sizeof(offsets)/sizeof(long), sizeof(long), (int (*)(const void *, const void *))compareLong);
    qsort(keys, sizeof(keys)/sizeof(int), sizeof(int), (int (*)(const void *, const void *))compareInt);

    size_t records_size = 0;
    for (size_t i = 1; i < sizeof(offsets)/sizeof(long); ++i) {
        if (offsets[i] - offsets[i-1] > max_size)
            break;
        records_size += keys[i] - keys[i-1];
    }

    if (records_size > max_size)
        return NULL;

    record_t* records = malloc(records_size * sizeof(record_t));
    if (!records)
        return NULL;

    srand(time(NULL));
    size_t idx = 0;
    for (size_t i = 0; i < sizeof(keys)/sizeof(int); ++i) {
        for (size_t j = keys[i]; j > keys[i-1] && j <= keys[i] + offsets[i+1] - offsets[i]; --j) {
            records[idx++] = (record_t){ .value = rand() % (max_value - min_value + 1) + min_value };
        }
    }

    long* new_offsets = malloc((sizeof(offsets)/sizeof(long) + 1)*sizeof(long));
    if (!new_offsets) {
        free(records);
        return NULL;
    }
    memcpy(new_offsets, offsets, sizeof(offsets));
    new_offsets[sizeof(offsets)/sizeof(long)] = offsets[sizeof(offsets)/sizeof(long)] + records_size;

    int* new_keys = malloc((sizeof(keys)/sizeof(int) + 1)*sizeof(int));
    if (!new_keys) {
        free(records);
        free(new_offsets);
        return NULL;
    }
    memcpy(new_keys, keys, sizeof(keys));

    return (record_t**) { new_offsets, new_keys, records };
}

int compareLong(const void* a, const void* b) {
    return (*(const long *)a - *(const long *)b);
}

int compareInt(const void* a, const void* b) {
    return (*(const int *)a - *(const int *)b);
