#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
} Record;

struct Pool {
    Record* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
};

static void initPool(struct Pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->length = 0;
    pool->data = malloc(sizeof(Record) * capacity);
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for data array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity; ++i)
        pool->data[i].value = -1; // initialized to invalid value

    pthread_mutex_init(&pool->lock, NULL);
}

static Record* getRecord(struct Pool* pool) {
    pthread_mutex_lock(&pool->lock);

    while (pool->length >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        usleep(1000); // yield CPU to avoid busy waiting
        pthread_mutex_lock(&pool->lock);
    }

    Record* record = &pool->data[pool->length];
    pool->length++;
    pthread_mutex_unlock(&pool->lock);

    return record;
}

static void putRecord(struct Pool* pool, Record* record) {
    pthread_mutex_lock(&pool->lock);
    *record = (Record){0}; // reset to empty record
    pool->length--;
    pthread_mutex_unlock(&pool->lock);
}

static void resizePool(struct Pool* pool, size_t newCapacity) {
    if (newCapacity <= pool->capacity || !pool->data)
        return;

    Record* newData = malloc(sizeof(Record) * newCapacity);
    if (!newData) {
        fprintf(stderr, "Failed to allocate memory for new data array\n");
        exit(EXIT_FAILURE);
    }

    size_t minLen = pool->length < newCapacity ? pool->length : newCapacity;
    memcpy(newData, pool->data, sizeof(Record) * minLen);
    free(pool->data);
    pool->data = newData;
    pool->capacity = newCapacity;
}

static int getUniqueRandom(int minValue, int maxValue, bool* hasDuplicate) {
    int value;
    do {
        value = rand() % (maxValue - minValue + 1) + minValue;
        *hasDuplicate = false;
    } while (hasDuplicate);

    return value;
}

void init(size_t N, int minValue, int maxValue) {
    struct Pool pool;
    initPool(&pool, N);

    Record* keys = malloc(sizeof(int) * N);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; ++i)
        keys[i] = i;

    pthread_t threads[N];

    // Launch worker threads
    for (size_t i = 0; i < N; ++i) {
        int rc = pthread_create(&threads[i], NULL, worker, &pool, &keys[i], minValue, maxValue);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < N; ++i)
        pthread_join(threads[i], NULL);

    free(keys);
}

void* worker(void* arg) {
    Record** recordPtr = (Record**)arg;
    int key = *(int*)((char*)arg + sizeof(void*));
    struct Pool* pool = *recordPtr;
    int minValue, maxValue;

    // Get required parameters
    gettimeofday(&(*((time_t*)arg + 1)), NULL); // Timestamp for logging
    memcpy(&minValue, ((char*)arg + sizeof(void*) + sizeof(time_t)), sizeof(int));
    memcpy(&maxValue, ((char*)arg + sizeof(void*) + sizeof(time_t) + sizeof(int)), sizeof(int));

    Record* record = getRecord(pool);
    int value;
    bool hasDuplicate;

    // Generate unique random number and populate the record with it
    do {
        value = getUniqueRandom(minValue, maxValue, &hasDuplicate);
    } while (record->value == value && hasDuplicate);

    record->value = value;

    free(arg); // Clean up stack memory
    return NULL;
}
