#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    void *data_ptr_long;
    void *data_ptr_int;
};

struct MemoryManager {
    struct Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void init_memory_manager(struct MemoryManager *mm, size_t initial_size) {
    mm->capacity = (initial_size > 10000) ? 10000 : initial_size;
    mm->size = 0;
    mm->records = malloc(mm->capacity * sizeof(struct Record));
    if (!mm->records) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&mm->lock, NULL);
}

void destroy_memory_manager(struct MemoryManager *mm) {
    free(mm->records);
    pthread_mutex_destroy(&mm->lock);
}

int random_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_record(struct Record *r, long offset, int key) {
    r->offset = offset;
    r->key = key;
    r->value = random_in_range(0, 100);
    r->data_ptr_long = &r->offset;
    r->data_ptr_int = &r->key;
}

void insert_record(struct MemoryManager *mm, long offset, int key) {
    pthread_mutex_lock(&mm->lock);

    if (mm->size == mm->capacity) {
        void *tmp = realloc(mm->records, (mm->capacity * 2) * sizeof(struct Record));
        if (!tmp) {
            perror("Memory allocation failure");
            pthread_mutex_unlock(&mm->lock);
            return;
        }
        mm->records = tmp;
        mm->capacity *= 2;
    }

    struct Record *r = &mm->records[mm->size];
    initialize_record(r, offset, key);
    mm->size++;
    pthread_mutex_unlock(&mm->lock);
}

int find_record(struct MemoryManager *mm, int key) {
    pthread_mutex_lock(&mm->lock);

    for (size_t i = 0; i < mm->size; ++i) {
        if (mm->records[i].key == key) {
            pthread_mutex_unlock(&mm->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&mm->lock);
    return -1;
}

void update_record(struct MemoryManager *mm, int index, int new_value) {
    pthread_mutex_lock(&mm->lock);

    if (index >= 0 && index < mm->size) {
        struct Record *r = &mm->records[index];
        r->value = new_value;
    }

    pthread_mutex_unlock(&mm->lock);
}

void example_usage(struct MemoryManager *mm) {
    srand(time(NULL));

    init_memory_manager(mm, 100);

    insert_record(mm, 1, 1);
    insert_record(mm, 2, 2);
    insert_record(mm, 3, 3);

    int index = find_record(mm, 2);
    printf("Index of key 2: %d\n", index); // Output: Index of key 2: 1

    update_record(mm, index, 99);

    index = find_record(mm, 2);
    printf("Updated index of key 2: %d\n", index); // Output: Updated index of key 2: 1
}
```

