typedef struct CacheNode {
    Record record;
    struct CacheNode* next;
} CacheNode;

struct Cache {
    unsigned long capacity;
    unsigned int size;
    CacheNode** table;
    pthread_mutex_t mutex;
};

Cache* create_cache(unsigned long capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->table = (CacheNode**)calloc((hash(0) % capacity), sizeof(CacheNode*));
    cache->mutex = PTHREAD_MUTEX_INITIALIZER;
    return cache;
}

unsigned int hash(unsigned long key) {
    // Implement your preferred hashing function here (e.g., open addressing or chaining)
    return key % CAPACITY;
}

Record* get_record(Cache* cache, unsigned int key) {
    pthread_mutex_lock(&cache->mutex);

    if (cache->size == 0) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        new_record->value = rand() % MAX_DOUBLE;
        CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
        node->record = *new_record;
        node->next = NULL;

        unsigned int index = hash(key) % cache->capacity;
        node->next = cache->table[index];
        cache->table[index] = node;
        cache->size++;

        pthread_mutex_unlock(&cache->mutex);
        return &node->record;
    }

    unsigned int index = hash(key) % cache->capacity;
    CacheNode* current = cache->table[index];

    while (current != NULL) {
        if (current->record.key == key) {
            pthread_mutex_unlock(&cache->mutex);
            return &current->record;
        }
        current = current->next;
    }

    // Create a new record and add it to the cache if not found
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->value = rand() % MAX_DOUBLE;
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    node->record = *new_record;
    node->next = NULL;

    current = cache->table[index];
    if (!current) {
        cache->table[index] = node;
    } else {
        node->next = current;
    }

    pthread_mutex_unlock(&cache->mutex);
    return &node->record;
}

