        int value;
        long* data;
        void* metadata;
    } record;
    std::chrono::steady_clock::time_point lastAccessedTime;
};

struct Metadata {
    std::chrono::steady_clock::time_point lastAccessedTime;
};

class RecordManager {
public:
    explicit RecordManager(size_t maxRecords) : records_(maxRecords), metadataMap_() {}

    void allocateRecord(long offset, int key) {
        Record& record = records_[currentIndex_];
        record.offset = offset;
        record.key = key;
        record.record.value = randomInt();
        record.record.data = nullptr;
        record.record.metadata = &metadata_[currentIndex_];
        record.lastAccessedTime = std::chrono::steady_clock::now();
        ++currentIndex_;
    }

    Record* getRecordByKey(int key) {
        auto it = metadataMap_.find(key);
        if (it == metadataMap_.end()) return nullptr;
        currentIndex_ = static_cast<size_t>(it->second);
        return &records_[currentIndex_];
    }

    void updateRecord(int key, long data) {
        Record* record = getRecordByKey(key);
        if (!record) return;
        record->record.data = const_cast<long*>(data ? &data : nullptr);
    }

    void deleteRecord(int key) {
        Record* record = getRecordByKey(key);
        if (!record) return;
        // Set lastAccessedTime to the current time to indicate that the record was deleted and can be compacted later.
        record->lastAccessedTime = std::chrono::steady_clock::now();
    }

    void compact() {
        // Implement compaction algorithm to reduce memory fragmentation.
        // This could involve moving records around, freeing unused memory, or reallocating in larger chunks.
    }

private:
    std::vector<Record> records_;
    std::unordered_map<int, size_t> metadataMap_;
    size_t currentIndex_ = 0;

    int randomInt(int min = INT32_MIN, int max = INT32_MAX) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(min, max);
        return dis(gen);
    }
};
