use std::sync::{Arc, Mutex};
use std::thread;
use std::mem;

type DataPoint = (f32, u16);
type CustomMemoryPool = Box<dyn MemoryPool>;

trait MemoryPool {
    fn alloc(&self, size: usize) -> Result<*, ()>;
    fn shrink_to(&mut self, min_capacity: usize);
}

struct SyncArray<T> {
    data: Arc<Mutex<Vec<T>>>,
    lock: Arc<SpinLock<()>>,
}

struct SpinLock<T>(Arc<Atomic<Option<T>>>);
impl<T> SpinLock<T> {
    fn new(value: T) -> Self {
        SpinLock(Arc::new(Atomic::new(Some(value))))
    }

    fn lock(&self) -> Option<MutexGuard<Vec<T>>> {
        loop {
            if let Some(value) = self.0.compare_exchange_weak(None, Some(vec![]), std::sync::atomic::Ordering::Acquire, std::sync::atomic::Ordering::Relaxed) {
                return Some(value.lock());
            }
        }
    }
}

fn initialize_arrays(m: u32, memory_pool: CustomMemoryPool) -> (SyncArray<f32>, SyncArray<u16>) {
    let data_flt = Arc::new(Mutex::new(vec![0.0; m]));
    let data_idx = Arc::new(Mutex::new(vec![0; m]));

    (SyncArray {
        data: Arc::new(Mutex::new(data_flt)),
        lock: Arc::new(SpinLock::new(())),
    }, SyncArray {
        data: Arc::new(Mutex::new(data_idx)),
        lock: Arc::new(SpinLock::new(())),
    })
}

fn initialize_data_points(arr: &mut SyncArray<DataPoint>, min_precision: f32, max_precision: f32) {
    let mut unique_values = vec![false; (max_precision - min_precision + 1) as usize];

    for _ in 0..arr.data.len() {
        let mut r = rand::thread_rng();
        loop {
            let value = min_precision + r.gen_range(max_precision - min_precision).clamp(0., 1.) as f32;
            let index = (value * (arr.data.len() as f64)) as u16;

            if !unique_values[(index as usize) % unique_values.len()] {
                unique_values[index as usize] = true;
                arr.lock().unwrap().lock().push((value, index));
                break;
            }
        }
    }
}

fn main() {
    let (flt_arr, idx_arr) = initialize_arrays(1024, Box::new(memory_pool::CustomMemoryPool {}));
    let arr = Arc::new((flt_arr.data, idx_arr.data));
    thread::scope(|s| {
        for _ in 0..8 {
            s.spawn(move || initialize_data_points(&mut flt_idx_arr, 0.0, 1.0));
        }
    }).unwrap();
}
```

