typedef struct Node {
    char *str;
    int value;
} Node;

void read_data(FILE **file, Node **nodes, size_t *num_nodes, size_t max_len) {
    if (*file == NULL) {
        *num_nodes = 0;
        return;
    }

    fseek(*file, 0, SEEK_SET); // Reset file position to the beginning

    Node *temp = malloc(sizeof(Node));
    char line[max_len + 1];

    size_t index = 0;
    while (fgets(line, max_len + 1, *file)) {
        if (strlen(line) > max_len) {
            fprintf(stderr, "Error: Line length exceeds the maximum allowed length.\n");
            break;
        }

        char *token = strtok(line, " \t\n");
        int value = atoi(token);

        if (value < **num_min || **num_max < value) {
            fprintf(stderr, "Error: Integer value out of range.\n");
            break;
        }

        temp->str = malloc((strlen(line) + 1) * sizeof(char));
        strcpy(temp->str, line);
        temp->value = value;

        if (index == *num_nodes) {
            size_t new_size = (*num_nodes) ? (*num_nodes) * 2 : 8;
            Node *new_nodes = realloc(*nodes, new_size * sizeof(Node));

            if (!new_nodes) {
                fprintf(stderr, "Error: Failed to allocate memory.\n");
                break;
            }

            *nodes = new_nodes;
        }

        (*nodes)[index] = temp;
        index++;
    }

    free(temp);
    fclose(*file);
    *num_nodes = index;
}

void init_set(Node **nodes, size_t num_nodes, size_t max_len, int min_value, int max_value) {
    if (num_nodes <= 0 || max_len <= 0 || min_value >= max_value) {
        fprintf(stderr, "Error: Invalid input.\n");
        return;
    }

    *nodes = malloc(num_nodes * sizeof(Node));
    for (size_t i = 0; i < num_nodes; ++i) {
        (*nodes)[i].str = calloc(max_len + 1, sizeof(char));
    }
}

void free_set(Node **nodes, size_t num_nodes) {
    if (!nodes || num_nodes <= 0) {
        return;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        free((*nodes)[i].str);
    }

    free(*nodes);
    *nodes = NULL;
}
