// Record structure definition
typedef struct {
    int value;
    char* buffer;
    size_t length;
} record;

// Custom RNG function using xorshift128+, ensuring reproducibility
void rng(unsigned long long* state) {
    *state = 69069 * (*state ^ (*state >> 30)) + (0xDEADBEEF69C1ull * (*state << 27));
}

// Function to manage memory for arrays and record structures
int allocate_memory(size_t offset_count, size_t key_count, size_t record_count, size_t buffer_size) {
    size_t r;
    long* offsets = calloc(offset_count, sizeof(long));
    if (!offsets) return -1;

    int* keys = malloc(key_count * sizeof(int));
    if (!keys) goto cleanup;

    record* records = malloc(record_count * sizeof(record));
    if (!records) goto cleanup;

    r = sysconf(_SC_PAGE_SIZE); // Measure process resident set size

    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = i;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % 100; // Ensure values are within a specified range
        records[i].buffer = malloc(buffer_size);
        if (!records[i].buffer) goto cleanup;

        rng(&rng_state); // Use RNG to fill record buffer with random data
        for (size_t j = 0; j < buffer_size; ++j) {
            records[i].buffer[j] = rand() % 256;
        }
        records[i].length = buffer_size;
    }

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);

    // Compile and run Rust code to measure time taken for these operations
    unsigned long long start, end, elapsed;
    rng(&rng_state);
    start = rng_state;

    int exit_code = rustc_driver::catch_with_exit_code([&]() {
        Rust::run("--log-to=stderr", "memory_benchmark", "--",
                  "-C", "opt-level=3",
                  "-o", "benchmark", "main.rs");
    });

    rng(&rng_state);
    end = rng_state;
    elapsed = end - start;

    // Report errors, memory usage, and time taken for these operations
    if (exit_code != 0) {
        early_error("Rust compilation failed with exit code %d\n", exit_code);
    }
    printf("Process resident set size: %zu bytes\n", r - sysconf(_SC_PAGE_SIZE));
    printf("Time taken for memory operations: %.6f seconds\n", elapsed / 1000000.0);

    return record_count - keys_left; // Return the number of successfully allocated records
}

// Global RNG state used across function calls
unsigned long long rng_state = 0xDEADBEEF69C1ull;

int main() {
    allocate_memory(10, 20, 30, 40);
    return 0;
