// Custom record structure
struct Record {
    int value;
    std::atomic<bool> deleted{ false }; // Flag for deletion
};

class HashTable {
public:
    HashTable(size_t offsetSize, size_t keySize, size_t recordSize)
        : offsets_(offsetSize), keys_(keySize), records_(recordSize / sizeof(Record)) {}

    Record* insert(int key, int value) {
        auto pos = hashFunction(key) % offsets_.size();

        // Find an empty record slot in the same bucket
        for (auto i = pos; i != pos + records_.size(); ++i) {
            if (!records_[i].deleted) {
                records_[i].value = value;
                keys_[pos * keys_.size() + i] = key;
                offsets_[pos] += sizeof(Record);
                return &records_[i];
            }
        }

        // No empty slot found, rehash the table if necessary
        if (offsets_.size() >= maxLoadFactor_) {
            rehash();
            return insert(key, value);
        }

        // No empty slot available, return null
        return nullptr;
    }

    Record* search(int key) const {
        auto pos = hashFunction(key) % offsets_.size();

        for (auto i = pos; i != pos + records_.size(); ++i) {
            if (!records_[i].deleted && keys_[pos * keys_.size() + i] == key) {
                return &records_[i];
            }
        }

        // Key not found, return null
        return nullptr;
    }

    void deleteRecord(int key) {
        auto record = search(key);
        if (record) {
            record->deleted = true;
        }
    }

private:
    std::vector<char> offsets_; // Offset array for keys and records
    std::vector<int> keys_;     // Key array
    std::vector<Record> records_; // Record array
    static constexpr int maxLoadFactor_ = 2; // Maximum load factor before rehashing
    static std::function<size_t(int)> hashFunction;
};

// Define the hash function outside of the HashTable class
std::function<size_t(int)> HashTable::hashFunction = [](int key) { return std::hash<int>{}(key); };

void HashTable::rehash() {
    // Implement rehashing strategy here
}

// Unit tests for the HashTable class
void testHashTable() {
    HashTable hashTable(10, 100000, sizeof(Record));

    // Insert records with random values and search for them
    srand(time(nullptr));
    for (size_t i = 0; i < 1000000; ++i) {
        auto key = rand() % 1000000;
        auto value = rand() % 10000;
        hashTable.insert(key, value);
        auto foundRecord = hashTable.search(key);
        if (foundRecord) {
            assert(foundRecord->value == value);
        } else {
            std::cout << "Failed to find inserted record with key: " << key << std::endl;
        }
    }

    // Delete records and search for them
    hashTable.deleteRecord(123456);
    auto deletedRecord = hashTable.search(123456);
    assert(deletedRecord == nullptr || deletedRecord->deleted);
}
