#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    char *key;
    int value;
} node;

struct collection {
    unsigned int size, capacity;
    node *nodes;
    sem_t mutex;
};

void init_collection(struct collection *coll) {
    coll->size = 0;
    coll->capacity = 16;
    coll->nodes = calloc(coll->capacity, sizeof(node));
    if (!coll->nodes) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        exit(EXIT_FAILURE);
    }
    sem_init(&(coll->mutex), 0, 1);
}

bool add_node(struct collection *coll, const char *key, int value) {
    node new_node = {.key = strdup(key), .value = value};

    if (!new_node.key || !new_node.value) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        free(new_node.key);
        return false;
    }

    sem_wait(&(coll->mutex));

    if (coll->size == coll->capacity) {
        node *temp = realloc(coll->nodes, (coll->capacity << 1) * sizeof(node));
        if (!temp) {
            fprintf(stderr, "Failed to resize collection memory\n");
            sem_post(&(coll->mutex));
            free(new_node.key);
            return false;
        }
        coll->nodes = temp;
        coll->capacity <<= 1;
    }

    int i;
    for (i = 0; i < coll->size; ++i) {
        if (!strcmp(coll->nodes[i].key, key)) {
            free(new_node.key);
            sem_post(&(coll->mutex));
            fprintf(stderr, "Duplicate value detected: %s\n", key);
            return false;
        }
    }

    coll->nodes[coll->size++] = new_node;

    sem_post(&(coll->mutex));
    return true;
}

void destroy_collection(struct collection *coll) {
    if (coll->nodes) {
        for (unsigned int i = 0; i < coll->size; ++i) {
            free(coll->nodes[i].key);
        }
        free(coll->nodes);
        coll->nodes = NULL;
    }
    sem_destroy(&(coll->mutex));
}

// Logging and concurrency management are left for the integration phase.
