static size_t records_used = 0;

// Heuristic-based resizing algorithm function
void grow_records(size_t new_capacity) {
    // Balance space efficiency with resizing overhead
    if ((new_capacity - records_used) > (records_capacity / 2))
        new_capacity = records_used * 2;

    record *temp = mmap(NULL, new_capacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (temp == MAP_FAILED) {
        log_error("Failed to allocate memory for records. Exiting...");
        exit(EXIT_FAILURE);
    }

    if (records != NULL && records_capacity > 0) {
        memcpy(temp, records, records_used * sizeof(record));
        munmap(records, records_capacity * sizeof(record));
    }

    records = temp;
    records_capacity = new_capacity;
}

int initialize_nodes(char *config_file) {
    json_object *root, *data, *array, *obj;
    json_object **entries;
    int i;

    // Load JSON configuration file
    root = json_load(config_file, 0, NULL);
    if (IS_ERROR(root)) {
        log_error("Failed to load configuration file. Using default values...");
        N = DEFAULT_N;
        max_string_length = DEFAULT_MAX_STRING_LENGTH;
        minValue = DEFAULT_MIN_VALUE;
        maxValue = DEFAULT_MAX_VALUE;
    } else {
        data = json_object_get(root, "data");
        if (!data || !IS_TYPE(data, json_object_t)) {
            log_error("Invalid JSON configuration. Using default values...");
            json_object_put(root);
            return -1;
        }

        array = json_object_get(data, "array");
        if (!array || !IS_TYPE(array, json_type_t)) {
            log_error("Invalid JSON configuration. Using default values...");
            json_object_put(root);
            return -1;
        }

        entries = json_object_get_array_elements(array);
        if (!entries || IS_ERROR(entries)) {
            log_error("Invalid JSON configuration. Using default values...");
            json_object_put(root);
            return -1;
        }

        N = json_object_array_length(array);
        max_string_length = json_object_array_get_int_element(entries, 0);
        minValue = json_object_array_get_int_element(entries, 1);
        maxValue = json_object_array_get_int_element(entries, 2);
    }

    pthread_mutex_lock(&init_mutex);
    if (records != NULL) {
        log_error("Multiple concurrent calls to initialize_nodes. Using existing data.");
    } else {
        grow_records(N);
    }
    pthread_mutex_unlock(&init_mutex);

    // Populate records with random integer values and dynamic strings, handling duplicates gracefully
    for (i = 0; i < N; ++i) {
        int value, found = 1;
        do {
            value = minValue + (rand() % ((maxValue - minValue) + 1));
            found = 0;
            for (size_t j = 0; j < records_used; ++j) {
                if (records[j].key == i || records[j].value == value) {
                    found = 1;
                    break;
                }
            }
        } while (found);

        records[i].key = i;
        records[i].value = value;
        records[i].str = malloc(max_string_length + 1);
        if (!records[i].str) {
            log_error("Failed to allocate memory for string. Using default values...");
            free(records[i].str);
            continue;
        }

        memset(records[i].str, 0, max_string_length + 1); // Ensure zero-initialized on all platforms
    }

    json_object_put(root);
    return 0;
}
