// Helper function to generate a unique random value within the specified range
long generate_unique_value(long minValue, long maxValue, long *used_values) {
    long rand_val;

    do {
        rand_val = (rand() % (maxValue - minValue + 1)) + minValue;
    } while (binary_search(used_values, sizeof(used_values)/sizeof(long), rand_val) != -1);

    used_values[sizeof(used_values) / sizeof(long)] = rand_val;
    return rand_val;
}

// Helper function to find the index of a specific value in the array
int binary_search(const long *arr, size_t size, long target) {
    int left = 0;
    int right = size - 1;
    int mid;

    while (left <= right) {
        mid = (left + right) / 2;

        if (arr[mid] == target) return mid;

        if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }

    return -1;
}

// Helper function to find the largest integer in an array
