    char **message_pool = malloc((N + 10) * sizeof(char *));
    for (int i = 0; i < N + 10; ++i) {
        message_pool[i] = malloc(BUFFER_SIZE);
        memset(message_pool[i], '\0', BUFFER_SIZE);
    }

    long *used_values = malloc((maxValue - minValue + 1) * sizeof(long));

    pthread_t threads[N];

    // Create and initialize events concurrently using a loop
    for (int i = 0; i < N; ++i) {
        int key = key_array[i];
        long offset = offset_array[i];

        records[key].key = key;
        records[key].offset = offset;

        // Generate a random message of specified length
        snprintf(event_message, BUFFER_SIZE, "%.*s", rand() % 10 + 5, "abcdefghijklmnopqrstuvwxyz");

        records[key].event.timestamp = time(NULL);
        records[key].event.priority = rand() % (maxValue - minValue + 1) + minValue;
        records[key].event.message = message_pool[(records[key].event.priority + 5) % (N + 10)];
        strncpy(records[key].event.message, event_message, BUFFER_SIZE);

        // Initialize and start the threads concurrently
        pthread_create(&threads[i], NULL, initialize_event, &records[key]);
    }

    // Wait for all threads to finish execution
    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated resources
    for (int i = 0; i < N + 10; ++i) free(message_pool[i]);
    free(message_pool);
    free(used_values);
}

