class DomTraverser {
  constructor(rootElement) {
    this.queue = [rootElement];
    this.visited = new Set();
  }

  traverse(selector, callback) {
    const result = [];

    let element;

    while ((element = this.queue.shift())) {
      if (!this.visited.has(element)) {
        this.visited.add(element);

        if (element.matches(selector)) {
          result.push(callback(element));
        }

        const shadowRoot = element.shadowRoot || element;
        const nodes = Array.from(shadowRoot.children);

        for (const node of nodes) {
          if (node.nodeType === Node.ELEMENT_NODE) {
            this.queue.push(node);
          }
        }
      }
    }

    return result;
  }

  cloneElement(element, deep = true) {
    const clonedElement = element.cloneNode(!deep);

    // Handle event listeners attached to nodes
    [...clonedElement.addEventListener].forEach(([eventType, callback]) => {
      if (callback && typeof callback === 'function') {
        const wrappedCallback = (...args) => callback.apply(clonedElement, args);
        clonedElement.addEventListener(eventType, wrappedCallback);
      }
    });

    return clonedElement;
  }

  batchProcessElements(elements, callback, maxBatchSize = 100) {
    const batches = [];
    let batch = [];

    for (const element of elements) {
      batch.push(element);

      if (batch.length === maxBatchSize || !element.parentNode) {
        batches.push(callback(batch));
        batch = [];
      }
    }

    // Execute the remaining elements in the last batch, if any
    if (batch.length > 0) {
      batches.push(callback(batch));
    }

    return Promise.all(batches);
  }
}

