    }
}

pub struct DynamicValueGenerator {
    min_value: f64,
    max_value: f64,
    rng: Arc<Mutex<dyn Rng>>,
    client: Option<Arc<RwLock<Client>>>,
    values: HashMap<usize, (f64, f64)>,
    batch_size: usize,
}

impl DynamicValueGenerator {
    pub async fn new(min_value: f64, max_value: f64, batch_size: usize) -> Self {
        let rng = Arc::new(Mutex::new(rand::thread_rng()));
        let client = Some(Arc::new(RwLock::new(Client::new())));

        let self_arc = Arc::new(Self {
            min_value,
            max_value,
            rng,
            client,
            values: HashMap::new(),
            batch_size,
        });

        tokio::spawn(self_arc.start());
        self_arc
    }

    async fn start(&self) {
        loop {
            let mut guard = self.values.write().await;
            let next_key = *guard.keys().next().unwrap_or(&0);
            if next_key >= self.values.len() {
                break;
            }

            let (min, max) = (*self.values.get(next_key).unwrap());
            if min > self.max_value || max < self.min_value {
                warn!("Invalid range detected: ({}, {}), updating from API...", min, max);

                // Perform HTTP request to update the range using your third-party API
                let mut client = self.client.as_ref().unwrap().read().await;
                match client.put("https://your-api-url/ranges/update")
                    .json(&(next_key, (self.min_value, self.max_value)))
                    .send()
                    .await
                {
                    Ok(_) => {
                        // Update the range in memory
                        *guard.get_mut(next_key).unwrap() = (self.min_value, self.max_value);
                    }
                    Err(e) => warn!("Error updating API: {}", e),
                }
            }
        }
    }

    pub fn generate(&self, count: usize) -> Vec<f64> {
        let mut results = Vec::with_capacity(count);
        let guard = self.values.read().await;

        for key in guard.keys() {
            if results.len() >= count {
                break;
            }

            let (min, max) = (*guard.get(*key).unwrap());
            let value = self.rng.lock().unwrap().gen_range(min as u32, (max - min) as u32 + 1);
            results.push(value as f64 + min);
        }

        // Sort the values and remove duplicates (if necessary) to ensure uniqueness
        results.sort();
        results.dedup();
        results
    }
}
