// Helper function for finding a cache entry with the specified key
struct CacheEntry *find_cache_entry(char* key) {
    struct CacheEntry *current = cache_head;
    while (current != NULL) {
        if (strstr(current->key, key)) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Helper function for removing the least recently used entries from the cache
void remove_least_recently_used() {
    struct CacheEntry *current = cache_head;
    struct CacheEntry *previous = NULL;
    time_t current_time;
    int removed = 0;

    while (current != NULL && cache_size > MAX_CACHE_SIZE) {
        current_time = time(NULL);
        if (current->last_access < current_time - 60) { // Adjust the timeout as needed
            if (previous == NULL) {
                cache_head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            removed++;
            current = previous;
        } else {
            previous = current;
            current = current->next;
        }
    }
