    FILE* file = stdin; // Change to a file descriptor if needed
    size_t currentNumRecords = *numRecords;
    record* newData = NULL;
    size_t newCapacity = currentNumRecords + 100; // Increase in increments for scalability

    while (1) {
        record newRecord;
        if (!fscanf(file, "%lf %ld %s", &newRecord.value, &newRecord.timestamp, newRecord.identifier)) break;

        if (currentNumRecords >= newCapacity) { // Reallocate memory if needed
            newCapacity *= 2;
            record* temp = realloc(newData, newCapacity * sizeof(record));
