        newRecord.identifier = strdup(newRecord.identifier); // Allocate memory for identifier string
        if (!newRecord.identifier) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            continue;
        }

        newData[currentNumRecords] = newRecord;
        currentNumRecords++;

        // Validate data and call callback if needed
        validateAndProcessRecord(&newData[currentNumRecords - 1], config);
    }

    // Filter records based on the specified range
    size_t filteredNumRecords = 0;
    for (size_t i = 0; i < currentNumRecords; ++i) {
        if (newData[i].timestamp >= start && newData[i].timestamp <= end) {
            if (filteredNumRecords >= *numRecords) { // Reallocate memory if needed
                *numRecords *= 2;
                record* temp = realloc(*data, *numRecords * sizeof(record));
                if (!temp) {
                    fprintf(stderr, "Error: Memory allocation failed\n");
                    continue;
                }
                *data = temp;
            }
            (*data)[filteredNumRecords] = newData[i];
            filteredNumRecords++;
        }
    }
}
