typedef struct {
    int value;
    pthread_mutex_t lock;
} Record;

static Record* records;
static size_t num_records = 0;
static const size_t MAX_RECORDS = 1024;
static pthread_mutex_t records_lock;
static const int minValue = 1;
static const int maxValue = 100;
static const int concurrency_limit = 4;

void init_config(size_t n, int timeout_range) {
    if (n == 0) return;

    pthread_mutex_init(&records_lock, NULL);

    records = malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        perror("Memory allocation error");
        return;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = -1; // Mark as unused
        pthread_mutex_init(&records[i].lock, NULL);
    }

    size_t required = n > MAX_RECORDS ? MAX_RECORDS : n;

    for (size_t i = 0; i < required; ++i) {
        int value;
        while (1) {
            value = minValue + rand() % timeout_range;
            if (!find_unused_value(value)) continue; // Value already exists
            break;
        }

        Record* record = find_record(value);
        if (!record) {
            pthread_mutex_lock(&records_lock);
            for (size_t j = 0; j < required; ++j) {
                if (records[j].value == -1) {
                    record = &records[j];
                    break;
                }
            }
            pthread_mutex_unlock(&records_lock);
        }

        record->value = value;
        num_records++;
        printf("Successfully initialized record with value: %d\n", value);

        if (num_records >= n) break;
    }
}

Record* find_record(int value) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value == value && i < MAX_RECORDS - 1)
            return &records[i];
    }
    return NULL;
}

bool find_unused_value(int value) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value == value)
            return false;
    }
    return true;
}

void cleanup() {
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_destroy(&records[i].lock);
    }
    free(records);
    pthread_mutex_destroy(&records_lock);
}
