typedef struct {
    int value;
} Record;

struct system_info {
    long total_ram;
    long available_ram;
};

void get_system_info(struct system_info *info) {
    char path[128];
    snprintf(path, sizeof(path), "/proc/meminfo");
    FILE *file = fopen(path, "r");
    char line[256], *token;
    long total_ram = 0, available_ram = 0;
    while (fgets(line, sizeof(line), file)) {
        token = strtok(line, ": ");
        if (!token || strcmp(token, "MemTotal")) continue;
        token = strtok(NULL, "\n");
        total_ram += atol(token);
        token = strtok(NULL, "K");
        total_ram *= 1024;
    }
    rewind(file);
    while (fgets(line, sizeof(line), file)) {
        token = strtok(line, ": ");
        if (!token || strcmp(token, "MemFree")) continue;
        token = strtok(NULL, "\n");
        available_ram += atol(token);
        token = strtok(NULL, "K");
        available_ram *= 1024;
    }
    fclose(file);
    info->total_ram = total_ram;
    info->available_ram = available_ram;
}

long get_used_memory() {
    struct system_info info;
    get_system_info(&info);
    return (info.total_ram - info.available_ram) * 60 / 100;
}

