int max_records = 1000000;
int min_key = 1, max_key = 100;
long chunk_size = sysconf(_SC_PAGE_SIZE) * 4;

void* read_chunk(void *arg) {
    int fd = *(int*)arg;
    struct Chunk *c = malloc(sizeof(struct Chunk));
    ssize_t nread = read(fd, c->buf, chunk_size);

    if (nread == -1) {
        free(c);
        return NULL;
    }

    c->len = nread;
    return c;
}

void validate_integrity(const void *data, size_t len) {
