void process_chunk(struct Chunk *c) {
    char *line = c->buf;
    char delimiter[] = "\t";
    char *token;
    int key, offset = 0;

    while ((token = strtok(line, delimiter)) != NULL) {
        if (sscanf(token, "%d", &key) == 1) {
            pthread_mutex_lock(&mutex);
            if ((key >= min_key && key <= max_key) && (offset + sizeof(Record)) < chunk_size) {
                Record *rec = (Record*)((char*)c->buf + offset);
                rec->key = key;
                rec->offset = offset;
                offset += sizeof(Record);
            }
            pthread_mutex_unlock(&mutex);
        }
        line = NULL;
        line = strtok(NULL, delimiter);
