#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

// External library API for data retrieval (replace with actual implementation)
typedef struct DataData {
    void *data;
    size_t size;
};

DataData data_retrieve(const char *key);

// LRU list node structure
struct lru_node {
    const char *key;
    void *data_block;
    struct lru_node *prev, *next;
};

// Cache structure
typedef struct Cache {
    size_t keys_size;
    size_t cache_size;
    size_t data_block_size;
    size_t total_allocated;
    struct lru_node **entries;
    struct lru_node *lru_head, *lru_tail;
    sem_t lock;
} Cache;

// Initialize a new cache with given sizes
Cache *cache_new(size_t keys_size, size_t cache_size, size_t data_block_size) {
    Cache *cache = malloc(sizeof(Cache));
    if (!cache) return NULL;
    cache->keys_size = keys_size;
    cache->cache_size = cache_size;
    cache->data_block_size = data_block_size;
    cache->total_allocated = 0;
    cache->entries = calloc(keys_size, sizeof(void*));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }
    cache->lru_head = cache->lru_tail = NULL;
    sem_init(&cache->lock, 0, 1);
    return cache;
}

// Find an entry in the cache for the given key
struct lru_node *cache_get(Cache *cache, const char *key) {
    struct lru_node *node = cache->lru_head;
    while (node) {
        if (strcmp(node->key, key) == 0) break;
        node = node->next;
    }
    return node;
}

// Allocate and populate a new data block for the given key
void *cache_populate(Cache *cache, const char *key) {
    void *data_block = malloc(cache->data_block_size);
    if (!data_block) return NULL;

    DataData result = data_retrieve(key);
    memcpy(data_block, result.data, result.size);
    free(result.data);

    // Update cache statistics and LRU list
    cache->total_allocated += (cache->data_block_size + sizeof(struct lru_node));

    struct lru_node *new_node = malloc(sizeof(struct lru_node));
    if (!new_node) {
        free(data_block);
        return NULL;
    }
    new_node->key = key;
    new_node->data_block = data_block;
    new_node->prev = NULL;
    new_node->next = NULL;

    sem_wait(&cache->lock);
    if (cache->total_allocated > cache->cache_size) {
        // Evict least recently used entry
        struct lru_node *lru_node_to_evict = cache->lru_tail;
        if (!lru_node_to_evict) {
            sem_post(&cache->lock);
            free(new_node);
            free(data_block);
            return NULL;
        }
        struct lru_node *prev = lru_node_to_evict->prev;
        if (prev) prev->next = NULL;
        else cache->lru_head = NULL;
        free(lru_node_to_evict->data_block);
        free(lru_node_to_evict);
    }

    if (!cache->lru_head) {
        cache->lru_head = new_node;
        cache->lru_tail = new_node;
    } else {
        new_node->prev = cache->lru_tail;
        new_node->next = NULL;
        cache->lru_tail->next = new_node;
        cache->lru_tail = new_node;
    }
    sem_post(&cache->lock);

    return data_block;
}

// Free the cache and all associated resources
void cache_free(Cache *cache) {
    sem_destroy(&cache->lock);
    free(cache->entries);
    struct lru_node *node = cache->lru_head;
    while (node) {
        struct lru_node *next = node->next;
        free(node->data_block);
        free(node);
        node = next;
    }
    free(cache);
}
