#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
} record;

record* create_records(size_t count, size_t min_offset, size_t max_offset, size_t min_key, size_t max_key) {
    size_t i, j;
    record *records = malloc(count * sizeof(record));
    if (!records) return NULL;

    long *offsets = malloc(sizeof(long) * count);
    int *keys = malloc(sizeof(int) * count);
    if (!(offsets && keys)) {
        free(records);
        return NULL;
    }

    for (i = 0; i < count; ++i) {
        offsets[i] = min_offset + rand() % ((max_offset - min_offset) + 1);
        keys[i] = min_key + rand() % ((max_key - min_key) + 1);
    }

    // Shuffle keys to avoid duplicates and preserve order of offsets
    for (i = count; i-- > 1; ) {
        size_t r = rand() % (i + 1);
        if (keys[r] == keys[i]) {
            i--;
            continue;
        }
        swap(&keys[r], &keys[i]);
    }

    for (i = j = 0; i < count; ++i) {
        bool duplicate = false;
        for (size_t k = 0; k < j && !duplicate; ++k) {
            if (keys[k] == keys[i]) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            records[j++] = (record){offsets[i], keys[i]};
        }
    }

    free(offsets);
    free(keys);
    return records;
}

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
```
