#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int *value;
    size_t size;
    time_t last_update;
} Record;

struct data_manager {
    long *offsets;
    int *keys;
    Record *records;
    size_t records_capacity;
    size_t records_count;
    pthread_mutex_t mutex;
};

DataManager *data_manager_init(size_t capacity) {
    DataManager *dm = malloc(sizeof(DataManager));
    dm->offsets = calloc(capacity, sizeof(long));
    dm->keys = calloc(capacity, sizeof(int));
    dm->records = NULL;
    dm->records_capacity = capacity;
    dm->records_count = 0;
    pthread_mutex_init(&dm->mutex, NULL);
    return dm;
}

void data_manager_add(DataManager *dm) {
    if (dm->records_count >= dm->records_capacity) {
        Record **new_records = realloc(dm->records, sizeof(Record) * (dm->records_capacity * 2));
        if (!new_records) {
            fprintf(stderr, "Error: Failed to allocate memory for records\n");
            return;
        }
        dm->records = new_records;
        dm->records_capacity *= 2;
    }
    Record *record = &dm->records[dm->records_count];
    record->value = malloc(sizeof(int));
    record->size = sizeof(int);
    record->last_update = time(NULL);
    *record->value = rand() % 100;
    dm->keys[dm->records_count] = 0;
    pthread_mutex_lock(&dm->mutex);
    dm->offsets[dm->records_count] = 0;
    dm->records_count++;
    pthread_mutex_unlock(&dm->mutex);
}

void data_manager_iterate(DataManager *dm, void (*print_record)(Record *)) {
    if (!dm || !print_record) return;
    pthread_mutex_lock(&dm->mutex);
    for (size_t i = 0; i < dm->records_count; ++i) {
        print_record(&dm->records[i]);
    }
    pthread_mutex_unlock(&dm->mutex);
}

void Record_print(Record *record) {
    printf("Offset: %ld, Key: %d, Value: %d, Last update: %s\n", record->offset, record->keys[0], *record->value, ctime(&record->last_update));
}

void data_manager_cleanup(DataManager **dm) {
    if (!dm || !*dm) return;
    pthread_mutex_destroy(&(*dm)->mutex);
    free((*dm)->offsets);
    free((*dm)->keys);
    for (size_t i = 0; i < (*dm)->records_count; ++i) {
        free((*dm)->records[i].value);
    }
    free(*dm);
    *dm = NULL;
}
```

