    init_log(log_config, "memory_log.txt", "%s\n");

    scanf("%zu %zu %d %f", &offsets_count, &keys_count, &max_value, &threshold);

    struct memory_pool* offsets_pool = create_memory_pool(offsets_count * sizeof(long), threshold);
    if (!offsets_pool) return 1;

    long* offsets = alloc_array(offsets_pool, offsets_count);
    if (!offsets) {
        free_memory_pool(offsets_pool);
        return 1;
    }

    struct memory_pool* keys_pool = create_memory_pool(keys_count * sizeof(int), threshold);
    if (!keys_pool) {
        free_memory_pool(offsets_pool);
        free(offsets);
        return 1;
    }

    int* keys = alloc_array(keys_pool, keys_count);
    if (!keys) {
        free_memory_pool(keys_pool);
        free_memory_pool(offsets_pool);
        free(offsets);
        return 1;
    }

    struct memory_pool* records_pool = create_memory_pool(records_count * sizeof(record), threshold);
    if (!records_pool) {
        free_memory_pool(keys_pool);
        free_memory_pool(offsets_pool);
        free(offsets);
        free(keys);
        return 1;
    }

    record* records = alloc_records(records_pool, records_count);
    if (!records) {
        free_memory_pool(records_pool);
        free_memory_pool(keys_pool);
        free_memory_pool(offsets_pool);
