typedef struct memory_block {
    void* data;
    size_t size;
    struct memory_block* next;
} memory_block;

memory_pool_t* create_memory_pool(size_t chunk_size) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->chunks = mmap(NULL, chunk_size * sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->chunks == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    pool->head = pool->tail = calloc(1, sizeof(memory_block));
    pool->current = pool->head;
    pool->chunk_size = chunk_size;
    pool->allocated = 0;
    return pool;
}

void* memory_pool_alloc(memory_pool_t* pool, size_t size) {
    if (pool->current->next == NULL || pool->current->next->size + pool->chunk_size <= size) {
        void* data = pool->current->data + pool->allocated;
        pool->allocated += size;
        return data;
    } else {
        memory_block* new_block = malloc(sizeof(memory_block));
        if (!new_block) return NULL;

        void* data = pool->chunks + pool->allocated;
        new_block->data = data;
        new_block->size = size;
        new_block->next = NULL;

        pool->current->next = new_block;
        pool->current = new_block;
        return data;
    }
}

void memory_pool_free(memory_pool_t* pool, void* ptr) {
    if (ptr >= pool->chunks && ptr < (pool->chunks + pool->allocated)) {
        size_t index = (ptr - pool->chunks) / pool->chunk_size;
        memory_block* block = pool->head;
        for (size_t i = 0; i < index; ++i) block = block->next;
        if (block->data == ptr) {
            block->allocated -= size;
        } else {
            // handle error: invalid memory block
        }
    } else {
        // handle error: invalid memory block
    }
}

