void* initialize_data(int M, log_level_t log_level) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    double* identifiers = calloc(M, sizeof(double));
    if (!identifiers) goto error;

    uint32_t* doublestoragemask = calloc(M, sizeof(uint32_t));
    if (!doublestoragemask) goto error;

    measurement* measurements = memory_pool_alloc(memory_pool, M * sizeof(measurement));
    if (!measurements) goto error;

    sem_t semaphore = SEM_INITIALIZE(M);

    for (int i = 0; i < M; ++i) {
        pthread_mutex_lock(&mutex);

        while (doublestoragemask[i]) {
            // retry
            sem_wait(&semaphore);
        }

        identifiers[i] = i;
        doublestoragemask[i] = 1;
        measurements[i].identifier = i;
        measurements[i].temperature = (rand() % 201) * 5.0 - 50.0;

        pthread_mutex_unlock(&mutex);
    }

    log(log_level, "Data initialization complete.");
    return measurements;

error:
    if (identifiers) free(identifiers);
    if (doublestoragemask) free(doublestoragemask);
    if (measurements) memory_pool_free(memory_pool, measurements);
    sem_destroy(&semaphore);
    return NULL;
}
```

