#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    int value;
} record;

struct collection {
    unsigned int size, capacity, growth_factor;
    record* array;
    pthread_mutex_t mutex;
};

int hash(unsigned int key) {
    return key % capacity;
}

void init_collection(struct collection *col, unsigned int size, unsigned int capacity, unsigned int growth_factor) {
    col->size = 0;
    col->capacity = capacity;
    col->growth_factor = growth_factor;
    col->array = (record*) malloc(capacity * sizeof(record));
    if (!col->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pthread_mutex_init(&(col->mutex), NULL);
}

void resize_collection(struct collection *col) {
    unsigned int new_capacity = col->capacity * col->growth_factor;
    record* temp = (record*) malloc(new_capacity * sizeof(record));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (unsigned int i = 0; i < col->capacity; ++i) {
        if (col->array[i].key != 0)
            temp[i] = col->array[i];
    }

    free(col->array);
    col->array = temp;
    col->capacity = new_capacity;
}

int find_record(struct collection *col, unsigned int key) {
    for (unsigned int i = hash(key); i < col->capacity; ++i) {
        if (col->array[i].key == key) return i;
        if (col->array[i].key != 0) continue;

        unsigned int new_hash = hash((i + col->growth_factor) % col->capacity);
        if (new_hash == i) return -1; // cycle detected, collection is not consistent
        if (i >= col->size) break; // reached the end of the collection, key not found
    }
    return -1;
}

void add_record(struct collection *col, unsigned int key, unsigned int value) {
    int index = find_record(col, key);
    if (index != -1) {
        col->array[index].value = value;
        return;
    }

    pthread_mutex_lock(&(col->mutex));
    if (col->size >= col->capacity) resize_collection(col);

    for (unsigned int i = hash(key); i < col->capacity; ++i) {
        if (col->array[i].key == 0) {
            col->array[i].key = key;
            col->array[i].value = value;
            col->size++;
            pthread_mutex_unlock(&(col->mutex));
            return;
        }
    }

    resize_collection(col); // ensure enough space for new record
    unsigned int new_index = find_record(col, key);
    col->array[new_index].key = key;
    col->array[new_index].value = value;
    col->size++;
    pthread_mutex_unlock(&(col->mutex));
}

void remove_record(struct collection *col, unsigned int key) {
    int index = find_record(col, key);
    if (index == -1) return;

    pthread_mutex_lock(&(col->mutex));
    memmove(&(col->array[index]), &(col->array[index+1]), (col->size-index-1)*sizeof(record));
    col->array[--(col->size)].key = 0;
    pthread_mutex_unlock(&(col->mutex));
}
```

This code defines a collection of `record` structures, with methods to initialize, resize, add, remove, and search for records. The collection uses a linear probing strategy for handling collisions, and employs a mutex lock to ensure thread safety in multi-threaded environments. The growth factor is set during initialization and can be adjusted based on system dependencies and performance constraints.']

