        int value;
        do {
            value = get_min_val() + rand() % (get_max_val() - get_min_val());
        } while (find_value(records, dataset_size, value));

        records[keys[i]].value = value;
        keys[i] = find_empty_record(records, dataset_size);
    }

    // Enforce sum limitation
    int sum = 0;
    for (int i = 0; i < dataset_size; ++i) {
        sum += records[i].value;
        if (sum > get_max_sum()) {
            printf("Sum exceeded maximum limit.\n");
            break;
        }
    }

    return records;
}

int find_empty_record(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (!records[i].value) {
            return i;
        }
    }
    return -1;
}

int find_value(record* records, int num_records, int value) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].value == value) {
            return 1;
        }
    }
    return 0;
}
