Record* allocateRecords(size_t N, size_t *out_allocatedSize) {
    const size_t alignment = 16;
    const size_t growthFactor = 2;
    size_t allocatedSize = (N + alignment - 1) / alignment * alignment;

    if (allocatedSize > INT_MAX / sizeof(Record)) {
        log("Memory allocation failure: Required memory exceeds system limit.");
        return NULL;
    }

    Record* records = mmap(NULL, allocatedSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (records == MAP_FAILED) {
