        Record* currentRecord = records;

        for (size_t i = 0; i < N; ) {
            if (i + alignment <= N) {
                // Check for duplicate keys here.
                int key = currentRecord->key;
                size_t j = usedSize - 1;

                while (j > 0 && currentRecord[j].key == key) --j;

                if (j >= usedSize - 1) {
