                    records = NULL;
                    break;
                }

                currentRecord->value = rand() % (maxValue - minValue + 1) + minValue;
                ++usedSize;
                i += alignment;
            } else {
                // Preallocate a larger chunk of memory when growth factor exceeded.
                allocatedSize *= growthFactor;
                currentRecord = (Record*)((long)(currentRecord + usedSize) & ~(alignment - 1));
            }
