// Function to generate a unique random number within the specified range
int getUniqueRandom(int *arr, size_t arrSize, int minValue, int maxValue) {
    int num;
    do {
        num = minValue + rand() % (maxValue - minValue + 1);
    } while (in_array(num, arr, arrSize));
    return num;
}

// Helper function to check if a number is in an array
int in_array(int needl, int *haystack, size_t haystack_len) {
    for (size_t i = 0; i < haystack_len; ++i) {
        if (needl == haystack[i]) return 1;
    }
    return 0;
}

void* initializeArrays(int N, int minValue, int maxValue, pthread_mutex_t *mutex) {
    long *offsets = malloc(N * sizeof(long));
    int *keys = malloc(N * sizeof(int));
    record *records = malloc(N * sizeof(record));

    pthread_mutex_lock(mutex);

    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
        records[i].value = getUniqueRandom(records, N, minValue, maxValue);
    }

    pthread_mutex_unlock(mutex);

    return NULL;
}

