struct GarbageCollector {
    void* free_list;
    size_t size;
};

void init_garbage_collector(struct GarbageCollector* gc, size_t initial_size) {
    gc->free_list = malloc(initial_size * sizeof(Record));
    if (!gc->free_list) {
        LOG_WARNING("Garbage collector initialization failed");
        return;
    }
    gc->size = initial_size;
}

void enqueue_garbage(struct GarbageCollector* gc, Record r) {
    if (gc->free_list == NULL) {
        LOG_WARNING("Garbage collector exhaustion");
        return;
    }
    memcpy((void*)((char*)gc->free_list + gc->size * sizeof(Record) - sizeof(Record)), &r, sizeof(Record));
    gc->size--;
}

Record dequeue_garbage(struct GarbageCollector* gc) {
    Record r;
    if (gc->free_list == NULL) return (Record){0}; // Empty garbage collector
    memcpy(&r, (void*)((char*)gc->free_list + gc->size * sizeof(Record)), sizeof(Record));
    gc->size++;
    return r;
}

