void allocate_and_init(Record** records, int num_records, size_t max_string_len, int seed) {
    *records = malloc(num_records * sizeof(Record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = calloc(num_records + 1, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array.\n");
        free(*records);
        exit(EXIT_FAILURE);
    }

    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for key array.\n");
        free(offsets);
        free(*records);
        exit(EXIT_FAILURE);
    }

    srand(seed);

    offsets[0] = 0;
    for (int i = 0; i < num_records; ++i) {
        keys[i] = i;
        Record* record = &((*records)[offsets[i]]);
        record->value = rand() % 100 + 1;
        record->string = malloc(max_string_len * sizeof(char));
        if (!record->string) {
            fprintf(stderr, "Failed to allocate memory for string buffer.\n");
            free(keys);
            free(offsets);
            free(*records);
            exit(EXIT_FAILURE);
        }
        record->length = 0;
        offsets[i + 1] = offsets[i] + 1;
    }

    // Cleanup on function exit
    for (int i = 0; i < num_records; ++i) {
        free((*records)[i].string);
    }
    free(keys);
    free(offsets);
}
