// Define the record structure, with an int value for each record
typedef struct Record {
    int value;
} Record;

// Initialize variables for shared memory, lock, and retry parameters
int *offsets;
int *keys;
Record *records;
pthread_mutex_t lock;
int N, minValue, maxValue;

// Helper function to generate a unique random number within the specified range using a hash-based uniqueness check mechanism
int generateRandom(void) {
    int seed = SHA1((char *)&N, sizeof(int), NULL);
    return (minValue + ((seed % (maxValue - minValue + 1)) * (maxValue - minValue)));
}

// Function to allocate memory for and initialize the arrays
void initArrays(int N, int minValue, int maxValue) {
    this_id = getpid();
    // Use shmget() to create a shared memory segment
    key_t key = ftok("/", this_id);
    int shmid = shmget(key, sizeof(int) * (N + 1), IPC_CREAT | 0666);

    // Attach the shared memory segment to our data space
