```c
#include <stdio.h>
#include <stdbool.h>
#include <inttypes.h>
#include <sys/mman.h> // mmap and munmap

typedef struct hash_table {
    size_t table_size;
    void* table;
} HashTable;

void create_hash_table(HashTable* table, size_t table_size) {
    table->table_size = table_size;
    table->table = mmap(NULL, sizeof(char)*table_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

// Hash function for the given set of characters (uppercase letters)
uint64_t hash(const char* key, size_t table_size) {
    uint64_t hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % table_size;
}

// Lookup function for the given key in the hash table.
bool lookup(HashTable* table, const char* key, size_t table_size) {
    uint64_t h = hash(key, table->table_size);
    size_t i;

    for (i = h; i < table->table_size; i = (i + 1) % table->table_size) {
        if (!table->table[i]) {
            break;
        }

        if (strncmp(key, ((char*)table->table)+i, strlen(key)) == 0) {
            return true;
        }
    }

    for (i = h; i--; ) {
        if (!table->table[i]) {
            break;
        }

        if (strncmp(((char*)table->table)+i, key, strlen(key)) == 0) {
            return true;
        }
    }

    return false;
}
