```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

unsigned long hashFunction(int key, unsigned int tableSize) {
    return key % tableSize;
}

struct Position {
    int key;
    Record* record;
};

void createDataStructure(unsigned int size, unsigned int range, unsigned int* offsets, int** keys, Record*** records) {
    *offsets = malloc(sizeof(unsigned long) * size);
    if (*offsets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(sizeof(int) * size);
    if (*keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(sizeof(Record*) * size);
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        free(*keys);
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    unsigned int tableSize = 101; // Define the size of the hash table
    for (unsigned i = 0; i < size; ++i) {
        (*offsets)[i] = rand() % range;
        unsigned long index = hashFunction((*keys)[i] = (*offsets)[i], tableSize);
        int j = 1;
        while (true) {
            if ((*records)[index] == NULL || (*records)[index]->value != (*offsets)[(*keys)[index]]) {
                break;
            }
            index = (index + j + 1) % tableSize;
            ++j;
        }
        (*records)[index] = malloc(sizeof(Record));
        if ((*records)[index] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record at index %lu\n", index);
            freeMemory(offsets, keys, records, size);
            exit(EXIT_FAILURE);
        }
        (*records)[index]->value = (*offsets)[(*keys)[i]];
    }
}

Record* findRecordByKey(int key, unsigned int tableSize, unsigned int* offsets, int* keys, Record** records) {
    unsigned long index = hashFunction(key, tableSize);
    int j = 1;
    while (true) {
        if ((*records)[index] == NULL || (*records)[index]->value != (*offsets)[(*keys)[index]]) {
            ++j;
            index = (index + j) % tableSize;
            continue;
        }
        if ((*keys)[index] == key) {
            return (*records)[index];
        }
    }
}

void freeMemory(unsigned long* offsets, int* keys, Record** records, unsigned int size) {
    for (unsigned i = 0; i < size; ++i) {
        if ((*offsets)[i] != UINT_MAX && (*records)[(*keys)[i]] != NULL) {
            free((*records)[(*keys)[i]]);
        }
    }
    free(offsets);
    free(keys);
    free(records);
}

void monitorMemoryUsage() {
    long pageSize = sysconf(_SC_PAGESIZE);
    unsigned long totalMem = 0;
    unsigned long usedMem = 0;
    FILE* fp = fopen("/proc/meminfo", "r");
    char line[256];

    while (fgets(line, sizeof(line), fp)) {
        if (!strncmp(line, "MemTotal:", 8)) {
            sscanf(line, "MemTotal: %lu kB", &totalMem);
            totalMem *= pageSize;
        } else if (!strncmp(line, "Used:", 4)) {
            sscanf(line, "Used: %lu kB", &usedMem);
            usedMem *= pageSize;
        }
    }
    fclose(fp);

    printf("Total Memory: %lukB\n", totalMem / pageSize);
    printf("Used Memory: %lukB\n", usedMem / pageSize);
}
```

