#include <libxml/parser.h>
#include <boost/random.hpp>
#include <boost/regex.hpp>

struct Record {
    int key;
    long offset;
};

class XMLParser {
public:
    explicit XMLParser(xmlDocPtr doc) : _doc(doc) {}

    std::vector<Record> parse(const std::string& xpath) {
        xmlNodeSetPtr nodes = xmlSearchNodeSet(_doc, reinterpret_cast<const xmlChar*>(xpath.c_str()));
        if (!nodes || !nodes->nodeNr) {
            throw std::runtime_error("No matching node found");
        }
        if (nodes->nodeNr > 1) {
            throw std::runtime_error("Multiple elements matched the given XPath");
        }

        auto* node = nodes->nodeTab[0];
        long offsetValues[1] = {0};
        int keys[1] = {0};
        parseNode(node, offsetValues, keys);

        std::vector<Record> records;
        records.reserve(offsetValues[0]);
        for (long i = 0; i < offsetValues[0]; ++i) {
            Record record{keys[0], offsetValues[i]};
            records.push_back(record);
        }
        return records;
    }

private:
    void parseNode(xmlNode *node, long* offsetValues, int* keys) {
        if (!node || !XML_NAME(node)) {
            return;
        }

        xmlNode *child = node->xmlChildrenNode;
        while (child) {
            if (XML_NAME(child) && XML_NAME(child)->localname == "offset") {
                ++*offsetValues;
            } else if (XML_NAME(child) && XML_NAME(child)->localname == "key") {
                keys[0] = std::stoi(std::string(reinterpret_cast<const char*>(XML_TEXT(child))));
            }
            child = child->next;
        }

        xmlNodeSetPtr nodeset = xmlFindXmlChildrenNodeSet(node, NULL);
        for (xmlNode *iter = nodeset->nodeNr > 0 ? nodeset->nodeTab[0] : node; iter; iter = iter->next) {
            parseNode(iter, offsetValues, keys);
        }
    }

private:
    xmlDocPtr _doc;
};

std::vector<Record> loadXML(const std::string& url, const std::string& xpath) {
    libxml_use_long_events();
    XMLParser parser = xmlReadFile(url.c_str(), NULL, XML_PARSE_NONET | XML_PARSE_NOBLANKS | XML_PARSE_NOCDATA);
    if (!parser._doc) {
        throw std::runtime_error("Failed to parse XML");
    }
    return parser.parse(xpath);
}

void populateArrays(std::vector<Record> records, long* offsetValues, int* keys, size_t capacity) {
    std::fill_n(offsetValues, capacity, 0);
    std::fill_n(keys, capacity, 0);

    if (records.empty()) {
        throw std::runtime_error("No records found");
    }

    std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) -> bool { return a.offset < b.offset; });

    size_t index = 0;
    for (const auto& record : records) {
        offsetValues[record.offset]++;
        keys[index++] = record.key;
    }
}

void setupArrays(xmlDocPtr doc, const std::string& xpath, long* offsetValues, int* keys, size_t capacity, unsigned minKey, unsigned maxKey, unsigned minOffset, unsigned maxOffset) {
    try {
        auto records = loadXML(xpath, xpath);
        populateArrays(records, offsetValues, keys, capacity);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return;
    }

    boost::random::mt19937 gen(std::time(nullptr));
    boost::uniform_int<> dis(minKey, maxKey);
    boost::uniform_int<> dos(minOffset, maxOffset);

    for (size_t i = 0; i < capacity; ++i) {
        keys[i] = dis(gen);
        offsetValues[keys[i]] = dos(gen);
    }
}
