        keysData[i - 1] = i;
        recordsData[i - 1].value = distribution(generator);
    }

    std::sort(offsetsData.get(), offsetsData.get() + recordsCount + 1);
    std::sort(keysData.get(), keysData.get() + recordsCount);

    long* offsetsPtr = offsetsData.release();
    int* keysPtr = keysData.release();
    record_t** recordsPtr = recordsData.release();

    xmlFreeDoc(xmlDoc); // Free the XML document after parsing is complete
    return recordsPtr;
}
