#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    long value;
    struct Node *next;
} Node;

typedef struct List {
    int capacity;
    int size;
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
} List;

List* create_list(int capacity) {
    List *list = malloc(sizeof(List));
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

Node* create_node(long value) {
    Node *node = malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation failed.");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->next = NULL;
    return node;
}

void add_node(List *list, long value) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        printf("List is full.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node *node = create_node(value + list->size);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

long get_node(List *list, int index) {
    if (index < 0 || index >= list->size) {
        printf("Index out of range.\n");
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    for (int i = 0; i < index; ++i) {
        if (!current) {
            printf("List empty or index out of range.\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        current = current->next;
    }
    long value = current->value;
    pthread_mutex_unlock(&list->mutex);
    return value;
}

void remove_node(List *list, int index) {
    if (index < 0 || index >= list->size) {
        printf("Index out of range.\n");
        return;
    }
    pthread_mutex_lock(&list->mutex);
    if (!list->head || !list->size) {
        perror("List empty or invalid state.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (index == 0) {
        Node *temp = list->head;
        list->head = list->head->next;
        free(temp);
        if (!list->head) list->tail = NULL;
        list->size--;
    } else {
        Node *current = list->head;
        for (int i = 0; i < index - 1; ++i) {
            current = current->next;
            if (!current || !current->next) {
                perror("List empty or invalid state.");
                pthread_mutex_unlock(&list->mutex);
                return;
            }
        }
        Node *temp = current->next;
        current->next = current->next->next;
        if (!current->next) list->tail = current;
        free(temp);
        list->size--;
    }
    pthread_mutex_unlock(&list->mutex);
}
```

