#include <random>
#include <thread>
#include <mutex>

// Define record structure
struct Record {
    int value;
};

std::mutex mtx;

void fill_records(std::vector<Record>& records, const std::vector<int>& keys, size_t start, size_t end) {
    std::default_random_engine generator(123456); // Seed for reproducibility
    std::uniform_int_distribution<> distribution(0, 100); // Random number range

    for (size_t i = start; i < end; ++i) {
        std::unique_lock<std::mutex> lock(mtx);
        records[keys[i]] = Record{distribution(generator)};
    }
}

void init_data(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records, size_t offsetSize, size_t keyCount, size_t recordCount) {
    offsets.resize(keyCount + 1); // Ensure last offset is set
    keys.resize(keyCount);
    records.resize(recordCount);

    long currentOffset = 0;
    for (size_t i = 0; i < keyCount; ++i) {
        if (currentOffset + recordCount > offsetSize) {
            offsetSize *= 2; // Double the size when needed
            offsets.resize(keyCount + 1);
        }
        offsets[i] = currentOffset;
        keys[i] = i;
        currentOffset += recordCount;
    }

    std::thread threads[std::thread::hardware_concurrency()];
    size_t chunkSize = keyCount / static_cast<size_t>(std::thread::hardware_concurrency());
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        size_t start = i * chunkSize;
        size_t end = (i == std::thread::hardware_concurrency() - 1) ? keyCount : (start + chunkSize);
        threads[i] = std::thread(fill_records, std::ref(records), std::ref(keys), start, end);
    }

    for (auto& thread : threads) {
        if (thread.joinable())
            thread.join();
    }
}

void free_data(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    offsets.clear();
    keys.clear();
    records.clear();
}
