typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxi;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cicr;
} NFAPI_CRAC_INDICATION_PDU_T;

#define MAX_RECORDS 10000
#define CACHE_RATIO 0.75

Record* head = NULL;
size_t active_records = 0;
size_t max_records = MAX_RECORDS;

Record* get_record(int key) {
    Record *current = head;
    while (current != NULL) {
        if (current->key == key)
            return current;
        current = current->next;
    }
    return NULL;
}

void create_pdu_list(size_t N) {
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRAC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRAC_INDICATION_PDU_T));
        // Set PDUs properties...

        Record* r = get_record((int)&pdu);
        if (r == NULL) {
            r = malloc(sizeof(Record));
            r->key = (int)&pdu;
            r->data = pdu;
            r->next = head;
            head = r;
            ++active_records;

            if (active_records > max_records * CACHE_RATIO) {
                size_t to_remove = active_records - max_records * CACHE_RATIO;
                Record* current = head;
                for (size_t i = 0; i < to_remove; ++i) {
                    if (current->next == NULL) break;
                    Record* next = current->next;
                    free(current->data);
                    free(current);
                    --active_records;
                    current = next;
                }
            }
        } else {
            r->data = pdu;
        }
    }
}
