typedef struct slab {
    Record records[4096];
    uint32_t next_idx;
    pthread_mutex_t lock;
} Slab;

struct ConcurrentDynamicRecordSet {
    size_t capacity;
    size_t max_records;
    size_t num_slabs;
    Slab* slabs;
    uint64_t total_allocated;
    pthread_mutex_t mutex;
};

void init_slab(Slab* slab) {
    memset(slab->records, 0, sizeof(Record) * 4096);
    slab->next_idx = 0;
    pthread_mutex_init(&slab->lock, NULL);
}

ConcurrentDynamicRecordSet* create_record_set(size_t capacity, size_t max_records, size_t num_slabs) {
    ConcurrentDynamicRecordSet* set = malloc(sizeof(ConcurrentDynamicRecordSet));
    if (!set) return NULL;

    set->capacity = capacity;
    set->max_records = max_records;
    set->num_slabs = num_slabs;
    set->slabs = calloc(num_slabs, sizeof(Slab));
    if (!set->slabs) {
        free(set);
        return NULL;
    }

    for (size_t i = 0; i < num_slabs; ++i) {
        set->slabs[i] = (Slab){.next_idx = 0};
        init_slab(&set->slabs[i]);
    }

    set->total_allocated = 0;
    pthread_mutex_init(&set->mutex, NULL);
    return set;
}

void destroy_record_set(ConcurrentDynamicRecordSet* set) {
    for (size_t i = 0; i < set->num_slabs; ++i) {
        pthread_mutex_destroy(&set->slabs[i].lock);
    }

    free(set->slabs);
    free(set);
}

int insert_record(ConcurrentDynamicRecordSet* set, const Record* record) {
