            memcpy(&set->slabs[slab_idx].records[i], record, sizeof(Record));
            set->total_allocated++;
            pthread_mutex_unlock(&set->slabs[slab_idx].lock);
            return i;
        }
    }

    pthread_mutex_unlock(&set->slabs[slab_idx].lock);

