size_t get_total_allocated(const ConcurrentDynamicRecordSet* set) {
    pthread_mutex_lock(&set->mutex);
    size_t total = set->total_allocated;
    pthread_mutex_unlock(&set->mutex);
    return total;
}

size_t get_num_records(const ConcurrentDynamicRecordSet* set) {
    pthread_mutex_lock(&set->mutex);
