[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

void init_arrays(size_t N, long *offsets, int *keys, double *floats, Record **records, pthread_mutex_t *mutex) {
    if (N <= 0) return; // Handle edge case of zero-sized arrays or negative N values

    // Allocate memory for offsets, keys, floats and records
    offsets = malloc(N * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed");
        return;
    }

    keys = malloc(N * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Memory allocation failed");
        return;
    }

    floats = malloc(N * sizeof(double));
    if (!floats) {
        free(offsets);
        free(keys);
        perror("Memory allocation failed");
        return;
    }

    records = malloc(N * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        free(floats);
        perror("Memory allocation failed");
        return;
    }

    pthread_mutex_init(mutex, NULL); // Initialize the mutex

    // Initialize offsets, keys, and floats with specified values
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(mutex);
        offsets[i] = i;
        keys[i] = i;
        floats[i] = i * 1.0; // Converting integer to double
        pthread_mutex_unlock(mutex);
    }

    // Initialize records with random values within specified ranges
    for (size_t i = 0; i < N; ++i) {
        Record tempRecord = { .offset = rand() % ((maxLong + 1) - minLong) + minLong,
                              .key = rand() % ((maxInt + 1) - minInt) + minInt,
                              .value = (rand() % ((maxDouble + 1e-9) - minDouble) + minDouble) * RAND_MAX / (maxDouble + 1e-9) };

        size_t j;
        pthread_mutex_lock(mutex);
        for (j = 0; j < i; ++j) {
            if ((tempRecord.offset == records[j].offset) || (tempRecord.key == records[j].key) || (fabs(tempRecord.value - records[j].value) <= 1e-9)) {
                break;
            }
        }
        pthread_mutex_unlock(mutex);

        if (j == i) records[i] = tempRecord;
    }

    // Log the successful memory allocation and initialization
    printf("Successfully allocated and initialized arrays of size %zu\n", N);
}

void cleanup(Record **records, pthread_mutex_t *mutex) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
    pthread_mutex_destroy(mutex);
}
