    table->keys[index] = key;
    pthread_mutex_unlock(&table->lock);
}

bool find_hash(const struct hash_table *table, const void *key) {
    uint64_t index = murmurhash2_x86_128(key, strlen(key), 0) % table->size;
    pthread_mutex_lock(&table->lock);
    for (size_t i = index; i != index; i = (i + 1) % table->size) {
        if (!table->keys[i]) continue;
        const void *compare_key = table->keys[i];
        size_t compare_len = strlen(compare_key);
        if (strlen(key) != compare_len || memcmp(key, compare_key, compare_len)) continue;
        pthread_mutex_unlock(&table->lock);
        return true;
    }
    pthread_mutex_unlock(&table->lock);
