typedef struct {
    int value;
} record;

static size_t systemCapacityLimit = 1000000; // Predefined capacity limit
static size_t chunkSize = 1024; // Chunk size for memory allocation and deallocation
static size_t allocatedChunks = 0; // Tracks allocated chunks
static record* chunkStarts[chunkSize]; // Hash map to store starting addresses of allocated chunks
static record** records = NULL; // Array of record pointers
static int* keys = NULL; // Array of sequential integers
static long* offsets = NULL; // Array for dynamic offset calculation

void handle_memory_error(const char* message) {
    printf("%s\n", message);
    free_memory();
    exit(EXIT_FAILURE);
}

void free_memory() {
    for (size_t i = 0; i < allocatedChunks; ++i) {
        free(chunkStarts[i]);
    }
    free(records);
    free(keys);
    free(offsets);
    allocatedChunks = 0;
}

void init_memory(size_t N) {
    if (N > systemCapacityLimit) {
        handle_memory_error("Error: Allocation limit exceeded.");
    }

    records = malloc((N + chunkSize - 1) * sizeof(record*));
    keys = malloc(N * sizeof(int));
    offsets = calloc(N, sizeof(long));

    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
        offsets[i] = i < chunkSize ? 0 : allocatedChunks * chunkSize + i;
    }
}

void allocate_chunk() {
    if (allocatedChunks + chunkSize > systemCapacityLimit) {
        handle_memory_error("Error: Allocation limit exceeded.");
    }

    record* newChunk = malloc(chunkSize * sizeof(record));
    if (!newChunk) {
        handle_memory_error("Error: Failed to allocate memory.");
    }

    chunkStarts[allocatedChunks++] = newChunk;
}

void generate_random_values() {
    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        records[offsets[i]] = (record){ .value = rand() % ((*maxValue) - (*minValue)) + *minValue };
    }
}

void log_allocation(const char* message, size_t N, int minValue, int maxValue) {
    printf("%s: Allocated memory for array of size %zu with range [%d, %d].\n", message, N, minValue, maxValue);
}

void manage_memory(size_t N, int minValue, int maxValue) {
    if (N > 0) {
        init_memory(N);
        allocate_chunk();
        log_allocation("Initializing", N, minValue, maxValue);
        generate_random_values();
    }
}
