} NetworkDevice;

// Function to configure network device
void configureNetworkDevice(NetworkDevice *device, const char *configFile) {
    JsonObject *json = json_object_from_file(configFile);
    int tileSize = json_object_get_int(json, "tileSize");
    int worldWidth = json_object_get_int(json, "worldWidth");
    int worldHeight = json_object_get_int(json, "worldHeight");

    device->capacity = tileSize * worldWidth * worldHeight;
    device->size = 0;
    device->keys = malloc(sizeof(HashEntry) * device->capacity);
    memset(device->offsets, 0, sizeof(long) * device->capacity);
    memset(device->identifiers, 0, sizeof(char *) * device->capacity);

    pthread_mutex_init(&device->lock, NULL);

    // Initialize custom hash table
    for (int i = 0; i < device->capacity; ++i) {
        device->keys[i].key = i;
        device->keys[i].identifier = NULL;
        device->keys[i].next = &device->keys[(i + 1) % device->capacity];
    }

    // Load settings from JSON file and process data
    JsonArray *settings = json_object_get_array(json, "settings");
    for (gsize i = 0; i < json_array_length(settings); ++i) {
        int key = json_array_get_integer_element(settings, i);
        if (key >= device->capacity || device->keys[key].identifier != NULL) continue; // Skip invalid keys

        // Generate unique identifier
        char idBuffer[256];
        snprintf(idBuffer, sizeof(idBuffer), "Setting_%d", key);
        device->identifiers[key] = strdup(idBuffer);

        // Allocate memory for setting and initialize with a random value within the specified range
        int value = rand() % device->capacity;
        device->settings[key] = value;

        // Insert key into hash table and update offsets
        insertKey(device, key, device->identifiers[key]);
    }

    json_object_put(json); // Free JSON object
}

// Helper function to find and print the largest integer in the array
void findLargest(const int *array, size_t size) {
    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) max = array[i];
    }
    printf("Largest integer: %d\n", max);
}

// Helper function to insert a key into the custom hash table
void insertKey(NetworkDevice *device, int key, char *identifier) {
    HashEntry *current = device->keys;
    for (;;) {
        if (!current->next || current->key == key) break;
        current = current->next;
    }

    current->identifier = identifier;
    current->key = key;
    current->next = malloc(sizeof(HashEntry));
    current = current->next;
}
