#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int* data;
    size_t size;
} Record;

typedef struct memory_pool {
    void* buffer;
    size_t capacity;
    size_t index;
    size_t buffer_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool create_memory_pool(size_t buffer_size) {
    MemoryPool pool = {NULL, 0, 0, buffer_size, PTHREAD_MUTEX_INITIALIZER};
    pool.buffer = malloc(buffer_size * sizeof(Record));
    return pool;
}

Record create_record(int value, size_t size) {
    Record r = {malloc(value * sizeof(int)), size};
    r.data[0] = rand() % 1000 + 1; // Set random integer within [1, 1000] range
    return r;
}

Record acquire_record(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->index < pool->capacity) {
        Record record = *(Record*)((char*)pool->buffer + pool->index * sizeof(Record));
        pool->index++;
        pthread_mutex_unlock(&pool->lock);
        return record;
    }
    pthread_mutex_unlock(&pool->lock);

    // Handle memory exhaustion gracefully.
    // This example demonstrates simple logging but consider implementing more robust error handling.
    printf("Memory pool exhausted.\n");
    return (Record){NULL, 0};
}

void release_record(MemoryPool* pool, Record record) {
    pthread_mutex_lock(&pool->lock);
    memcpy((char*)pool->buffer + pool->index * sizeof(Record), &record, sizeof(Record));
    pool->index++;
    pthread_mutex_unlock(&pool->lock);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <buffer_size>\n", argv[0]);
        return 1;
    }

    MemoryPool pool = create_memory_pool(atoi(argv[1]));
