#include <stdbool.h>

typedef struct {
    int value;
    long offset;
    size_t ref_count;
} record;

struct hash_table {
    size_t capacity;
    void** table;
    pthread_mutex_t mutex;
};

void* hash_function(const void* key, const void* data) {
    return ((size_t)key ^ ((size_t)data << 3)) % ((struct hash_table*)data)->capacity;
}

struct hash_table* create_hash_table(size_t capacity) {
    struct hash_table* table = malloc(sizeof(struct hash_table));
    table->capacity = capacity;
    table->table = calloc(capacity, sizeof(void*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void put_in_hash_table(struct hash_table* table, const void* key, const void* data) {
    size_t index = hash_function(key, table);
    pthread_mutex_lock(&table->mutex);
    while (table->table[index] != NULL) {
        if (!strcmp(key, table->table[index])) {
            ((record**)table->table[index])->ref_count++;
            pthread_mutex_unlock(&table->mutex);
            return;
        }
        index = (index + 1) % table->capacity;
    }
    record** new_data = malloc(sizeof(record*));
    *new_data = malloc(sizeof(record));
    ((record*)*new_data)->value = rand() % 100; // replace with your random number generator function
    ((record*)*new_data)->offset = 0;
    ((record*)*new_data)->ref_count = 1;
    table->table[index] = new_data;
    pthread_mutex_unlock(&table->mutex);
}

record* get_from_hash_table(struct hash_table* table, const void* key) {
    size_t index = hash_function(key, table);
    record** current = &table->table[index];
    while (*current != NULL) {
        if (!strcmp(key, ((record*)*current)->offset)) {
            ((record*)*current)->ref_count++;
            return *current;
        }
        current = &(*current)[0]; // dereference to access the struct within the pointer and get its address
    }
    return NULL;
}

void free_hash_table(struct hash_table* table) {
    pthread_mutex_destroy(&table->mutex);
    for (size_t i = 0; i < table->capacity; ++i) {
        record** current = &table->table[i];
        while (*current != NULL) {
            record** to_free = current;
            current = &(*current)[0]; // dereference to access the struct within the pointer and get its address
            free(to_free);
        }
    }
    free(table->table);
    free(table);
}

record* create_data_structure(size_t offset_count, size_t key_count) {
    if (offset_count <= 0 || key_count <= 0) {
        fprintf(stderr, "Error: Invalid input for array lengths\n");
        return NULL;
    }

    struct hash_table* offsets_table = create_hash_table(offset_count);
    struct hash_table* keys_table = create_hash_table(key_count);
    record** records = malloc(key_count * sizeof(record*));

    for (size_t i = 0; i < key_count; ++i) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % 100; // replace with your random number generator function
        records[i]->offset = offsets_table->capacity;
        records[i]->ref_count = 1;
        put_in_hash_table(keys_tables, &records[i]->value, records[i]);
        put_in_hash_table(offsets_table, &records[i]->offset, records[i]);
    }

    return records;
}
```

