        success = 0;
        goto cleanup;
    }

    records = calloc(n_records, sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        success = 0;
        goto cleanup;
    }

    // Initialize offset and key arrays
    pthread_mutex_lock(&mutex);
    for (i = 0; i < n_offsets && success; ++i) {
        if ((size_t)i >= n_keys) break;
        offsets[i] = i;
