        pthread_mutex_lock(&mutex);
        records[i++] = record;
    }
    pthread_mutex_unlock(&mutex);

cleanup:
    if (success) {
        *p_n_initialized = i;
    } else {
        free(offsets);
        free(keys);
        free(records);
    }

    return success;
}

