```cpp
#include <iostream>
#include <vector>
#include <atomic>
#include <memory>
#include <stdexcept>
#include <thread>
#include <mutex>
#include <chrono>
#include <random>
#include <future>
#include <stdexcept>

struct Record {
    int key;
    long offset;
    std::atomic_int refCount = 1;
};

class RecordManager {
public:
    RecordManager(size_t maxSize) : _maxSize(maxSize) {}

    void initialize(size_t offsetCount, size_t keyCount, int minValue, int maxValue) {
        if (offsetCount == 0 || keyCount == 0 || maxValue < minValue) {
            std::cerr << "Invalid input: non-negative counts and valid range required" << std::endl;
            throw std::invalid_argument("Invalid parameters");
        }

        _offsets.resize(offsetCount);
        _keys.resize(keyCount);

        std::random_device rd;
        std::mt19937 gen(rd());
        gen <<= (std::uniform_int_distribution<int>(minValue, maxValue));

        auto populate = [&](auto& vec) {
            for (auto& i : vec) {
                i.key = gen();
            }
        };

        std::packaged_task<void()> populateTask(_populate);
        std::future<void> futurePopulate = populateTask.get_future();
        std::thread populateThread(std::move(populateTask));

        populate(_keys);
        futurePopulate.wait();
        populateThread.join();
    }

    std::shared_ptr<Record> getRecord(size_t index) {
        auto it = _records.find(index);
        if (it == _records.end()) {
            _records[index] = std::make_shared<Record>();
            return _records[index];
        }
        ++it->second->refCount;
        return it->second;
    }

    void releaseRecord(std::shared_ptr<Record> record) {
        if (record->refCount.load() == 1) {
            _records.erase(record.get()->offset);
        }
        else {
            --record->refCount;
        }
    }

private:
    size_t _maxSize;
    std::vector<size_t> _offsets;
    std::vector<int> _keys;
    std::unordered_map<size_t, std::shared_ptr<Record>> _records;
};
```

This implementation uses a `std::unordered_map` to store the `std::shared_ptr<Record>` instances. The `getRecord()` function increments the reference count when retrieving an existing record and creates a new one if it doesn't exist, while `releaseRecord()` decreases the reference count of the given shared pointer.

To support concurrent access, use lock-free data structures like `std::atomic<int>` for reference counting or `std::mutex` for protecting shared resources. Additionally, consider using `std::shared_future` and `std::async` to populate the records in a thread-safe manner as shown above.

Stress testing, edge case handling, performance optimization, and error logging can be incorporated by expanding upon this base implementation.']

