    unsigned long count;
} hash_map;

// Record structure
struct record {
    int value;
};

hash_map map;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initMap(unsigned long N) {
    map.table = calloc(N, sizeof(hash_node *));
    map.size = N;
}

// Helper function to find the largest integer in an array
int findLargest(struct record *array, unsigned long N) {
    int largest = INT32_MIN;
    for (unsigned long i = 0; i < N; ++i) {
        if (array[i].value > largest)
            largest = array[i].value;
    }
    return largest;
}

void insertRecord(struct record *record, int key) {
    pthread_mutex_lock(&lock);
    hash_node **table = map.table + (key % map.size);
    hash_node *node = malloc(sizeof(hash_node));
    node->key = key;
    node->data = record;
    node->next = *table;
    *table = node;
    ++map.count;
    pthread_mutex_unlock(&lock);
}

struct record* findRecord(int key) {
    pthread_mutex_lock(&lock);
    hash_node **table = map.table + (key % map.size);
    hash_node *current = *table;
    while (current != NULL) {
        if (current->key == key) {
            struct record *record = current->data;
            pthread_mutex_unlock(&lock);
            return record;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void initArrays(unsigned long N, int minValue, int maxValue) {
    struct record *records = malloc(N * sizeof(struct record));
    for (unsigned long i = 0; i < N; ++i) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        bool unique = true;
        struct record *record = &records[i];
        while (unique && findRecord(value)) {
            value = rand() % (maxValue - minValue + 1) + minValue;
            unique = true;
        }
        *record = (struct record){ .value = value };
    }

    int *keys = malloc(N * sizeof(int));
    for (unsigned long i = 0; i < N; ++i)
        keys[i] = i;
}
