mem_pool fp_pool, is_pool, dp_pool;
pthread_once_t once_flag = PTHREAD_ONCE_INIT;
unsigned short M;
float minPrecision, maxPrecision;
int retry_limit;

// Initialize memory pools
void init_memory_pools() {
    pthread_mutex_init(&fp_pool.lock, NULL);
    pthread_mutex_init(&is_pool.lock, NULL);
    pthread_mutex_init(&dp_pool.lock, NULL);
}

// Thread-safe memory allocation function
void* thread_safe_malloc(size_t size) {
    void* buffer;

    if (pthread_once(&once_flag, init_memory_pools) != 0)
        return NULL; // Initialize memory pools only once

    pthread_mutex_lock(&dp_pool.lock);

    if (dp_pool.size - dp_pool.allocated >= size) {
        buffer = dp_pool.buffer + dp_pool.allocated;
        dp_pool.allocated += size;
    } else {
        buffer = realloc(dp_pool.buffer, dp_pool.size * 2);
        if (!buffer) {
            pthread_mutex_unlock(&dp_pool.lock);
            return NULL;
        }
        dp_pool.buffer = buffer;
        dp_pool.size *= 2;
    }

    pthread_mutex_unlock(&dp_pool.lock);
    return buffer;
}

// Function to perform the tasks as specified
