2) Java Code for disjoint pairs check using Union-Find:

```java
import java.util.*;

public class DisjointPairs {
    private int[] parents;
    private int[] ranks;

    public int countDisjointPairs(int[] arr) {
        int n = arr.length;
        parents = new int[n];
        ranks = new int[n];

        for (int i = 0; i < n; ++i) {
            parents[i] = i;
            ranks[i] = 1;
        }

        long startTime = System.currentTimeMillis();
        int count = 0;

        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (find(i) != find(j)) {
                    union(i, j);
                    count++;
                }
            }
        }

        System.out.println("Time taken: " + (System.currentTimeMillis() - startTime) + " milliseconds");

        return count;
    }

    private int find(int x) {
        if (parents[x] != x) {
            parents[x] = find(parents[x]);
        }
        return parents[x];
    }

    private void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI == rootJ) {
            return;
        }

        if (ranks[rootI] < ranks[rootJ]) {
            parents[rootI] = rootJ;
            ranks[rootJ] += ranks[rootI];
        } else {
            parents[rootJ] = rootI;
            ranks[rootI] += ranks[rootJ];
        }
    }
}
```

