```java
import java.util.*;

public class DisjointPairChecker {
    private UnionFind uf;

    public DisjointPairChecker(int[] arr) {
        this.uf = new UnionFind(arr.length);
    }

    public int countPairs() {
        long start = System.nanoTime();
        int pairs = 0;
        for (int i = 0; i < uf.getSize(); ++i) {
            if (uf.find(i) == i && uf.count(i) > 1) {
                pairs += uf.count(i) - 1;
            }
        }
        long end = System.nanoTime();
        System.out.printf("Time taken: %.3f ms\n", (end - start) / 1e6);
        return pairs;
    }
}

class UnionFind {
    private int[] parent, rank;

    public UnionFind(int size) {
        this.parent = new int[size];
        this.rank = new int[size];
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
                rank[rootX] += rank[rootY];
            } else {
                parent[rootX] = rootY;
                rank[rootY] += rank[rootX];
            }
        }
    }

    public int getSize() {
        return parent.length;
    }

    public int count(int x) {
        return rank[find(x)];
    }
}
```

