import java.util.*;

class UnionFind {
    int[] parent;
    int[] size;

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public void unionSets(int p, int q) {
        int rootP = findSet(p);
        int rootQ = findSet(q);
        if (rootP != rootQ) {
            if (size[rootP] < size[rootQ]) {
                parent[rootP] = rootQ;
                size[rootQ] += size[rootP];
            } else {
                parent[rootQ] = rootP;
                size[rootP] += size[rootQ];
            }
        }
    }

    public int findSet(int x) {
        if (parent[x] != x) {
            parent[x] = findSet(parent[x]); // Path Compression Optimization
        }
        return parent[x];
    }
}

public class DisjointPairs {
    public static void main(String[] args) throws InterruptedException {
        int[] arr = new int[]{1, 2, 3, 4, 5};
        UnionFind uf = new UnionFind(arr.length);
        long startTime = System.currentTimeMillis();
        int count = 0;
        for (int i = 0; i < arr.length - 1; ++i) {
            for (int j = i + 1; j < arr.length; ++j) {
                if (!uf.findSet(arr[i]) == uf.findSet(arr[j])) continue;
                count++;
                System.out.printf("Pair (%d, %d) is disjoint.\n", arr[i], arr[j]);
            }
        }
        long elapsedTime = System.currentTimeMillis() - startTime;
        System.out.printf("Number of disjoint pairs: %d\n", count);
        System.out.printf("Time taken to check for each pair: %d milliseconds\n", elapsedTime);
    }
}
```

