            recordPool = malloc(RECORD_POOL_SIZE * sizeof(Record));
            if (!recordPool) return NULL;
        }
        recordPoolCount += RECORD_POOL_SIZE;
    }
    Record *record = &recordPool[recordPoolIndex];
    recordPoolIndex++;
