struct custom_array {
    void *memory;
    size_t memory_size;
    size_t used;
};

void array_init(struct custom_array *arr, size_t element_size, size_t num_elements) {
    arr->memory = mmap(NULL, num_elements * element_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (arr->memory == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        exit(EXIT_FAILURE);
    }

    arr->memory_size = num_elements * element_size;
    arr->used = 0;
}

void *array_get(struct custom_array *arr) {
    return arr->memory + arr->used;
}

void array_resize(struct custom_array *arr, size_t new_size) {
    void *new_memory = mremap(arr->memory, arr->memory_size, new_size * arr->element_size, MREMAP_MAYMOVE);
    if (new_memory == MAP_FAILED) {
        fprintf(stderr, "Failed to resize array memory\n");
        exit(EXIT_FAILURE);
    }

    arr->memory = new_memory;
    arr->memory_size = new_size * arr->element_size;
}

void *array_push(struct custom_array *arr) {
    void *result = array_get(arr);
    if (++arr->used == arr->memory_size / arr->element_size) {
        array_resize(arr, arr->memory_size * 2);
    }
    return result;
}

void array_destroy(struct custom_array *arr) {
    munmap(arr->memory, arr->memory_size);
}

record_t *record_init(const char *str) {
    record_t *record = malloc(sizeof(record_t));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        exit(EXIT_FAILURE);
    }

    size_t len = strlen(str);
    record->data = malloc(len + 1);
    if (!record->data) {
        free(record);
        fprintf(stderr, "Failed to allocate memory for record data\n");
        exit(EXIT_FAILURE);
    }

    strncpy(record->data, str, len + 1);
    record->modified = false;

    return record;
}

