    array_init((struct custom_array *)&record_array, sizeof(record_t*), num_elements);
    array_init((struct custom_array *)&metadata_array, sizeof(void*), num_elements);

    pthread_mutex_init(&mutex, NULL);

    return 0;
}

int deinit_arrays() {
