    array_destroy((struct custom_array *)&key_array);
    array_destroy((struct custom_array *)&record_array);
    array_destroy((struct custom_array *)&metadata_array);

    pthread_mutex_destroy(&mutex);

    return 0;
}

void push_offset(long offset) {
