    memcpy(mem, &key, sizeof(int));
}

record_t* push_record(const char *str) {
    record_t *record = record_init(str);
    void *mem = array_push((struct custom_array *)&record_array);
    memcpy(mem, record, sizeof(record_t*));
    return record;
}

