struct MemoryBlock {
    void *data;
    size_t size;
    struct MemoryBlock *next;
};

void *memory_pool_alloc(size_t size) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    struct MemoryBlock *head = NULL, *current, *bestFit = NULL, *worstFit = NULL;

    void *result;

    if (size > 0) {
        current = head;

        while (current != NULL) {
            if (current->size >= size) {
                if (!bestFit || (current->size < bestFit->size)) {
                    bestFit = current;
                }

                if (!worstFit || (current->size > worstFit->size)) {
                    worstFit = current;
                }
            }

            current = current->next;
        }

        if (bestFit) {
            pthread_mutex_lock(&lock);
            result = bestFit->data;
            bestFit->size -= size;
            pthread_mutex_unlock(&lock);
        } else if (worstFit) {
            pthread_mutex_lock(&lock);
            void *temp = malloc(size + worstFit->size);
            memcpy(temp, worstFit->data, worstFit->size);
            free(worstFit->data);
            worstFit->data = temp;
            worstFit->size -= size;
            result = worstFit->data + worstFit->size;
            pthread_mutex_unlock(&lock);
        } else {
            result = malloc(size);
        }
    }

    return result;
}

void memory_pool_free(void *ptr, size_t size) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    struct MemoryBlock *newBlock = malloc(sizeof(struct MemoryBlock));
    newBlock->data = ptr;
    newBlock->size = size;
    newBlock->next = head;
    head = newBlock;
}

