#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char* key;
} element;

struct memory_pool {
    void* data;
    size_t capacity;
    size_t allocated;
};

static struct memory_pool pool = { NULL, 0, 0 };
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* mem_alloc(size_t size) {
    void* data;

    pthread_mutex_lock(&pool_mutex);
    if (pool.capacity - pool.allocated >= size) {
        data = pool.data + pool.allocated;
        pool.allocated += size;
    } else {
        data = realloc(pool.data, pool.capacity + size);
        if (!data) {
            // Handle out of memory error here...
        }
        pool.capacity += size;
    }
    pthread_mutex_unlock(&pool_mutex);

    return data;
}

void mem_free(void* ptr) {
    pthread_mutex_lock(&pool_mutex);
    free(ptr);
    pool.allocated -= sizeof(*ptr);
    pthread_mutex_unlock(&pool_mutex);
}

void log(const char* function, const char* msg) {
    time_t now;
    struct tm tm;
    char strftime_buf[64];

    time(&now);
    localtime_r(&now, &tm);
    strftime(strftime_buf, sizeof(strftime_buf), "%Y-%m-%d %H:%M:%S", &tm);

    printf("[%s] [Thread ID: %lu] [%s]: %s\n", strftime_buf, pthread_self(), function, msg);
}

void initialize(size_t M, double minValue, double maxValue) {
    double* values = (double*)mem_alloc(M * sizeof(*values));
