} Record;

static pthread_mutex_t resourcePoolMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t maxCacheSize = 1024;
static Record* cache = NULL;
static size_t cacheCount = 0;
static size_t cacheCapacity = 0;

void initResources() {
    if (cache) {
        free(cache);
        pthread_mutex_destroy(&resourcePoolMutex);
    }
    cache = malloc(maxCacheSize * sizeof(Record));
    if (!cache) {
        fprintf(stderr, "Error: Unable to allocate memory for cache.\n");
        return;
    }
    cacheCount = 0;
    cacheCapacity = maxCacheSize;
    pthread_mutex_init(&resourcePoolMutex, NULL);
}

Record* getOrCreateRecord(int value) {
    pthread_mutex_lock(&resourcePoolMutex);
    if (cacheCount < cacheCapacity && !cacheCount) {
        Record* record = &cache[cacheCount++];
        record->value = value;
        pthread_mutex_unlock(&resourcePoolMutex);
        return record;
    } else {
        Record* record = NULL;
        if (cacheCount < cacheCapacity) {
            record = &cache[--cacheCount];
            record->value = value;
        } else {
            if (cacheSize() > maxCacheSize) {
                free(cache);
                initResources();
            }
            record = findRecordInCache(value);
            if (!record) {
                record = malloc(sizeof(Record));
                if (!record) {
                    fprintf(stderr, "Error: Unable to allocate memory for new record.\n");
                    pthread_mutex_unlock(&resourcePoolMutex);
                    return NULL;
                }
                record->value = value;
                addToCache(record);
            }
        }
        pthread_mutex_unlock(&resourcePoolMutex);
        return record;
    }
}

void addToCache(Record* record) {
    if (cacheSize() + 1 > cacheCapacity) {
        resizeCache();
    }
    cache[cacheCount++] = *record;
}

Record* findRecordInCache(int value) {
    for (size_t i = 0; i < cacheCount; ++i) {
        if (cache[i].value == value) {
            return &cache[i];
        }
    }
    return NULL;
}

size_t cacheSize() {
    return cacheCount;
}

void resizeCache() {
    Record* newCache = malloc((cacheCapacity * 2) * sizeof(Record));
    if (!newCache) {
        fprintf(stderr, "Error: Unable to allocate memory for expanded cache.\n");
        return;
    }
    memcpy(newCache, cache, cacheCount * sizeof(Record));
    free(cache);
    cache = newCache;
    cacheCapacity *= 2;
}

