```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <boost/random.hpp>
#include <thread>
#include <mutex>
#include <memory>
#include <atomic>

struct Record {
    int value;
    std::shared_ptr<Record> refCountPtr;
    std::atomic_int refCount;

    Record(int v) : value(v), refCountPtr(this, 1), refCount(1) {}
};

std::vector<std::mutex> mutexes(std::max_align_t(sizeof(Record)), std::mutex());

void populateRecords(std::vector<Record>& records, int minValue, int maxValue, size_t N) {
    std::uniform_int_distribution<> distrib(minValue, maxValue);
    std::vector<int> usedValues;

    for (size_t i = 0; i < N; ++i) {
        int value = distrib(boost::rand48());
        while (std::find(usedValues.begin(), usedValues.end(), value) != usedValues.end()) {
            value = distrib(boost::rand48());
        }
        unique_lock<mutex> lock(mutexes[i]);
        records[i].value = value;
        usedValues.push_back(value);
    }
}

class Collection {
public:
    explicit Collection(size_t N, int minValue, int maxValue) : keys(N), offsets(N, 0), records(N) {
        populateRecords(records, minValue, maxValue, N);
        resizeArrays();
    }

    ~Collection() {
        for (auto& rec : records) {
            rec.refCountPtr->reset();
        }
    }

    void resizeArrays(size_t newN = 0) {
        if (newN == 0) {
            newN = keys.size() * 2;
        }
        keys.resize(newN);
        offsets.resize(newN);
        records.resize(newN);
    }

    Record& operator[](int key) {
        int offset = offsets[key];
        return *(records.data() + offset);
    }

private:
    std::vector<int> keys;
    std::vector<int> offsets;
    std::vector<Record> records;
};
```

