// Custom error handling function
void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }
    printf("Successfully allocated memory of size %zu\n", size);
    return ptr;
}

