typedef struct record {
    int value;
} Record;

// Function to initialize and manage the data structure
void init_data_structure(int N, int minValue, int maxValue) {
    // Dynamically allocate memory for offset array
    long *offset = my_malloc((N+1)*sizeof(long));
    if (!offset) return;

    // Initialize offset array with sequential integers from 0 to N-1
    for (int i = 0; i < N; ++i) {
        offset[i] = i;
    }

    // Dynamically allocate memory for key and record arrays
    int *key = my_malloc(N*sizeof(int));
    if (!key) return;

    Record *recordArray = my_malloc(N*sizeof(Record));
    if (!recordArray) return;

    // Set the value of each record to a random number within [minValue, maxValue]
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        int r = minValue + rand() % (maxValue - minValue + 1); // generate a random number
        bool duplicate = false;
        do {
            if (i != key[key[offset[r]]]) {
                key[offset[r]] = i;
                recordArray[i].value = r;
                offset[r]++;
                duplicate = false;
                break;
            } else {
                duplicate = true;
            }
        } while (duplicate);
    }
}
