typedef struct record {
    int value;
    struct record* next;
} Record;

typedef struct hash_table {
    unsigned long capacity;
    Record** buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(unsigned long capacity) {
    HashTable* table = (HashTable*) malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->buckets = calloc(capacity, sizeof(Record*));
    table->lock = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

unsigned long hash(int key, unsigned long capacity) {
    // Your custom external hash function here
}

Record* create_record(int value) {
    Record* record = (Record*) malloc(sizeof(Record));
    record->value = value;
    record->next = NULL;
    return record;
}

void insert(HashTable* table, int key, int value) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(key, table->capacity);
    Record *record = create_record(value);
    Record *current = table->buckets[index];
    if (current == NULL) {
        table->buckets[index] = record;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
    pthread_mutex_unlock(&table->lock);
}

Record* find(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(key, table->capacity);
    Record *current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(key, table->capacity);
    Record *current = table->buckets[index];
    Record *prev = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (current == table->buckets[index]) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void initialize_hash_table(HashTable* table, unsigned long capacity, int min_value, int max_value) {
    for (unsigned long i = 0; i < capacity; ++i) {
        table->buckets[i] = NULL;
    }
    srand(time(NULL));
    for (unsigned long i = 0; i < capacity / 4; ++i) {
        int key = rand() % (max_value - min_value + 1) + min_value;
        int value = rand() % (max_value - min_value + 1) + min_value;
        insert(table, key, value);
    }
}
