struct log_entry {
    char uuid[37]; // UUID generated by uuid library
    time_t timestamp;
    int log_level;
    char message[1024];
};

typedef struct log_entry *LogEntry;

// Function to generate a new log entry with random log level and current system time.
LogEntry new_log_entry() {
    LogEntry le = malloc(sizeof(*le));
    if (!le) return NULL;

    uuid_t uuid;
    uuid_generate(uuid);
    snprintf((char *) le->uuid, sizeof(le->uuid), "%s", uuid_unparse(uuid));

    le->timestamp = time(NULL);
    le->log_level = rand() % 5 + 1;

    return le;
}

// Allocate and initialize an array of log entries with a specified size.
LogEntry *new_log_array(size_t size) {
    LogEntry *lea = malloc(sizeof(*lea) * size);
    if (!lea) return NULL;

    for (size_t i = 0; i < size; ++i) {
        lea[i] = new_log_entry();
        if (!lea[i]) {
            free(lea);
            return NULL;
        }
    }

    return lea;
}

// Frees the memory allocated for a log entry or an array of log entries.
void free_log_entry(LogEntry *le) {
    if (le) {
        free((char *) le->uuid);
        free(le);
    }
}

void free_log_array(LogEntry **lea, size_t size) {
    for (size_t i = 0; i < size; ++i)
        free_log_entry(&(*lea)[i]);

    free(lea);
}

// Main function to demonstrate the usage of the dynamic data structure.
