```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <memory>

struct DataPoint {
    double timestamp;
    float data_value;
};

// Custom deleter for unique_ptr
class Deleter {
public:
    void operator()(DataPoint* ptr) const noexcept { delete ptr; }
};

std::unique_ptr<DataPoint[], Deleter> create_data_array(size_t N, double epoch_start) {
    auto data = std::make_unique<DataPoint[]>(N);

    // Initialize timestamps and data values
    for (size_t i = 0; i < N; ++i) {
        data[i].timestamp = epoch_start + i;
        data[i].data_value = 0.0f;
    }

    return data;
}

std::unique_ptr<double[], Deleter> create_timestamps(size_t N, double epoch_start) {
    auto timestamps = std::make_unique<double[]>(N);

    // Initialize timestamps with sequential floating-point numbers
    for (size_t i = 0; i < N; ++i) {
        timestamps[i] = epoch_start + i;
    }

    return timestamps;
}

std::vector<std::unique_ptr<DataPoint>> create_data_pool(size_t N, std::mutex& lock) {
    std::vector<std::unique_ptr<DataPoint>> data_pool(N);
    std::lock_guard<std::mutex> guard(lock); // Lock on creation for consistency

    for (auto& element : data_pool) {
        element = std::make_unique<DataPoint>();
    }

    return data_pool;
}

void populate_data(const std::vector<std::unique_ptr<DataPoint>>& data, double minValue, double maxValue, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        // Generate random float value within the specified range
        float data_value = static_cast<float>(std::rand() * (static_cast<unsigned int>(maxValue - minValue) + 1)) + minValue;

        auto it = std::find_if(data.begin(), data.end(), [i, &data](const std::unique_ptr<DataPoint>& d) { return d->timestamp == i; });

        // Retry if a duplicate value is found
        while (it != data.end() && it->get()->timestamp == i) {
            data_value = static_cast<float>(std::rand() * (static_cast<unsigned int>(maxValue - minValue) + 1)) + minValue;
            it = std::find_if(data.begin(), data.end(), [i, &data](const stdunique_ptr<DataPoint>& d) { return d->timestamp == i; });
        }

        // Update the found data point with the new value
        if (it != data.end()) {
            it->get()->data_value = data_value;
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 7) {
        std::cerr << "Usage: timestream N epoch_start minValue maxValue threads num_iterations" << std::endl;
        return -1;
    }

    size_t N = static_cast<size_t>(std::atoll(argv[1]));
    double epoch_start = std::atof(argv[2]);
    double minValue = std::atof(argv[3]);
    double maxValue = std::atof(argv[4]);
    size_t threads = static_cast<size_t>(std::atoll(argv[5]));
    size_t num_iterations = static_cast<size_t>(std::atoll(argv[6]));

    auto timestamps = create_timestamps(N, epoch_start);
    std::unique_ptr<double[]> data(create_data_array(N));

    // Lock for concurrent access to the data pool
    std::mutex lock;
    auto data_pool = create_data_pool(N, lock);

    populate_data(data_pool, minValue, maxValue, N);

    // Concurrent access to the data array
    std::vector<std::thread> threads;
    for (size_t i = 0; i < threads; ++i) {
        threads.emplace_back([&data, &data_pool, minValue, maxValue]() {
            populate_data(data_pool, minValue, maxValue, N);
        });
    }

    for (auto& t : threads) {
        t.join();
    }
}
