typedef struct MemPool {
    void *storage;
    size_t size;
    size_t alloc_count;
    pthread_mutex_t lock;
} MemPool;

void log(int level, const char *func, const char *msg) {
    if (level > MAX_LOG_LEVEL) return;
    time_t now = time(NULL);
    char buffer[64];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s][Thread %lu][%s] %s\n", buffer, pthread_self(), func, msg);
}

MemPool *mem_pool_create(size_t size) {
    MemPool *mp = malloc(sizeof(MemPool));
    if (!mp) {
        log(1, __func__, "Failed to allocate memory for mem_pool.");
        return NULL;
    }
    mp->storage = malloc(size);
    if (!mp->storage) {
        free(mp);
        log(1, __func__, "Failed to allocate memory for mem_pool storage.");
        return NULL;
    }
    mp->size = size;
    mp->alloc_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void *mem_pool_get(MemPool *mp, size_t size) {
    void *ptr;
    pthread_mutex_lock(&mp->lock);
    if (mp->alloc_count + size > mp->size) {
        log(2, __func__, "Requested memory exceeds mem_pool capacity.");
        ptr = malloc(size);
        if (!ptr) {
            pthread_mutex_unlock(&mp->lock);
            log(1, __func__, "Failed to allocate memory from system.");
            return NULL;
        }
    } else {
        ptr = mp->storage + mp->alloc_count;
        mp->alloc_count += size;
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void mem_pool_free(MemPool *mp, void *ptr) {
    if (ptr >= mp->storage && ptr < (mp->storage + mp->size)) {
        pthread_mutex_lock(&mp->lock);
        mp->alloc_count -= ((char *)ptr - (char *)mp->storage);
        pthread_mutex_unlock(&mp->lock);
    } else {
        free(ptr);
    }
}

element **init_dataset(size_t M, double minValue, double maxValue) {
    size_t key_len = (M < 10) ? 2 : (M < 100) ? 3 : 4;
    element **data = malloc(sizeof(element *) * M);
    if (!data) {
        log(1, __func__, "Failed to allocate memory for dataset.");
        return NULL;
    }
    MemPool *doubles_pool = mem_pool_create(M * sizeof(double));
    MemPool *strings_pool = mem_pool_create(M * key_len);
    if (!doubles_pool || !strings_pool) {
        log(1, __func__, "Failed to initialize memory pools for dataset.");
        free(data);
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < M; ++i) {
        double *dptr = (double *)mem_pool_get(doubles_pool, sizeof(double));
        char *strptr = (char *)mem_pool_get(strings_pool, key_len);
        if (!dptr || !strptr) {
            log(1, __func__, "Failed to allocate memory for dataset elements.");
            clean_up_and_exit(data, doubles_pool, strings_pool);
        }
        *((double *)dptr) = (minValue + (maxValue - minValue) * i / M);
        strncpy(strptr, (char *)i, key_len - 1);
        strptr[key_len - 1] = '\0';
        data[i] = malloc(sizeof(element));
        if (!data[i]) {
            log(1, __func__, "Failed to allocate memory for dataset element.");
            clean_up_and_exit(data, doubles_pool, strings_pool);
        }
        data[i]->value = *dptr;
        data[i]->key = strptr;
    }

    pthread_mutex_destroy(&lock);
    mem_pool_free(doubles_pool, NULL);
    mem_pool_free(strings_pool, NULL);
    return data;
}

void clean_up_and_exit(element **data, MemPool *doubles_pool, MemPool *strings_pool) {
    for (size_t i = 0; i < M; ++i) {
        if (data[i]) {
            free(data[i]);
        }
    }
    free(data);
    mem_pool_free(doubles_pool, NULL);
    mem_pool_free(strings_pool, NULL);
    exit(1);
}
```

