    size_t points_used = 0;
    for (i = 0; i < num_points && points_used < num_points; ++i) {
        if (num_doubles > 0) points[i].value = 0.0;
        else points[i].value = NAN; // or other value to indicate incomplete data
        points[i].identifier = NULL;
