public byte[] DecryptWithAES(byte[] ciphertext, byte[] key, byte[] iv, AesEncryptionMode mode = AesEncryptionMode.CBC)
{
    using (var aes = Aes.Create())
    {
        // Set encryption key and IV
        aes.Key = key;
        aes.IV = iv;

        // Create a memory stream for decryption
        var msDecrypt = new MemoryStream(ciphertext);
        using (var csDecrypt = new CryptoStream(msDecrypt, aes.CreateDecryptor(), mode))
        {
            using (var msPlaintext = new MemoryStream())
            {
                csDecrypt.CopyTo(msPlaintext);
                return msPlaintext.ToArray();
            }
        }
    }
}
