// Custom memory pool class for dynamic memory allocation and management
class MemoryPool {
public:
    void* allocate(size_t size) {
        if (size > free_memory) return nullptr;

        void* ptr = malloc(size);
        if (!ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        free_memory -= size;
        used_memory += size;

        log_event("Allocated", size);
        return ptr;
    }

    void deallocate(void* ptr, size_t size) {
        if (!ptr || !size) return;

        free_memory += size;
        used_memory -= size;
        log_event("Deallocated", size);
        memset(ptr, 0, size);
        free(ptr);
    }

private:
    void log_event(const char* event, size_t size) {
        time_t now = time(nullptr);
        struct tm* local = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);

        printf("%s: Allocated/Deallocated %zd bytes\n", timestamp, size);
    }

    size_t free_memory = 0;
    size_t used_memory = 0;
};

void sensor_module(MemoryPool& memory_pool, int N, double minTemp, double maxTemp) {
    // Allocate and initialize temperature, timestamp, and sensor identifier arrays
    double* temperatures = (double*)memory_pool.allocate(N * sizeof(double));
