    // Initialize timestamps
    for (int i = 0; i < N; ++i) {
        timestamps[i] = (int)(i + time(nullptr));
    }

    // Generate unique temperature readings within the specified range
    double temp_min = minTemp;
    double temp_max = maxTemp;
    for (int i = 0; i < N; ++i) {
        data_points[i].temperature = temp_min + ((temp_max - temp_min) * rand() / RAND_MAX);
        data_points[i].timestamp = timestamps[i];
        data_points[i].sensor_id = sensor_ids[i];
    }

    // Integrate with a pre-existing logging framework (not implemented here)

    // Cleanup resources when exiting the function
    memory_pool.deallocate(temperatures, N * sizeof(double));
    memory_pool.deallocate(timestamps, N * sizeof(int));
    memory_pool.deallocate(sensor_ids, (sizeof(char) + 1) * N);
    memory_pool.deallocate(data_points, N * sizeof(struct data_point));
}

int main() {
