    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        munmap(offsets, N * sizeof(long));
        exit(1);
    }

    item **records = mmap(NULL, N * sizeof(item*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(keys);
        munmap(offsets, N * sizeof(long));
        exit(1);
    }

    for (int i = 0; i < N; ++i) {
        offsets[i] = i;
        keys[i] = i;
        records[i] = malloc(sizeof(item));
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            free(keys);
            munmap(offsets, N * sizeof(long));
            munmap(records, N * sizeof(item*));
            exit(1);
        }
        records[i]->value = rand() % (maxValue - minValue + 1) + minValue;
    }

    transaction *transactions = mmap(NULL, M * sizeof(transaction), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (transactions == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        for (int i = 0; i < N; ++i) free(records[i]);
        free(keys);
        munmap(offsets, N * sizeof(long));
        munmap(records, N * sizeof(item*));
        exit(1);
