    for (int i = 0; i < M; ++i) {
        transactions[i].value = ((double)rand() / RAND_MAX) * 200.0 - 100.0;
        transactions[i].character = 'a' + (rand() % 26);
        transactions[i].index = -1; // Not initialized yet
    }

    compression_init(COMPRESSION_LEVEL);
}

void cleanup() {
    for (int i = 0; i < N; ++i) free(records[i]);
    free(keys);
    munmap(offsets, N * sizeof(long));
    munmap(records, N * sizeof(item*));
    compression_free();
