// Helper function to convert a Record to a V8 Local<Object>
Local<Object> RecordToV8(const Record& record) {
    Isolate* isolate = Isolate::GetCurrent();
    Local<Context> context = isolate->GetCurrentContext();
    Local<Object> obj = Object::New(context);
    obj.Set(context, Int32String::NewFromValue(record.value), Integer::New(isolate, record.value));
    return obj;
}
```

