```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the node structure
typedef struct Node {
    double value;
    struct Node *next;
} Node;

// Memory pool for efficient memory management
typedef struct MemPool {
    void* buffer;
    size_t capacity;
    size_t index;
} MemPool;

// A thread-safe binary search tree implementation (assuming bst.h)
#include "bst.h"

// Memory pool initialization
MemPool mem_pool_init(size_t size) {
    // ...
}

// Allocate a new node from the memory pool
Node* get_node(MemPool* mem_pool) {
    if (mem_pool->index >= mem_pool->capacity) {
        // Extend the memory pool if necessary
        void* new_buffer = malloc((mem_pool->capacity * 2) * sizeof(Node));
        if (!new_buffer) {
            fprintf(stderr, "Failed to allocate memory for memory pool extension\n");
            exit(EXIT_FAILURE);
        }
        memmove(new_buffer, mem_pool->buffer, mem_pool->capacity * sizeof(Node));
        free(mem_pool->buffer);
        mem_pool->buffer = new_buffer;
        mem_pool->capacity *= 2;
    }
    return (Node*)((char*)mem_pool->buffer + mem_pool->index++ * sizeof(Node));
}

// Initialize the linked list with provided parameters
void init_list(BST* bst, size_t N, double minValue, double increment, MemPool* mem_pool) {
    for (size_t i = 0; i < N; ++i) {
        Node* node = get_node(mem_pool);
        node->value = minValue + i * increment;
        bst_insert(bst, node);
    }
}

// Logging function for tracking successful allocations, initializations, and insertions
