#include <iostream>
#include <vector>
#include <random>
#include <thread>
#include <mutex>
#include <chrono>

struct Record {
    int value;
};

class MemoryManager {
public:
    MemoryManager(size_t n, int minValue, int maxValue) : _n(n), _minValue(minValue), _maxValue(maxValue) {}

    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;

    void initialize() {
        if (_initialized) {
            throw std::runtime_error("MemoryManager already initialized");
        }

        // Initialize memory and seeds for random number generator
        offsets.resize(_n);
        keys.resize(_n, 0);
        records.resize(_n);
        _randomEngine.seed(std::chrono::system_clock::now().time_since_epoch().count());

        // Perform memory allocation and random initialization concurrently with a thread-safe approach
        std::mutex mtx;
        std::vector<std::thread> threads;
        for (size_t i = 0; i < _n; ++i) {
            threads.push_back(std::thread([&, i]() mutable {
                std::unique_lock<std::mutex> lock(mtx);
                mtx.unlock(); // Unlocking to allow concurrent execution
                records[i].value = _randomEngine() % (_maxValue - _minValue + 1) + _minValue;
                lock.lock(); // Locking after setting the value for safe access
            }));
        }
        for (auto& t : threads) {
            t.join();
        }

        // Verify unique values in records array and set _initialized to true
        std::sort(records.begin(), records.end());
        bool unique = true;
        int prevValue = records[0].value;
        for (size_t i = 1; i < records.size(); ++i) {
            if (records[i].value == prevValue) {
                unique = false;
                break;
            }
            prevValue = records[i].value;
        }
        _initialized = unique;
    }

private:
    size_t _n;
    int _minValue, _maxValue;
    std::mt19937 _randomEngine; // Random number generator
    bool _initialized;
};

// Function to clean up resources upon function exit
MemoryManager::~MemoryManager() {
    if (_initialized) {
        offsets.clear();
        keys.clear();
        records.clear();
    }
}
```

