#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/msg.h>
#include "config.h" // External configuration service header

typedef struct {
    long timestamp;
    signed int event_id;
    char severity;
} NetworkEvent;

struct network_event_manager {
    NetworkEvent* events;
    size_t capacity;
    size_t count;
    sem_t mutex;
    sem_t queue_not_full;
    sem_t queue_not_empty;
    void* msgq_id; // Message queue ID for event delivery
};

struct network_event_manager* create_network_event_manager(size_t initial_capacity) {
    struct network_event_manager* manager = malloc(sizeof(struct network_event_manager));
    if (!manager) return NULL;

    manager->events = calloc(initial_capacity, sizeof(NetworkEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    sem_init(&manager->mutex, 0, 1);
    sem_init(&manager->queue_not_full, 0, initial_capacity);
    sem_init(&manager->queue_not_empty, 0, 0);

    manager->msgq_id = msgget(IPC_PRIVATE, IPC_CREAT | 0666);

    return manager;
}

void add_network_event(struct network_event_manager* manager, const NetworkEvent* event) {
    sem_wait(&manager->queue_not_full);

    // Fetch new parameters from external configuration service
    long min_ts = get_min_timestamp();
    long max_ts = get_max_timestamp();
    int min_eid = get_min_event_id();
    int max_eid = get_max_event_id();

    // Generate unique event within the specified ranges
    long timestamp = generate_timestamp(min_ts, max_ts);
    int event_id = generate_unique_event_id(min_eid, max_eid, manager->count);

    NetworkEvent* current_event = &manager->events[manager->count];
    current_event->timestamp = timestamp;
    current_event->event_id = event_id;
    current_event->severity = event->severity;

    manager->count++;
    sem_post(&manager->queue_not_empty);
}

NetworkEvent* get_next_network_event(struct network_event_manager* manager) {
    NetworkEvent* current_event = NULL;

    sem_wait(&manager->queue_not_empty);
    sem_wait(&manager->mutex);

    if (manager->count > 0) {
        current_event = &manager->events[manager->count - 1];
        manager->count--;
    }

    sem_post(&manager->mutex);
    sem_post(&manager->queue_not_full);

    return current_event;
}

void free_network_event_manager(struct network_event_manager* manager) {
    if (manager && manager->events) {
        free(manager->events);
        msgctl(manager->msgq_id, IPC_RMID, NULL);
        free(manager);
    }
}
```
