```cpp
#include <boost/atomic.hpp>
#include <boost/pool/pool.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/thread/condition_variable.hpp>
#include <boost/unordered_map.hpp>
#include <cstdlib>
#include <iostream>
#include <pthread.h>
#include <vector>

// Custom memory pool for varying allocation sizes
struct MemPool : boost::pool<void*> {
    MemPool(size_t minSize, size_t maxSize) : MinSize_(minSize), MaxSize_(maxSize) {}

    void* allocate(size_t n) {
        if (n < MinSize_) return pool::allocate(MinSize_); // Fallback to base implementation for small allocations
        if (n > MaxSize_) n = MaxSize_;                     // Cap large allocations
        void* memory = malloc(n);
        if (!memory) {
            std::cerr << "Failed to allocate memory\n";
            pthread_cond_signal(&condition_);
            pthread_mutex_lock(&mutex_);
            while (pooledMemory_.find(n) != pooledMemory_.end()) {
                pthread_cond_wait(&condition_, &mutex_);
            }
            memory = pooledMemory_[n];
            pooledMemory_.erase(n);
            pthread_mutex_unlock(&mutex_);
        }
        return memory;
    }

private:
    size_t MinSize_;
    size_t MaxSize_;
    mutable boost::mutex mutex_;
    std::condition_variable condition_;
    boost::unordered_multimap<size_t, void*> pooledMemory_;
};

// Custom hash map with concurrent access support
struct Record {
    int key;
    int value;
    bool operator==(const Record& other) const { return key == other.key && value == other.value; }
};

class ConcurrentHashMap {
public:
    void put(const Record& record) {
        auto it = hashMap_.find(record.key);
        if (it != hashMap_.end()) { // Handle duplicate values efficiently
            while (true) {
                ++record.value;
                it = hashMap_.find(record.key);
                if (it == hashMap_.end() || it->second == record) break;
            }
        }
        hashMap_[record.key] = record;
    }

    const Record* get(int key) const {
        auto it = hashMap_.find(key);
        if (it != hashMap_.end()) return &it->second;
        return nullptr;
    }

private:
    boost::unordered_map<int, Record> hashMap_;
    mutable boost::mutex mtx_;
};

void initArrays(size_t N, int minValue, int maxValue, ConcurrentHashMap& map) {
    MemPool memPool(16, 8192); // Custom memory pool settings
    std::vector<long> offsets(N, 0);
    std::vector<int> keys(N);

    pthread_rwlock_t lock;
    pthread_rwlock_init(&lock, nullptr);

    for (size_t i = 0; i < N; ++i) {
        pthread_rwlock_wrlock(&lock);
        keys[i] = i;
        auto record = map.get(keys[i]);
        while (record && record->key == keys[i]) {
            pthread_rwlock_unlock(&lock);
            usleep(10); // Yield CPU to other threads
            pthread_rwlock_wrlock(&lock);
        }
        if (!record) {
            Record newRecord{keys[i], minValue};
            map.put(newRecord);
        }
        offsets[i] = record ? record->value : 0;
        pthread_rwlock_unlock(&lock);
    }

    // Perform other tasks like allocating 'record' structures here

    // Integrate with logging framework as needed
}
