use std::sync::{Arc, Mutex};
use std::mem;
use rand::Rng;
use log::{debug, error, info};
use rayon::prelude::*;

type SensorData = (f64, u32); // Custom sensor data struct
type MemPool = Arc<Mutex<Box<[SensorData]>>>; // Thread-safe memory pool
type IndexArray = Vec<u32>; // Array for unsigned long indices

// Define a custom error type
#[derive(Debug)]
enum MyError {
    AllocationFailure,
    DuplicateValue,
}

// Thread-safe initialization function for double and unsigned long arrays
fn init_arrays(n: u32) -> Result<(Vec<f64>, IndexArray), MyError> {
    let mut double_array = Vec::with_capacity(n);
    let mut index_array = vec![0; n];

    let mut guard = index_array.par_iter_mut().enumerate();
    double_array.resize(n, 0.0); // Initialize with zeros

    guard.for_each(|(_i, index)| {
        *index += 1;
        Ok(())
    })?;

    Ok((double_array, index_array))
}

// Custom memory pool implementation
struct CustomMemoryPool {
    data: MemPool,
    max_allocation: u32,
}

impl CustomMemoryPool {
    fn new(max_allocation: u32) -> Self {
        Self {
            data: Arc::new(Mutex::new(Box::new([(); 0]; max_allocation as usize))),
            max_allocation,
        }
    }

    // Allocate memory and initialize sensor data array
    fn allocate(&self) -> Result<Vec<SensorData>, MyError> {
        let mut guard = self.data.lock().unwrap();
        if guard.len() == 0 {
            return Err(MyError::AllocationFailure);
        }

        let data: Vec<SensorData> = guard.drain(..self.max_allocation as usize)
                                         .map(|()| (0.0, 0))
                                         .collect();

        data
    }

    // Find an unused index in the sensor data array and return it with the corresponding value
    fn get_unused_index(&self, data: &[SensorData]) -> Option<usize> {
        (0..data.len())
            .find(|i| !data[*i].1 as u64 == i as u64) // Check for unique indices
            .and_then(|i| {
                if data[i].0 >= min_accuracy && data[i].0 <= max_accuracy {
                    Some(i)
                } else {
                    None
                }
            })
    }
}

// Retry function for getting an unused index in case of duplicates or out-of-range values
fn retry<F>(f: F, max_retries: u32) -> Result<(), MyError>
where
    F: FnOnce() -> Result<u32, MyError>,
{
    let mut retries = 0;

    loop {
        match f() {
            Ok(index) => return Ok(()),
            Err(MyError::DuplicateValue) | Err(MyError::AllocationFailure) => {
                if retries >= max_retries {
                    return Err(MyError::DuplicateValue); // Abort after max retries
                }
                retries += 1;
                std::thread::sleep(std::time::Duration::from_millis(10)); // Backoff strategy
            }
        }
    }
}

// Main function
fn initialize(n: u32, min_accuracy: f64, max_accuracy: f64) -> Result<(), MyError> {
    let (double_array, index_array) = init_arrays(n)?;
    let mem_pool = CustomMemoryPool::new(n);

    // Configure log framework here

    // Allocate memory for sensor data array and initialize values
    let sensor_data: Vec<SensorData> = retry(move || {
        mem_pool.allocate()?.par_iter_mut().for_each(|sd| {
            *sd.0 = rand::thread_rng().gen::<f64>().map_err(|e| MyError::AllocationFailure)?;
            sd.1 = *index_array.get(sd.1 as usize).ok_or_else(|| MyError::AllocationFailure)?;
        });

        Ok(mem_pool.data.lock().unwrap().drain(..n))
    }, max_retries)?;

    // Log successful allocation and initialization
    info!("Successfully allocated memory for sensor data array");

    Ok(())
}
