Node* new_node(int key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    record->value = Random_integer(0, 100); // Initialize with random number

    Node *node = malloc(sizeof(Node));
    if (!node) {
        free(record);
        return NULL;
    }
    pthread_mutex_init(&node->lock, NULL);
    node->data = *record;
    node->next = NULL;

    return node;
}

struct Cache* new_cache() {
    struct Cache *cache = malloc(sizeof(struct Cache));
    if (!cache) return NULL;
    cache->size = 0;
    cache->capacity = 10; // Initial capacity
    cache->cache = calloc(cache->capacity, sizeof(Node*));
    return cache;
}
