                while (temp->next != NULL) temp = temp->next;
                temp->next = new_node;
            }
            pthread_mutex_unlock(&cache->cache[(key + 1) % cache->capacity]->lock);
        }
    }

    pthread_mutex_unlock(&cache->cache[key % cache->capacity]->lock);
}

Record* find(struct Cache* cache, int key, long offset) {
    pthread_mutex_lock(&cache->cache[key % cache->capacity]->lock);
    Node *current = cache->cache[key % cache->capacity];

    if (current != NULL) {
        while (current != NULL && current->data.key == key) {
            if (current->data.offset == offset) return &current->data;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&cache->cache[key % cache->capacity]->lock);
    return NULL;
}
