            pthread_create(&threads[i], NULL, thread_func, (void*)keys[i]);
        }
        for (int i = 0; i < 10; ++i) {
            pthread_join(threads[i], NULL);
        }

        // Dynamically resize the cache based on access patterns and expected load
        if (cache->size > cache->capacity * 2 / 3) {
            int new_capacity = cache->capacity * 2;
            Node** new_cache = realloc(cache->cache, sizeof(Node*) * new_capacity);
            if (!new_cache) break; // Handle memory allocation failures gracefully
            cache->cache = new_cache;
            cache->capacity *= 2;
        }
    }
}
