    unsigned char *buffer;
    size_t buffer_size;
    CRC32 crc;
} FileProcessingManager;

FileProcessingManager* FileProcessingManager_create(const char *path) {
    int flags = O_RDWR | O_CREAT | O_APPEND;
    mode_t mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;
    FileProcessingManager *fp = malloc(sizeof(FileProcessingManager));
    fp->fd = open(path, flags, mode);
    fp->pos = lseek(fp->fd, 0, SEEK_SET);
    fp->buffer = calloc(1, 4096);
    fp->buffer_size = sizeof(fp->buffer);
    fp->crc = crc32(0L, NULL);
    return fp;
}

void FileProcessingManager_destroy(FileProcessingManager *fp) {
    free(fp->buffer);
    close(fp->fd);
    free(fp);
}

size_t FileProcessingManager_read(FileProcessingManager *fp, unsigned char *buf, size_t max_len) {
    ssize_t bytes_read = read(fp->fd, buf, min(max_len, fp->buffer_size));
    if (bytes_read > 0) {
        memcpy(fp->buffer, buf, bytes_read);
        fp->pos += bytes_read;
        fp->crc = crc32(fp->crc, buf, bytes_read);
        return bytes_read;
    } else if (bytes_read == 0) {
        // End of file reached
        return 0;
    } else {
        perror("Error reading from file");
        return -1;
    }
}

size_t FileProcessingManager_write(FileProcessingManager *fp, const unsigned char *buf, size_t len) {
    if (len > fp->buffer_size - fp->pos) {
        // Resize buffer and recalculate CRC
        unsigned char *new_buffer = realloc(fp->buffer, fp->pos + len + fp->buffer_size);
        memcpy(new_buffer + fp->pos, buf, len);
        fp->buffer = new_buffer;
        fp->buffer_size += len + 1024; // Allow for some overhead
        fp->crc = crc32(fp->crc, buf, len);
    } else {
        memcpy(fp->buffer + fp->pos, buf, len);
        fp->pos += len;
        fp->crc = crc32(fp->crc, buf, len);
    }

    if (lseek(fp->fd, fp->pos - fp->buffer_size, SEEK_SET) == -1 || write(fp->fd, fp->buffer, fp->buffer_size) == -1) {
        perror("Error writing to file");
        return -1;
    }

    fp->pos = 0;
    return len;
}

// Implement thread-safe buffer management and synchronization strategies
