[' Here is a simplified version of the requested C code, focusing on key components:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    double d;
    char *id;
    time_t t;
} record;

// Custom Memory Pool
struct mem_pool {
    void **mem;
    size_t cap, used;
    pthread_mutex_t mutex;
};

// Custom Hash Map
typedef struct hashmap_node {
    record rec;
    struct hashmap_node *next;
} hashmap_node;

struct hashmap {
    hashmap_node **buckets;
    size_t size;
    pthread_mutex_t mutex;
};

// Function for initializing the memory pool
void init_mem_pool(struct mem_pool *mp, size_t cap) {
    mp->mem = malloc(cap * sizeof(void*));
    mp->cap = mp->used = cap;
    pthread_mutex_init(&mp->mutex, NULL);
}

// Function for initializing the hash map
void init_hashmap(struct hashmap *hm, size_t size) {
    hm->buckets = malloc(size * sizeof(hashmap_node*));
    hm->size = size;
    pthread_mutex_init(&hm->mutex, NULL);
    for (size_t i = 0; i < size; ++i) {
        hm->buckets[i] = NULL;
    }
}

// Function to allocate memory from the custom memory pool
void *get_mem(struct mem_pool *mp, size_t size) {
    pthread_mutex_lock(&mp->mutex);
    void *ptr = mp->mem[mp->used - 1];
    mp->used--;
    pthread_mutex_unlock(&mp->mutex);
    return ptr;
}

// Function to free memory back to the custom memory pool
void put_mem(struct mem_pool *mp, void *ptr) {
    pthread_mutex_lock(&mp->mutex);
    mp->mem[mp->used++] = ptr;
    pthread_mutex_unlock(&mp->mutex);
}

// Function to allocate and initialize the array of records
void init_records(struct hashmap *hm, struct mem_pool *mp, size_t N, double minValue, double maxValue, int retries) {
    // Allocate memory for records
    record *rec_arr = malloc(N * sizeof(record));
    if (!rec_arr) return;

    // Initialize custom memory pool for the records
    struct mem_pool rec_mem_pool = { .cap = N, .used = 0 };
    init_mem_pool(&rec_mem_pool, N);

    pthread_mutex_t rec_lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize hash map for records
    struct hashmap rec_hm = { .size = 32 };
    init_hashmap(&rec_hm, rec_hm.size);

    // Perform random initialization and memory management for each record
    for (size_t i = 0; i < N; ++i) {
        char id[16];
        snprintf(id, sizeof(id), "ID_%zu", i);

        record *rec = get_mem(&rec_mem_pool, sizeof(record));
        rec->d = (rand() % (maxValue - minValue + 1)) + minValue;
        rec->id = strdup(id);
        rec->t = time(NULL);

        pthread_mutex_lock(&rec_lock);
        bool unique = true;
        hashmap_node *node = hm->buckets[hash(id) % hm->size];
        while (node && strcmp(node->rec.id, id)) {
            if (!unique) break;
            node = node->next;
            unique = true;
        }
        pthread_mutex_unlock(&rec_lock);

        if (unique) {
            // Add record to hash map and array
            struct hashmap_node *new_node = malloc(sizeof(hashmap_node));
            new_node->rec = *rec;
            new_node->next = node;

            pthread_mutex_lock(&rec_hm.mutex);
            hm->buckets[hash(id) % hm->size] = new_node;
            pthread_mutex_unlock(&rec_hm.mutex);

            rec_arr[i] = *rec;
        } else {
            if (retries-- > 0) continue; // Retry limit reached, move on
        }
    }

    free(rec_arr); // Free the array of records after initialization
}

// Function to implement your desired logging interface
