void processRecords(MemoryPool& memoryPool, int numRecords, size_t recordSize, int minValue, int maxValue, const std::string& logFileName) {
    // Dynamically allocate memory for an array of 'record' structures using the custom memory pool
    Record* records = static_cast<Record*>(memoryPool.alloc((numRecords * recordSize)));

