        record->value = rand() % (maxValue - minValue + 1) + minValue;
        LOG(LOG_LEVEL, "Allocation and initialization of record %d with value: %d\n", i, record->value);
    }

    // Implement a batch update operation to optimize performance for large datasets
    for (int i = 0; i < numRecords; ++i) {
        Record* record = static_cast<Record*>(records + i);
        // Update each record's value within the specified range and log the operation
        record->value += rand() % (maxValue - minValue + 1) - (maxValue - minValue) / 2;
        LOG(LOG_LEVEL, "Batch update of record %d with new value: %d\n", i, record->value);
    }

    // Implement a custom hash map for fast lookups based on keys
    for (int i = 0; i < numRecords; ++i) {
