        Record* record = static_cast<Record*>(records + i);
        record->cipher = cipherMode;
        record->key = std::to_string(rand()); // Generate random key for each record
        LOG(LOG_LEVEL, "Cipher mode assignment and key generation for record %d with key: %s\n", i, record->key.c_str());
    }

    // Periodically free unused memory using the custom garbage collection mechanism
    while (!memoryPool.collect()) {}

    // Free allocated resources upon function exit
    memoryPool.free(records);
