#include <unordered_map>
#include <atomic>
#include <mutex>

template<typename T>
class ConcurrentHashMap {
public:
    void put(T key, T value) {
        // Use an atomic compare-and-swap (CAS) to avoid race conditions.
        if (!map_.compare_exchange_strong(value_for_[key], value))
            return;  // Key already exists

        map_[key] = value;
    }

    T get(T key) const {
        auto it = map_.find(key);
        if (it != map_.end())
            return it->second;
        return nullptr;
    }

private:
    std::unordered_map<T, T> map_;
    std::mutex mtx_;
    std::unordered_map<T, T> value_for_{};  // used for CAS operation
};
```

2. Memory Pool (using a custom allocator):

```cpp
#include <vector>
#include <list>
#include <mutex>

template<typename T>
class MemoryPool {
public:
    T* allocate() {
        std::lock_guard<std::mutex> lck(mtx_);

        if (!free_list_.empty()) {
            T* element = free_list_.front();
            free_list_.pop_front();
            return element;
        }

        return new T();
    }

    void deallocate(T* ptr) {
        std::lock_guard<std::mutex> lck(mtx_);
        free_list_.push_back(ptr);
    }

private:
    std::list<T*> free_list_;  // Doubly-linked list of available elements.
    std::mutex mtx_;          // Mutex for thread safety.
};
