struct prime_data {
    long *offsets;
    int *keys;
    size_t len;
};

static void find_primes(struct prime_data *pd) {
    bool is_prime[101] = {0};
    for (int i = 2; i <= 100; ++i) {
        if (!is_prime[i]) {
            for (int j = i + i; j <= 100; j += i) {
                is_prime[j] = true;
            }
            pd->offsets[(pd->len - 1)] = i;
            pd->keys[(pd->len - 1)] = i;
            ++(pd->len);
        }
    }
}

record *create_records(size_t num) {
    record *rec_arr = (record *)calloc(num, sizeof(record));
    if (!rec_arr) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    return rec_arr;
}

struct prime_data pd;
ReqwestPool pool;
pthread_mutex_t pm = PTHREAD_MUTEX_INITIALIZER;

long *offsets, *keys;
record *records;

void init() {
    pthread_mutex_lock(&pm);
    if (!pd.len) find_primes(&pd);
    offsets = (long *)calloc(pd.len, sizeof(long));
    keys = (int *)calloc(pd.len, sizeof(int));
    records = create_records(pd.len);
    pthread_mutex_unlock(&pm);
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}

ReqwestResponse handle_request(int key) {
    // Implement the request handling logic here using reqwest library functions.
}

void worker(void *arg) {
    while (true) {
        pthread_mutex_lock(&pm);
        int index = rand() % pd.len;
        int key = keys[index];
        long offset = offsets[index];
        pthread_mutex_unlock(&pm);

        ReqwestResponse resp = handle_request(key);
        if (resp.status != 200) {
            // Handle error case here.
        }

        records[offset].val = resp.data;
    }
}

int main() {
    init();
    pool.max_connections = 10;
    pool.keep_alive = true;

    pthread_t workers[pd.len];
    for (size_t i = 0; i < pd.len; ++i) {
        pthread_create(&workers[i], NULL, worker, NULL);
    }

    // Wait for all threads to finish and clean up resources.

    return 0;
}
