```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    double value;
    char* key;
    node* next;
} node;

typedef struct entry {
    int key;
    float data;
} entry;

node** nodes = NULL;
entry** entries = NULL;
pthread_mutex_t mutex;

void init(int num_nodes, int rows, int cols) {
    nodes = malloc(num_nodes * sizeof(node*));
    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = malloc(sizeof(node));
        nodes[i]->key = NULL;
        nodes[i]->value = 0.0;
        nodes[i]->next = NULL;
    }

    entries = malloc(rows * cols * sizeof(entry*));
    for (int i = 0; i < rows * cols; ++i) {
        entries[i] = malloc(sizeof(entry));
        entries[i]->key = -1;
        entries[i]->data = 0.0f;
    }

    pthread_mutex_init(&mutex, NULL);
}

void destroy() {
    for (int i = 0; i < nodesSize(); ++i) {
        free(nodes[i]);
    }
    free(nodes);

    for (int i = 0; i < entriesSize(); ++i) {
        free(entries[i]);
    }
    free(entries);

    pthread_mutex_destroy(&mutex);
}

void add_node(const char* key, double value) {
    node** current = nodes;
    while (*current != NULL) {
        if (strcmp((*current)->key, key) == 0) {
            (*current)->value = value;
            return;
        }
        current = &(*current)->next;
    }

    node* new_node = malloc(sizeof(node));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    *current = new_node;
    pthread_mutex_unlock(&mutex);
}

void add_entry(int key, float data) {
    pthread_mutex_lock(&mutex);
    entries[key]->data = data;
    entries[key]->key = key;
    pthread_mutex_unlock(&mutex);
}

int nodesSize() {
    int size = 0;
    node** current = nodes;
    while (*current != NULL) {
        ++size;
        current = &(*current)->next;
    }
    return size;
}

int entriesSize() {
    return rows * cols;
}
```

