            keys = realloc(keys, num_keys++ * sizeof(*keys));
            keys[num_keys - 1] = transform_offset(offset);
        } else if (offset != 0) { // Search for an empty slot in the linked list to store this key
            size_t j;
            for (j = 0; j < num_keys && keys[j] != transform_offset(offset); ++j);
            if (j == num_keys) { // No free slot found, so reallocate memory for the key array
                keys = realloc(keys, (num_keys + 1) * sizeof(*keys));
                keys[num_keys++] = transform_offset(offset);
            } else { // Found an empty slot, use it to store this key
                memmove(&keys[j + 1], &keys[j], (num_keys - j) * sizeof(*keys));
                keys[j] = transform_offset(offset);
            }
        }
    }

    // Allocate memory for the record array, with a buffer to account for potential memory fragmentation
    size_t max_records = (num_keys + 1) / 2; // Assuming approximately equal numbers of keys and records
    Record *records = malloc(max_records * sizeof(*records));
    if (!records) {
        fprintf(stderr, "Error: Insufficient system memory.\n");
        free(offsets);
        free(keys);
        return -2;
    }

    // Initialize the record array with unique randomly generated integers
    for (size_t i = 0; i < max_records; ++i) {
        int key = keys[i];
        while (true) {
            int *data = malloc(sizeof(*data));
            if (!data) {
                fprintf(stderr, "Error: Insufficient system memory.\n");
                free_records(records, i);
                free(offsets);
                free(keys);
                return -2;
            }
            *data = rand() % 201 - 100; // Generating random values between -100 and 100 (inclusive)

            size_t j;
            for (j = 0; j < i && records[j].data != data; ++j);
            if (j == i) { // Found an empty slot, store the record in the array
                records[i].data = data;
                break;
            } else { // This record shares the same allocated integer with another record, so free it and continue searching
                free(data);
            }
        }
    }

    *records = records;
    return num_keys;
}
