#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Node {
    double value;
    char *key;
    node* next;
} node;

typedef struct Entry {
    int key;
    float data;
} entry;

struct MemoryPool {
    void* pool;
    size_t size;
    size_t used;
};

struct CircularBuffer {
    pthread_mutex_t lock;
    node** buffer;
    int capacity, head, tail;
};

void initHashTable(node*** table, size_t* tableSize, float loadFactor, struct MemoryPool* memoryPool) {
    *table = (node**)calloc(*tableSize, sizeof(node*));
    *memoryPool = (struct MemoryPool){.pool = malloc(1024), .size = 1024, .used = 0};
    for (int i = 0; i < *tableSize; ++i) {
        (*table)[i] = (node*)memoryPool->pool + memoryPool->used++;
        (*table)[i]->value = rand() / RAND_MAX * 1.0;
        (*table)[i]->key = NULL;
        (*table)[i]->next = NULL;
    }
}

void resizeHashTable(node** table, size_t* tableSize, float loadFactor) {
    node** newTable = (node**)realloc(*table, *tableSize * 2 * sizeof(node*));
    for (int i = *tableSize; i < *tableSize * 2; ++i) {
        newTable[i] = (node*)calloc(1, sizeof(node));
        (*newTable)[i]->value = rand() / RAND_MAX * 1.0;
        (*newTable)[i]->key = NULL;
        (*newTable)[i]->next = NULL;
    }
    *tableSize *= 2;
    memcpy(*table, newTable, *tableSize * sizeof(node*));
    free(newTable + *tableSize);
}

void initEntryArray(entry** array, size_t width, size_t height, const char* string) {
    *array = (entry*)calloc(width * height, sizeof(entry));
    srand((uint32_t)hashString(string));
    for (int i = 0; i < width * height; ++i) {
        (*array)[i].key = rand() % string_length(string);
        (*array)[i].data = rand() / RAND_MAX * 1.0;
    }
}

uint32_t hashString(const char* str) {
    uint32_t h = 5381;
    for (int i = 0; str[i]; ++i)
        h = h * 33 + str[i];
    return h % INT_MAX;
}

size_t string_length(const char* str) {
    size_t len = 0;
    for (; str[len]; ++len);
    return len;
}

void* memoryPoolAlloc(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        void* newPool = realloc(pool->pool, pool->size * 2);
        if (!newPool) return NULL;
        pool->pool = newPool;
        pool->size *= 2;
    }
    void* ptr = pool->pool + pool->used;
    pool->used += size;
    return ptr;
}

void memoryPoolFree(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->pool || ptr >= pool->pool + pool->size) return;
    memmove(ptr - pool->used, ptr, sizeof(char) * pool->used);
    pool->used -= sizeof(char) * (ptr - pool->pool);
}

struct CircularBuffer* createCircularBuffer(int capacity) {
    struct CircularBuffer* cb = (struct CircularBuffer*)calloc(1, sizeof(struct CircularBuffer));
    cb->buffer = (node**)malloc(capacity * sizeof(node*));
    cb->capacity = cb->head = cb->tail = 0;
    pthread_mutex_init(&cb->lock, NULL);
    return cb;
}

void pushCB(struct CircularBuffer* cb, node* n) {
    pthread_mutex_lock(&cb->lock);
    cb->buffer[cb->head] = n;
    if (++cb->head == cb->capacity) cb->head = 0;
    pthread_mutex_unlock(&cb->lock);
}

node* popCB(struct CircularBuffer* cb) {
    node* n;
    pthread_mutex_lock(&cb->lock);
    n = cb->buffer[cb->tail];
    if (++cb->tail == cb->capacity) cb->tail = 0;
    pthread_mutex_unlock(&cb->lock);
    return n;
}

// Implement other necessary functions for the data processing application
