void resize_node_array(Node** nodes, int* capacity) {
    *capacity *= 2;
    Node** new_nodes = realloc(nodes, *capacity * sizeof(Node*));
    if (!new_nodes) {
        perror("Out of memory while resizing node array");
        exit(EXIT_FAILURE);
    }
    memmove(new_nodes + (*capacity) / 2, nodes, *capacity * sizeof(Node*));
    for (int i = *capacity / 2; i < *capacity; ++i) {
        new_nodes[i] = NULL;
    }
    nodes = new_nodes;
}
