#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char *key;
} item;

typedef void (*update_fn)(double *);

struct collection {
    size_t size;
    item **items;
    pthread_mutex_t lock;
    // External data source validation function
    int (*validate)(const char *key);
};

// Thread-safe function to add an item to the collection
void add_item(struct collection *coll, const char *key, double value) {
    pthread_mutex_lock(&coll->lock);

    // Attempt validation and log if failed
    if (!coll->validate(key)) {
        printf("Error: Invalid key '%s'\n", key);
        pthread_mutex_unlock(&coll->lock);
        return;
    }

    // Allocate memory for new item and resize items array if needed
    item *new_item = malloc(sizeof(item));
    if (!new_item) {
        printf("Error: Out of memory\n");
        pthread_mutex_unlock(&coll->lock);
        return;
    }
    new_item->value = value;
    new_item->key = strdup(key);

    size_t i;
    for (i = coll->size; i > 0 && !strcmp(coll->items[i - 1]->key, key); --i) {
        // Shift all items after the found one up to make space for the new item
        coll->items[i] = coll->items[i - 1];
    }
    free(new_item->key); // Free duplicate key if it overlaps with an existing one
    new_item->key = strdup(key);
    if (i == coll->size) {
        // If the key is not already in the collection, append the new item
        coll->items[coll->size++] = new_item;
    } else {
        // Otherwise, overwrite the existing item with the new one
        coll->items[i] = new_item;
    }

    pthread_mutex_unlock(&coll->lock);
}

// Thread-safe function to iterate through items and apply an update function
void for_each(struct collection *coll, update_fn fn) {
    pthread_mutex_lock(&coll->lock);

    for (size_t i = 0; i < coll->size; ++i) {
        // Attempt to apply the update function to each item
        if (coll->items[i]) {
            fn(&coll->items[i]->value);
        }
    }

    pthread_mutex_unlock(&coll->lock);
}

// Function to clean up unused items periodically. Implement deferred cleanup strategy.
void clean_up(struct collection *coll) {
    pthread_mutex_lock(&coll->lock);

    item **temp = malloc(sizeof(item*) * coll->size);
    size_t temp_index = 0;

    for (size_t i = 0; i < coll->size; ++i) {
        if (!coll->items[i]) {
            continue;
        }

        // Overwrite the empty item with the non-empty one to keep memory contiguous
        temp[temp_index++] = coll->items[i];
    }

    free(coll->items);
    coll->size = temp_index;
    coll->items = temp;

    pthread_mutex_unlock(&coll->lock);
}
```

