    pool.memory = malloc((N * sizeof(Record)) + (maxValue - minValue + 1) * sizeof(int));
    if (!pool.memory) {
        // Handle out-of-memory condition here.
    }

    int avail[maxValue - minValue + 1];
    for (size_t i = 0; i < maxValue - minValue + 1; ++i) {
        avail[i] = true;
    }

    Record *records = (Record *)pool.memory;
    for (size_t i = 0; i < N; ++i) {
