size_t num_cores = sysconf(_SC_NPROCESSORS_CONF);

// Memory pool for efficient dynamic memory allocation
struct MemPool mempool;

void *mempool_malloc(size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&mempool.freelist);
    if (mempool.freelist != NULL) {
        ptr = mempool.freelist;
        mempool.freelist = ((char *)mempool.freelist) + size;
    } else {
        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr == MAP_FAILED) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mempool.freelist);
            return NULL;
        }
    }
    mempool.size += size;
    pthread_mutex_unlock(&mempool.freelist);
    return ptr;
}

void mempool_free(void *ptr) {
    pthread_mutex_lock(&mempool.freelist);
    mempool_malloc((char *)ptr - (char *)&mempool);
    pthread_mutex_unlock(&mempool.freelist);
}

