HashNode** createHashTable(int size) {
    HashNode** table = malloc(sizeof(HashNode*) * size);
    for (int i = 0; i < size; ++i) {
        table[i] = NULL;
    }
    return table;
}

unsigned int hashFunction(char* key, int tableSize) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % tableSize;
}

void insertHashTable(HashNode** table, int size, char* key, Data* data) {
    unsigned int index = hashFunction(key, size);
    HashNode* current = table[index];

    if (!current) {
        current = malloc(sizeof(HashNode));
        strcpy(current->key, key);
        current->index = index;
        current->next = NULL;
        table[index] = current;
    } else {
        HashNode* newNode = malloc(sizeof(HashNode));
        strcpy(newNode->key, key);
        newNode->index = index;
        newNode->next = current;

        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }
}

Data* findInHashTable(HashNode** table, int size, char* key) {
    unsigned int index = hashFunction(key, size);
    HashNode* current = table[index];

    if (!current) {
        return NULL;
    }

