#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>

// Custom memory pool and allocation functions
typedef struct MemPool {
    void* data;
    size_t size;
    struct MemPool* next;
} MemPool;

MemPool* mem_pool = NULL;

void* mem_alloc(size_t size) {
    if (mem_pool) {
        MemPool* pool = mem_pool;
        MemPool* next = pool->next;

        if (pool->size >= size) {
            void* ptr = pool->data;
            pool->data += size;
            pool->size -= size;
            return ptr;
        } else {
            mem_pool = next;
        }
    }

    return mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void mem_free(void* ptr) {
    if (mem_pool) {
        MemPool* pool = (MemPool*)mem_alloc(sizeof(MemPool));
        pool->data = ptr;
        pool->size = sizeof(Record) * N;
        pool->next = mem_pool;
        mem_pool = pool;
    } else {
        munmap(ptr, sizeof(Record) * N);
    }
}

