            return &dataset[i];
        }
    }
    *index = -1;
    return NULL;
}

// Thread-safe data manipulation functions using pthread_mutex_t
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_dataset(size_t N) {
    dataset = (Record*)mem_alloc(sizeof(Record) * N);
}

void insert_record(Record* record, size_t* index) {
    pthread_mutex_lock(&mutex);
    // Attempt to insert the record and handle duplicates by retrying until unique
    while (!unique_value(record, *index)) {
        (*index)++;

        if (*index >= N) {
            pthread_mutex_unlock(&mutex);
            fprintf(stderr, "Error: Unable to insert record due to high contention.\n");
            return;
        }
    }

    dataset[*index] = *record;
    pthread_mutex_unlock(&mutex);
}

