// Define record structure and macros for memory allocation and logging
typedef struct {
    int value;
} Record;

#define N (size_t)malloc(sizeof(long)*sizeof(void*))
#define KEYS (int*)N = malloc(sizeof(int)*N)
#define RECORDS (Record*)((char*)N + sizeof(long)) = calloc(N, sizeof(Record))
#define LOG(message, ...) printf("[%ld] " message "\n", pthread_self(), ##__VA_ARGS__)

void init_array(size_t* arr, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        arr[i] = i;
    }
}

// Function that implements the given requirements
void my_function(size_t N, int minValue, int maxValue) {
    // Check if range is too small to provide unique values
    if ((maxValue - minValue + 1) < N) {
        LOG("Range too small for unique values. Aborting.\n");
        exit(EXIT_FAILURE);
    }

    init_array(N, sizeof(void*)); // Initialize memory pointers array

    sem_t lock; // Synchronization mechanism for thread-safety
    sem_init(&lock, 0, 1);

    pthread_t tid;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Parallel loop to set record values using random numbers and thread-safe data structures
    for (size_t i = 0; i < N; ++i) {
        pthread_create(&tid, &attr, worker, &i);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(tid, NULL);
    }

    sem_destroy(&lock); // Cleanup thread-safe data structures
    pthread_attr_destroy(&attr);
}

void* worker(void* arg) {
    size_t index = *(size_t*)arg;
    long offset = KEYS[index];
    int value, uniqueCount = 0;

    sem_wait(&lock); // Acquire lock for thread-safety
    while (uniqueCount < N && offset >= 0) {
        value = minValue + (rand() % (maxValue - minValue + 1));
        if (KEYS[offset] == value) {
            uniqueCount++;
            offset--;
        } else {
            RECORDS[index].value = value;
            KEYS[offset] = value;
        }
    }
    sem_post(&lock); // Release lock for thread-safety

    pthread_exit(NULL);
}
