    int *keys;
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

MemLayout* initMemLayout(size_t N) {
    MemLayout *mem_layout = (MemLayout *) malloc(sizeof(MemLayout));
    mem_layout->capacity = N;
    mem_layout->size = 0;
    mem_layout->offsets = (long *) calloc(N, sizeof(long));
    mem_layout->keys = (int *) calloc(N, sizeof(int));
    mem_layout->records = (Record*) calloc(N, sizeof(Record));
    mem_layout->mutex = PTHREAD_MUTEX_INITIALIZER;
    return mem_layout;
}

int findKey(MemLayout* mem_layout, int key) {
    for (size_t i = 0; i < mem_layout->size; ++i) {
        if (mem_layout->keys[i] == key) {
            return i;
        }
    }
    return -1;
}

int insertRecord(MemLayout* mem_layout, Record record) {
    int key = record.key;
    for (int i = 0; i < mem_layout->size; ++i) {
        if (mem_layout->records[i].key == key) {
            return -1;
        }
    }
    pthread_mutex_lock(&mem_layout->mutex);
    int idx = findKey(mem_layout, key);
    if (idx != -1) { // Key already exists, update the value and release lock.
        mem_layout->records[idx].value = record.value;
        pthread_mutex_unlock(&mem_layout->mutex);
        return idx;
    }
    if (mem_layout->size >= mem_layout->capacity) { // Resize the array if necessary.
        size_t new_capacity = mem_layout->capacity * 2;
        Record* tmp_records = (Record*) realloc(mem_layout->records, new_capacity * sizeof(Record));
        if (!tmp_records) {
            pthread_mutex_unlock(&mem_layout->mutex);
            return -1;
        }
        mem_layout->records = tmp_records;
        long* tmp_offsets = (long*) realloc(mem_layout->offsets, new_capacity * sizeof(long));
        if (!tmp_offsets) {
            free(mem_layout->records);
            pthread_mutex_unlock(&mem_layout->mutex);
            return -1;
        }
        mem_layout->offsets = tmp_offsets;
        mem_layout->capacity = new_capacity;
    }
    int idx = mem_layout->size++; // Insert the record and update offset.
    mem_layout->keys[idx] = key;
    mem_layout->records[idx].key = key;
    mem_layout->records[idx].value = record.value;
    mem_layout->offsets[key] = idx;
    pthread_mutex_unlock(&mem_layout->mutex);
    return idx;
}

void cleanup(MemLayout* mem_layout) {
    free(mem_layout->offsets);
    free(mem_layout->keys);
    free(mem_layout->records);
    free(mem_layout);
}
