        MemoryPool {
            data: Vec::new(),
            allocated: RefCell::new(Vec::new()),
        }
    }

    // ... Implement the necessary methods for dynamic memory allocation and freeing, including shrinkage operations.
}

fn allocate_arrays<T: Copy + Default>(n: usize, pool: Arc<Mutex<MemoryPool>>) -> (Vec<T>, Vec<usize>) {
    let pool = pool.lock().unwrap();
    // Allocate memory for the double precision values and indices arrays.
    let mut double_arr = vec![Default::default(); n];
    let mut index_arr = vec![0; n];

    for (i, v) in double_arr.par_iter_mut() {
        // Allocate a MemoryBlock from the pool if needed, and initialize the value with default(0.0).
        if i.is_null() {
            let mem_block = pool.allocate(n);
            unsafe {
                let ptr: *mut f64 = mem::transmute(mem_block.data());
                std::ptr::write(ptr, 0.0);
            }
            v.set(ptr as *const _);
        }
    }

    // Allocate memory for the complex numbers array.
    let mut complex_arr = vec![ComplexNumber::default(); n];

    // Use rayon's parallel iteration to initialize the complex numbers in a thread-safe manner.
    complex_arr.par_iter_mut().for_each(|complex| {
        let mut value = complex.real;

        loop {
            if value >= minPrecision as f64 && value <= maxPrecision as f64 {
                complex.imag = 0.0;
                break;
            }
            value += (maxPrecision - minPrecision).to_f64().unwrap() / 2.0;
        }

        // Find a unique index for the complex number in the array, retrying if a duplicate is encountered.
        let mut index = 0;
        while complex_arr[index].real == value {
            index = (index + 1) % n;
            if index == mem::size_of::<ComplexNumber>() as usize * n {
                panic!("Exceeded maximum retries");
            }
        }
        complex.index = index;
    });

    (double_arr, index_arr)
}
