class Measurement {
public:
    int id;
    int value;

    Measurement(int id, int value) : id(id), value(value) {}
};

std::unordered_map<int, std::unique_ptr<Measurement>> measurements;
MemoryPool memoryPool;
spdlog::async_logger_mt log;

void createSensorData(int M, int minValue, int maxValue, MemoryPool& pool) {
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < M; ++i) {
        void* data = pool.allocate(sizeof(Measurement));
        Measurement* measurement = new (data) Measurement(i, std::rand() % (maxValue - minValue + 1) + minValue);

        measurements[i] = std::unique_ptr<Measurement>(measurement);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    log->info("Created {} measurements in {}ms", M, duration);
}

void cleanup() {
    for (auto& measurement : measurements) {
        if (measurement.second) {
            measurement.second->~Measurement();
            memoryPool.deallocate(measurement.first.get(), sizeof(Measurement));
        }
    }
}

int main(int argc, char* argv[]) {
    std::string log_file = "log.txt";
    if (argc > 1) {
        log_file = argv[1];
    }
    log->set_level(spdlog::level::info);
    log->flush_on(spdlog::level::debug);
    log->set_pattern("%v");
    log->set_async_mode(true);
    log->set_target([&](std::string msg) {
        std::ofstream ofs(log_file, std::ios_base::app);
        ofs << msg;
    });

    int M = 1000000;
    int minValue = 0;
    int maxValue = 100;

    createSensorData(M, minValue, maxValue, memoryPool);
    std::this_thread::sleep_for(std::chrono::seconds(5)); // Pause for logging purposes
    cleanup();

    return 0;
}
