['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char *key;
    unsigned long id;
    int timestamp;
} entry;

struct hash_node {
    entry data;
    struct hash_node *next;
};

typedef struct hash_table {
    struct hash_node **nodes;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} hash_table;

hash_table* create_hash_table() {
    hash_table *ht = malloc(sizeof(hash_table));
    ht->nodes = calloc(16, sizeof(entry*));
    ht->size = 0;
    ht->capacity = 16;
    ht->mutex = PTHREAD_MUTEX_INITIALIZER;
    return ht;
}

unsigned long hash_function(const char *key, size_t table_size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % table_size;
}

entry* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Allocation failure\n");
        abort();
    }
    return ptr;
}

void insert_entry(hash_table* ht, const char *key, unsigned long id) {
    pthread_mutex_lock(&ht->mutex);

    size_t index = hash_function(key, ht->capacity);
    struct hash_node *current = ht->nodes[index];
    struct hash_node *new_node = custom_malloc(sizeof(struct hash_node));

    new_node->data.id = id;
    new_node->data.key = strdup(key);
    new_node->data.timestamp = time(NULL);
    new_node->next = current;

    if (current) {
        ht->nodes[index] = new_node;
    } else {
        ht->nodes[index] = new_node;
    }

    if ((double)(ht->size + 1) / ht->capacity >= 0.9)
        resize_hash_table(ht);

    pthread_mutex_unlock(&ht->mutex);
}

void resize_hash_table(hash_table *ht) {
    hash_table new_ht = create_hash_table();
    size_t old_capacity = ht->capacity;
    ht->capacity *= 2;

    for (size_t i = 0; i < old_capacity; ++i) {
        struct hash_node *current = ht->nodes[i];
        while (current != NULL) {
            struct hash_node *tmp = current;
            current = current->next;

            insert_entry(new_ht, tmp->data.key, tmp->data.id);
            free(tmp);
        }
    }
    ht->nodes = new_ht.nodes;
}
```

