// Thread-safe random number generator
class TRand {
public:
    explicit TRand(unsigned long seed) : m_engine(seed), m_mutex() {}

    double get() const {
        std::lock_guard<std::mutex> lock(m_mutex);
        return m_engine.minstd_rand0() * (maxValue - minValue) + minValue;
    }

private:
    std::mt19937 m_engine;
    mutable std::mutex m_mutex;
    const double minValue, maxValue;
};

// Memory management class with reference counting
class MemManager {
public:
    MemManager(size_t blockSize) : m_blocks(), m_refCount() {
        for (size_t i = 0; i < blockSize; ++i) {
            m_blocks.push_back(std::unique_ptr<char[]>(new char[sizeof(DataPoint) + sizeof(int)]));
            m_refCount.push_back(1);
        }
    }

    std::pair<DataPoint*, int*> allocate() {
        for (auto& block : m_blocks) {
            if (m_refCount[block.get() - &m_blocks.front()] == 1) {
                return {reinterpret_cast<DataPoint*>(block.get()), reinterpret_cast<int*>(static_cast<char*>(block.get()) + sizeof(int))};
            }
        }
        throw std::runtime_error("Out of memory!");
    }

    void deallocate(DataPoint*, int*) {
        ++m_refCount[static_cast<char*>(std::get<1>(std::get<0>())) - &m_blocks.front()];
    }

private:
    std::vector<std::unique_ptr<char[]>> m_blocks;
    std::vector<size_t> m_refCount;
};

// Logging macro
#define LOG(level, message) log4cpp::Category::getRootCat().infoStream() << "[" \
                               << std::chrono::system_clock::now().time_since_epoch().count() / 1000000 \
                               << "] [" << level << "] " << message;

// Function to perform the task
void initDataSystem(size_t N, double minValue, double maxValue) {
    MemManager memManager(N);
    std::vector<DataPoint> dataPoints;
    std::vector<int> indices;
    TRand randGen(std::chrono::system_clock::now().time_since_epoch().count());

    // Initialize arrays with smart pointers and reference counting
    std::unique_ptr<DataPoint[], decltype(&MemManager::deallocate)> dataPointsPtr(new DataPoint[N], MemManager::deallocate);
    std::unique_ptr<int[], decltype(&MemManager::deallocate)> indicesPtr(new int[N], MemManager::deallocate);

    // Fill index array sequentially and data array with random numbers
    for (size_t i = 0; i < N; ++i) {
        indicesPtr[i] = i;
        dataPointsPtr[i].value = randGen.get();
    }

    // Log initialization operation
    LOG(INFO, "Initializing data system with N=" << N << ", [minValue, maxValue]=[" << minValue << ", " << maxValue << "]");

    // Extend dataPoints vector to store all the data points
    dataPoints.reserve(N);
    for (auto& dataPoint : dataPointsPtr) {
        dataPoints.push_back(dataPoint);
    }

    // Compute statistics and log results
    double mean = std::accumulate(dataPoints.begin(), dataPoints.end(), 0.0, [](double a, const DataPoint& b) { return a + b.value; }) / dataPoints.size();
    double variance = std::accumulate(dataPoints.cbegin(), dataPoints.cend(), 0.0, [mean](double a, const DataPoint& b) {
        return a + (b.value - mean) * (b.value - mean);
    }) / (dataPoints.size() - 1);

    LOG(INFO, "Mean: " << mean << ", Variance: " << variance);

    // Read additional data points from standard input and update statistics
    std::vector<double> inputData;
    double inputValue;
    while (std::cin >> inputValue) {
        if (inputValue < minValue || inputValue > maxValue) {
            LOG(WARN, "Ignoring invalid value: " << inputValue);
            continue;
        }
        inputData.push_back(inputValue);
    }

    double newMean = std::accumulate(inputData.begin(), inputData.end(), mean, [](double a, const double& b) { return a + b / inputData.size(); });
    double newVariance = std::accumulate(inputData.cbegin(), inputData.cend(), 0.0, [newMean](double a, const double& b) {
        return a + (b - newMean) * (b - newMean);
    }) / (inputData.size() - 1);

    LOG(INFO, "Updated Mean: " << newMean << ", Updated Variance: " << newVariance);
}

int main() {
    try {
        initDataSystem(100, 0, 100);
    } catch (const std::exception& e) {
        LOG(ERROR, "Error initializing data system: " << e.what());
    }
}']

