            cleanup(*offsets, *keys, mutexes);
            exit(EXIT_FAILURE);
        }
    }

    // Resource Management
    for (size_t i = 0; i < (*N); ++i) {
        pthread_join(threads[i], NULL);
    }
    cleanup(*offsets, *keys, mutexes);
}

// Cleanup function
