    offsets.resize(N);
    keys.resize(N);
    records.resize(N);

    // Initialize the key array with sequential integers starting from 0 up to N-1
    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
    }

    // Use a loop to set the value of each record's int field to a random value within the specified range [minValue, maxValue].
    std::random_device rd;  //Will be used to obtain a seed for the random number engine
    std::mt19937 gen(rd());  //Standard mersenne_twister_engine seeded with rd()
    std::uniform_int_distribution<> distr(minValue, maxValue);

    std::unique_lock<std::mutex> lock(mtx);

