// Memory pool for dynamic allocation
struct MemPool {
    void *mem_start;
    size_t mem_size;
    size_t used;
};

Record *filter_metadata(struct Session *session, struct Metadata *input_data, size_t start, size_t end) {
    // Initialize memory pool and create new metadata list
    struct MemPool mem_pool = {.mem_start = malloc(session->max_records * sizeof(Record)), .mem_size = session->max_records * sizeof(Record), .used = 0};
    Record *output_data = (Record *)mem_pool.mem_start;

    // Use buffering mechanism for efficient batch processing
    size_t buffer_size = 1024;
    size_t buffer_idx = 0;
    size_t record_idx = 0;

    // Iterate through input data, filtering based on the specified range and session constraints
    for (size_t i = start; i < end; ++i) {
        if (input_data[i].timestamp > session->latency_cutoff || input_data[i].payload_size > session->bandwidth_limit) continue;

        // Allocate packet ID and payload description using memory pool
        struct PacketID *pid = (struct PacketID *)((char *)mem_pool.mem_start + mem_pool.used);
        pid->id = generate_random_packet_id(1, session->max_packet_ids);
        mem_pool.used += sizeof(struct PacketID);

        char *payload = (char *)((char *)pid + 1);
        size_t payload_size = input_data[i].payload_size;
        if (mem_pool.used + payload_size > mem_pool.mem_size) {
            // Reallocate memory pool if necessary
            void *new_mem = realloc(mem_pool.mem_start, session->max_records * 2 * sizeof(Record));
            if (!new_mem) {
                custom_log("Error: Failed to reallocate memory");
                break;
            }
            mem_pool.mem_start = new_mem;
            mem_pool.mem_size *= 2;
        }
        memcpy(payload, input_data[i].payload, payload_size);
        mem_pool.used += payload_size;

        // Save the filtered record to output data
        Record *record = output_data + record_idx++;
        record->ts = input_data[i].timestamp;
        record->pid = *pid;
        record->payload = payload;

        // Buffering mechanism: accumulate records and process when buffer is full or at the end of input data
        if (++buffer_idx >= buffer_size || i == end - 1) {
            process_buffered_data(session, output_data, buffer_idx);
            buffer_idx = 0;
        }
    }

    // Process any remaining records in the buffer
    if (buffer_idx > 0) process_buffered_data(session, output_data, buffer_idx);

    return output_data;
}

void deallocate_resources(struct MemPool *mem_pool) {
    // Deallocate memory pool and other resources gracefully
    if (mem_pool->mem_start) free(mem_pool->mem_start);
}
