void allocateDevices(int num_devices) {
    for (int i = 0; i < num_devices; ++i) {
        DeviceContext* device = static_cast<DeviceContext*>(malloc(sizeof(DeviceContext)));
        if (!device) {
            std::cerr << "Failed to allocate memory for device" << std::endl;
            return;
        }
        memset(device, 0, sizeof(DeviceContext));
        devices_mutex.lock();
        devices.push_back(device);
        devices_mutex.unlock();
    }
}

DeviceContext* getDeviceContextByID(char deviceID[32]) {
    DeviceContext* device = nullptr;
    devices_mutex.lock();
    for (auto d : devices) {
        if (strcmp(d->deviceID, deviceID) == 0) {
            device = d;
            break;
        }
    }
    devices_mutex.unlock();
    return device;
}

