```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class MD5Service {
    private static ConcurrentHashMap<String, BigInteger> cache;

    public static List<String> getMD5Hashes(List<String> inputs) throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");
        List<BigInteger> hashes = new ArrayList<>();
        for (String input : inputs) {
            if (cache.containsKey(input)) {
                hashes.add(cache.get(input));
                continue;
            }
            messageDigest.reset();
            messageDigest.update(input.getBytes());
            BigInteger hash = new BigInteger(1, messageDigest.digest());
            cache.putIfAbsent(input, hash);
            hashes.add(hash);
        }
        return hashes.stream().map(b -> b.toString(16)).collect(Collectors.toList());
    }
}
```

