Configuration config;

// Helper function to find the index of a key in the configuration
size_t find_key(int key) {
    for (size_t i = 0; i < config.count; ++i) {
        if (config.keys[i] == key) return i;
    }
    return (size_t)-1;
}

// Helper function to generate a unique random integer within a specified range
int rand_in_range(int min, int max) {
    static const unsigned long long SEED = 1234567890;
    static unsigned long long s = SEED;
    static unsigned long long b = (unsigned long long)(SEED << 32 | 1);
    s = (s * b) % INT_MAX;
    return min + (int)(s / ((double)(max - min + 1)));
}

// Helper function to find and print the largest integer in the array
void print_largest(Configuration *config, int start, int end) {
    int max_index = -1;
    int max = INT_MIN;
    for (int i = start; i < end; ++i) {
        if (config->keys[i] >= start && config->keys[i] < end && config->values[i] > max) {
            max_index = i;
            max = config->values[i];
        }
    }
    if (max_index != -1) printf("Largest integer: %d\n", max);
}

// Function to configure network device
void configureNetworkDevice(Record *device, Configuration *config, int start, int end, void (*callback)(Record*)) {
    pthread_mutex_lock(&config->lock);
    int key;
    do {
        key = rand_in_range(start, end);
    } while (find_key(key) != (size_t)-1);

    config->keys[config->count] = key;
    config->offsets[config->count] = 0;
    if (asprintf(&(config->identifiers[config->count]), "device_%d", key) < 0) {
        // Handle memory allocation failure gracefully
    }

    device->value = rand_in_range(1, 255);
    device->offset = config->offsets[config->count];
    strcpy(device->identifier, config->identifiers[config->count]);

    if (callback) callback(device);
    config->offsets[config->count] += sizeof(Record);
    config->count++;

    // Reallocate arrays when necessary
    if (config->count >= config->capacity) {
        size_t new_capacity = config->capacity ? (config->capacity * 2) : 16;
        Record *temp_keys = realloc(config->keys, new_capacity * sizeof(int));
        long *temp_offsets = realloc(config->offsets, new_capacity * sizeof(long));
        char **temp_identifiers = realloc(config->identifiers, new_capacity * sizeof(char*));
        if (!temp_keys || !temp_offsets || !temp_identifiers) {
            // Handle memory allocation failure gracefully
        } else {
            config->keys = temp_keys;
            config->offsets = temp_offsets;
            config->identifiers = temp_identifiers;
            config->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&config->lock);
}

// Function to free all resources and clean up the configuration
void cleanup(Configuration *config) {
    for (size_t i = 0; i < config->count; ++i) {
        if (config->identifiers[i]) free(config->identifiers[i]);
    }
    free(config->keys);
    free(config->offsets);
    free(config->identifiers);
}
