#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <time.h>

struct UserProfile {
    int id;
    char name[256];
    char *picture_url;
    struct UserProfile *next;
};

typedef struct UserProfile UserProfile;

sem_t list_mutex; // Mutex for the user profile list
sem_t mem_mutex; // Mutex for memory allocation operations
sem_t log_mutex; // Mutex for logging failed allocations

long long failed_allocations = 0;

void *malloc_wrapper(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && posix_memalign(&ptr, 16, size)) {
        ++failed_allocations;
    }
    return ptr;
}

UserProfile* create_user_profile(int id, const char *name, const char *picture_url) {
    UserProfile *new_profile = (UserProfile*) malloc_wrapper(sizeof(UserProfile));
    if (!new_profile) return NULL;

    new_profile->id = id;
    strncpy(new_profile->name, name, sizeof(new_profile->name) - 1);
    new_profile->picture_url = picture_url ? malloc_wrapper(strlen(picture_url) + 1) : NULL;
    if (!new_profile->picture_url) {
        free(new_profile);
        return NULL;
    }
    strncpy(new_profile->picture_url, picture_url, strlen(picture_url) + 1);
    new_profile->next = NULL;

    return new_profile;
}

void log_failed_allocations() {
    sem_wait(&log_mutex);
        printf("Failed allocations: %lld\n", failed_allocations);
    sem_post(&log_mutex);
}

int add_user_profile(UserProfile **head, UserProfile *new_profile) {
    if (!head || !new_profile) return -1; // Invalid input check

    sem_wait(&mem_mutex);
        new_profile->next = *head;
        *head = new_profile;
    sem_post(&mem_mutex);

    UserProfile *current = *head;
    UserProfile *prev = NULL;

    while (current != NULL) {
        if (current->id < new_profile->id) {
            prev = current;
            current = current->next;
        } else if (current->id == new_profile->id) {
            // Handle duplicate user IDs as needed (e.g., error, update, or ignore)
            return -1;
        } else {
            break;
        }
    }

    if (!prev) {
        sem_wait(&list_mutex);
            new_profile->next = *head;
            *head = new_profile;
        sem_post(&list_mutex);
    } else {
        sem_wait(&list_mutex);
            new_profile->next = current;
            prev->next = new_profile;
        sem_post(&list_mutex);
    }

    return 0;
}
```

