    // Allocate memory for offset and key arrays, and initialize with sequential integers
    int* offsets = malloc(N * sizeof(int));
    int* keys = malloc(N * sizeof(int));
    for (int i = 0; i < N; ++i) {
        offsets[i] = 0;
        keys[i] = i;
    }

    // Allocate memory for NIC records and set each int field to a random value
    nic_record* nics = malloc(N * sizeof(nic_record));
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        nics[i].int_field = rand() % (maxValue - minValue + 1) + minValue;
        // Populate the rest of the record with dummy data
        memset(nics[i].mac, '\0', sizeof(nics[i].mac));
        memset(nics[i].ip, '\0', sizeof(nics[i].ip));
    }

    // Clean up on exit
    free(offsets);
    free(keys);
    free(nics);
}

int find_largest_integer(int array[], int size) {
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}
