class Aggregator {
  constructor(config) {
    this.config = config;
    this.cache = new LRUCache(config.cacheSize);
    this.batchSize = config.batchSize || 10000;
    this.concurrencyLimit = config.concurrencyLimit || 10;
    this.globalStop = false;
    this.healthCheckInterval = setInterval(() => this.healthCheck(), 1000);
  }

  async run(logStream) {
    if (this.globalStop) return;

    let aggregatedData = [];
    let currentBatch = [];

    logStream.on('data', chunk => {
      if (this.globalStop) return;

      for (let entry of chunk) {
        if (!this.cache.has(entry.id)) {
          currentBatch.push(entry);

          if (currentBatch.length >= this.batchSize || this.concurrencyLimit <= this.activeTasks.length) {
            await this.processBatch(currentBatch);
          }
        } else {
          aggregatedData.push(this.cache.get(entry.id));
        }
      }
    });

    logStream.on('end', async () => {
      if (this.globalStop) return;

      await this.processBatch(currentBatch);

      // Combine the results from the cache and processed batches
      const finalResult = [...aggregatedData, ...batchResults];
      this.saveFinalResult(finalResult);
    });
  }

  async processBatch(batch) {
    const startTime = Date.now();

    const batchResults = await Promise.all(
      batch.map(async entry => {
        try {
          const result = await this.aggregationStrategy(entry);
          return result;
        } catch (error) {
          console.error(`Error processing log entry ${entry.id}:`, error);
          return null;
        }
      })
    );

    const elapsedTime = Date.now() - startTime;
    if (elapsedTime > this.config.timeout) {
      console.warn(`Batch processing timeout: ${elapsedTime}ms`);
      // Mark the batch as failed and handle retries or backpressure as needed
    }

    return batchResults;
  }

  healthCheck() {
    console.log(
      `Aggregator Health Check:\n\tActive Tasks: ${this.activeTasks.length}\n\tCache Size: ${this.cache.size}`
    );
  }
}
