#define DATA_POINT_SIZE 4
typedef struct {
    long long offset;
    int key;
    double dval;
    int int_value;
} data_point;

struct mem_pool {
    void* memory;
    size_t capacity;
    size_t used;
};

void init_mem_pool(struct mem_pool* pool, size_t size) {
    pool->memory = malloc(size);
    if (pool->memory == NULL) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = size;
    pool->used = 0;
}

void* mem_pool_alloc(struct mem_pool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        fprintf(stderr, "Memory pool overflow\n");
        exit(EXIT_FAILURE);
    }
    void* result = pool->memory + pool->used;
    pool->used += size;
    return result;
}

void mem_pool_free(struct mem_pool* pool, void* ptr) {
    if (ptr >= pool->memory && ptr < pool->memory + pool->capacity) {
        pool->used -= (char*)ptr - (char*)pool->memory;
    } else {
        fprintf(stderr, "Invalid memory address in the memory pool\n");
        exit(EXIT_FAILURE);
    }
}

void log_allocation(const char* operation, size_t count, size_t elem_size) {
    // Implement logging with a pre-existing logging framework.
}

