    long* offsets = mem_pool_alloc(&g_offset_pool, N * sizeof(long));
    int* keys = mem_pool_alloc(&g_key_pool, N * sizeof(int));
    double* floats = mem_pool_alloc(&g_float_pool, N * sizeof(double));
    int* indices = mem_pool_alloc(&g_index_pool, N * sizeof(int));
    int* key_indices = mem_pool_alloc(&g_key_pool, N * sizeof(int));
    double* values = mem_pool_alloc(&g_value_pool, N * sizeof(double));

    struct mem_pool data_point_pool;
    init_mem_pool(&data_point_pool, N * DATA_POINT_SIZE);

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < N; ++i) {
        indices[i] = i;
        key_indices[i] = i;
        floats[i] = i + 0.0;
    }

    pthread_mutex_unlock(&lock);

    for (size_t i = 0; i < N; ++i) {
        data_point* dp = static_cast<data_point*>(mem_pool_alloc(&data_point_pool, DATA_POINT_SIZE * sizeof(data_point)));
        dp[0].offset = (rand() % (maxLong - minLong + 1)) + minLong;
        dp[0].key = key_indices[i];
        dp[0].dval = (rand() % (maxDouble - minDouble + 1)) / RAND_MAX * (maxDouble - minDouble) + minDouble;
        dp[0].int_value = i;
        for (size_t j = 1; j < DATA_POINT_SIZE; ++j) {
            dp[j].int_value = (rand() % N + i) % N;
        }
        key_indices[(dp->key)]++;
    }

    // Log the allocation details.
    log_allocation("Data points", N, DATA_POINT_SIZE);

    *data = dp;

    mem_pool_free(&g_offset_pool, offsets);
    mem_pool_free(&g_key_pool, keys);
    mem_pool_free(&g_float_pool, floats);
    mem_pool_free(&g_index_pool, indices);
    mem_pool_free(&g_key_pool, key_indices);
    mem_pool_free(&g_value_pool, values);
    mem_pool_free(&data_point_pool, dp);
}

struct mem_pool g_offset_pool, g_key_pool, g_float_pool, g_index_pool, g_value_pool;
