struct dataset {
    struct data_item **items;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void destroy_dataset(struct dataset *ds) {
    if (!ds || !ds->items) return;

    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->items[i]->name);
        free(ds->items[i]);
    }
    free(ds->items);
    pthread_mutex_destroy(&ds->mutex);
}

struct dataset *create_dataset(size_t initial_capacity) {
    struct dataset *ds = malloc(sizeof(*ds));
    if (!ds) return NULL;

    ds->items = calloc(initial_capacity, sizeof(void*));
    if (!ds->items) goto error;

    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->mutex, NULL);

    log_mem("allocated", ds, sizeof(*ds));
    return ds;

error:
    destroy_dataset(ds);
    return NULL;
}

void add_to_dataset(struct dataset *ds, const char *identifier, double value) {
    if (!ds || !identifier || !value) return;

    pthread_mutex_lock(&ds->mutex);

    if (ds->size == ds->capacity) {
        ds->capacity *= 2;
        ds->items = realloc(ds->items, sizeof(void*) * ds->capacity);
        if (!ds->items) goto error;
    }

    struct data_item *new_item = malloc(sizeof(*new_item));
    if (!new_item) goto error;

    new_item->id = ds->size++;
    new_item->name = strdup(identifier);
    if (!new_item->name) goto error;
    new_item->value = value;

    log_mem("allocated", new_item, sizeof(*new_item));
    ds->items[ds->size - 1] = new_item;

error:
    pthread_mutex_unlock(&ds->mutex);
}

