typedef struct Element {
    int value;
    struct Element *prev, *next;
} Element;

typedef struct Node {
    int *value;
    struct Element *element;
    struct Node *next;
} Node;

void init_memory(Node**, Element**, int num_elements, int min_val, int max_val) {
    *Node = (Node*)malloc(num_elements * sizeof(Node));
    *Element = (Element*)malloc((num_elements + 1) * sizeof(Element));

    if (!*Node || !*Element) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < num_elements; ++i) {
        (*Node)[i].value = malloc(sizeof(int));
        if (!(*Node)[i].value) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        (*Node)[i].value[0] = rand() % (max_val - min_val + 1) + min_val;

        (*Element)[i].value = rand() % (max_val - min_val + 1) + min_val;
        (*Element)[i].prev = i > 0 ? &(*Element)[i - 1] : NULL;
        (*Element)[i].next = (i < num_elements - 1) ? &(*Element)[i + 1] : NULL;

        (*Node)[i].element = &(*Element)[i];
    }

    // Set the first and last elements' pointers
    (*Element)[0].prev = NULL;
    (*Element)[num_elements - 1].next = NULL;
}
```

