void *pool_alloc(struct metadata *meta, size_t size) {
    if (size <= 0 || !meta->memory_region) return NULL;

    char *mem = meta->memory_region + meta->size;
    meta->size += size;

    // Use POSIX memory protection to keep data contiguous and maximize cache utilization
    mprotect(mem, size, PROT_READ | PROT_WRITE);
    return mem;
}

// Pool deallocation function that returns memory back to the pool
void pool_free(struct metadata *meta, void *ptr) {
    if (!meta->memory_region || !ptr) return;

    meta->size -= (ptr - meta->memory_region);
    memset((char *)ptr + sizeof(data_item), 0, (ptr - (char *)meta->memory_region));
}

