void process_csv(LockFreeQueue<std::string>& queue, MemoryPool<data_item>& pool, DatabaseInterface& db) {
    while (true) {
        std::string line = queue.pop(); // pop a CSV line from the lock-free queue
        if (line.empty()) break; // exit if the queue is empty

        std::istringstream iss(line);
        data_item item = parse_csv_line(iss); // parse the CSV line into a data_item record

        // allocate memory for the item and insert it into the database using the memory pool and database interface
        data_item* pItem = pool.alloc();
        *pItem = item;
        db.insert(pItem);
    }
}

int main(int argc, char** argv) {
