int allocate_and_initialize(Node** nodes, Element*** elements, char** chars, int M) {
    *nodes = (Node*)malloc(M * sizeof(Node));
    if (!*nodes) return -1;

    *elements = (Element**)calloc(M, sizeof(Element*));
    if (!*elements) {
        free(*nodes);
        return -1;
    }

    *chars = (char*)malloc(M * sizeof(char));
