    node->next = NULL;
    return node;
}

int insert_element(Node** head, Element* element) {
    Node* new_node = create_node(element);
    if (!new_node) log_error("Failed to allocate memory for new node");

    if (*head == NULL) {
        *head = new_node;
        return 0;
    }

    Node* last_node = *head;
    while (last_node->next) last_node = last_node->next;

    last_node->next = new_node;
    return 0;
}

int insert_elements(Node** head, Element** elements, int M) {
    for (int i = 0; i < M; ++i) {
