void allocate_memory(int N, int minValue, int maxValue, void **offsets, void **keys, void **records) {
    *offsets = mmap(NULL, N * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*offsets == MAP_FAILED) {
        perror("mmap offsets failure");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(N * sizeof(int));
    if (!*keys) {
        perror("malloc keys failure");
        munmap(*offsets, N * sizeof(long));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N; ++i) {
        (*keys)[i] = i;
    }

    *records = calloc(N, sizeof(Record));
    if (!*records) {
        perror("calloc records failure");
        free(*keys);
        munmap(*offsets, N * sizeof(long));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N; ++i) {
        int randomValue = minValue + rand() % (maxValue - minValue + 1);
        (*records)[i].key = i;
        (*records)[i].value = randomValue;
