typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint32_t image_width;
    uint32_t image_height;
    uint32_t image_dim[4]; // optional dimensions for multi-dimensional images
    uint32_t compression_type;
    char *image_data; // allocated dynamically as needed
} tiff_metadata;

typedef struct {
    sem_t sem_mutex;
    bool is_initialized;
    tiff_metadata metadata;
    int fd;
    size_t current_page;
    size_t num_pages;
} tiff_image;

void* fetch_and_cache(const char *url, tiff_image *image) {
    // Implement asynchronous download and caching strategies here
}

int process_tiff_page(TIFF *tif, tiff_image *image) {
    // Process page data and fill image metadata
}

void acquire_mutex(tiff_image *image) {
    sem_wait(&image->sem_mutex);
}

void release_mutex(tiff_image *image) {
    sem_post(&image->sem_mutex);
}

int extract_tiff_metadata(const char *url, tiff_metadata *metadata) {
    int error = TIFFERROR;
    tiff_image image = {};
    image.fd = open(url, O_RDONLY);

    if (image.fd == -1) {
        return TIFF_NOTFOUND;
    }

    if (fstat(image.fd, &image.stbuf) < 0) {
        close(image.fd);
        return TIFF_ERROR;
    }

    if ((TIFFSetFile(image.fd) == NULL) || (TIFFGetFieldDefaulted(TIFFFileno(image.fd), TIFFTAG_IMAGEWIDTH) == 0)) {
        close(image.fd);
        return TIFF_ERROR;
    }

    image.num_pages = TIFFNumberOfPages(TIFFFileno(image.fd));
    pthread_mutex_init(&image.sem_mutex, NULL);
    image.is_initialized = false;

    if (image.num_pages > 0) {
        // Fetch and cache the first page asynchronously
        fetch_and_cache(url, &image);

        acquire_mutex(&image);
        image.current_page = 0;

        for (size_t i = 0; i < image.num_pages; ++i) {
            TIFFSetPage(TIFFFileno(image.fd), i + 1);
            process_tiff_page(TIFFGetTidTag(TIFFFileno(image.fd)), &image);
        }

        release_mutex(&image);
    } else {
        error = TIFF_EMPTY;
    }

    close(image.fd);

    if (!error) {
        *metadata = image.metadata;
    }

    return error;
}
