typedef struct node {
    int key;
    void *value;
    struct node *next;
} Node;

Node* create_node(int key, void *value) {
   Node *new_node = (Node*) malloc(sizeof(Node));
   new_node->key = key;
   new_node->value = value;
   new_node->next = NULL;
   return new_node;
}

void insert(Node **head, int key, void *value) {
    if (!*head) {
        *head = create_node(key, value);
        return;
    }

    Node *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = create_node(key, value);
}

void* find(Node *head, int key) {
   Node *current = head;
   while (current != NULL) {
       if (current->key == key) {
           return current->value;
       }
       current = current->next;
   }
   return NULL; // Key not found in the set.
}
