unsigned long align(unsigned long size, unsigned long alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

Record* allocate_records(size_t len) {
    size_t aligned_len = align(len * sizeof(Record), sizeof(Record));
    Record *records = malloc(aligned_len);
    if (!records) return NULL;
    memset(records, 0, aligned_len);
    return records;
}

void free_records(Record* records, size_t len) {
