    long *offsets = allocate_longs(max_records, 8);
    if (!offsets) return EXIT_FAILURE;

    size_t ints_len = 512; // A power of 2 that does not exceed 1000
    int *ints = allocate_ints(ints_len, align(sizeof(int), sizeof(long)));
    if (!ints) {
        free_longs(offsets, max_records);
        return EXIT_FAILURE;
    }

