import java.io.File;
import java.util.concurrent.*;
import javax.management.*;
import org.apache.commons.lang3.exception.ExceptionUtils;
import com.google.common.util.concurrent.RateLimiter;

public class FileProcessor {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final RateLimiter rateLimiter = RateLimiter.create(0.75); // CPU usage limit
    private final int maxMemoryUsagePercentage = 85;
    private final RetryPolicy retryPolicy = new RetryPolicy();
    private static ObjectName objectName;

    public void initializeJMX() throws MalformedObjectNameException {
        objectName = new ObjectName("com.example:type=FileProcessor");
        MBeanServer mbeanServer = JMXUtil.getMBeanServer();
        AtomicInteger cpuUsage = new AtomicInteger(0);
        AtomicLong memoryUsage = new AtomicLong(0);
        mbeanServer.registerMBean(new FileProcessorStatistics(cpuUsage, memoryUsage), objectName);
    }

    public void processFiles(List<File> files) {
        for (File file : files) {
            Callable<Void> callable = () -> processFile(file);
            Future<?> future = executor.submit(callable);
            retryPolicy.registerFuture(future, callable);
        }
    }

    private void processFile(File file) {
        try {
            rateLimiter.acquire();
            // Process the file here
            // ...
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Failed to process file", e);
        } finally {
            rateLimiter.release();
        }
    }

    public static void main(String[] args) throws Exception {
        FileProcessor processor = new FileProcessor();
        processor.initializeJMX();
        // Process files here, e.g., by reading them from a directory
    }
}

class RetryPolicy {
    private final ConcurrentHashMap<Future<?>, Callable> futures = new ConcurrentHashMap<>();

    void registerFuture(Future<?> future, Callable callable) {
        futures.put(future, callable);
    }

    // Implement retry mechanism here with maximum of two retries per file
}
