#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <inttypes.h>

typedef struct {
    int value;
} record;

bool validate(uintmax_t maxOffsets, uintmax_t maxKeys, uintmax_t maxRecords) {
    return maxOffsets > 0 && maxKeys <= maxOffsets && maxRecords > 0;
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_free(void *ptr) {
    if (ptr) free(ptr);
}

uintmax_t find_next_power_of_two(uintmax_t n) {
    uintmax_t power = 1;
    while (power < n) power *= 2;
    return power;
}

void init_arrays(uintmax_t *offsets, size_t maxOffsets, int *keys, size_t maxKeys, record **records, size_t maxRecords, uintmax_t start, uintmax_t end) {
    if (!validate(maxOffsets, maxKeys, maxRecords)) {
        fprintf(stderr, "Error: Invalid arguments\n");
        exit(EXIT_FAILURE);
    }

    *offsets = (long*)safe_malloc((maxOffsets + 1) * sizeof(long));
    if (!*offsets) {
        fprintf(stderr, "Error: Out of memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < maxKeys; ++i) {
        (*keys)[i] = i;
    }

    size_t capacity = find_next_power_of_two(maxRecords);
    *records = (record*)safe_malloc(capacity * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Error: Out of memory for records\n");
        exit(EXIT_FAILURE);
    }

    capacity /= 2; // Half the array for easier reallocation when necessary
    size_t used = 0;

    while (used < maxRecords) {
        int key = (*keys)[rand() % maxKeys];
        bool found = false;

        for (size_t i = 0; i < used && !found; ++i) {
            if ((*records)[i].value == key) found = true;
        }

        if (!found) {
            (*records)[used].value = key;
            ++used;
        }
    }
}

void deinit_arrays(uintmax_t *offsets, int *keys, record **records, size_t maxRecords) {
    safe_free(*offsets);
    safe_free(*keys);
    safe_free(*records);
}
```

