#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <unistd.h>
#include <sys/syscall.h>

typedef struct record {
    int value;
    pthread_mutex_t mutex;
} Record;

struct hash_node {
    Record *record;
    struct hash_node *next;
};

unsigned long long get_hash(int key) {
    // Custom hash function based on the given requirements
    unsigned long long hash = 0;
    for (int i = 0; i < sizeof(key); ++i) {
        hash = (hash * 31 + key) % HASH_TABLE_SIZE;
    }
    return hash;
}

struct hash_table {
    struct hash_node **nodes;
    int size;
};

void init_hash_table(struct hash_table *ht, int size) {
    ht->size = size;
    ht->nodes = mmap(NULL, sizeof(struct hash_node *) * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
}

struct record* create_record() {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Error allocating memory for record");
        exit(-1);
    }
    pthread_mutex_init(&record->mutex, NULL);
    return record;
}

void insert(struct hash_table *ht, int key, Record *record) {
    unsigned long long hash = get_hash(key);
    struct hash_node **chain = ht->nodes + hash;

    pthread_mutex_lock(&record->mutex);
    while (*chain) {
        if ((*chain)->key == key) {
            record->value = (*chain)->value;
            free(*chain->record);
            free(*chain);
            break;
        }
        chain = &((*chain)->next);
    }
    if (!*chain) {
        *chain = malloc(sizeof(struct hash_node));
        if (!*chain) {
            perror("Error allocating memory for hash node");
            exit(-1);
        }
        (*chain)->record = record;
        (*chain)->next = NULL;
    }
    pthread_mutex_unlock(&record->mutex);
}

Record* lookup(struct hash_table *ht, int key) {
    unsigned long long hash = get_hash(key);
    struct hash_node **chain = ht->nodes + hash;
    Record *record = NULL;

    while (*chain) {
        if ((*chain)->key == key) {
            record = (*chain)->record;
            break;
        }
        chain = &((*chain)->next);
    }
    return record;
}

