```java
import java.util.*;

public class DisjointPairs {
    private int[] parent;
    private long[] rank;

    public int disjointPairs(int[] arr) {
        int n = arr.length;
        parent = new int[n];
        rank = new long[n];

        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            rank[i] = 1;
        }

        long startTime = System.currentTimeMillis();
        int pairs = 0;
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (!unionFind(i, j)) {
                    ++pairs;
                }
            }
        }
        long elapsedTime = System.currentTimeMillis() - startTime;

        System.out.printf("Number of disjoint pairs: %d\n", pairs);
        System.out.printf("Elapsed time for check (ms): %d\n", elapsedTime);

        return 0;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private boolean unionFind(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP == rootQ) {
            return false;
        }

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
            rank[rootP] += rank[rootQ];
        } else {
            parent[rootP] = rootQ;
            rank[rootQ] += rank[rootP];
        }
        return true;
    }
}
