class MemoryManager {
public:
    MemoryManager(int maxOffsets, int maxKeys, int maxRecords) : maxOffsets_(maxOffsets), maxKeys_(std::min(maxOffsets_, maxKeys)), maxRecords_(maxRecords_) {
        offsets_ = std::make_unique<long[]>(maxOffsets_);
        keys_ = std::make_unique<int[]>(maxKeys_);
        records_ = std::make_unique<record[]>(maxRecords_);

        for (int i = 0; i < maxKeys_; ++i)
            keys_[i] = i;
    }

    long& getOffset(int index) {
        if (index >= maxOffsets_)
            throw std::out_of_range("Index out of range");
        return offsets_[index];
    }

    int getKey(int index) {
        if (index >= maxKeys_)
            throw std::out_of_range("Index out of range");
        return keys_[index];
    }

    record& getRecord(int index) {
        if (index >= maxRecords_)
            throw std::out_of_range("Index out of range");
        return records_[index];
    }

private:
    int maxOffsets_;
    int maxKeys_;
    int maxRecords_;
    std::unique_ptr<long[]> offsets_;
    std::unique_ptr<int[]> keys_;
    std::unique_ptr<record[]> records_;
