#include <fcntl.h>

#define MAX_VALUE 1000
#define MAX_SIZE N
#define KEY_ARRAY_SIZE MAX_SIZE
#define OFFSET_ARRAY_SIZE MAX_SIZE
#define FILENAME_LENGTH 256
#define LOG_BUFFER_SIZE 1024

struct record {
    int key;
    long offset;
    char filename[FILENAME_LENGTH];
};

struct logger {
    char buffer[LOG_BUFFER_SIZE];
    size_t position;
    pthread_mutex_t lock;
};

void init_logger(struct logger *logger) {
    pthread_mutex_init(&logger->lock, NULL);
    logger->position = 0;
}

void log(struct logger *logger, const char *message) {
    pthread_mutex_lock(&logger->lock);
    strncat(logger->buffer, message, LOG_BUFFER_SIZE - logger->position);
    logger->position += strlen(message);
    if (logger->position > LOG_BUFFER_SIZE / 2) {
        write(STDOUT_FILENO, logger->buffer, logger->position);
        logger->position = 0;
    }
    pthread_mutex_unlock(&logger->lock);
}

void* allocate_memory_mapped_file(size_t size) {
    int fd = open("/tmp/record_collection", O_RDWR | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1 && errno != EEXIST) {
        perror("allocate_memory_mapped_file: open");
        exit(EXIT_FAILURE);
    }
    off_t offset = lseek(fd, 0, SEEK_CUR);
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_FIXED | MAP_ANONYMOUS, fd, offset);
    if (ptr == MAP_FAILED) {
        perror("allocate_memory_mapped_file: mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

struct record* initialize_collection(size_t size, struct logger *logger) {
    sem_t resize_sem;
