// Custom Memory Pool Allocator
class MemoryPoolAllocator {
public:
    void* allocate(size_t size) {
        if (freeList.empty() && newList.size() + size > maxSize) {
            throw std::bad_alloc();
        }

        if (!freeList.empty()) {
            void* ptr = freeList.front();
            freeList.pop_front();
            return ptr;
        }

        void* ptr = operator new(size);
        newList.push_back(ptr);
        return ptr;
    }

    void deallocate(void* pointer, size_t) {
        if (newList.contains(pointer)) {
            freeList.push_back(pointer);
            newList.erase(std::remove(newList.begin(), newList.end(), pointer), newList.end());
        }
    }

private:
    std::list<void*> freeList;
    std::list<void*> newList;
    size_t maxSize;
};

// Record Structure
struct Record {
    int value;
    explicit Record(int v) : value(v) {}
};

// Helper Function to find the maximum value in an array
int findMax(const std::vector<Record>& records) {
    int max = INT_MIN;
    for (auto& record : records) {
        if (record.value > max) {
            max = record.value;
        }
    }
    return max;
}

// Function to allocate and initialize the required arrays
void allocArrays(int N, int minValue, int maxValue, MemoryPoolAllocator& allocator, std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    auto start = std::chrono::high_resolution_clock::now();

    keys.resize(N);
    for (int i = 0; i < N; ++i) {
        keys[i] = i;
    }

    records.resize(N);
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    std::mutex mtx;
    for (auto& record : records) {
        int value = dis(gen);
        bool unique = true;
        {
            std::lock_guard<std::mutex> lock(mtx);
            for (const auto& existingRecord : records) {
                if (existingRecord.value == value && &existingRecord != &record) {
                    unique = false;
                    break;
                }
            }
        }
        if (unique) {
            record.value = value;
        } else {
            while (!unique) {
                value = dis(gen);
                unique = true;
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    for (const auto& existingRecord : records) {
                        if (existingRecord.value == value && &existingRecord != &record) {
                            unique = false;
                            break;
                        }
                    }
                }
            }
            record.value = value;
        }
    }

    offsets.resize(N);

    std::ofstream logFile("allocation_log.txt", std::ios::app);
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count();
    logFile << "Time: " << elapsed << "ms\n";
    logFile << "N: " << N << "\n";
    logFile << "minValue: " << minValue << "\n";
    logFile << "maxValue: " << maxValue << "\n";
    logFile << "\nKeys:\n";
    for (auto key : keys) {
        logFile << key << " ";
    }
    logFile << "\n\nRecords:\n";
    for (const auto& record : records) {
        logFile << record.value << " ";
    }
    logFile << "\n\nOffsets:\n";
    for (auto offset : offsets) {
        logFile << offset << " ";
    }
    logFile << "\n-------------------------\n";
}

