    int N, minValue, maxValue;
    std::cin >> N >> minValue >> maxValue;

    if (N <= 0 || minValue >= maxValue) {
        std::cerr << "Invalid input. Please enter a valid range for N and a valid range with minValue less than maxValue." << std::endl;
