['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* identifier;
    size_t length;
} data_entry;

// Global variables for performance optimization and ease of management
static data_entry** entries = NULL;
static size_t capacity = 0;
static size_t count = 0;

void resize() {
    if (capacity == count) {
        capacity *= 2;
        entries = realloc(entries, sizeof(data_entry*) * capacity);
    }
}

size_t find_index(const char* identifier) {
    for (size_t i = 0; i < count; ++i) {
        if (!strcmp(entries[i]->identifier, identifier)) return i;
    }
    return SIZE_MAX; // Indicates not found
}

void add_entry(const char* identifier, double value, size_t length) {
    if (count == capacity) resize();

    data_entry* new_entry = malloc(sizeof(data_entry));
    if (!new_entry) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    new_entry->value = value;
    new_entry->identifier = strdup(identifier);
    new_entry->length = length;

    size_t index = find_index(identifier);
    if (index != SIZE_MAX) {
        // Entry already exists, replace it with the new one
        free(entries[index]->identifier);
        entries[index] = new_entry;
    } else {
        // Insert at the end of the array
        entries[count++] = new_entry;
    }
}

void remove_entry(const char* identifier) {
    size_t index = find_index(identifier);
    if (index == SIZE_MAX) return;

    free(entries[index]->identifier);
    memmove(&entries[index], &entries[index + 1], (count - index - 1) * sizeof(data_entry*));
    --count;
    free(entries[count]);
}

void iterate_entries(void(*func)(const data_entry*)) {
    for (size_t i = 0; i < count; ++i) {
        if (func) func(entries[i]);
    }
}
