// Function to generate unique identifiers using a hash-based lookup mechanism and linear probing
char* generate_identifier(int key) {
    static const int HASH_TABLE_SIZE = 1024;
    static char hash_table[HASH_TABLE_SIZE][32]; // each slot is 32 bytes, can be adjusted for desired string length
    int index = key % HASH_TABLE_SIZE;

    while (strcmp(hash_table[index], "")) { // check if the slot is empty
        index = (index + 1) % HASH_TABLE_SIZE;

        if (index == key % HASH_TABLE_SIZE) { // linear probing
            index += 2;
        }
    }

    sprintf(hash_table[index], "%d", key); // write the integer key as a string in the slot

    return hash_table[index];
}

