    // Generate descriptive strings for labels (up to 256 characters) and store them in the labelCache map
    auto generateLabel = [&]() {
        std::stringstream ss;
        ss << "Descriptive string " << keys[rand() % N];
        return ss.str();
    };
    for (size_t i = 0; i < N; ++i) {
        auto label = generateLabel();
        if (labelCache.find(label.length()) == labelCache.end() || labelCache[label.length()].empty()) {
            labels[keys[i]] = std::move(label);
            log(config.log_level, "Allocated label array space for key: " + std::to_string(keys[i]) + ", label: " + label);
        } else {
            labels[keys[i]] = std::move(labelCache[label.length()].front());
            log(config.log_level, "Reused label array space for key: " + std::to_string(keys[i]) + ", label: " + labels[keys[i]]);
            labelCache[label.length()].pop_back();
        }
    }

    callback(N); // Call the provided callback function with the number of elements N
}
