// Record structure and serialization
namespace boost {
    namespace serialization {
        template<class Archive>
        void serialize(Archive & ar, Record, const unsigned int) {
            ar & boost::serialization::make_nvp("value", record.value);
        }
    }
}

struct Record {
    int value;
};
BOOST_CLASS_EXPORT_IMPLEMENT(Record)

// Function to perform the given tasks
void init_data(int N, int minValue, int maxValue, int M, Logger& logger) {
    std::vector<long> offsets(N); // Offset array
    std::iota(offsets.begin(), offsets.end(), 0);

    std::vector<int> keys(N); // Key array
    std::copy(offsets.cbegin(), offsets.cend(), keys.begin());

    std::vector<std::unique_ptr<Record>> records(N); // Record array

    std::mt19937 gen(std::random_device{}()); // Random number generator
    std::uniform_int_distribution<> distr_value(minValue, maxValue);
    std::uniform_int_distribution<> distr_offset(0, N - 1);
    std::mutex mtx;

    for (size_t i = 0; i < records.size(); ++i) {
        int value = distr_value(gen);
        int uniqueCounter = 0;
        while (uniqueCounter < M) {
            // Ensure uniqueness of values within the array
            if (std::find(records.begin(), records.end(), value.get()) == records.end()) {
                break;
            }
            ++uniqueCounter;
            std::unique_lock<std::mutex> lock(mtx);
            std::this_thread::sleep_for(std::chrono::milliseconds(1)); // Yield CPU for concurrency
            lock.unlock();
        }

        records[i] = std::make_unique<Record>();
        records[i]->value = value;

        // Generate offsets for duplicate records
        if (M > 1) {
            auto offset = distr_offset(gen);
            records[i]->get()->offset = offset;
        }

        logger.log("Successfully allocated and initialized data structure");
    }

    // Validate system resources before serializing and exiting
    if (validate_system_resources()) {
        std::ofstream file("data.bin", std::ios::binary | std::ios::out);
        if (file.is_open()) {
            boost::archive::binary_oarchive oa(file);
            oa & BOOST_SERIALIZATION_NVP(offsets);
            oa & BOOST_SERIALIZATION_NVP(keys);
            oa & BOOST_SERIALIZATION_NVP(records);
        } else {
            logger.log("Failed to open output file for serialization");
        }
    } else {
        logger.log("Insufficient system resources, skipping serialization and cleaning up data structures");
    }
}
