[' Here is the C code that fulfills the given programming task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct record {
    int value;
} record;

struct memory_manager {
    long* offsets;
    int* keys;
    record* records;
    size_t N;
    int minValue, maxValue;
    pthread_mutex_t mutex;
    unsigned long allocation_count;
    unsigned long deallocation_count;
};

void init_memory_manager(struct memory_manager* mm, size_t N, int minValue, int maxValue) {
    mm->N = N;
    mm->minValue = minValue;
    mm->maxValue = maxValue;
    mm->allocation_count = 0;
    mm->deallocation_count = 0;
    mm->offsets = malloc(sizeof(long) * N);
    mm->keys = malloc(sizeof(int) * N);
    for (size_t i = 0; i < N; ++i) {
        mm->keys[i] = i;
        mm->offsets[i] = -1; // -1 indicates an unused slot
    }
    mm->records = malloc(sizeof(record) * N);
    for (size_t i = 0; i < N; ++i) {
        mm->records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
    pthread_mutex_init(&mm->mutex, NULL);
}

bool allocate(struct memory_manager* mm, void** data_ptr) {
    bool success = false;
    pthread_mutex_lock(&mm->mutex);
    size_t i;
    for (i = 0; i < mm->N; ++i) {
        if (mm->offsets[mm->keys[i]] == -1) {
            success = true;
            *data_ptr = &mm->records[mm->keys[i]];
            mm->offsets[mm->keys[i]] = i;
            break;
        }
    }
    if (success) {
        ++(mm->allocation_count);
        printf("Successful memory allocation.\n");
    }
    pthread_mutex_unlock(&mm->mutex);
    return success;
}

void deallocate(struct memory_manager* mm, void* data_ptr) {
    if (data_ptr != NULL) {
        pthread_mutex_lock(&mm->mutex);
        size_t i = mm->offsets[((record*) data_ptr - mm->records)];
        mm->offsets[i] = -1;
        ++(mm->deallocation_count);
        printf("Successful memory deallocation.\n");
        pthread_mutex_unlock(&mm->mutex);
    }
}

void clean_memory_manager(struct memory_manager* mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    pthread_mutex_destroy(&mm->mutex);
}
```

This code defines a `memory_manager` structure with fields for the offset array, key array, record array, size, minimum value, maximum value, mutex, and counters for allocations and deallocations. The `init_memory_manager`, `allocate`, `deallocate`, and `clean_memory_manager` functions are provided to initialize, allocate, deallocate, and clean up the memory manager, respectively.

