    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays and structures
    *double_array = (double*)malloc(num_elements * sizeof(double));
    if (*double_array == NULL) {
        log_error("Failed to allocate double array memory.");
        return;
    }

    *identifier_array = (unsigned short*)calloc(num_elements, sizeof(unsigned short));
    if (*identifier_array == NULL) {
        free(*double_array);
        log_error("Failed to allocate identifier array memory.");
        return;
    }

    *data_units = (data_unit*)calloc(num_elements, sizeof(data_unit));
    if (*data_units == NULL) {
        free(*double_array);
        free(*identifier_array);
        log_error("Failed to allocate data units array memory.");
        return;
