    // Call API for populating arrays
    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&mutex);
        if (!api_callback(i, &(*double_array)[i], identifier_array + i, data_units + i)) {
            log_error("Failed to get valid data from API.");
            break;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Perform validation and handle invalid data
    for (size_t i = 0; i < num_elements; ++i) {
        if ((*double_array)[i] == 0.0 || (*data_units + i)->value == 0.0 || !(*data_units + i)->string || (*identifier_array)[i] == 0) {
            log_error("Invalid data received from API.");
        }
    }
}

