['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>

typedef struct Record {
    int value;
} Record;

void init_arrays(size_t *offsets, size_t *keys, Record **records, size_t num_elements, size_t offset_range, size_t key_range) {
    void *buffer;
    size_t buffer_size = sizeof(long) * num_elements + sizeof(int) * num_elements + num_elements * sizeof(Record);

    if (!(buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0))) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    offsets = (size_t *) buffer;
    keys = (size_t *) ((char *) buffer + sizeof(long) * num_elements);
    records = (Record **) ((char *) buffer + sizeof(long) * num_elements + sizeof(int) * num_elements);

    srand(time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = (rand() % offset_range);
        keys[i] = (rand() % key_range);
        records[i]->value = rand();
    }

    // Verification of the allocated data integrity
    for (size_t i = 0; i < num_elements; ++i) {
        if ((offsets[i] >= num_elements) || (keys[i] >= num_elements) || (records[i]->value < 0)) {
            fprintf(stderr, "Integrity error: invalid index or negative value.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Memory deallocation upon program termination
    munmap(buffer, buffer_size);
}
```

