typedef struct {
    double value;
    char* data;
    size_t size;
} custom_data;

typedef struct transaction {
    custom_data* config;
    int timestamp;
} transaction;

int dynamic_configuration(custom_data** settings, network_device* device, int start, int end, size_t* offsets, int* keys, transaction** transactions, int max_transactions, int min_timestamp, int max_timestamp) {
    if (start > end || start < 1 || end > *settings_len || max_transactions <= 0 || max_timestamp - min_timestamp < 1) {
        return -1; // Invalid input
    }

    size_t* new_offsets = malloc((end - start + 1) * sizeof(size_t));
    int* new_keys = malloc((end - start + 1) * sizeof(int));
    transaction** new_transactions = calloc((max_transactions), sizeof(transaction*));

    for (int i = start; i <= end; ++i) {
        size_t index = offsets[i];
        new_offsets[i - start] = index;
        new_keys[i - start] = keys[i];
    }

    custom_data** new_settings = realloc(settings, ((*settings_len) + (end - start + 1)) * sizeof(custom_data*));
    for (int i = *settings_len; i < (*settings_len) + (end - start + 1); ++i) {
        new_settings[i] = NULL;
    }

    for (int i = *settings_len; i <= (*settings_len) + (end - start + 1); ++i) {
        size_t index = new_offsets[i - (*settings_len)];
        if (!new_settings[index]) {
            new_settings[index] = malloc(sizeof(custom_data));
            new_settings[index]->value = (double)(rand() % max_timestamp + min_timestamp);
            new_settings[index]->data = malloc((rand() % 100 + 50) * sizeof(char));
            strcpy(new_settings[index]->data, "Randomly Generated String");
            new_settings[index]->size = (rand() % 100 + 50);
        }
    }

    for (int i = start; i <= end; ++i) {
        size_t index = offsets[i];
        if (!new_settings[index]) {
            return -2; // Configuration not found
        }
        new_transactions[new_offsets[i] - (*settings_len)] = malloc(sizeof(transaction));
        new_transactions[new_offsets[i] - (*settings_len)]->config = new_settings[index];
        new_transactions[new_offsets[i] - (*settings_len)]->timestamp = rand() % (max_timestamp - min_timestamp + 1) + min_timestamp;
    }

    for (int i = *settings_len + end - start; i < *settings_len + (end - start + 1); ++i) {
        if (new_offsets[i - (*settings_len)] && new_offsets[i - (*settings_len)] != *settings_len + end) {
            settings[new_offsets[i - (*settings_len)]]->next = &new_settings[i];
        }
    }

    device->configurations = new_settings;
    device->transactions = new_transactions;
    *settings_len += (end - start + 1);

    return 0; // Success
}
