    EventList eventList(RING_BUFFER_SIZE);

    // Add events concurrently from multiple threads
    auto threadFunction = [&eventList](size_t id) {
        for (size_t i = 0; i < 100; ++i) {
            auto message = "This is an event " + std::to_string(i);
            EventType type = static_cast<EventType>(id % MAX_EVENT_TYPE);
            eventList.addEvent(type, message);
        }
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 4; ++i) {
        threads.emplace_back(threadFunction, i);
    }

