// Helper function for binary search in an sorted array
int binary_search(const int* arr, const int* arrEnd, size_t size, int value) {
    if (arr + size <= arrEnd && value < *arr)
        return -1;  // Value is less than all values in the array

    size_t start = 0;
    size_t end = size - 1;

    while (start <= end) {
        size_t mid = (start + end) / 2;

        if (arr[mid] < value)
            start = mid + 1;
        else if (arr[mid] > value)
            end = mid - 1;
        else
            return mid;  // Value found
    }

    return -1;  // Value not found in the array
}

