typedef struct MemPool {
    void* start;
    size_t size;
    size_t allocated;
    pthread_mutex_t lock;
} MemPool;

// Custom memory pool functions
MemPool* memPoolInit(size_t size) {
    MemPool* pool = malloc(sizeof(MemPool));
    pool->start = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->start == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    pool->size = size;
    pool->allocated = 0;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    return pool;
}

void* memPoolAlloc(MemPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void* ptr = pool->start + pool->allocated;
    pool->allocated += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

