#include <iostream>
#include <forward_list>
#include <string>
#include <algorithm>
#include <chrono>
#include <random>
#include <thread>
#include <mutex>
#include <boost/log/trivial.hpp>
#include <boost/container/small_vector.hpp>

namespace bl = boost::log;
using namespace std;

class Logger {
public:
    void log(const string& message) {
        auto t = chrono::system_clock::now();
        auto tm = chrono::system_clock::to_time_t(t);
        char buf[20];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&tm));
        bl::record r("Insertion");
        r << "Time: " << buf << ", Message: " << message;
        r.add_attribute("AllocatedSize", allocSize);
        r.add_attribute("OperationTime", chrono::duration<double>(t - start).count());
        r.push_back();
    }

    void incrementAllocation(size_t size) {
        lock_guard<mutex> lock(mtx);
        allocSize += size;
    }

private:
    mutex mtx;
    size_t allocSize = 0;
    chrono::time_point<chrono::system_clock> start;
};

void insertAfterKeyValue(forward_list<string>& list, const string& key, const string& value, Logger& logger) {
    boost::container::small_vector<const_iterator, 5> pos;
    auto it = list.begin();
    bool found = false;
    for (auto e = list.begin(); e != list.end() && !found; ++e, ++it) {
        if (*e == key) {
            pos[0] = it;
            found = true;
        } else {
            pos.push_back(e);
        }
    }

    if (found) {
        for (size_t i = 1, sz = pos.size(); i < sz; ++i) {
            list.erase_after(pos[i]);
        }
        logger.incrementAllocation(value.size());
        *++it = value;
    } else {
        auto gen = bind(uniform_int_distribution<>{minValue, maxValue}, mt19937{rd()});
        for (size_t i = 0; i < 5; ++i) {
            try {
                list.emplace_after(list.end(), gen());
                logger.incrementAllocation(value.size());
                *it = value;
                return;
            } catch (const exception& e) {
                cerr << "Error during insertion: " << e.what() << endl;
                logger.log("Insertion error");
            }
        }
        cerr << "Max retries reached, giving up on insertion." << endl;
        logger.log("Insertion failed after max retries");
    }
}
```
This code provides a function `insertAfterKeyValue` that takes a forward list of strings, a key to search for and a value to insert, along with a Logger object for logging purposes. The function searches for the key in the list, inserts the value after it if found, or appends it to the end otherwise. It supports retrying up to five times using a random number generator from the Boost library, handles memory allocation failures by logging errors and cleaning up partially allocated resources, and uses a mutex to ensure thread-safety. The function also logs timestamps, operation durations, and allocated sizes for each successful insertion or error encountered. Consider adjusting `minValue`, `maxValue` and any other parameters according to your needs.']

