    }

    mmap((char *) offsets + N * sizeof(long), N * sizeof(void *), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    for (size_t i = 0; i < N; ++i) {
        int key = keys[mrandom() % N];
        while (memchr((char *) *records + key * sizeof(record), 1, N * sizeof(record))) {
            key = mrandom() % N;
        }
        (*records)[key].value = mrandom(minValue, maxValue);
        offsets[i] = (long) (&((char *) *records)[key * sizeof(record)]);
    }
}

int mrandom(int min, int max) {
    static unsigned long seed = 1;
    const unsigned long m = (unsigned long) (1 << 31);
    const unsigned long a = 16807;
    const unsigned long c = m / 4;

    if (seed <= 0 || seed >= m) {
        seed = 1 + (unsigned long) time(NULL) * getpid();
    }
    seed = ((a * seed) + c) % m;

    return min + (seed / m) * (max - min + 1);
}
