    pthread_mutex_lock(&g_mutex);
    for (i = 0; i < n; ++i)
        records[i].value = minValue + rand() % (maxValue - minValue + 1);
    pthread_mutex_unlock(&g_mutex);
    return records;
}

void thread_function(int tid) {
    int i, j = tid * (g_config.n / (getconf(_SC_NPROCESSORS_ONLN)));
    for (i = j; i < g_config.n && i < j + (g_config.n / getconf(_SC_NPROCESSORS_ONLN)); ++i) {
        Record* record = &data[keys[offsets[i]]];
        if (i > j && i % (g_config.n / getconf(_SC_NPROCESSORS_ONLN)) == 0) {
            pthread_mutex_lock(&g_mutex);
            for (j = i - 1; j >= 0 && j < offsets[i] - 2; --j)
