void geospatial_init(size_t *keys, size_t *doubles, size_t *points, size_t *geometries, FILE *fp) {
    posix_memalign(keys, 64, sizeof(size_t) * *points);
    posix_memalign(doubles, 64, sizeof(double) * (*geometries * *points * 3));
    posix_memalign(points, 64, sizeof(point_t) * *points);

    geometry_t *geoms = malloc(*geometries * sizeof(geometry_t));
    for (size_t i = 0; i < *geometries; ++i) {
        geoms[i].coords = mmap(NULL, (*points * 3) * sizeof(double), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        geoms[i].point = (point_t*)((char*)geoms[i].coords + (*points * 3) * sizeof(double));
    }

    for (size_t i = 0; i < *points; ++i) {
        fread(&points[i].x, sizeof(float), 1, fp);
        fread(&points[i].y, sizeof(float), 1, fp);
    }

    size_t num_geoms = 0;
    while (!feof(fp)) {
        double coords[3];
        for (size_t j = 0; j < 3; ++j)
            fread(&coords[j], sizeof(double), 1, fp);

        size_t key;
        fread(&key, sizeof(size_t), 1, fp);
        geoms[num_geoms].coords[num_geoms * 3 + 0] = coords[0];
        geoms[num_geoms].coords[num_geoms * 3 + 1] = coords[1];
        geoms[num_geoms].coords[num_geoms * 3 + 2] = coords[2];
        keys[num_geoms] = key;
        ++num_geoms;
    }
}
