int init(size_t max, size_t* offsets, size_t* keys, size_t* records, size_t record_count) {
    if (max < 2 * record_count) {
        fprintf(stderr, "Insufficient memory for requested operation.\n");
        return -1;
    }

    *offsets = calloc(max + 1, sizeof(size_t));
    if (!*offsets) {
        perror("Error allocating offsets array\n");
        return -1;
    }

    *keys = calloc(record_count, sizeof(size_t));
    if (!*keys) {
        perror("Error allocating keys array\n");
        free(*offsets);
        return -1;
    }

    size_t records_allocated = 0;
    *records = malloc(record_count * sizeof(Record));
    if (!*records) {
        perror("Error allocating records array\n");
        free(*offsets);
        free(*keys);
        return -1;
    }
    records_allocated = record_count;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    // Initialize the random number generator here and use it for generating record values

    // Generate random keys and assign values to records in a thread-safe manner using pthreads
