    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&mutex);

        (*keys)[i] = i;
        rec = &((*records)[i]);
        rec->key = myrand(0, max - records_allocated - 1);
        *offsets[rec->key + 1] = i + 1;

        pthread_mutex_unlock(&mutex);
    }

    // Sort the records based on their keys using qsort() and a custom comparison function
    qsort(*records, record_count, sizeof(Record), compare_records);

    return 0;
}

// Free allocated memory when the function is no longer needed
