typedef struct {
    int fd;
    off_t current_position;
    unsigned long checksum;
} FileProcessor;

FileProcessor* FileProcessor_init(const char* path) {
    int flags = O_RDWR | O_CREAT | O_APPEND;
    int mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;
    struct stat st;
    int ret;

    // Ensure that the file can be created and accessed with appropriate permissions
    if (stat(path, &st) == -1 || !(S_ISREG(st.st_mode) && (st.st_mode & S_IWUSR))) {
        mode |= S_IRUSR | S_IWUSR;
        ret = mkdir(path, mode);
    }

    if (ret == -1 || (ret = open(path, flags, mode)) == -1) {
        perror("Error opening file");
        return NULL;
    }

    // Lock the file for exclusive access by a single thread during initialization
    pthread_mutexattr_t attr;
    pthread_mutex_t lock;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    ret = pthread_mutex_init(&lock, &attr);
    if (ret != 0) {
        perror("Error initializing lock");
        close(ret);
        return NULL;
    }

    fcntl(ret, F_SETLKW, F_WRLCK); // Lock the file for exclusive access during initialization

    FileProcessor* fp = malloc(sizeof(FileProcessor));
    if (!fp) {
        perror("Error allocating memory for FileProcessor");
        close(ret);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    fp->fd = ret;
    fp->current_position = lseek(ret, 0, SEEK_CUR); // Set the current position to 0 for subsequent reads and writes
    fp->checksum = 0;

    fcntl(ret, F_SETLK, F_UNLCK); // Unlock the file after initialization
    pthread_mutex_destroy(&lock);

    return fp;
}

void FileProcessor_write(FileProcessor* fp, const void* data, size_t length) {
    // Check for buffer overflow and handle concurrent write operations safely
    char* buffer = realloc(fp->buffer, fp->buffer_size);
    if (!buffer) {
        perror("Error allocating memory for buffer");
        return;
    }
    fp->buffer = buffer;

    pthread_mutexattr_t attr;
    pthread_mutex_t lock;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    ret = pthread_mutex_init(&lock, &attr);
    if (ret != 0) {
        perror("Error initializing lock");
        return;
    }

    fcntl(fp->fd, F_SETLKW, F_WRLCK); // Lock the file for exclusive access during writing

    char* start = fp->buffer + fp->written;
    memcpy(start, data, length < (fp->buffer_size - fp->written) ? length : (fp->buffer_size - fp->written));
    fp->written += length;

    // Calculate and store the checksum for written data
    unsigned long new_checksum = Adler32(start, length);
    fp->checksum += new_checksum;

    fcntl(fp->fd, F_SETLK, F_UNLCK); // Unlock the file after writing
    pthread_mutex_destroy(&lock);
}

void FileProcessor_destroy(FileProcessor* fp) {
    if (fp && fp->fd != -1) {
        close(fp->fd);
        free(fp);
    }
}
