hash_table_t* create_hash_table(unsigned long long capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->size = 0;
    table->capacity = capacity;
    table->nodes = calloc(capacity, sizeof(node_t*));
    if (!table->nodes) {
        free(table);
        return NULL;
    }

    return table;
}

void insert_node(hash_table_t *table, node_t *n) {
    unsigned long index = n->value % table->capacity;

    if (!table->nodes[index]) table->nodes[index] = n;
    else {
        node_t* current = table->nodes[index];
        while (current != NULL) {
            if (current->value == n->value) return; // Duplicate values are not allowed.
            index = (index + 1) % table->capacity;
            current = table->nodes[index];
        }

        table->nodes[index] = n;
    }
}

void randomize_metadata(node_t *n, int minMetadata, int maxMetadata) {
    srand(time(NULL));
    n->metadata = malloc(sizeof(int)); // Assume metadata is an integer.
    if (!n->metadata) return;

    *(int*)n->metadata = (rand() % (maxMetadata - minMetadata + 1)) + minMetadata;
}

void* create_node_list(size_t N, int minMetadata, int maxMetadata) {
    node_t *head = malloc(sizeof(node_t));
    if (!head) return NULL;

    head->next = NULL;
    head->value = -1; // Marker for end of list.

    hash_table_t* table = create_hash_table(N);
    if (!table) {
        free(head);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        node_t *n = malloc(sizeof(node_t));
        if (!n) {
            destroy_hash_table(table);
            free(head);
            return NULL;
        }

        n->next = NULL;
        n->value = i;
        randomize_metadata(n, minMetadata, maxMetadata);

        avl_insert(&head->next, n);
        insert_node(table, n);
    }

    return head;
}

void destroy_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        node_t* current = table->nodes[i];
        while (current != NULL) {
            node_t* next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->nodes);
    free(table);
}
