class MemoryPool {
public:
    MemoryPool(size_t poolSize) : freeList_(poolSize), usedList_(), data_(new Record[poolSize]) {}

    Record* allocate() {
        if (!freeList_.empty()) {
            auto it = freeList_.back();
            freeList_.pop_back();
            usedList_.insert(it);
            return &data_[it];
        }
        return nullptr;
    }

    void free(Record* record) {
        if (usedList_.find(record - data_) != usedList_.end()) {
            usedList_.erase(record - data_);
            freeList_.push_back(record - data_);
        }
    }

private:
    std::vector<Record*> freeList_;
    std::unordered_set<size_t> usedList_;
    std::vector<Record> data_;
};

