// Helper function for generating unique random numbers using reservoir sampling
unsigned int getUniqueRandom(unsigned int minValue, unsigned int maxValue, std::vector<unsigned int>& usedNumbers) {
    unsigned int result = (minValue + rand() % ((maxValue - minValue) + 1));
    if (std::find(usedNumbers.begin(), usedNumbers.end(), result) == usedNumbers.end()) {
        usedNumbers.push_back(result);
    } else {
        while (usedNumbers.size() < minValue + rand() % ((maxValue - minValue) + 1)) {
            result = (minValue + rand() % ((maxValue - minValue) + 1));
            if (std::find(usedNumbers.begin(), usedNumbers.end(), result) == usedNumbers.end()) {
                usedNumbers[usedNumbers.size()] = result;
                break;
            }
        }
    }
    return result;
}

