pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static char* log_file = "system_log.txt";
static bool fatal_error = false;

void log(const char* message, ...) {
    va_list args;
    if (!fatal_error) {
        va_start(args, message);
        vfprintf(stderr, message, args);
        fprintf(stderr, "\n");
        va_end(args);
    }
    pthread_mutex_lock(&log_mutex);
    fprintf(stderr, "[%s] ", __func__);
    va_start(args, message);
    vfprintf(stderr, message, args);
    fprintf(stderr, "\n");
    va_end(args);
    pthread_mutex_unlock(&log_mutex);
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && !fatal_error) {
        log("Memory allocation failure. Adjusting dataset size.");
        fatal_error = true;
    }
    return ptr;
}

void safe_free(void* ptr) {
    if (ptr && !fatal_error) {
        free(ptr);
    }
}

int* initialize_keys(size_t N) {
    int *keys = safe_malloc(N * sizeof(int));
    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
    }
    return keys;
}

long* initialize_offsets(size_t N) {
    long *offsets = safe_malloc(N * sizeof(long));
    memset(offsets, 0, N * sizeof(long));
    return offsets;
}

Record* generate_unique_records(size_t N, int minValue, int maxValue) {
    const int bucket_count = 1024;
    size_t bucket_size = N / bucket_count;
    if (bucket_size == 0) {
        log("Insufficient uniqueness within the specified range.");
        fatal_error = true;
    }

    int *buckets[bucket_count];
    for (int i = 0; i < bucket_count; ++i) {
        buckets[i] = safe_malloc(maxValue - minValue + 1);
        memset(buckets[i], 0, (maxValue - minValue + 1) * sizeof(int));
    }

    Record* records = safe_malloc(N * sizeof(Record));
    int count = 0;

    for (size_t i = 0; i < N; ++i) {
        int key = keys[i];
        int index = key / bucket_size;
        int bucket = buckets[index][key % bucket_size];

        // If the current value is not yet used, set it as the new record's value and update the corresponding bucket.
        if (bucket == -1) {
            records[count].value = key;
            buckets[index][key % bucket_size] = count++;
        } else {
            log("Failed to generate unique values within the specified range.");
            fatal_error = true;
        }
    }

    for (int i = 0; i < bucket_count; ++i) {
        safe_free(buckets[i]);
    }

    return records;
}

void process_chunk(size_t chunk_size, Record* records, long* offsets, int minValue, int maxValue, void(*function)(int, int)) {
    for (size_t i = 0; i < chunk_size; ++i) {
        function(records[offsets[i]].value, minValue);
        ++offsets[i];
    }
}

void cleanup_resources(Record* records, long* offsets, int* keys, long* offsets) {
    if (records) {
        safe_free(records);
    }
    if (keys) {
        safe_free(keys);
    }
    if (offsets) {
        safe_free(offsets);
    }
}

void handle_large_dataset(size_t N, int minValue, int maxValue, size_t chunk_size, void(*function)(int, int)) {
    long *keys = initialize_keys(N);
    long *offsets = initialize_offsets(N);
    Record* records = generate_unique_records(N, minValue, maxValue);

    if (fatal_error) {
        cleanup_resources(records, offsets, keys, NULL);
        return;
    }

    size_t adjusted_N = N;
    while (adjusted_N > 0 && fatal_error) {
        adjusted_N /= 2;
    }

    log("Successfully allocated and initialized memory for a dataset of size ", adjusted_N);
    if (adjusted_N == 0) {
        cleanup_resources(records, offsets, keys, NULL);
        return;
    }

    pthread_t threads[adjusted_N];

    // Process data in chunks of the specified chunk size
    long* current_offset = initialize_offsets(chunk_size);
    for (size_t i = 0; i < adjusted_N - chunk_size + 1; i += chunk_size) {
        process_chunk(chunk_size, records + i, current_offset, minValue, maxValue, function);

        // Move the processing position to the next chunk and reset the offsets for it.
        memmove(current_offset, current_offset + chunk_size, (adjusted_N - i - chunk_size + 1) * sizeof(long));
    }

    // Process any remaining chunks.
    for (size_t i = adjusted_N - chunk_size; i < adjusted_N; ++i) {
        process_chunk(1, records + i, current_offset, minValue, maxValue, function);
    }

    cleanup_resources(records, offsets, keys, current_offset);
}

