#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long value;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int *keys, offsets[N];
static Record *records, *temp_records;
static size_t records_capacity, records_size;
static const int N; // Replace with the value of N from main function call

Record* generate_record() {
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    new_record->key = -1;
    new_record->value = 0;
    return new_record;
}

long find_next_offset() {
    pthread_mutex_lock(&mutex);
    long result = offsets[N - 1] + 1;
    offsets[N - 1] = result;
    pthread_mutex_unlock(&mutex);
    return result;
}

int find_key(int key) {
    for (size_t i = 0; i < records_size; ++i) {
        if (records[i].key == key) {
            return i;
        }
    }
    return -1;
}

void add_record(Record* record) {
    pthread_mutex_lock(&mutex);
    if (records_size >= records_capacity) {
        if (records_capacity == 0) {
            records_capacity = 8;
            records = generate_record();
        } else {
            records = realloc(records, records_capacity * 2 * sizeof(Record));
            if (!records) {
                fprintf(stderr, "Out of memory\n");
                return;
            }
            records_capacity *= 2;
        }
    }
    record->key = records_size++;
    record->value = find_next_offset();
    records[record->key] = *record;
    pthread_mutex_unlock(&mutex);
}

void remove_record(int key) {
    size_t index = (size_t) key;
    if (index >= records_size || index < 0) {
        return;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = index + 1; i < records_size; ++i) {
        records[i].key--;
    }
    free(records[index]);
    memmove(&records[index], &records[records_size - 1], sizeof(Record) * (records_size - 1 - index));
    records_size--;
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    for (size_t i = 0; i < records_size; ++i) {
        free(records[i]);
    }
    free(records);
    records = NULL;
    records_capacity = 0;
    records_size = 0;
}

void initialize() {
    keys = (int*) malloc((N + 1) * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    for (int i = 0; i < N; ++i) {
        keys[i] = i;
    }
    offsets[0] = 0;
    records_capacity = 8;
    records = generate_record();
    if (!records) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
}

// Generate random unique values within the specified range for each record.
void populate() {
    temp_records = generate_record();
    srand((unsigned int)time(NULL));
    Record* current_record, *next_record;

    pthread_mutex_lock(&mutex);
    while (records_size < N) {
        current_record = next_record = temp_records + rand() % records_capacity;

        if (current_record->key == -1 && find_key(next_record->key) == -1) {
            add_record(current_record);
            current_record->value = next_record->value =
                find_next_offset();
            current_record->key = next_record->key;
        }
    }
    pthread_mutex_unlock(&mutex);
}
