#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Memory pool for record structures
struct RecordPool {
    void* records;
    size_t capacity;
    size_t used;
};

struct RecordPool* createRecordPool(size_t capacity) {
    struct RecordPool* pool = malloc(sizeof(struct RecordPool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->used = 0;
    pool->records = calloc(capacity, sizeof(struct Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    return pool;
}

struct Record* getRecordFromPool(struct RecordPool* pool) {
    if (pool->used == pool->capacity) return NULL;

    struct Record* record = &((struct Record*)pool->records)[pool->used++];
    return record;
}

void releaseRecordToPool(struct RecordPool* pool, struct Record* record) {
    record->value = 0;
}

typedef struct {
    long* offsets;
    int* keys;
    struct Record* records;
    pthread_mutex_t log_mutex;
    size_t N;
} InitData;

void initLog(InitData* data) {
    pthread_mutex_init(&data->log_mutex, NULL);
}

void logOperation(const char* operation, const void* arg1, const void* arg2) {
    pthread_mutex_lock(&((InitData*)arg1)->log_mutex);
    printf("Performed %s operation: %ld and %d\n", operation, *(long*)arg2, *(int*)arg1);
    pthread_mutex_unlock(&((InitData*)arg1)->log_mutex);
}

void* generateRecords(void* data) {
    InitData* initData = (InitData*)data;
    srand(time(NULL));

    int minValue = 0, maxValue = 1000000 / initData->N;
    size_t attempts = 0;
    while (attempts < 5) { // Adjust the number of attempts as needed
        for (size_t i = 0; i < initData->N; ++i) {
            struct Record* record = getRecordFromPool(initData->recordPool);
            if (!record) break;

            int value = rand() % maxValue + minValue;
            bool unique = true;
            for (size_t j = 0; j < i; ++j) {
                if (initData->records[j].value == value) {
                    unique = false;
                    break;
                }
            }

            if (unique) {
                record->value = value;
                logOperation("Record generation", i, value);
                --attempts;
                if (attempts == 0) break; // All records successfully generated
            }
        }
    }

    if (attempts != 0) {
        minValue *= 2;
        maxValue /= 2;
    }

    return NULL;
}

void initArrays(InitData* data) {
    data->offsets = malloc(data->N * sizeof(long));
    if (!data->offsets) {
        fprintf(stderr, "Failed to allocate offset array\n");
        exit(EXIT_FAILURE);
    }

    data->keys = calloc(data->N, sizeof(int));
    if (!data->keys) {
        free(data->offsets);
        fprintf(stderr, "Failed to allocate key array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < data->N; ++i) data->keys[i] = i;
}

void cleanup(InitData* data) {
    if (data->recordPool) {
        free(data->recordPool->records);
        free(data->recordPool);
    }

    free(data->offsets);
    free(data->keys);
}

void findLargestNumber(const InitData* data) {
    int largest = INT_MIN;
    for (size_t i = 0; i < data->N; ++i) largest = fmax(largest, data->keys[i]);
    printf("The largest number is: %d\n", largest);
}

int main() {
    InitData data = {};
    data.N = 100000;
    data.recordPool = createRecordPool(data.N);
    if (!data.recordPool) return EXIT_FAILURE;

    initLog(&data);

    pthread_t threads[data.N];
    for (size_t i = 0; i < data.N; ++i) {
        if (pthread_create(&threads[i], NULL, &generateRecords, &data)) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < data.N; ++i) pthread_join(threads[i], NULL);

    initArrays(&data);

    findLargestNumber(&data);

    cleanup(&data);

    return EXIT_SUCCESS;
}
```

