    {
        var metadata = reader.ReadBytes(sizeof(int)); // Message metadata size is assumed to be 4 bytes in this example
        int messageMetadata = BitConverter.ToInt32(metadata, 0);

        var keyIndex = messageMetadata & 0xFFFFFF;
        var ivIndex = (messageMetadata >> 24) & 0xFFFFFF;

        if (!_keys.TryGetValue(keyIndex.ToString(), out byte[] key) || !_ivs.TryGetValue(ivIndex.ToString(), out byte[] iv))
        {
            throw new ArgumentException("Invalid key or IV");
        }

        using (var hmac = new HMACSHA256(key))
        {
            var signature = reader.ReadBytes(sizeof(int)); // Signature size is assumed to be 4 bytes in this example
            int messageSignatureIndex = BitConverter.ToInt32(signature, 0);

            var signatureData = await reader.ReadByteArrayAsync(messageSignatureIndex);
            var computedSignature = hmac.ComputeHash(reader.BaseStream);

            if (!Enumerable.SequenceEqual(computedSignature, signatureData))
            {
                throw new InvalidDataException("Invalid HMAC-SHA256 signature");
            }
        }

        using (var encryptor = Aes.Create())
        {
            encryptor.Key = key;
            encryptor.IV = iv;

            var decryptedData = await reader.ReadByteArrayAsync(int.MaxValue); // Assuming the rest of the stream is the encrypted data
            return encryptor.Decrypt(decryptedData, iv);
        }
