constexpr size_t N = std::getenv("N") ? std::stoul(std::getenv("N")) : 10;
const auto minValue = std::atof(std::getenv("minValue"));
const auto maxValue = std::atof(std::getenv("maxValue"));
const auto startDate = std::getenv("startDate") ? std::getenv("startDate") : "2022-01-01";

struct data_point {
    double value;
    std::string date;
    bool valid;
};
using data_points_ptr = std::unique_ptr<data_point[]>;
using data_points_vec = std::vector<std::pair<double, std::shared_ptr<const char>>>;
using data_points_list = std::list<data_points_ptr>;

auto getDate(int day) {
    auto t = std::chrono::system_clock::to_time_t(std::make_tuple(std::stoi(startDate.substr(0, 4)),
                                                                   std::stoi(startDate.substr(5, 2)), day));
    auto tm = *std::localtime(&t);
    return std::format("{}-{:02d}-{:02d}", 1900 + tm.tm_year, 1 + tm.tm_mon, tm.tm_mday);
}

data_points_list generateDataPoints(size_t count) {
    std::vector<std::string> dates;
    for (int i = 0; i < count; ++i) {
        dates.push_back(getDate(i));
    }

    auto random = std::bind(std::uniform_real_distribution<>(minValue, maxValue), std::default_random_engine{});
    std::mt19937 engine;
    data_points_list result;

    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<size_t> idx(0);
    std::unordered_set<std::string> usedDates;

    auto generateDataPoint = [&](double value) {
        while (usedDates.count(dates[idx])) {
            std::unique_lock<std::mutex> lck(mtx);
            cv.wait(lck, [&]() { return idx >= dates.size(); });
            if (idx == dates.size())
                return;
            ++idx;
        }

        auto dp = std::make_unique<data_point>();
        dp->value = value;
        dp->date = dates[idx - 1];
        dp->valid = true;
        usedDates.insert(dp->date);

        return dp;
    };

    for (size_t i = 0; i < count; ++i) {
        result.push_back(generateDataPoint(random()));
    }

    return result;
}

