```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

[StructLayout(LayoutKind.Sequential)]
struct Record
{
    public long Value;
}

public class DataProcessor
{
    private readonly int _minValue;
    private readonly int _maxValue;
    private readonly int _N;
    private Record[] _data;
    private IntPtr _memoryHandle;

    private readonly object _lock = new object();
    private readonly Stopwatch _timer = new Stopwatch();

    public DataProcessor(int minValue, int maxValue, int N)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _N = N;
    }

    public void AllocateMemory()
    {
        if (_memoryHandle != IntPtr.Zero) return; // Prevent double allocation

        _timer.Start();
        GCHandle handle = GCHandle.Alloc(new Record[_N], GCHandleType.Pinned);
        _memoryHandle = handle.AddrOfPinnedObject();
        _data = (Record[])Marshal.PtrToStructure(_memoryHandle, typeof(Record));
        _timer.Stop();
        Console.WriteLine($"Allocated memory for {_N} records in {_timer.ElapsedMilliseconds} ms.");
    }

    public void ReadInput()
    {
        int[] input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        if (input.Length != _N)
            throw new ArgumentException("Invalid input length.");

        lock (_lock)
        {
            for (int i = 0; i < _N; i++)
                _data[i] = new Record { Value = input[i] };
        }
    }

    public void FindLargest()
    {
        var largest = default(long);

        lock (_lock)
        {
            foreach (var record in _data)
                if (record.Value > largest)
                    largest = record.Value;
        }

        Console.WriteLine($"The largest number is: {largest}");
    }

    public void DeallocateMemory()
    {
        if (_memoryHandle == IntPtr.Zero) return; // Prevent double deallocation

        GCHandle handle = GCHandle.FromIntPtr(_memoryHandle);
        handle.Free();
        _memoryHandle = IntPtr.Zero;
        Console.WriteLine("Deallocated memory.");
    }

    public void Cleanup()
    {
        DeallocateMemory();
    }
}
```

