void manageDynamicRecordsAndFiles(int N) {
    // Allocate offsets array and check for memory allocation failures
    long* offsets = malloc((size_t)MAX_OFFSETS * sizeof(long));
    if (!offsets) {
        pthread_mutex_lock(&log_mutex);
        fprintf(logfile, "Failed to allocate memory for offsets array.\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }
    printf("Successfully allocated memory for offsets array.\n");

    // Allocate keys array and validate uniqueness
    int* keys = malloc((size_t)MAX_KEYS * sizeof(int));
    if (!keys) {
        pthread_mutex_lock(&log_mutex);
        fprintf(logfile, "Failed to allocate memory for keys array.\n");
        pthread_mutex_unlock(&log_mutex);
        free(offsets);
        return;
    }
    int key = 0;
    for (int i = 0; i < N; ++i) {
        keys[i] = key++;
        if (key >= MAX_KEYS) {
            pthread_mutex_lock(&log_mutex);
            fprintf(logfile, "Key allocation failure: too many unique keys.\n");
            pthread_mutex_unlock(&log_mutex);
            free(keys);
            free(offsets);
            return;
        }
