            fprintf(logfile, "Data allocation failure: invalid data values.\n");
            pthread_mutex_unlock(&log_mutex);
            free(records);
            free(keys);
            free(offsets);
            return;
        }
    }
    printf("Successfully allocated memory for records array and filled with valid data.\n");

    // Modify filename extension and handle large filenames efficiently
