use std::collections::{HashMap, VecDeque};
use reqwest::{Client, Error, Response};
use serde_json::{Value, Map};
use num_traits::Prime;
use rand::{thread_rng, Rng};
use rayon::prelude::*;
use std::sync::{Arc, Mutex};

type Record = (i32, f32, char);
type Records = Vec<Record>;

fn main() {
    let client = Arc::new(Mutex::new(Client::builder().build().expect("Failed to create HTTP client")));
    let primes = get_primes_up_to(100).unwrap();
    let size = primes.len();

    let longs = vec![0; size];
    let keys = vec![0; size];
    let weights = vec![0.0; size];
    let records: Records = (0..size).into_par_iter().map(|_| {
        (
            rand::thread_rng().gen_range(0, 100),
            rand::thread_rng().gen(),
            rand::thread_rng().gen_ascii_char()
        )
    }).collect();

    let mut api_requests = VecDeque::new();
    let rate_limit = Arc::new(Mutex::new(5));

    // REST API call to fetch primes data in a concurrent and rate-limited manner.
    for prime in &primes {
        let client = Arc::clone(&client);
        let rate_limit = rate_limit.clone();
        api_requests.push_back(thread::spawn(move || {
            let mut guard = rate_limit.lock().unwrap();
            *guard -= 1;
            if *guard >= 0 {
                make_api_call(*prime, &client)
            } else {
                println!("Rate limit exceeded for prime {}", prime);
                Vec::new()
            }
        }));
    }

    while let Some(result) = api_requests.pop_front() {
        match result {
            Ok(response) => {
                let data: Value = response.json().unwrap();
                if let Map(data) = data.as_object() {
                    for (index, value) in data {
                        longs[usize::from(*index)] = value.as_i64().unwrap();
                        keys[usize::from(*index)] = usize::from(*index);
                        weights[usize::from(*index)] = value.as_f64().unwrap() as f32;
                    }
                }
            },
            Err(e) => eprintln!("API request failed with error: {}", e),
        }
    }
}

fn get_primes_up_to(n: u32) -> Result<Vec<u32>, Box<dyn Error>> {
    let mut primes = vec![2];
    let mut candidates = (2..=n).collect::<Vec<u32>>();

    while !candidates.is_empty() {
        for prime in &primes {
            let candidates_iter = candidates.iter().filter(|x| x % prime != 0);
            candidates.retain(|x| candidates_iter.any(|y| y == x));
        }
        if !candidates.is_empty() {
            primes.push(candidates[0]);
        }
    }

    Ok(primes)
}

fn make_api_call(prime: u32, client: &Client) -> Result<Response, Error> {
    client.get(&format!("https://example.com/api/prime/{}/data", prime))
        .send()
}
```

