};

DataStructure create_data_structure(int capacity) {
    DataStructure ds = {NULL, NULL, (HashTable){0, NULL, PTHREAD_MUTEX_INITIALIZER}};
    ds.hash_table.size = capacity;
    ds.hash_table.table = malloc(capacity * sizeof(Entry*));
    if (!ds.hash_table.table) {
        // Log error and exit gracefully
    }
    return ds;
}

void put(DataStructure *ds, int key, double value, time_t expire_time) {
    pthread_mutex_lock(&ds->hash_table.lock);

    int index = key % ds->hash_table.size;
    Entry *entry = malloc(sizeof(Entry));
    if (!entry) {
        // Log error and exit gracefully
    }

    entry->prev = (Entry*)&ds->hash_table.table[index];
    entry->next = ds->hash_table.table[index];
    memcpy(&ds->hash_table.table[index], entry, sizeof(entry));

    Entry *new_head;
    pthread_mutex_lock(&ds->hash_table.lock);
    if (!ds->head) {
        ds->head = entry;
        ds->tail = entry;
    } else {
        new_head = ds->head;
        while (new_head->next && ((time_t)difftime(new_time, new_head->expire_time) > 0)) {
            new_head = new_head->next;
        }
        entry->prev = new_head->prev;
        entry->next = new_head;
        if (new_head->prev) {
            *(Entry**)new_head->prev = entry;
        } else {
            ds->head = entry;
        }
        *(Entry**)&ds->tail = entry;
    }

    pthread_mutex_unlock(&ds->hash_table.lock);
}

int get(DataStructure *ds, int key) {
    pthread_mutex_lock(&ds->hash_table.lock);
    int index = key % ds->hash_table.size;
    Entry* entry = ds->hash_table.table[index];
    pthread_mutex_unlock(&ds->hash_table.lock);

    if (!entry) {
        return -1;
    }

    while (entry && entry->key != key) {
        entry = entry->next;
    }

    if (!entry) {
        return -1;
    }

    pthread_mutex_lock(&ds->hash_table.lock);
    Entry *prev = (Entry*)entry->prev;
    Entry *next = (Entry*)entry->next;
    pthread_mutex_unlock(&ds->hash_table.lock);

    if (prev) {
        *(Entry**)prev = next;
    } else {
        ds->head = next;
    }
    if (next) {
        *(Entry**)&next->prev = prev;
    } else {
        ds->tail = prev;
    }

    return (int)((double*)entry - (double*)ds->hash_table.table[0]);
}

void destroy(DataStructure *ds) {
    pthread_mutex_destroy(&ds->hash_table.lock);
    free(ds->hash_table.table);
}
