void insertNode(Node** head, Node* newNode, int N, int minMetadata, int maxMetadata) {
    if (*head == NULL || newNode->metadata < ((*head)->metadata)) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && current->next->metadata < newNode->metadata) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

void insertHash(struct HashNode** table, int key, Node* node) {
    int index = hashFunction(key, table_size);
    struct HashNode* current = table[index];

    if (current == NULL) {
        table[index] = (struct HashNode*)malloc(sizeof(struct HashNode));
        table[index]->node = node;
        table[index]->next = NULL;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (struct HashNode*)malloc(sizeof(struct HashNode));
        current = current->next;
        current->node = node;
        current->next = NULL;
    }
}

