use std::cell::RefCell;
use std::rc::Rc;
use std::collections::{HashMap, VecDeque};
use std::sync::atomic::AtomicUsize;
use std::sync::Mutex;
use reqwest::{Client, Method};
use log::{error, debug, trace};

// Define Resource struct
struct Resource {
    device_id: u64,
    string: String,
    value: i32,
    float: f64,
}

// Create a custom MemoryPool structure
struct MemoryPool {
    pool: Vec<RefCell<Resource>>,
    free_list: VecDeque<usize>,
    size: AtomicUsize,
    max_size: usize,
    log: RefCell<Mutex<log::Logger>>,
}

impl MemoryPool {
    fn new(max_size: usize, log: &log::Logger) -> Self {
        let pool = Vec::with_capacity(max_size);
        for _ in 0..max_size {
            pool.push(RefCell::new(Resource {
                device_id: AtomicUsize::new(0).fetch_add(1, std::sync::atomic::Ordering::Relaxed),
                string: String::new(),
                value: 0,
                float: 0.0,
            }));
        }

        MemoryPool {
            pool,
            free_list: VecDeque::new(),
            size: AtomicUsize::new(0),
            max_size,
            log: RefCell::new(Mutex::new(log.clone())),
        }
    }

    fn allocate(&self) -> Option<&RefCell<Resource>> {
        if let Some(idx) = self.free_list.pop_front() {
            self.pool[idx].take()
        } else if self.size.load(std::sync::atomic::Ordering::Relaxed) < self.max_size {
            let idx = self.size.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            Some(&self.pool[idx])
        } else {
            None
        }
    }

    fn deallocate(&mut self, resource: &RefCell<Resource>) {
        let idx = resource.borrow_mut().device_id as usize;
        *resource.borrow_mut() = RefCell::new(Resource {
            device_id: 0,
            string: String::new(),
            value: 0,
            float: 0.0,
        });
        self.pool[idx].replace(resource);
        self.free_list.push_back(idx);
    }
}

fn resourceCoordinator(pool: &Rc<RefCell<MemoryPool>>, num_resources: usize) {
    let mut resources = HashMap::with_capacity(num_resources);

