// Custom memory pool interface
typedef struct mem_pool_t {
    void* data;
    size_t capacity;
} mem_pool_t;

mem_pool_t* mem_pool_create(size_t initial_capacity);
void mem_pool_destroy(mem_pool_t* pool);
void* mem_pool_alloc(mem_pool_t* pool, size_t size);
void mem_pool_free(mem_pool_t* pool, void* ptr);
void mem_pool_shrink(mem_pool_t* pool);

// Data point structure
typedef struct data_point_t {
    float value;
    unsigned short index;
} data_point_t;

// Thread-safe data structure for managing function states
struct state_t {
    pthread_mutex_t mutex;
    mem_pool_t* mem_pool;
    size_t M;
    float minPrecision, maxPrecision;
    unsigned int retries;
};

// Initialize data structures function
void init_data_structures(size_t M, float minPrecision, float maxPrecision) {
    struct state_t* state = malloc(sizeof(struct state_t));
    pthread_mutex_init(&state->mutex, NULL);

    // Initialize memory pool
    state->mem_pool = mem_pool_create(M * 4); // Assume a factor of 4 for cache locality

    state->M = M;
    state->minPrecision = minPrecision;
    state->maxPrecision = maxPrecision;
    state->retries = 100; // Number of retries before failing

    // Allocate and initialize arrays
    float* values = mem_pool_alloc(state->mem_pool, M * sizeof(float));
    unsigned short* indices = mem_pool_alloc(state->mem_pool, M * sizeof(unsigned short));

    // Initialize sequential indices
    for (size_t i = 0; i < M; ++i) {
        indices[i] = i;
    }

    // Allocate and initialize data points array
    data_point_t* data_points = mem_pool_alloc(state->mem_pool, M * sizeof(data_point_t));

    for (size_t i = 0; i < M; ++i) {
        // Generate unique values within range and retry if necessary
        float value = minPrecision + (rand() % ((int)((maxPrecision - minPrecision) * 10000))) / 10000.f;
        for (unsigned int j = 0; j < state->retries; ++j) {
            bool unique = true;
            pthread_mutex_lock(&state->mutex);
            for (size_t k = 0; k < i; ++k) {
                if (data_points[k].value == value) {
                    unique = false;
                    break;
                }
            }
            pthread_mutex_unlock(&state->mutex);
            if (unique) {
                data_points[i] = (data_point_t){value, indices[i]};
                break;
            }
        }
    }

    // Integrate with logging framework
    log_info("Memory allocation and initialization successful");

    // Cleanup on function exit
    mem_pool_destroy(state->mem_pool);
    free(state);
}
