void parse_config(FILE *fp, device_info **device_infos, size_t *num_devices) {
    fscanf(fp, "%zu\n", num_devices);

    *device_infos = malloc(*num_devices * sizeof(**device_infos));
    if (!*device_infos) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *num_devices; ++i) {
        fscanf(fp, "%d %lf %*[^\n]\n", &((*device_infos)[i].serial_number),
               &((*device_infos)[i].temperature_reading));
        ((*device_infos)[i].error_code) = NO_ERROR;
    }
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *init_devices(void *arg) {
    parse_config(arg, &device_infos, &num_devices);

    for (size_t i = 0; i < num_devices; ++i) {
        device_infos[i].temperature_reading += rand() / (RAND_MAX / 10.0);
        device_infos[i].error_code = (enum error_code)(rand() % 3);
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void init_devices_safe(size_t num_threads) {
    pthread_t threads[num_threads];

    device_infos = NULL;
    num_devices = 0;

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(threads + i, NULL, init_devices, stdin)) {
            perror("Thread creation failure");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(device_infos);
    device_infos = NULL;
    num_devices = 0;

    pthread_mutex_unlock(&mutex);
}
```

