typedef struct Value {
    char key[37]; // UUID as a string
    time_t timestamp;
    struct Value *next;
} Value;

Node* create_node() {
    Node* node = (Node*) malloc(sizeof(Node));
    for (int i = 0; i < 10; ++i)
        node->values[i] = NULL;

    pthread_mutex_init(&node->lock, NULL);

    return node;
}

Value* create_value() {
    Value* value = (Value*) malloc(sizeof(Value));
    // Generate UUID as a string
    uuid_t uuid;
    uuid_generate(uuid);
    snprintf(value->key, sizeof(value->key), "%08x%04x%04x%04x%04x%08x%04x%04x%04x%08x%04x%04x",
              uuid[1], uuid[2], uuid[3],
              uuid[4], uuid[5], uuid[6], uuid[7], uuid[8], uuid[9],
              uuid[10], uuid[11], uuid[12], uuid[13]);

    value->timestamp = time(NULL);
    value->next = NULL;

    return value;
}

Value* add_value_to_node(Node* node, Value* value) {
    pthread_mutex_lock(&node->lock);

    // Find an empty slot in the values array
    for (int i = 0; i < 10; ++i) {
        if (!node->values[i]) {
            node->values[i] = value;
            break;
        }
    }

    pthread_mutex_unlock(&node->lock);
    return value;
}

Node** create_nodes(size_t count) {
