#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>

typedef struct {
    char id[32];
    int priority;
    time_t scheduled;
    void* context;
} task_info;

struct task_list {
    size_t capacity;
    size_t count;
    task_info** tasks;
    pthread_mutex_t mutex;
};

void task_list_init(struct task_list* list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->count = 0;
    list->tasks = calloc(initial_capacity, sizeof(task_info*));
    if (!list->tasks) {
        fprintf(stderr, "Failed to allocate memory for task list\n");
        return;
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void task_list_destroy(struct task_list* list) {
    free(list->tasks);
}

void load_tasks_from_file(const char* filename, struct task_list* list) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file: %s\n", filename);
        return;
    }

    char line[256];
    task_info new_task;
    size_t num_tasks = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%s %d", new_task.id, &new_task.priority) != 2) {
            continue; // Invalid or missing entry
        }

        struct tm time_struct;
        if (!strptime(line, "%s %T ", new_task.id, &time_struct)) {
            continue; // Invalid scheduled execution time
        }
        new_task.scheduled = mktime(&time_struct);

        pthread_mutex_lock(&list->mutex);
        if (num_tasks >= list->capacity) {
            fprintf(stderr, "Task list capacity exceeded\n");
            pthread_mutex_unlock(&list->mutex);
            break;
        }
        list->tasks[num_tasks] = malloc(sizeof(task_info));
        if (!list->tasks[num_tasks]) {
            fprintf(stderr, "Failed to allocate memory for a new task\n");
            pthread_mutex_unlock(&list->mutex);
            break;
        }
        memcpy(list->tasks[num_tasks], &new_task, sizeof(task_info));
        num_tasks++;
        pthread_mutex_unlock(&list->mutex);
    }

    fclose(file);
}

void* task_exec(void* arg) {
    // Implement task execution logic here
}

void schedule_tasks(struct task_list* list) {
    time_t current_time = time(NULL);
    pthread_t thread;

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i]->scheduled <= current_time) {
            void* thread_arg = list->tasks[i];
            pthread_create(&thread, NULL, task_exec, thread_arg);
            memmove(&(list->tasks[i]), &(list->tasks[i+1]), (list->count-i-1)*sizeof(task_info*));
            --list->count;
            free(list->tasks[(list->capacity - 1)]);
            list->tasks[(list->capacity - 1)] = NULL;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
```

