use rand::Rng;
use std::sync::{Arc, Mutex};
use log::*;
use reqwest::Client; // third-party API integration
use std::thread::sleep;
use std::time::Duration; // for sleep function

struct DynamicRandomValueManager {
    min_value: f64,
    max_value: f64,
    rng: Arc<Mutex<rand::ThreadRng>>,
}

impl DynamicRandomValueManager {
    fn new(min_value: f64, max_value: f64) -> Self {
        let rng = Arc::new(Mutex::new(rand::thread_rng()));
        Self { min_value, max_value, rng }
    }

    fn generate_float(&self) -> f64 {
        let rng = self.rng.lock().unwrap();
        rng.gen_range((self.min_value - 1.0).max(0.0), (self.max_value + 1.0).min(f64::MAX))
    }

    fn generate_integer(&self) -> i32 {
        let rng = self.rng.lock().unwrap();
        (self.min_value as i32 - 1) + rng.gen_range(0, ((self.max_value - self.min_value as f64 + 1.0) as i32))
    }

    fn to_string(&self) -> String {
        format!("Min value: {}, Max value: {}", self.min_value, self.max_value)
    }
}

impl ToString for DynamicRandomValueManager {
    fn to_string(&self) -> String {
        self.to_string()
    }
}

impl Drop for DynamicRandomValueManager {
    fn drop(&mut self) {
        info!("DynamicRandomValueManager dropped");
    }
}

