// Custom error structure
typedef struct {
    const char* message;
    bool freed;
} Error;

Error* error_new(const char* message) {
    Error* err = malloc(sizeof(Error));
    if (!err) return NULL;
    err->message = message;
    err->freed = false;
    return err;
}

void error_free(Error* err) {
    if (err && !err->freed) {
        free(err);
        err->freed = true;
    }
}

// Memory pool for efficient allocation and deallocation
typedef struct MemPool {
    size_t capacity;
    size_t used;
    void** data;
} MemPool;

MemPool* mempool_new(size_t initial_capacity) {
    MemPool* pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->data = calloc(initial_capacity, sizeof(void*));
    if (!pool->data) {
        error_free(pool);
        return NULL;
    }
    return pool;
}

void* mempool_alloc(MemPool* pool, size_t size) {
    if (pool->used >= pool->capacity) {
        pool->capacity *= 2;
        pool->data = realloc(pool->data, pool->capacity * sizeof(void*));
        if (!pool->data) return NULL;
    }
    void* ptr = pool->data[pool->used++];
    memset(ptr, 0, size);
    return ptr;
}

void mempool_free(MemPool* pool) {
    free(pool->data);
    error_free(pool);
}

// Main function
int main() {
    MemPool* pool = mempool_new(16);
    if (!pool) return 1; // Handle memory allocation failure

    time_t start = time(NULL);

    int N, minValue, maxValue;
    scanf("%d%d%d", &N, &minValue, &maxValue);

