        goto cleanup;
    }

    int* records = mempool_alloc(pool, N * sizeof(int));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array.\n");
        goto cleanup;
    }

    log_err = error_new("Initialization succeeded.");

    for (size_t i = 0; i < N; ++i) {
        keys[i] = i;
        offsets[i] = -1;
    }

    srand(start);

    int* unique_values = malloc((N + 1) * sizeof(int)); // Buffer for unique values
    size_t used = 0;

    for (size_t i = 0; i < N; ) {
        int record_val = rand() % (maxValue - minValue + 1) + minValue;
        if (used <= unique_values[record_val]) {
            records[i] = record_val;
            used += 1;
            unique_values[record_val]++;
            i++;
        }
    }

cleanup:
    free(unique_values);
    error_free(log_err);
    mempool_free(pool);

    // Helper function to find and print the largest integer in the array
    int find_largest(int* arr, size_t size) {
