```python
import threading
import functools
import abc
import json
import os
import time
import requests
from collections.abc import Callable

class IJSONProcessor(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    async def process(self, json_data: str) -> dict:
        pass

class JSONProcessorFactory(metaclass=abc.ABCMeta):
    @staticmethod
    @abc.abstractmethod
    def create():
        pass

class ThreadSafeRegistry:
    def __init__(self):
        self._lock = threading.Lock()
        self._registrar = {}

    def register(self, id: str, factory_func: Callable[..., IJSONProcessor]) -> None:
        with self._lock:
            if id not in self._registrar:
                self._registrar[id] = factory_func
            else:
                raise ValueError(f"ID {id} already registered.")

    def get_factory(self, id: str) -> Callable[..., IJSONProcessor]:
        with self._lock:
            if id in self._registrar:
                return self._registrar[id]
            raise KeyError(f"ID {id} not found.")

class JSONProcessingFramework:
    def __init__(self, registry: ThreadSafeRegistry):
        self._registry = registry

    async def create_processor(self, id: str) -> IJSONProcessor:
        return await functools.wraps(self._registry.get_factory(id))(self._registry.get_factory(id).create)()

    async def process_json(self, json_data: str, processor_id: str = None) -> dict:
        if not processor_id:
            processor = await self.create_processor("default")
        else:
            processor = await self.create_processor(processor_id)

        start_time = time.time()
        result = await processor.process(json_data)
        elapsed_time = time.time() - start_time

        return result, {"elapsed_time": elapsed_time}

    # Add your logging function here, using a suitable logger library like rich or logging
