typedef struct Node {
    char value;
    int priority;
    struct Node* next;
} Node;

Node* init_node(char c, int prio) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Could not allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    new_node->value = c;
    new_node->priority = prio;
    new_node->next = NULL;
    return new_node;
}

Node* create_list(int size, void(*init_func)(Node* node)) {
    int i;
    Node* head = init_node('S', 1);
    Node* current = head;

    for (i = 2; i <= size; ++i) {
        current->next = init_node(0, 0); // Initialize new node with default values
        if (!current->next) {
            fprintf(stderr, "Error: Could not allocate memory.\n");
            free_list(head);
            exit(EXIT_FAILURE);
        }
        current = current->next;
        init_func(current); // Call user-provided function to set node values
    }

    return head;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Example user-provided function to set node values
