            record->offset = get_current_time(); // Get current time
            record->key = ... // generate key from external API
            record->value = rand() % (max_value - min_value + 1) + min_value;
            // Lock the mutex to insert the new record into the data structure
            pthread_mutex_lock(&mutex_);
            records_count_++;
            if (records_count_ <= max_records) {
                data_[record->key] = record;
            } else {
                // Compact the data store if it reaches the maximum number of records
                compact();
                data_[record->key] = record;
            }
            pthread_mutex_unlock(&mutex_);
        }
        return nullptr;
    }

    void* api2_callback(void* arg) {
        // Implement API call logic here
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(api_interval));
            int value = ... // generate random value within the specified range from external API
            // Lock the mutex to iterate through the data structure and find a record with the key "0"
            pthread_mutex_lock(&mutex_);
            auto it = data_.find(0);
            if (it != data_.end()) {
                it->second->value = value;
            }
            pthread_mutex_unlock(&mutex_);
        }
        return nullptr;
    }

    void compact() {
        // Implement memory compaction logic here
        ...
    }

public:
    DataStore() {
        // Initialize mutex and start API callback threads
        pthread_mutex_init(&mutex_, NULL);
        pthread_t api1_thread;
        pthread_t api2_thread;
        pthread_create(&api1_thread, NULL, &DataStore::api1_callback, this);
        pthread_create(&api2_thread, NULL, &DataStore::api2_callback, this);
    }

    ~DataStore() {
        // Cleanup API callback threads and free allocated memory
        pthread_mutex_destroy(&mutex_);
        pthread_join(api1_thread, nullptr);
        pthread_join(api2_thread, nullptr);
        for (auto& it : data_) {
            munmap(it.second, record_size);
        }
    }

    Record* getRecordByKey(int key) const {
        // Lock the mutex and return the record with the given key if found, otherwise return null
        pthread_mutex_lock(&mutex_);
        auto it = data_.find(key);
        Record* record = (it != data_.end()) ? it->second : nullptr;
        pthread_mutex_unlock(&mutex_);
        return record;
    }
};
