void init_arrays(size_t* sizes, size_t total_elements, bool* success) {
    double* doubles = NULL;
    char* chars1 = NULL, *chars2 = NULL;
    struct data** data_ptrs = NULL;
    status_t* statuses = NULL;

    if (total_elements > 10000 || sizes[0] > total_elements) {
        fprintf(stderr, "Invalid initialization size\n");
        goto cleanup;
    }

    doubles = malloc(total_elements * sizeof(double));
    chars1 = malloc(sizes[1] * sizeof(char));
    chars2 = malloc(sizes[2] * sizeof(char));
    data_ptrs = malloc(sizes[3] * sizeof(struct data*));
    statuses = malloc(sizes[4] * sizeof(status_t));

    if (!doubles || !chars1 || !chars2 || !data_ptrs || !statuses) {
        fprintf(stderr, "Out of memory\n");
        goto cleanup;
    }

    size_t max_index = total_elements - 1;
    double multiplier = (double)max_index / 10.0;
    double min_value = -10 * multiplier;
    double max_value = 10 * multiplier;

    for (size_t i = 0; i < total_elements; ++i) {
        double d = min_value + ((double)i / multiplier);
        doubles[i] = d * d; // Using a mathematical formula to populate the array

        if (i < sizes[1])
            chars1[i] = 'a' + i % 26;

        if (i < sizes[2])
            chars2[i] = i % 3 == 0 ? 'X' : 'O';

        if (i < sizes[3]) {
            data_ptrs[i] = malloc(sizeof(struct data));
            if (!data_ptrs[i]) {
                fprintf(stderr, "Out of memory\n");
                goto cleanup;
            }
            data_ptrs[i]->id = i;
            data_ptrs[i]->value = doubles[i];
            data_ptrs[i]->type = i % 3 == 0 ? 'A' : (i % 2 == 0 ? 'B' : 'C');
        }

        if (i < sizes[4]) {
            statuses[i] = (doubles[i] > 1.0) ? SUCCESS : FAILED;
        }
    }

    success[0] = true;

cleanup:
    if (!success[0]) {
        for (size_t i = 0; i < sizes[3]; ++i) {
            if (data_ptrs[i]) free(data_ptrs[i]);
        }
        free(data_ptrs);

        free(chars1);
        free(chars2);
        free(statuses);
        free(doubles);
    }
}
