#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Custom error handling structure
typedef struct Error {
    int code;
    char* message;
} Error;

// Custom record structure
typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

// Function to validate uniqueness of keys and handle allocation errors
Error validateKey(int* keys, size_t index, size_t N) {
    if (index >= N || keys[index] != -1) {
        return (Error){.code = 1, .message = "Key already in use"};
    }
    return (Error){.code = 0, .message = nullptr};
}

// Function to generate a random number within a specified range
int generateRandomNumber(int minValue, int maxValue) {
    return rand() % (maxValue - minValue + 1) + minValue;
}

// Function to manage dynamic memory allocation and file operations under stringent resource constraints
void handleDynamicRecordsAndFiles(size_t N, int minValue, int maxValue, const char* baseFilename, bool isDebugLoggingEnabled) {
    // Allocate keys array and initialize values with -1 to indicate unused
    int* keys = (int*)calloc(N, sizeof(int));

    // Allocate offsets array with a valid range of long integers
    long* offsets = (long*)malloc((size_t)maxValue * sizeof(long));

    // Allocate records array with memory for N structures
    Record* records = (Record*)calloc(N, sizeof(Record));

    // Initialize logging framework
    FILE* logFile;
    if (isDebugLoggingEnabled) {
        char logFileName[256];
        sprintf(logFileName, "%s_debug.log", baseFilename);
        logFile = fopen(logFileName, "w");
    } else {
        logFile = stderr;
    }

    // Loop through N iterations with error checking
    for (size_t i = 0; i < N; ++i) {
        Error err = validateKey(keys, i, N);
        if (err.code != 0) {
            fprintf(logFile, "Error: %s\n", err.message);
            continue;
        }

        keys[i] = i; // Mark key as used

        err = validateKey((int*)offsets, records[i].value, (size_t)maxValue);
        if (err.code != 0) {
            fprintf(logFile, "Error: %s\n", err.message);
            continue;
        }

        records[i].key = i; // Populate key for record
        records[i].value = generateRandomNumber(minValue, maxValue); // Generate random value for record
        offsets[records[i].value] = (long)i; // Update offset with corresponding index
    }

    // Modify filename extension based on specific criteria
    char filenameExt[16];
    sprintf(filenameExt, "_%lu.dat", N);
    strcat(baseFilename, filenameExt);

    // Open file for writing and write records data
    FILE* outputFile = fopen(baseFilename, "w");
    if (outputFile == nullptr) {
        fprintf(logFile, "Error: Failed to open output file\n");
        return;
    }

    // Iterate through records and write data to output file
    for (size_t i = 0; i < N; ++i) {
        fprintf(outputFile, "%ld %d\n", offsets[records[i].value], records[i].key);
    }

    // Cleanup resources and close files
    free(keys);
    free(offsets);
    fclose(logFile);
    fclose(outputFile);
}
