    task->command = command;
    task->next = NULL;
    task->last_executed = timestamp;
    return task;
}

// Function to initialize a new dynamic task queue with specified size
void init_queue(struct queue* queue, int size, task_command_generator generator) {
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = initialize_task(generator(), time(NULL));
    queue->tail = queue->head;

    for (int i = 1; i < size; ++i) {
        struct task* new_task = initialize_task(generator(), time(NULL));
        queue->tail->next = new_task;
        queue->tail = new_task;
    }
}

// Thread-safe function to pop tasks from the queue and submit them to the external scheduler API
void process_queue(struct queue* queue, void (*submit_function)(char)) {
    pthread_mutex_lock(&queue->lock);

    struct task* current = queue->head;
    while (current != NULL) {
        struct task* next = current->next;

        // Implement task prioritization and resource throttling based on the desired performance characteristics

        submit_function(current->command);
        current->last_executed = time(NULL);

        current = next;
    }

    pthread_mutex_unlock(&queue->lock);
}

