// Scalable data structure for 'record' structures
template<typename T>
class RecordArray {
private:
    std::vector<T> data_;
    size_t capacity_ = 0;
public:
    explicit RecordArray(size_t capacity) : capacity_(capacity) {
        if (capacity < 1) throw std::invalid_argument("Capacity should be greater than zero.");
        data_.resize(capacity);
    }

    T& operator[](size_t index) {
        if (index >= capacity_) throw std::out_of_range("Index out of range.");
        return data_[index];
    }

    void resize(size_t newCapacity) {
        if (newCapacity <= capacity_) return;
        data_.resize(newCapacity);
        capacity_ = newCapacity;
    }
};

// Function for dynamic memory allocation, log, and initialization
void initMemory(Logger& logger, int N, int minValue, int maxValue, RecordArray<int>* offsets, RecordArray<int>* keys, std::vector<RecordArray<int>>* records) {
    // Implement retry mechanism for memory allocation failures
    auto retry = [](auto task) {
        for (size_t i = 0; i < 10; ++i) {
            try {
                return task();
            } catch (const std::exception& e) {
                if (i == 9) throw e;
            }
        }
    };

    // Allocate dynamic memory for offsets and keys, ensuring thread-safety
    auto offsetLock = std::mutex();
    offsets->resize(N);
    std::fill_n(offsets->begin(), N, -1);
    {
        std::lock_guard<std::mutex> lock(offsetLock);
        for (size_t i = 0; i < N; ++i) {
            if (offsets->at(i) == -1) {
                offsets->at(i) = i;
                break;
            }
        }
    }

    // Allocate dynamic memory for keys, ensuring thread-safety
    auto keyLock = std::mutex();
    keys->resize(N);
    std::iota(keys->begin(), keys->end(), 0);

    // Initialize records with random values within the specified range
    std::uniform_int_distribution<int> distrib(minValue, maxValue);
    auto recordLock = std::mutex();
    records->resize(1, RecordArray<int>(N));
    {
        std::lock_guard<std::mutex> lock(recordLock);
        for (auto& record : *records) {
            if (record.capacity() < N) {
                record.resize(N);
            }
            std::generate(record.begin(), record.end(), [&distrib]() -> int {
                int value;
                do {
                    value = distrib(*global_randomEngine);
                } while (find(record.begin(), record.end(), value) != record.end());
                return value;
            });
        }
    }

    // Logging and timing information
    auto start = std::chrono::high_resolution_clock::now();
    logger.log("Successful memory allocation and initialization");
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    logger.log(std::to_string(duration) + "ms");
}

// Helper function to find and print the largest integer in an array
void findLargestInteger(const std::vector<int>& numbers) {
    int maxValue = std::numeric_limits<decltype(maxValue)>::min();
    for (auto number : numbers) {
        if (number > maxValue && std::is_integer(std::begin(numbers), std::end(numbers))) {
