    double val;
    int index;
};

// Define a logging structure for integration with a modular logging framework
typedef struct Logger {
    void (*log)(const char*, ...);
} Logger;

void log_memory(Logger* logger, const char* message, void* ptr, size_t size) {
    time_t current_time = time(NULL);
    struct tm* local_time = localtime(&current_time);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
    logger->log("%s Allocated %zu bytes at 0x%p: %s\n", timestamp, size, ptr, message);
}

void* allocate_safe(size_t nmemb, size_t size, Logger* logger) {
    void *ptr = mmap(NULL, nmemb * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
    log_memory(logger, "Memory", ptr, nmemb * size);
    return ptr;
}

void free_safe(void* ptr, size_t size) {
    if (ptr != nullptr) {
        munmap(ptr, size);
        log_memory(logger, "Freed memory", ptr, size);
    }
}

// Thread-safe random number generation using pthread_rwlock_t
pthread_rwlock_t rwlock;
double minVal = 0.0;
double maxVal = 1.0;
int num_generated = 0;

void rand_init() {
    pthread_rwlock_init(&rwlock, NULL);
}

double random_in_range(double min, double max) {
    if (min > max) {
        double temp = min;
        min = max;
        max = temp;
    }

    pthread_rwlock_wrlock(&rwlock);
    double rand_value = min + ((max - min) * (double)rand() / RAND_MAX);
    num_generated++;
    pthread_rwlock_unlock(&rwlock);

    return rand_value;
}

void init_arrays(struct data** data, int* indices, double* values, Logger* logger) {
    *indices = (int*)allocate_safe(M, sizeof(int));
    for (int i = 0; i < M; ++i)
        (*indices)[i] = i;

    *data = (struct data*)allocate_safe(M, sizeof(struct data));
    for (int i = 0; i < M; ++i) {
        double val;
        do {
            val = random_in_range(minVal, maxVal);
        } while (num_generated <= i && val == values[i]);
        (*data)[i].val = val;
        (*data)[i].index = i;
    }
}

void clean_up(struct data* data, int* indices, double* values) {
    free_safe(data, sizeof(struct data) * M);
    free_safe(indices, sizeof(int) * M);
    free_safe(values, sizeof(double));
}
