void create_directory(const char *base_path, const char *new_dir) {
    char full_path[4096]; // Maximum path length on most systems
    char *curr_path = getcwd(full_path, sizeof(full_path));
    if (!curr_path) {
        perror("Failed to get current working directory");
        return;
