    records = calloc(num_records, sizeof(record*));
    if (!records) {
        perror("Failed to allocate records array memory");
        free(offsets);
        free(keys);
        return;
    }

    pthread_t threads[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        int rc = pthread_create(&threads[i], NULL, &random_record, &range);
        if (rc) {
            perror("Failed to create thread");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        record *rec;
        rc = pthread_join(threads[i], (void **) &rec);
        if (rc) {
            perror("Failed to join thread");
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        pthread_mutex_lock(&records_mutex);
        records[i] = rec;
        pthread_mutex_unlock(&records_mutex);
    }
