        while ((*component)->unique_keys[i]) {
            // The key is not unique, try again with a new one
            (*component)->records[i].key = i;
            pthread_mutex_unlock(&(*component)->mutex);
            (*component)->unique_keys[i] = 0;
            for (size_t j = 0; j < i; ++j) {
                if ((*component)->records[j].key == (*component)->records[i].key) {
                    // The key is already in use, try again with a new one
                    goto retry;
                }
            }
            pthread_mutex_lock(&(*component)->mutex);
        }
        (*component)->unique_keys[i] = 1;
        retry: {};
        pthread_mutex_unlock(&(*component)->mutex);
    }

    // Initialize the record array with random values within a given range
