int isUnique(int key, int size, int* existingKeys) {
    for (int i = 0; i < size; ++i) {
        if (existingKeys[i] == key) return 0;
    }
    return 1;
}

long randomValue(long min, long max) {
    return rand() % ((max - min) + 1) + min;
}

void* generateRandomString(int length, char* characterSet) {
    void* result = malloc(length + 1);
    if (!result) return NULL;
    memset(result, '\0', length + 1);
    for (int i = 0; i < length; ++i) {
        ((char*)result)[i] = characterSet[rand() % strlen(characterSet)];
    }
    return result;
}

void resizeRecords(Record** records, int capacity) {
    Record* newRecords = realloc(*records, sizeof(Record) * capacity);
    if (!newRecords) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return;
    }
    memmove(newRecords, *records, sizeof(Record) * (*capacity));
    free(*records);
    *records = newRecords;
}

int* findEmptyRecord(Record** records, int capacity) {
    for (int i = 0; i < capacity; ++i) {
        if ((*records)[i].key == -1) return &((*records)[i].key);
    }
    return NULL;
}

