    if (!sysData) {
        fprintf(stderr, "Failed to allocate memory for system data.\n");
        return NULL;
    }

    pthread_mutex_init(&sysData->mutex, NULL);

    sysData->records = (Record*)malloc(recordCapacity * sizeof(Record));
    if (!sysData->records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        goto error;
    }

    memset(sysData->records, 0, recordCapacity * sizeof(Record));

    sysData->id = (char*)generateRandomString(strlen(characterSet) * 3, characterSet);
    if (!sysData->id) {
        fprintf(stderr, "Failed to generate unique identifier.\n");
        goto error;
    }

    sysData->configParams = (int*)malloc(configParamSize * sizeof(int));
