#include <sys/mman.h> // for memalign and malloc_usable_size

typedef struct {
    long offset;
    int key;
} Record;

typedef struct HashTableEntry {
    int key;
    struct HashTableEntry* next;
} HashTableEntry;

Record* initializeSystemComponent(unsigned int size, unsigned int seed, unsigned int config_size, unsigned int record_count, unsigned int range) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    unsigned long memory_limit = 1048576UL; // 1MB for example

    // Generate unique keys and hash table for efficient access
    HashTableEntry* keys = malloc(sizeof(HashTableEntry) * size);
    for (unsigned int i = 0; i < size; ++i) {
        int key = i;
        while (true) {
            bool unique = true;
            for (unsigned int j = 0; j < i; ++j) {
                if (keys[j].key == key) {
                    key = rand_r(&seed);
                    unique = false;
                    break;
                }
            }
            if (unique) break;
        }
        keys[i].key = key;
        keys[key].next = &keys[i];
    }

    // Allocate and initialize system component's records array
    Record* records = calloc(record_count, sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    // Initialize offset and key fields in the records array
    unsigned int offset = 0;
    for (unsigned int i = 0; i < record_count; ++i) {
        while (true) {
            int key = keys[offset].key;
            if (!key) {
                records[i].offset = rand() % range;
                records[i].key = key;
                keys[offset] = NULL;
                break;
            }
            offset = (offset + 1) % size;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Allocate and initialize configuration parameters array using a hash table for quick lookups
    unsigned int config_key_count = 0;
    int* config_params = calloc(config_size, sizeof(int));
    if (!config_params) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Validate and store configuration parameters
    HashTableEntry* config_table = malloc(sizeof(HashTableEntry) * config_size);
    for (unsigned int i = 0; i < config_size; ++i) {
        int param = rand() % range;
        if (param < 0 || param >= config_size) {
            fprintf(stderr, "Invalid configuration parameter: %d\n", param);
            exit(EXIT_FAILURE);
        }
        config_params[i] = param;
        config_table[param].key = i;
    }

    // Allocate memory for and initialize an array of record structures
    unsigned int record_size = sizeof(int) * record_count;
    int* records_data = mmap(NULL, record_size, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records_data == MAP_FAILED) {
        perror("Memory mapping failed");
        exit(EXIT_FAILURE);
    }

    for (unsigned int i = 0; i < record_count; ++i) {
        *(int*)(records_data + i * sizeof(int)) = rand() % range;
    }

    // Implement thread-safe memory management using a mutex
    pthread_mutex_lock(&mutex);
    // Monitor memory usage and adapt memory allocation strategies as needed
    unsigned long total_memory_usage = (unsigned long)malloc_usable_size(NULL) + records_data - (void*)config_params;
    if (total_memory_usage > memory_limit) {
        fprintf(stderr, "Memory usage exceeded limit: %lu\n", total_memory_usage);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&mutex);

    // Provide detailed logging and monitoring capabilities
    time_t start_time = time(NULL);
    struct tm* local_time = localtime(&start_time);
    FILE* logfile = fopen("system_component_log.txt", "w");
    fprintf(logfile, "Initialization started at %s\n", asctime(local_time));
    fprintf(logfile, "Size: %u\n", size);
    fprintf(logfile, "Config size: %u\n", config_size);
    fprintf(logfile, "Record count: %u\n", record_count);
    fprintf(logfile, "Range: %u\n", range);
    fclose(logfile);

    return records;
