["```javascript
angular.module('myApp').service('DataRefreshService', ['$q', function ($q) {
    var fieldList = new Map();

    function addField(fieldName, fieldInstance) {
        if (!fieldList.has(fieldName)) {
            fieldList.set(fieldName, new Set());
        }
        fieldList.get(fieldName).add(fieldInstance);
    }

    function removeField(fieldName, fieldInstance) {
        let fields = fieldList.get(fieldName);
        if (fields) {
            fields.delete(fieldInstance);
            if (fields.size === 0) {
                fieldList.delete(fieldName);
            }
        }
    }

    function refreshData(id, url, fieldNames) {
        let deferred = $q.defer();
        let promises = [];

        fieldNames.forEach(function (fieldName) {
            let promisesForField = [];
            if (fieldList.has(fieldName)) {
                fieldList.get(fieldName).forEach(function (fieldInstance) {
                    promisesForField.push(new Promise(function (resolve, reject) {
                        function updateField(result) {
                            fieldInstance.value = result;
                            resolve();
                        }

                        window.parent.postMessage({ id, action: 'updateField', name: fieldName, value: fieldInstance.value }, '*');

                        let timeoutId = setTimeout(function () {
                            clearTimeout(timeoutId);
                            reject('Timeout while waiting for parent response.');
                        }, 5000);

                        window.addEventListener('message', function (event) {
                            if (event.data.id === id && event.data.action === 'updateFieldResponse') {
                                clearTimeout(timeoutId);
                                updateField(event.data.value);
                                resolve();
                            }
                        });
                    }));
                });
                promises.push($q.all(promisesForField));
            }
        });

        $q.all(promises).then(function () {
            deferred.resolve();
        }, function (error) {
            deferred.reject(error);
        });

        return deferred.promise;
    }

    return {
        addField: addField,
        removeField: removeField,
        refreshData: refreshData
    };
}]);
```

