}

char* generate_unique_string(unsigned long id, char item_cache[ num_items ][256]) {
    static const char alphabet[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char buffer[256];
    memset(buffer, 0, sizeof(buffer));

    for (int i = 0; i < 8; ++i) {
        buffer[i] = alphabet[id % 62];
        id /= 62;
    }

    // Check if the generated string is already in the cache and generate a unique one if it is
    for (unsigned long j = 0; j < num_items; ++j) {
        if (strcmp(buffer, item_cache[j]) == 0) {
            return generate_unique_string(id, item_cache);
        }
    }

    return buffer;
}

double rand_in_range(double min, double max) {
    return rand() / (RAND_MAX / (max - min)) + min;
}

double calculate_weighted_average(double current, double weight) {
    return (current * (1.0 - weight)) + (weight * current);
}
