// Custom memory pool structure
typedef struct MemoryPool {
    void *memory;
    size_t allocated_size;
    size_t free_size;
} MemoryPool;

// Initialize a custom memory pool with the given size
MemoryPool* init_memory_pool(size_t size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->memory = calloc(1, size);
    mp->allocated_size = size;
    mp->free_size = size;
    return mp;
}

// Allocate memory from the custom memory pool
void* mempool_alloc(MemoryPool *mp, size_t size) {
    if (mp->free_size < size) {
        // Extend the memory pool if necessary
        mp->memory = realloc(mp->memory, mp->allocated_size + size);
        mp->allocated_size += size;
        mp->free_size += size;
    }

    void *result = mp->memory;
    mp->memory += size;
    mp->free_size -= size;

    return result;
}

// Free memory back to the custom memory pool
void mempool_free(MemoryPool *mp, void *ptr) {
    mp->free_size += (mp->memory - ptr);
    mp->memory = ptr;
}

// Initialize arrays and populate record structures with random unique values
long* init_arrays(int N, int minValue, int maxValue, MemoryPool *mp) {
