#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long *strings;
    int key;
} Record;

struct mem_block {
    void *ptr;
    size_t size;
    pthread_mutex_t lock;
};

struct mem_pool {
    struct mem_block *blocks;
    size_t capacity;
    size_t count;
};

void* mem_block_alloc(struct mem_pool *pool, size_t size) {
    pthread_mutex_lock(&pool->blocks[size]->lock);
    void *ptr = pool->blocks[size]->ptr;
    if (ptr == NULL || pool->blocks[size]->size < size) {
        free(pool->blocks[size]->ptr);
        pool->blocks[size]->ptr = malloc(size);
        pool->blocks[size]->size = size;
    }
    void *result = pool->blocks[size]->ptr;
    pool->blocks[size]->ptr = ((char*)result) + size;
    pthread_mutex_unlock(&pool->blocks[size]->lock);
    return result;
}

void mem_block_free(struct mem_pool *pool, void *ptr, size_t size) {
    pthread_mutex_lock(&pool->blocks[size]->lock);
    pool->blocks[size]->ptr = (char*)ptr - size;
    pthread_mutex_unlock(&pool->blocks[size]->lock);
}

void mem_pool_init(struct mem_pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->count = 0;
    pool->blocks = malloc(sizeof(struct mem_block)*capacity);
    for (size_t i = 0; i < capacity; ++i) {
        pool->blocks[i] = malloc(sizeof(struct mem_block));
        pool->blocks[i]->ptr = NULL;
        pool->blocks[i]->size = 0;
        pthread_mutex_init(&pool->blocks[i]->lock, NULL);
    }
}

