    for (size_t i = 0; i < count; ++i) {
        Record *record = calloc(1, sizeof(Record));
        record->strings = (long*)mem_block_alloc(string_pool, offsets[i]);
        record->key = keys[i];
        pthread_create(&threads[i], NULL, generate_string_in_thread, (void*)record);
    }
    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* generate_string_in_thread(void *arg) {
