    int newCapacity = dataset->N * 2;
    Record* newRecords = realloc(dataset->records, newCapacity * sizeof(Record));
    if (!newRecords) {
        // Handle memory allocation failure
    }
    long* newOffsets = realloc(dataset->offsets, (newCapacity + 1) * sizeof(long));
    if (!newOffsets) {
        free(newRecords);
        // Handle memory allocation failure
    }
    dataset->records = newRecords;
    dataset->offsets = newOffsets;
    for (size_t i = dataset->N; i < newCapacity; ++i) {
        dataset->records[i].value = -1; // Default value
        dataset->offsets[i] = dataset->offsets[i - 1] + 1;
    }
}

void resize(struct Dataset* dataset) {
