    pthread_t resizeThread;
    if (pthread_create(&resizeThread, NULL, resize_helper, dataset)) {
        // Handle thread creation failure
    }
    pthread_join(resizeThread, NULL);
}

void create_record(struct Dataset* dataset, int key, int value) {
