    if (i < dataset->N) {
        pthread_mutex_unlock(&dataset->mutex);
    } else {
        resize(dataset);
        pthread_mutex_unlock(&dataset->mutex);
        create_record(dataset, key, value); // Retry with resized dataset
    }
