constexpr size_t DEFAULT_BACKOFF = 100;
constexpr size_t MAX_RETRIES = 5;

struct record {
    int value;
};

typedef struct record *record_ptr;

static std::mutex g_lock; // Global lock for thread-safety
static atomic<size_t> g_max_concurrent_requests = ATOMIC_VAR_INIT(1);
static atomic<int64_t> g_total_requests = ATOMIC_VAR_INIT(0);
static atomic<int64_t> g_success_requests = ATOMIC_VAR_INIT(0);
static atomic<int64_t> g_failure_requests = ATOMIC_VAR_INIT(0);
static atomic<size_t> g_max_failed_attempts = ATOMIC_VAR_INIT(MAX_RETRIES);

// Memory allocation helper function with retry mechanism
record_ptr* reallocate(record_ptr* ptr, size_t new_size) {
    while (true) {
        ptr = static_cast<record_ptr*>(realloc(ptr, new_size * sizeof(record)));
        if (ptr != nullptr) {
            memset(ptr, 0, new_size * sizeof(record));
            return ptr;
        }

        // Backoff before retrying
        usleep(DEFAULT_BACKOFF);
    }
}

// Function for generating a dataset of unique random integers with given parameters N, minValue, maxValue.
void generate_dataset(size_t N, int minValue, int maxValue) {
    if (N == 0 || maxValue < minValue) {
        return;
    }

    // Memory allocation for keys and offsets arrays with retry mechanism
    record_ptr keys = reallocate(static_cast<record_ptr>(calloc(N, sizeof(record))), N);
    long* offsets = reallocate(static_cast<long*>(calloc(N, sizeof(long))), N);

    // Initialize keys array with sequential integers from 0 to N-1
    for (size_t i = 0; i < N; ++i) {
        keys[i].value = i;
    }

    std::set<int> used_values; // Data structure to track unique random integers
    record_ptr current_record = keys;
    long current_offset = 0;

    // Concurrent generation of unique random integers with external data source integration
    for (size_t i = 0; i < N && g_total_requests < std::numeric_limits<decltype(g_total_requests)>::max(); ++i) {
        // Atomic increment to ensure concurrent requests are handled correctly
        g_lock.lock();
        size_t concurrent_requests = g_max_concurrent_requests.load(std::memory_order_acquire);
        g_total_requests.fetch_add(1, std::memory_order_release);
        g_lock.unlock();

        if (concurrent_requests >= g_max_concurrent_requests.load(std::memory_order_relaxed)) {
            continue;
        }

        int random_value = generate_random_int(minValue, maxValue);

        // Thread-safe data structure to store and check for uniqueness
        g_lock.lock();
        if (!used_values.count(random_value)) {
            used_values.insert(random_value);
            current_record[current_offset].value = random_value;
            offsets[current_value] = current_offset++;
        }
        g_lock.unlock();
    }

    // Logging and error handling for successful operations, retries, and failures
    if (g_total_requests > 0) {
        g_success_requests.fetch_add(g_total_requests - g_failure_requests, std::memory_order_release);
    }

    free(keys);
    free(offsets);
}
