// Thread-safe logging function.
void log(const std::string& msg) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);
    std::cout << msg << std::endl;
}

void initRecords(size_t N, int minValue, int maxValue) {
    auto rng = std::default_random_engine{};
    auto uniformDist = std::uniform_int_distribution<>{minValue, maxValue};

    if (!records.empty()) {
        // Cleanup previously allocated memory.
        records.clear();
    }

    records.resize(N);

    std::unique_ptr<std::vector<Record>> tmp;

    size_t attempts = 0;
    while (true) {
        try {
            tmp.reset(new std::vector<Record>());
            break;
        } catch (...) {
            if (++attempts > 10) {
                log("Memory allocation failed too many times, giving up.");
                return;
            }
            log("Attempting to allocate memory for records again...");
            std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Backoff before retrying.
        }
    }

    *tmp = records;

    std::unique_ptr<Record> currentValue;
    std::vector<int> uniqueValues;

    for (size_t i = 0; i < N; ++i) {
        int value;

        do {
            value = uniformDist(rng);
        } while (std::find(uniqueValues.begin(), uniqueValues.end(), value) != uniqueValues.end());

        unique_lock<std::mutex> lock(mtx);
        log("Generated unique value: " + std::to_string(value));
        uniqueValues.push_back(value);

        currentValue.reset(new Record{value});

        if (currentValue == nullptr) {
            log("Memory allocation for record failed, cleaning up...");
            *tmp = {}; // Clear records vector to avoid dangling pointers.
            throw std::bad_alloc();
        }

        (*tmp)[i] = std::move(*currentValue);
    }
}

// Provide a way to resize arrays and record structures if initial allocation fails due to insufficient memory.
void resize(size_t& N) {
    size_t newN = N * 2;
    log("Resizing data structures to accommodate more elements.");
    offsets.resize(newN);
    keys.resize(newN);
    records.resize(newN);
    N = newN;
}

void initializeDataStructures(size_t N, size_t minValue, size_t maxValue) {
    if (N <= 0 || maxValue < minValue) {
        throw std::invalid_argument("Invalid arguments: N must be greater than zero and maxValue must be greater or equal to minValue.");
    }

    offsets.resize(N);
    keys.assign(N, 0);

    if (records.empty()) {
        initRecords(N, minValue, maxValue);
    }
}

std::vector<long> offsets; // Provide a global storage for the offset values.
