// Custom memory pool for efficient dynamic allocations
typedef struct MemoryPool {
    void *pool;
    size_t capacity;
    size_t allocated;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pool->capacity = size;
    pool->allocated = 0;
    return pool;
}

void* memory_pool_malloc(MemoryPool *pool, size_t size) {
    if (pool->allocated + size > pool->capacity) {
        void *new_pool = mmap(NULL, 2 * pool->capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_pool == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        memcpy(new_pool, pool->pool, pool->allocated);
        munmap(pool->pool, pool->capacity);
        pool->capacity *= 2;
        pool->pool = new_pool;
    }
    void *ptr = (char *) pool->pool + pool->allocated;
    pool->allocated += size;
    return ptr;
}

// Concurrent hash map for efficient lookups
