HashMap* create_hash_map(int capacity) {
    HashMap *map = malloc(sizeof(HashMap));
    map->capacity = capacity;
    map->offsets = calloc((capacity + 1), sizeof(long));
    map->keys = calloc((capacity + 1), sizeof(int));
    map->mutex = PTHREAD_MUTEX_INITIALIZER;
    return map;
}

void insert_hash_map(HashMap *map, int key, long offset) {
    pthread_mutex_lock(&map->mutex);
    int index = hash(key) % map->capacity;
    while (map->keys[index] != 0 && map->keys[index] != key) {
        index = (index + 1) % map->capacity;
    }
    map->offsets[index] = offset;
    map->keys[index] = key;
    pthread_mutex_unlock(&map->mutex);
}

long get_hash_map(HashMap *map, int key) {
    pthread_mutex_lock(&map->mutex);
    int index = hash(key) % map->capacity;
    while (map->keys[index] != 0 && map->keys[index] != key) {
        index = (index + 1) % map->capacity;
    }
    long result = map->offsets[index];
    pthread_mutex_unlock(&map->mutex);
    return result;
}

