#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <time.h>

typedef struct {
    double value;
    char str[256];
    size_t index;
} element;

struct sort_params {
    element** data;
    size_t* indexes;
    size_t length;
    int ascending;
};

void qsort_elements(void* params) {
    struct sort_params* p = params;
    qsort(p->data, p->length, sizeof(element), compare);
}

int compare(const void* a, const void* b) {
    if (p->ascending)
        return ((element*)a)->value - ((element*)b)->value;
    else
        return ((element*)b)->value - ((element*)a)->value;
}

void* read_csv(const char* filename, element** data, size_t* indexes, size_t* length) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    char line[4096];
    *length = 0;
    size_t current_index = 0;

    while (fgets(line, sizeof(line), file)) {
        element* e = malloc(sizeof(element));
        if (!e) {
            perror("Error allocating memory for an element");
            fclose(file);
            return NULL;
        }

        char* token = strtok(line, ",");
        if (!token) {
            free(e);
            continue;
        }

        double value = strtod(token, NULL);
        if (value == HUGE_VALF) { // NaN or infinite number detection
            free(e);
            continue;
        }

        strncpy(e->str, token, sizeof(e->str));
        e->index = current_index++;

        if (!*data) {
            *data = malloc((*length += 1) * sizeof(element));
            if (!(*data)) {
                perror("Error allocating memory for data array");
                fclose(file);
                return NULL;
            }
        }

        (*data)[*length - 1] = *e;
        (*indexes)[*length - 1] = current_index - 1;
    }

    fclose(file);
    return NULL; // Indicates successful processing
}

int main(int argc, char** argv) {
    if (argc != 3 && argc != 4) {
        fprintf(stderr, "Usage: %s <input-file> [sorting-order(ascending|descending)]\n", argv[0]);
        return 1;
    }

    const char* filename = argv[1];
    int ascending = 1; // Assume ascending sorting by default

    if (argc == 4) {
        if (!strcmp(argv[3], "descending"))
            ascending = -1;
        else if (strcmp(argv[3], "ascending") != 0 && strcmp(argv[3], "descending") != 0) {
            fprintf(stderr, "Invalid sorting order: %s\n", argv[3]);
            return 1;
        }
    }

    element* data = NULL;
    size_t indexes[100000]; // Assuming maximum of 100k elements
    size_t length = 0;

    if (!read_csv(filename, &data, indexes, &length))
        return 1;

    struct sort_params params = { data, indexes, length, ascending };
    pthread_t threads[8]; // Assuming a maximum of 8 threads

    for (size_t i = 0; i < 8 && length > 0; ++i) {
        if (length <= 8 * sizeof(element) / sizeof(element*) + 1) break;
        size_t chunk_start = i * (length / 8);
        size_t chunk_size = (length / 8) - chunk_start + 1;

        params.data = &data[chunk_start];
        params.length = chunk_size;
        pthread_create(&threads[i], NULL, qsort_elements, &params);
    }

    for (size_t i = 0; i < 8; ++i)
        pthread_join(threads[i], NULL);

    // Print or further process the sorted data as needed...

    return 0;
}
