} Transaction;

void parse_transaction(const char* input, Transaction* transaction) {
    char buffer[50]; // Assuming max length for input string
    int i = 0;
    bool is_number = false;

    memset(buffer, 0, sizeof(buffer));

    while (*input && i < sizeof(buffer)) {
        if (*input == ',') {
            if (!is_number) continue; // Skip commas if not a number yet

            buffer[i] = '\0';
            transaction->transaction_id = transaction->transaction_id + 1;
            transaction->timestamp = atol(buffer);
            is_number = false;
        } else if (isdigit((int)*input)) { // Start parsing a number
            buffer[i] = *input;
            is_number = true;
        }

        input++; i++;
    }

    if (!is_number) return; // Return early if no numbers were found

    memset(buffer, 0, sizeof(buffer));
    i = 0;

    while (*input && i < sizeof(buffer)) {
        if (i > 0 && *input == ',') break;

        if (*input == ',' || *input == '\0') {
            buffer[i] = '\0';
            transaction->amount = strtod(buffer, NULL);
            return;
        }

        buffer[i++] = *input++;
    }
}

Transaction* create_transaction_list(int num_transactions) {
    int size = sizeof(Transaction) * num_transactions;
    Transaction* transactions = (Transaction*)malloc(size);

    if (!transactions) {
        fprintf(stderr, "Failed to allocate memory for transaction list\n");
        exit(EXIT_FAILURE);
    }

    memset(transactions, 0, size);
    return transactions;
}

void process_transactions(Transaction* transactions, int num_transactions) {
    // Perform processing on each transaction here
}

void cleanup(Transaction* transactions, int num_transactions) {
    free(transactions);
}

int main() {
    int num_transactions;
    printf("Enter the number of transactions: ");
    scanf("%d", &num_transactions);

    Transaction* transactions = create_transaction_list(num_transactions);
    char input[1024];

    for (int i = 0; i < num_transactions; ++i) {
        printf("Enter transaction %d data (timestamp,amount): ", i + 1);
        scanf("%ld,%s", &transactions[i].timestamp, input);

        parse_transaction(input, &transactions[i]);
    }

    process_transactions(transactions, num_transactions);

    cleanup(transactions, num_transactions);

    return 0;
}
