memory_pool *find_suitable_pool(size_t size) {
    memory_pool *current = head;

    while (current != NULL) {
        if ((current->mem_size - current->used) >= size) {
            break;
        }
        current = current->next;
    }

    return current;
}

my_struct* allocate_structure(int N, int minValue, int maxValue) {
    memory_pool *pool = find_suitable_pool(sizeof(my_struct) + (maxValue - minValue));

    if (!pool) {
        log_error("Failed to find suitable pool");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    my_struct *new_struct = (my_struct*)(pool->mem_start + pool->used);
    if (!new_struct) {
        log_error("Failed to allocate structure from pool");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    // Initialize the structure here, including handling unique keys within [minValue, maxValue] range.

    pool->used += sizeof(my_struct) + (maxValue - minValue);
    pthread_mutex_unlock(&pool->lock);

    return new_struct;
}

void cleanup() {
    memory_pool *current = head, *temp;

    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }

    head = NULL;
}
