type Resource = (String, i32, f64); // Custom resource struct

struct MemoryPool {
    data: Vec<Resource>,
    free_list: Mutex<VecDeque<usize>>,
}

impl MemoryPool {
    fn new(size: usize) -> Self {
        let mut pool = Self {
            data: vec![Resource::default(); size],
            free_list: Mutex::new(VecDeque::new()),
        };
        for i in 0..size {
