// Custom memory pool structure
typedef struct MemoryPool {
    void *memory;
    size_t allocatedSize;
    size_t usedSize;
    pthread_mutex_t mutex;
} MemoryPool;

// Custom macro to handle memory allocation failures
#define ALLOCATE(size)                                                           \
    (void *) ((alloca((1 << 20)) || malloc(size)) || calloc(1, size))

// Global thread-safe data structure to manage state across different calls
static MemoryPool memory_pool;
static pthread_once_t init_once = PTHREAD_ONCE_INIT;

// Function to initialize the arrays and memory pool
void init_resources(size_t M) {
    pthread_mutex_init(&memory_pool.mutex, NULL);
    float *precision_values = ALLOCATE(M * sizeof(float));
    unsigned short *indices = ALLOCATE(M * sizeof(unsigned short));
    data_point *data_array = ALLOCATE(M * sizeof(data_point));

    // Fill indices array with sequential integers
    for (size_t i = 0; i < M; ++i) {
        indices[i] = i;
    }

    // Implement custom retry mechanism to handle duplicate values efficiently
    pthread_mutex_lock(&memory_pool.mutex);
    size_t usedSize = memory_pool.usedSize;
    pthread_mutex_unlock(&memory_pool.mutex);

    for (size_t i = 0; i < M; ) {
        float value = precision_values[i];
        data_point *current_data = &data_array[i++];

        // Use the memory pool to allocate unique and contiguous memory segments for data_points
        pthread_mutex_lock(&memory_pool.mutex);
        while (usedSize >= M) {
            pthread_cond_wait(&memory_pool.cond, &memory_pool.mutex);
        }
        size_t index = usedSize++;
        current_data->value = value;
        current_data->index = indices[index];
        memory_pool.usedSize++;
        pthread_mutex_unlock(&memory_pool.mutex);

        // Ensure the value is unique within the array
        if (i > 1 && current_data->value == data_array[i - 2].value) {
            free(current_data);
            memory_pool.usedSize--;
            continue;
        }
    }
}

// Function to initialize once on first call
void init() {
    pthread_once(&init_once, init_resources, 0);
}

