void* memory_pool_alloc(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void* ptr = (char*)pool->start + pool->used;
    if ((char*)ptr + size > (char*)pool->start + pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void memory_pool_free(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    if ((char*)ptr >= (char*)pool->start && (char*)ptr < (char*)pool->start + pool->size) {
        pool->used -= (char*)ptr - (char*)pool->start;
    }
    pthread_mutex_unlock(&pool->lock);
