typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

long *offsets = NULL;
int *keys = NULL;
Record *records = NULL;
size_t offsets_capacity = 0;
size_t keys_capacity = 0;
size_t records_capacity = 0;
size_t num_records = 0;

const unsigned long MAX_FILE_SIZE = (1ULL << 32); // Max file size is 4GB.
const unsigned int HASH_SEED = 97; // User-provided seed.
const float LOAD_FACTOR = 0.75f; // Load factor for hash table.

unsigned long calculateHash(const char *line, unsigned int seed) {
    unsigned long hash = seed;
    for (size_t i = 0; line[i] != '\0'; ++i) {
        hash += line[i];
        hash *= HASH_SEED;
    }
    return hash % (keys_capacity / LOAD_FACTOR);
}

void reallocate(size_t *array, size_t capacity, size_t size) {
    if (capacity < size) {
        capacity = (capacity * 2 > size) ? capacity * 2 : size;
        array = realloc(array, capacity * sizeof(*array));
        if (!array) exit(1);
    }
}

int main() {
    FILE *file = fopen("large_text_file.txt", "r");
    if (!file) return 1;

    long file_size = 0, prev_offset = -1;
    char line[4096];
    while ((fgets(line, sizeof(line), file)) != NULL && !feof(file)) {
        reallocate(&offsets, offsets_capacity, ++num_records);
        offsets[num_records - 1] = ftell(file);
        prev_offset = offsets[num_records - 1];

        // Allocate keys array when needed.
        if (keys == NULL || keys_capacity <= num_records) {
            reallocate(&keys, keys_capacity, num_records + LOAD_FACTOR * num_records);
        }

        int key = calculateHash(line, HASH_SEED);
        keys[key] = key;

        // Allocate records array when needed.
        if (records == NULL || records_capacity <= num_records) {
            reallocate(&records, records_capacity, num_records + LOAD_FACTOR * num_records);
        }

        records[num_records - 1].offset = offsets[num_records - 1];
        records[num_records - 1].key = keys[key];
        records[num_records - 1].value = rand() % 100 + 1; // Initialize with a random value within [1, 100] range.

        if (prev_offset < file_size) file_size = prev_offset + strlen(line);
    }

    if (fclose(file)) return 1;

    printf("File processed successfully!\n");
    printf("Number of records: %lu\n", num_records);
    printf("File size: %lu\n", file_size);

    // Free allocated memory.
    free(offsets); free(keys); free(records);

    return 0;
}
