        if (minValue > maxValue) throw std::invalid_argument("Invalid range settings: minValue must be less than maxValue.");

        this->maxBufferSize = maxBufferSize;
        this->minValue = minValue;
        this->maxValue = maxValue;
        this->seed = seed;
