#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
} record;

bool is_prime(int num) {
    if (num <= 1) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;

    for (int i = 3; i * i <= num; i += 2) {
        if (num % i == 0) return false;
    }
    return true;
}

void initialize_arrays(int N, int offsetMin, int offsetMax, int* keys, long* offsets) {
    for (int i = 0; i < N; ++i) {
        keys[i] = i;
        offsets[i] = (rand() % (offsetMax - offsetMin + 1)) + offsetMin;
    }
}

void initialize_records(int N, int minValue, int maxValue, record* records) {
    for (int i = 0; i < N; ++i) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        while (!is_prime(value)) {
            value++;
        }
        records[i].value = value;
    }
}

void allocate_and_initialize(int N, int offsetMin, int offsetMax, int minValue, int maxValue, record** records) {
    *records = (record*)malloc(N * sizeof(record));
    if (*records == NULL) {
        perror("Memory allocation failed");
        return;
    }

    initialize_records(N, minValue, maxValue, *records);
}
