// Custom memory pool for efficient allocation and minimal fragmentation
typedef struct MemPool {
    void* blocks; // Contiguous block of allocated memory
    size_t capacity; // Total capacity of the memory pool
    size_t used; // Current amount of memory used in the pool
    size_t granularity; // Allocation granularity within the memory pool
} MemPool;

// Function to handle thread-safe initialization of keys and offsets arrays
void initArrays(size_t* keys, long* offsets, size_t N, MemPool* memPool) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < N; ++i) {
        // Acquire the lock to ensure thread safety
        pthread_mutex_lock(&mutex);

        // Adjust N dynamically to fit within available system resources
        if (N > memPool->capacity / (2 * sizeof(size_t)))
            N = memPool->capacity / (2 * sizeof(size_t));

        // Allocate memory and initialize keys array
        keys[i] = i;

        // Allocate memory for offsets array using the custom memory pool
        offsets[i] = memPoolAlloc(memPool, sizeof(long));

        // Release the lock
        pthread_mutex_unlock(&mutex);
    }
}

// Function to initialize records array with unique and random values
void initRecords(int* records, size_t N, size_t minValue, size_t maxValue) {
    for (size_t i = 0; i < N; ++i) {
        bool found = false;
        int value;
        do {
            value = rand() % (maxValue - minValue + 1) + minValue;
            found = true;
            for (size_t j = 0; j < i; ++j) {
                if (records[j] == value) {
                    found = false;
                    break;
                }
            }
        } while (!found);
        records[i] = value;
    }
}

// Implement custom retry mechanism for duplicate record values
