    MemPool memPool;
    memPool.blocks = mmap(NULL, 1024 * 1024, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memPool.blocks == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    memPool.capacity = 1024 * 1024;
    memPool.used = 0;
    memPool.granularity = sizeof(size_t);

    size_t* keys;
    long* offsets;
    initArrays(keys, offsets, N > INT_MAX ? INT_MAX : N, &memPool);

    int* records = malloc(N * sizeof(int));
    if (!records) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    initRecords(records, N, minValue, maxValue);

